// Instrucciones del catálogo (free-exercise-db, inglés) traducidas a portugués de Brasil.
// Clave = `exercises.name` original; valor = pasos unidos con "\n", igual que
// la columna `instructions` de la DB. Ver `localizedInstructions` en
// `exerciseLabels.ts` para el fallback al inglés.
export const exerciseInstructionsPt: Record<string, string> = {
  '3/4 Sit-Up':
    'Deite-se no chão e prenda os pés. As pernas devem estar flexionadas na altura dos joelhos.\nColoque as mãos atrás ou ao lado da cabeça. Você começará com as costas apoiadas no chão. Esta será a sua posição inicial.\nFlexione o quadril e a coluna para elevar o tronco em direção aos joelhos.\nNo topo da contração, o tronco deve ficar perpendicular ao chão. Inverta o movimento, descendo apenas ¾ do caminho.\nRepita o número de repetições recomendado.',
  '90/90 Hamstring':
    'Deite-se de costas, com uma perna estendida para a frente.\nCom a outra perna, flexione o quadril e o joelho a 90 graus. Se necessário, você pode apoiar a perna com as mãos. Esta será a sua posição inicial.\nEstenda a perna reta para o alto, fazendo uma breve pausa no topo. Volte a perna à posição inicial.\nRepita de 10 a 20 repetições e depois troque de perna.',
  'Ab Crunch Machine':
    'Selecione uma carga leve e sente-se na máquina de abdominais, colocando os pés sob os apoios e segurando as alças superiores. Os braços devem ficar flexionados a 90 graus, com os tríceps apoiados nas almofadas. Esta será a sua posição inicial.\nAo mesmo tempo, comece a elevar as pernas enquanto faz o crunch com a parte superior do tronco. Expire ao realizar este movimento. Dica: use um movimento lento e controlado. Concentre-se em mover o peso com os abdominais, relaxando as pernas e os pés.\nApós uma pausa de um segundo, volte lentamente à posição inicial enquanto inspira.\nRepita o movimento pelo número de repetições prescrito.',
  'Ab Roller':
    'Segure a roda abdominal com as duas mãos e ajoelhe-se no chão.\nAgora coloque a roda no chão à sua frente, de modo que você fique apoiado nas mãos e nos joelhos (como em uma flexão de braço com joelhos no chão). Esta será a sua posição inicial.\nRole lentamente a roda para a frente em linha reta, alongando o corpo até ficar na posição estendida. Dica: desça o máximo que puder sem tocar o chão com o corpo. Inspire durante esta parte do movimento.\nApós uma pausa na posição alongada, comece a voltar à posição inicial enquanto expira. Dica: vá devagar e mantenha os abdominais contraídos o tempo todo.',
  Adductor:
    'Deite-se de bruços com uma perna sobre um rolo de espuma.\nGire a perna para que o rolo de espuma faça contato com a parte interna da coxa. Transfira para o rolo o máximo de peso que conseguir tolerar.\nEnquanto tenta relaxar os músculos da parte interna da coxa, role sobre o rolo entre o quadril e o joelho, mantendo os pontos de tensão por 10 a 30 segundos. Repita com a outra perna.',
  'Adductor/Groin':
    'Deite-se de costas com os pés elevados em direção ao teto.\nPeça para o seu parceiro segurar seus pés ou tornozelos. Abra as pernas o máximo que puder. Esta será a sua posição inicial.\nTente juntar as pernas com força por 10 segundos ou mais, enquanto o seu parceiro impede o movimento.\nAgora relaxe os músculos das pernas enquanto o seu parceiro afasta seus pés, alongando até onde for confortável para você. Avise o seu parceiro quando o alongamento for suficiente, para evitar alongar demais ou se lesionar.',
  'Advanced Kettlebell Windmill':
    'Faça um clean e press de um kettlebell acima da cabeça com um braço.\nMantendo o kettlebell com o braço estendido o tempo todo, empurre o quadril para trás na direção do kettlebell. Mantenha o braço livre atrás das costas e vire os pés para fora em um ângulo de quarenta e cinco graus em relação ao braço que segura o kettlebell.\nDesça o máximo que puder.\nFaça uma pausa de um segundo e inverta o movimento até a posição inicial.',
  'Air Bike':
    'Deite-se de costas no chão com a lombar pressionada contra o solo. Para este exercício, coloque as mãos ao lado da cabeça. Tenha cuidado para não forçar o pescoço ao executá-lo. Agora eleve os ombros até a posição de abdominal.\nLeve os joelhos para cima até ficarem perpendiculares ao chão, com as canelas paralelas ao solo. Esta será a sua posição inicial.\nAgora, simultaneamente e devagar, faça um movimento de pedalada, estendendo a perna direita para a frente e trazendo o joelho da perna esquerda. Aproxime o cotovelo direito do joelho esquerdo fazendo o abdominal para o lado, enquanto expira.\nVolte à posição inicial enquanto inspira.\nFaça o abdominal para o lado oposto enquanto pedala com as pernas, aproximando o cotovelo esquerdo do joelho direito, e expire.\nContinue alternando dessa maneira até completar todas as repetições recomendadas para cada lado.',
  'All Fours Quad Stretch':
    'Comece de quatro apoios, sobre as mãos e os joelhos; depois levante uma perna do chão e segure o pé com a mão.\nUse a mão para segurar o pé ou o tornozelo, mantendo o joelho totalmente flexionado, alongando o quadríceps e os flexores do quadril.\nConcentre-se em estender o quadril, empurrando-o em direção ao chão. Mantenha por 10 a 20 segundos e depois troque de lado.',
  'Alternate Hammer Curl':
    'Fique em pé com o tronco ereto e um halter em cada mão, com os braços estendidos. Os cotovelos devem ficar próximos ao tronco.\nAs palmas das mãos devem estar voltadas para o tronco. Esta será a sua posição inicial.\nMantendo o braço parado, flexione o halter direito para a frente contraindo o bíceps enquanto expira. Continue o movimento até que o bíceps esteja totalmente contraído e os halteres estejam na altura dos ombros. Mantenha a posição contraída por um segundo enquanto aperta o bíceps. Dica: apenas os antebraços devem se mover.\nComece a baixar lentamente os halteres até a posição inicial enquanto inspira.\nRepita o movimento com a mão esquerda. Isso equivale a uma repetição.\nContinue alternando dessa maneira pelo número de repetições recomendado.',
  'Alternate Heel Touchers':
    'Deite-se no chão com os joelhos flexionados e os pés apoiados, afastados cerca de 45 a 60 cm. Os braços devem ficar estendidos ao lado do corpo. Esta será a sua posição inicial.\nFaça um abdominal levando o tronco para a frente e para cima cerca de 8 a 10 cm em direção ao lado direito e toque o calcanhar direito, mantendo a contração por um segundo. Expire enquanto realiza este movimento.\nAgora volte lentamente à posição inicial enquanto inspira.\nAgora faça um abdominal levando o tronco para a frente e para cima cerca de 8 a 10 cm em direção ao lado esquerdo e toque o calcanhar esquerdo, mantendo a contração por um segundo. Expire enquanto realiza este movimento e depois volte à posição inicial enquanto inspira. Ao tocar os dois calcanhares, conta-se 1 repetição.\nContinue alternando os lados dessa maneira até concluir todas as repetições prescritas.',
  'Alternate Incline Dumbbell Curl':
    'Sente-se em um banco inclinado com um halter em cada mão, com os braços estendidos. Dica: mantenha os cotovelos próximos ao tronco. Esta será a sua posição inicial.\nMantendo o braço parado, flexione o halter direito para a frente contraindo o bíceps enquanto expira. Ao fazer isso, gire a mão para que a palma fique voltada para cima. Continue o movimento até que o bíceps esteja totalmente contraído e os halteres estejam na altura dos ombros. Mantenha a posição contraída por um segundo enquanto aperta o bíceps. Dica: apenas os antebraços devem se mover.\nComece a baixar lentamente o halter até a posição inicial enquanto inspira.\nRepita o movimento com a mão esquerda. Isso equivale a uma repetição.\nContinue alternando dessa maneira pelo número de repetições recomendado.',
  'Alternate Leg Diagonal Bound':
    'Assuma uma postura confortável com um pé ligeiramente à frente do outro.\nComece impulsionando-se com a perna da frente, levando o joelho oposto para a frente e o mais alto possível antes de aterrissar. Tente cobrir a maior distância possível para cada lado a cada salto.\nPode ajudar usar uma linha no chão para medir a distância de um lado ao outro.\nRepita a sequência com a outra perna.',
  'Alternating Cable Shoulder Press':
    'Coloque os cabos na parte inferior da torre e selecione uma carga adequada.\nSegure os cabos e mantenha-os na altura dos ombros, com as palmas voltadas para a frente. Esta será a sua posição inicial.\nMantendo a cabeça e o peito erguidos, estenda o cotovelo para empurrar um lado diretamente acima da cabeça.\nApós uma pausa no topo, volte à posição inicial e repita com o lado oposto.',
  'Alternating Deltoid Raise':
    'Em pé, segure um par de halteres ao lado do corpo.\nMantendo os cotovelos ligeiramente flexionados, eleve os pesos diretamente à sua frente até a altura dos ombros, evitando balanços ou impulsos.\nVolte os pesos para o lado do corpo.\nNa repetição seguinte, eleve os pesos lateralmente, para os lados até cerca da altura dos ombros.\nVolte os pesos à posição inicial e continue alternando entre a frente e o lado.',
  'Alternating Floor Press':
    'Deite-se no chão com dois kettlebells ao lado dos ombros.\nPosicione um deles sobre o peito e depois o outro, segurando os kettlebells pela alça com as palmas voltadas para a frente.\nEstenda os dois braços, de modo que os kettlebells fiquem sustentados acima do peito. Baixe um kettlebell, levando-o ao peito, e gire o punho na direção do kettlebell que permanece estendido.\nEleve o kettlebell e repita com o lado oposto.',
  'Alternating Hang Clean':
    'Coloque dois kettlebells entre os pés. Para chegar à posição inicial, empurre o quadril para trás e olhe para a frente.\nFaça um clean de um kettlebell até o ombro e segure o outro em posição pendurada. Leve o kettlebell ao ombro estendendo as pernas e o quadril enquanto o puxa em direção aos ombros. Gire o punho ao fazer isso.\nBaixe o kettlebell para a posição pendurada e faça o clean com o outro kettlebell. Repita.',
  'Alternating Kettlebell Press':
    'Faça o clean de dois kettlebells até os ombros. Leve os kettlebells aos ombros estendendo as pernas e o quadril enquanto os puxa em direção aos ombros. Gire os punhos ao fazer isso.\nEmpurre um deles diretamente acima da cabeça estendendo o cotovelo e girando-o para que a palma fique voltada para a frente, enquanto mantém o outro kettlebell parado.\nBaixe o kettlebell à posição inicial e imediatamente empurre o outro com o outro braço.',
  'Alternating Kettlebell Row':
    'Coloque dois kettlebells à frente dos pés. Flexione ligeiramente os joelhos e empurre o quadril para trás o máximo possível. Ao se inclinar para chegar à posição inicial, segure os dois kettlebells pelas alças.\nLevante um kettlebell do chão enquanto segura o outro. Retraia a escápula do lado que está trabalhando enquanto flexiona o cotovelo, puxando o kettlebell em direção ao abdômen ou às costelas.\nBaixe o kettlebell do braço que está trabalhando e repita com o outro braço.',
  'Alternating Renegade Row':
    'Coloque dois kettlebells no chão, afastados na largura dos ombros. Posicione-se sobre os dedos dos pés e as mãos como se fosse fazer uma flexão de braço, com o corpo reto e estendido. Use as alças dos kettlebells para apoiar a parte superior do corpo. Pode ser necessário afastar bem os pés para ter apoio.\nEmpurre um kettlebell contra o chão e reme com o outro, retraindo a escápula do lado que está trabalhando enquanto flexiona o cotovelo, puxando-o em direção ao seu lado.\nDepois baixe o kettlebell até o chão e comece com o kettlebell da mão oposta. Repita por várias repetições.',
  'Ankle Circles':
    'Use um objeto firme, como um rack de agachamento, para se apoiar.\nLevante a perna direita no ar (a cerca de 5 cm do chão) e faça um movimento circular com o dedão do pé. Imagine que está desenhando um círculo grande com ele. Dica: um círculo equivale a 1 repetição. Respire normalmente enquanto realiza o movimento.\nQuando terminar com o pé direito, repita com a perna esquerda.',
  'Ankle On The Knee':
    'Partindo de uma posição deitada, flexione os joelhos e mantenha os pés no chão.\nColoque o tornozelo de um pé sobre o joelho oposto.\nSegure a coxa ou o joelho da perna de baixo e puxe as duas pernas em direção ao peito. Relaxe o pescoço e os ombros. Mantenha por 10 a 20 segundos e depois troque de lado.',
  'Anterior Tibialis-SMR':
    'Comece sentado no chão com as pernas flexionadas e os pés apoiados.\nUsando um rolo muscular ou um rolo de massa, aplique pressão nos músculos da parte externa das canelas. Trabalhe desde logo abaixo do joelho até acima do tornozelo, pausando nos pontos de tensão por 10 a 30 segundos. Repita na outra perna.',
  'Anti-Gravity Press':
    'Coloque uma barra no chão atrás da cabeceira de um banco inclinado.\nDeite-se de bruços no banco. Com pegada pronada, levante a barra do chão. Flexione os cotovelos, fazendo uma rosca inversa para trazer a barra perto do peito. Esta será a sua posição inicial.\nPara começar, empurre a barra para a frente da cabeça estendendo os cotovelos. Mantenha os braços paralelos ao chão durante todo o movimento.\nVolte à posição inicial e repita até completar a série.',
  'Arm Circles':
    'Fique em pé e estenda os braços retos para os lados. Os braços devem ficar paralelos ao chão e perpendiculares (ângulo de 90 graus) ao tronco. Esta será a sua posição inicial.\nComece lentamente a fazer círculos de cerca de 30 cm de diâmetro com cada braço estendido. Respire normalmente enquanto realiza o movimento.\nContinue o movimento circular dos braços estendidos por cerca de dez segundos. Depois inverta o movimento, girando na direção oposta.',
  'Arnold Dumbbell Press':
    'Sente-se em um banco com apoio para as costas e segure dois halteres à sua frente na altura da parte superior do peito, com as palmas voltadas para o corpo e os cotovelos flexionados. Dica: os braços devem ficar junto ao tronco. A posição inicial deve parecer a parte contraída de uma rosca com halteres.\nAgora, para realizar o movimento, eleve os halteres enquanto gira as palmas das mãos até que fiquem voltadas para a frente.\nContinue elevando os halteres até que os braços fiquem estendidos acima de você. Expire durante esta parte do movimento.\nApós uma pausa de um segundo no topo, comece a baixar os halteres à posição original girando as palmas das mãos em sua direção. Dica: o braço esquerdo girará no sentido anti-horário enquanto o direito girará no sentido horário. Inspire durante esta parte do movimento.\nRepita o número de repetições recomendado.',
  'Around The Worlds':
    'Deite-se em um banco reto segurando um halter em cada mão com as palmas voltadas para o teto. Dica: os braços devem ficar paralelos ao chão e ao lado das coxas. Para evitar lesões, mantenha os cotovelos ligeiramente flexionados. Esta será a sua posição inicial.\nAgora movimente os halteres descrevendo um semicírculo desde a posição inicial até acima da cabeça. Todo o movimento deve ser feito com os braços paralelos ao chão o tempo todo. Inspire durante esta parte do movimento.\nInverta o movimento para voltar o peso à posição inicial enquanto expira.',
  'Atlas Stone Trainer':
    'Este equipamento é eficaz para desenvolver a força para as pedras Atlas em quem não tem acesso a pedras, e costuma ser feito com pontas de barra ou tubo pesado.\nComece carregando o peso desejado na barra. Posicione-se sobre o peso, com uma perna de cada lado, envolvendo-o com os braços e flexionando o quadril.\nComece puxando o peso para cima, passando os joelhos, estendendo o quadril. Quando o peso passar dos joelhos, você pode apoiá-lo sobre as coxas sentando-se para trás, abraçando-o firmemente contra o peito.\nFinalize o movimento estendendo o quadril e os joelhos para elevar o peso o mais alto possível. O peso pode voltar às coxas ou ao chão para as repetições seguintes.',
  'Atlas Stones':
    'Comece com a pedra Atlas entre os pés. Flexione o quadril para envolver a pedra Atlas verticalmente com os braços, tentando colocar os dedos por baixo da pedra. Muitas pedras têm uma pequena parte plana na base, o que facilita segurá-las.\nPuxando a pedra em direção ao tronco, empurre com a parte de trás dos pés para tirar a pedra do chão.\nQuando a pedra passar dos joelhos, apoie-a sentando-se para trás, puxando a pedra para cima das coxas.\nSente-se baixo, levando a pedra bem alto no peito enquanto troca a pegada para passar por cima da pedra. Levante-se, empurrando com o quadril. Aproxime-se da plataforma de carga e incline-se para trás, estendendo o quadril para levar a pedra o mais alto possível.',
  'Axle Deadlift':
    'Aproxime-se da barra de modo que ela fique centrada sobre os pés. Os pés devem ficar afastados na largura do quadril. Flexione o quadril para segurar a barra na largura dos ombros, permitindo que as escápulas se protraiam. Normalmente, usa-se uma pegada mista.\nCom os pés e a pegada posicionados, respire fundo e depois abaixe o quadril e flexione os joelhos até que as canelas encostem na barra. Olhe para a frente, mantenha o peito erguido e as costas arqueadas, e comece a empurrar com os calcanhares para mover o peso para cima.\nDepois que a barra passar dos joelhos, puxe-a com força para trás, aproximando as escápulas enquanto empurra o quadril para a frente contra a barra.\nBaixe a barra flexionando o quadril e guiando-a até o chão.',
  'Back Flyes - With Bands':
    'Passe uma faixa elástica ao redor de um poste fixo, como o de um rack de agachamento.\nSegure a faixa pelas alças e afaste-se até que a tensão da faixa aumente.\nEstenda e levante os braços retos à sua frente. Dica: os braços devem ficar retos e paralelos ao chão, e perpendiculares ao tronco. Os pés devem estar firmemente apoiados no chão, afastados na largura dos ombros. Esta será a sua posição inicial.\nAo expirar, leve os braços para os lados e para trás. Mantenha os braços estendidos e paralelos ao chão. Continue o movimento até que os braços fiquem estendidos para os lados.\nApós uma pausa, volte à posição original enquanto inspira.\nRepita o número de repetições recomendado.',
  'Backward Drag':
    'Carregue um trenó com o peso desejado, prendendo ao trenó uma corda ou alças que você possa segurar.\nComece o exercício movendo-se para trás por uma distância determinada. Inclinando-se para trás, estenda as pernas com passos curtos para se mover o mais rápido possível.',
  'Backward Medicine Ball Throw':
    'Este exercício é melhor feito com um parceiro. Se você não tiver um, pode arremessar e buscar a bola ou arremessá-la contra uma parede.\nComece em pé a alguns metros à frente do seu parceiro, ambos virados para a mesma direção. Segure a bola entre as pernas.\nAgache-se e depois inverta a direção com força, chegando à extensão completa enquanto arremessa a bola por cima da cabeça para o seu parceiro.\nSeu parceiro pode rolar a bola de volta para você. Repita pelo número de repetições desejado.',
  'Balance Board':
    'Coloque uma prancha de equilíbrio à sua frente.\nSuba nela e tente manter o equilíbrio.\nMantenha o equilíbrio pelo tempo que desejar.',
  'Ball Leg Curl':
    'Comece deitado de costas no chão com os pés sobre a bola.\nPosicione a bola de modo que, quando as pernas estiverem estendidas, os tornozelos fiquem sobre a bola. Esta será a sua posição inicial.\nEleve o quadril do chão, mantendo o peso sobre as escápulas e os pés.\nFlexione os joelhos, puxando a bola o mais perto de você que conseguir, contraindo os posteriores de coxa.\nApós uma breve pausa, volte à posição inicial.',
  'Band Assisted Pull-Up':
    'Passe a faixa elástica pelo centro da barra fixa e ajuste-a com um laço. Você pode usar faixas diferentes para dar diferentes níveis de assistência.\nPuxe a ponta da faixa para baixo e coloque um joelho flexionado no laço, certificando-se de que não vai escorregar. Segure a barra com uma pegada de largura média a ampla. Esta será a sua posição inicial.\nPuxe-se para cima contraindo os dorsais enquanto flexiona o cotovelo. O cotovelo deve ser levado em direção ao seu lado. Suba à frente, tentando passar o queixo acima da barra. Evite balançar ou dar solavancos.\nApós uma breve pausa, volte à posição inicial.',
  'Band Good Morning':
    'Usando uma faixa de 41 polegadas, pise em uma das pontas, afastando um pouco os pés. Flexione o quadril para passar a outra ponta da faixa por trás do pescoço. Esta será a sua posição inicial.\nMantendo as pernas retas, estenda o quadril até chegar a uma posição quase vertical.\nCertifique-se de não arredondar as costas ao descer de volta à posição inicial.',
  'Band Good Morning (Pull Through)':
    'Passe a faixa ao redor de um poste. Posicione-se a certa distância e passe a ponta oposta ao redor do pescoço. Suas mãos podem ajudar a manter a faixa no lugar.\nComece flexionando o quadril, levando-o para trás o máximo possível. Mantenha as costas retas e incline-se para a frente cerca de 90 graus. Os joelhos devem ficar apenas ligeiramente flexionados.\nVolte à posição inicial empurrando com o quadril para retornar à posição em pé.',
  'Band Hip Adductions':
    'Prenda uma faixa elástica ao redor de um poste sólido ou outro objeto.\nFique com o lado esquerdo voltado para o poste e passe o pé direito pela faixa, ajustando-a ao redor do tornozelo.\nFique em pé, com o corpo ereto, e segure no poste se necessário. Esta será a sua posição inicial.\nMantendo o joelho reto, eleve a perna direita para o lado o máximo que puder.\nVolte à posição inicial e repita pelo número de repetições desejado.\nTroque de lado.',
  'Band Pull Apart':
    'Comece com os braços estendidos retos à sua frente, segurando a faixa com as duas mãos.\nInicie o movimento realizando uma abertura inversa, levando as mãos para fora, para os lados.\nMantenha os cotovelos estendidos enquanto realiza o movimento, trazendo a faixa em direção ao peito. Mantenha os ombros para trás durante o exercício.\nFaça uma pausa ao completar o movimento e volte à posição inicial de forma controlada.',
  'Band Skull Crusher':
    'Prenda uma faixa elástica na base de um rack ou do banco. Deite-se no banco de modo que a faixa fique alinhada com a sua cabeça.\nSegure a faixa, elevando os cotovelos de modo que a parte superior do braço fique perpendicular ao chão. Com o cotovelo flexionado, a faixa deve ficar acima da cabeça. Esta será a sua posição inicial.\nEstenda o cotovelo para esticar o braço, mantendo a parte superior do braço no lugar. Faça uma pausa no topo do movimento e volte à posição inicial.',
  'Barbell Ab Rollout':
    'Para este exercício, você deve assumir a posição de flexão de braço, mas em vez de apoiar as mãos no chão, você vai segurar uma barra olímpica (carregada com 5-10 lbs de cada lado). Esta será a sua posição inicial.\nMantendo um leve arco nas costas, eleve o quadril e role a barra em direção aos pés enquanto expira. Dica: ao realizar o movimento, os glúteos devem subir, você deve manter os abdominais contraídos e conservar a postura das costas o tempo todo. Além disso, os braços devem permanecer perpendiculares ao chão durante todo o movimento. Se não fizer isso, você trabalhará mais os ombros e as costas do que os abdominais.\nApós uma contração de um segundo no topo, comece a rolar a barra de volta para a frente até a posição inicial lentamente enquanto inspira.\nRepita o número de repetições recomendado.',
  'Barbell Ab Rollout - On Knees':
    'Segure uma barra olímpica carregada com 5-10 lbs de cada lado e ajoelhe-se no chão.\nAgora coloque a barra no chão à sua frente, de modo que você fique apoiado nas mãos e nos joelhos (como em uma flexão de braço com joelhos no chão). Esta será a sua posição inicial.\nRole lentamente a barra para a frente em linha reta, alongando o corpo até ficar na posição estendida. Dica: desça o máximo que puder sem tocar o chão com o corpo. Inspire durante esta parte do movimento.\nApós uma pausa de um segundo na posição alongada, comece a voltar à posição inicial enquanto expira. Dica: vá devagar e mantenha os abdominais contraídos o tempo todo.',
  'Barbell Bench Press - Medium Grip':
    'Deite-se em um banco reto. Usando uma pegada de largura média (uma pegada que forma um ângulo de 90 graus no meio do movimento entre os antebraços e a parte superior dos braços), retire a barra do rack e segure-a reta acima de você com os braços estendidos. Esta será a sua posição inicial.\nA partir da posição inicial, inspire e comece a descer lentamente até que a barra toque a parte média do peito.\nApós uma breve pausa, empurre a barra de volta à posição inicial enquanto expira. Concentre-se em empurrar a barra com os músculos do peito. Estenda os braços e contraia o peito na posição contraída no topo do movimento, mantenha por um segundo e depois comece a descer lentamente de novo. Dica: idealmente, descer o peso deve levar cerca do dobro do tempo de subir.\nRepita o movimento pelo número de repetições prescrito.\nQuando terminar, coloque a barra de volta no rack.',
  'Barbell Curl':
    'Fique em pé com o tronco ereto segurando uma barra com pegada na largura dos ombros. As palmas das mãos devem estar voltadas para a frente e os cotovelos próximos ao tronco. Esta será a sua posição inicial.\nMantendo a parte superior dos braços parada, flexione o peso para a frente contraindo o bíceps enquanto expira. Dica: apenas os antebraços devem se mover.\nContinue o movimento até que os bíceps estejam totalmente contraídos e a barra esteja na altura dos ombros. Mantenha a posição contraída por um segundo e aperte bem o bíceps.\nComece a baixar lentamente a barra até a posição inicial enquanto inspira.\nRepita o número de repetições recomendado.',
  'Barbell Curls Lying Against An Incline':
    'Deite-se de bruços contra um banco inclinado, com os braços segurando uma barra e pendurados em linha vertical. Esta será a sua posição inicial.\nMantendo a parte superior dos braços parada, flexione o peso o mais alto que puder apertando o bíceps. Expire durante esta parte do movimento. Dica: apenas os antebraços devem se mover. Não balance os braços.\nApós uma contração de um segundo, volte lentamente à posição inicial enquanto inspira. Dica: certifique-se de descer completamente.\nRepita o número de repetições recomendado.',
  'Barbell Deadlift':
    'Fique em pé diante de uma barra carregada.\nMantendo as costas o mais retas possível, flexione os joelhos, incline-se para a frente e segure a barra com uma pegada pronada de largura média (na largura dos ombros). Esta será a posição inicial do exercício. Dica: se for difícil segurar a barra com essa pegada, alterne a pegada ou use straps.\nSegurando a barra, comece o levantamento empurrando com as pernas e, ao mesmo tempo, levando o tronco à posição ereta enquanto expira. Na posição ereta, estufe o peito e contraia as costas levando as escápulas para trás. Pense em como os soldados ficam em posição de sentido.\nVolte à posição inicial flexionando os joelhos enquanto inclina o tronco para a frente a partir da cintura, mantendo as costas retas. Quando os pesos da barra tocarem o chão, você terá voltado à posição inicial e estará pronto para fazer outra repetição.\nRealize o número de repetições prescrito no programa.',
  'Barbell Full Squat':
    'Este exercício é melhor realizado dentro de um rack de agachamento por questões de segurança. Para começar, posicione a barra em um rack um pouco acima da altura dos ombros. Depois de escolher a altura correta e carregar a barra, entre embaixo da barra e apoie a parte de trás dos ombros (ligeiramente abaixo do pescoço) sobre ela.\nSegure a barra com as duas mãos, uma de cada lado, e retire-a do rack empurrando primeiro com as pernas e, ao mesmo tempo, endireitando o tronco.\nAfaste-se do rack e posicione as pernas em uma base média, na largura dos ombros, com as pontas dos pés ligeiramente voltadas para fora. Mantenha a cabeça erguida o tempo todo e as costas retas. Esta será a sua posição inicial.\nComece a baixar lentamente a barra flexionando os joelhos e sentando-se para trás com o quadril, mantendo uma postura reta com a cabeça erguida. Continue descendo até que os posteriores de coxa fiquem sobre as panturrilhas. Inspire durante esta parte do movimento.\nComece a subir a barra enquanto expira, empurrando o chão com o calcanhar ou o meio do pé enquanto endireita as pernas e estende o quadril para voltar à posição inicial.\nRepita o número de repetições recomendado.',
  'Barbell Glute Bridge':
    'Comece sentado no chão com uma barra carregada sobre as pernas. Usar uma barra grossa ou colocar uma almofada na barra pode reduzir muito o desconforto deste exercício. Role a barra até que fique diretamente sobre o quadril e deite-se de costas no chão.\nComece o movimento empurrando com os calcanhares, estendendo o quadril verticalmente através da barra. O seu peso deve ficar apoiado na parte superior das costas e nos calcanhares.\nEstenda o máximo possível e depois inverta o movimento para voltar à posição inicial.',
  'Barbell Guillotine Bench Press':
    'Usando uma pegada de largura média (uma pegada que forma um ângulo de 90 graus no meio do movimento entre os antebraços e a parte superior dos braços), retire a barra do rack e segure-a reta acima do pescoço com os braços estendidos. Esta será a sua posição inicial.\nAo inspirar, desça a barra lentamente até ficar a cerca de 2,5 cm do pescoço.\nApós uma pausa de um segundo, leve a barra de volta à posição inicial enquanto expira e empurra a barra com os músculos do peito. Estenda os braços e contraia o peito na posição contraída, mantenha por um segundo e depois comece a descer lentamente de novo. Deve levar pelo menos o dobro do tempo para descer do que para subir.\nRepita o movimento pelo número de repetições prescrito.\nQuando terminar, coloque a barra de volta no rack.',
  'Barbell Hack Squat':
    'Fique em pé, com o corpo ereto, segurando uma barra atrás de você com os braços estendidos e os pés na largura dos ombros. Dica: o ideal é uma pegada na largura dos ombros com as palmas das mãos voltadas para trás. Você pode usar munhequeiras neste exercício para ter uma pegada melhor. Esta será a sua posição inicial.\nMantendo a cabeça e o olhar erguidos e as costas retas, agache até que a parte superior das coxas fique paralela ao chão. Inspire enquanto desce lentamente.\nEmpurrando principalmente com o calcanhar e apertando as coxas, suba enquanto expira.\nRepita o número de repetições recomendado.',
  'Barbell Hip Thrust':
    'Comece sentado no chão com um banco diretamente atrás de você. Tenha uma barra carregada sobre as pernas. Usar uma barra grossa ou colocar uma almofada na barra pode reduzir muito o desconforto deste exercício.\nRole a barra até que fique diretamente sobre o quadril e recline-se contra o banco de modo que as escápulas fiquem perto da parte superior dele.\nComece o movimento empurrando com os pés, estendendo o quadril verticalmente através da barra. O seu peso deve ficar apoiado nas escápulas e nos pés. Estenda o máximo possível e depois inverta o movimento para voltar à posição inicial.',
  'Barbell Incline Bench Press - Medium Grip':
    'Deite-se em um banco inclinado. Usando uma pegada de largura média (uma pegada que forma um ângulo de 90 graus no meio do movimento entre os antebraços e a parte superior dos braços), retire a barra do rack e segure-a reta acima de você com os braços estendidos. Esta será a sua posição inicial.\nAo inspirar, desça lentamente até sentir a barra na parte superior do peito.\nApós uma pausa de um segundo, leve a barra de volta à posição inicial enquanto expira e empurra a barra com os músculos do peito. Estenda os braços na posição contraída, aperte o peito, mantenha por um segundo e depois comece a descer lentamente de novo. Dica: deve levar pelo menos o dobro do tempo para descer do que para subir.\nRepita o movimento pelo número de repetições prescrito.\nQuando terminar, coloque a barra de volta no rack.',
  'Barbell Incline Shoulder Raise':
    'Deite-se em um banco inclinado. Usando uma pegada de largura média (uma pegada ligeiramente mais larga que os ombros), retire a barra do rack e segure-a reta acima de você com os braços estendidos. Esta será a sua posição inicial.\nMantendo os braços retos, levante a barra protraindo as escápulas e elevando os ombros do banco enquanto expira.\nVolte a barra à posição inicial enquanto inspira.\nRepita o número de repetições recomendado.',
  'Barbell Lunge':
    'Este exercício é melhor realizado dentro de um rack de agachamento por questões de segurança. Para começar, posicione a barra em um rack um pouco abaixo da altura dos ombros. Depois de escolher a altura correta e carregar a barra, entre embaixo da barra e apoie a parte de trás dos ombros (ligeiramente abaixo do pescoço) sobre ela.\nSegure a barra com as duas mãos, uma de cada lado, e retire-a do rack empurrando primeiro com as pernas e, ao mesmo tempo, endireitando o tronco.\nAfaste-se do rack e dê um passo à frente com a perna direita e desça em afundo com o quadril, mantendo o tronco ereto e o equilíbrio. Inspire enquanto desce. Nota: não deixe o joelho avançar além da ponta do pé ao descer, pois isso colocará uma tensão excessiva na articulação do joelho.\nUsando principalmente o calcanhar do pé, empurre para cima e volte à posição inicial enquanto expira.\nRepita o movimento pelo número de repetições recomendado e depois realize com a perna esquerda.',
  'Barbell Rear Delt Row':
    'Fique em pé, com a coluna reta, segurando uma barra com pegada larga (mais aberta que a largura dos ombros) e pronada (palmas voltadas para o corpo).\nFlexione levemente os joelhos e incline-se para a frente mantendo a curvatura natural da coluna. Deixe os braços pendurados à sua frente segurando a barra. Quando o tronco estiver paralelo ao chão, abra os cotovelos para fora, afastando-os do corpo. Dica: seu tronco e seus braços devem formar a letra "T". Agora você está pronto para começar o exercício.\nMantendo os braços perpendiculares ao tronco, puxe a barra em direção à parte superior do peito enquanto contrai os deltoides posteriores e expira. Dica: se feito corretamente, este exercício deve parecer um supino ao contrário. Além disso, evite usar os bíceps para fazer o trabalho. Concentre-se nos deltoides posteriores; os braços devem servir apenas como ganchos.\nVolte lentamente à posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado.',
  'Barbell Rollout from Bench':
    'Coloque uma barra carregada no chão, perto da extremidade de um banco. Ajoelhe-se com as duas pernas sobre o banco e segure a barra com pegada média a estreita. Esta será sua posição inicial.\nPara começar, estenda os quadris para rolar a barra lentamente para a frente. Enquanto rola, flexione o ombro para levar a barra acima da cabeça. Certifique-se de que os braços permaneçam estendidos durante todo o movimento.\nQuando a barra estiver o mais longe possível à frente, volte à posição inicial.',
  'Barbell Seated Calf Raise':
    'Coloque um bloco a cerca de 30 cm (12 polegadas) à frente de um banco reto.\nSente-se no banco e apoie a parte da frente dos pés sobre o bloco.\nPeça a alguém que coloque uma barra sobre a parte superior das coxas, cerca de 3 polegadas acima dos joelhos, e a mantenha ali. Esta será sua posição inicial.\nSuba na ponta dos pés o mais alto possível enquanto contrai as panturrilhas e expira.\nApós uma contração de um segundo, volte lentamente à posição inicial. Dica: para obter o máximo benefício, alongue as panturrilhas o máximo que puder.\nRepita pelo número de repetições recomendado.',
  'Barbell Shoulder Press':
    'Sente-se em um banco com encosto dentro de um rack de agachamento. Posicione a barra a uma altura um pouco acima da cabeça. Segure a barra com pegada pronada (palmas voltadas para a frente).\nDepois de pegar a barra com a largura de pegada correta, levante-a acima da cabeça estendendo os braços. Segure-a na altura dos ombros e um pouco à frente da cabeça. Esta é sua posição inicial.\nAbaixe a barra lentamente até os ombros enquanto inspira.\nLevante a barra de volta à posição inicial enquanto expira.\nRepita pelo número de repetições recomendado.',
  'Barbell Shrug':
    'Fique em pé, com a coluna reta e os pés na largura dos ombros, segurando uma barra com as duas mãos à sua frente com pegada pronada (palmas voltadas para as coxas). Dica: suas mãos devem ficar um pouco mais afastadas que a largura dos ombros. Você pode usar munhequeiras ou straps para melhorar a pegada. Esta será sua posição inicial.\nEleve os ombros o máximo que conseguir enquanto expira e mantenha a contração por um segundo. Dica: evite tentar levantar a barra usando os bíceps.\nVolte lentamente à posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado.',
  'Barbell Shrug Behind The Back':
    'Fique em pé, com a coluna reta e os pés na largura dos ombros, segurando uma barra com as duas mãos atrás das costas com pegada pronada (palmas voltadas para trás). Dica: suas mãos devem ficar um pouco mais afastadas que a largura dos ombros. Você pode usar munhequeiras ou straps para melhorar a pegada. Esta será sua posição inicial.\nEleve os ombros o máximo que conseguir enquanto expira e mantenha a contração por um segundo. Dica: evite tentar levantar a barra usando os bíceps. Os braços devem permanecer estendidos o tempo todo.\nVolte lentamente à posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado.',
  'Barbell Side Bend':
    'Fique em pé, com a coluna reta, segurando uma barra apoiada na parte de trás dos ombros (um pouco abaixo do pescoço). Os pés devem ficar na largura dos ombros. Esta será sua posição inicial.\nMantendo as costas retas e a cabeça erguida, incline-se para a direita apenas a partir da cintura o máximo que conseguir. Inspire enquanto se inclina para o lado. Depois segure por um segundo e volte à posição inicial enquanto expira. Dica: mantenha o resto do corpo parado.\nAgora repita o movimento inclinando-se para a esquerda. Segure por um segundo e volte à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Barbell Side Split Squat':
    'Fique em pé, com a coluna reta, segurando uma barra apoiada na parte de trás dos ombros (um pouco abaixo do pescoço). Mantenha os pés bem afastados, com o pé da perna que vai à frente apontado para o lado. Esta será sua posição inicial.\nAbaixe o corpo em direção ao lado do pé girado flexionando o joelho e o quadril da perna que guia o movimento, mantendo a outra perna apenas levemente flexionada. Inspire enquanto abaixa o corpo.\nVolte à posição inicial estendendo o quadril e o joelho da perna que guia o movimento. Expire enquanto realiza este movimento.\nApós realizar o número recomendado de repetições, repita o movimento com a perna oposta.',
  'Barbell Squat':
    'Este exercício é melhor realizado dentro de um rack de agachamento, por segurança. Para começar, posicione a barra no rack logo abaixo da altura dos ombros. Depois de escolher a altura correta e carregar a barra, entre embaixo dela e apoie-a na parte de trás dos ombros (um pouco abaixo do pescoço).\nSegure a barra com os dois braços ao lado do corpo e retire-a do rack empurrando primeiro com as pernas e, ao mesmo tempo, endireitando o tronco.\nAfaste-se do rack e posicione as pernas em uma base média, na largura dos ombros, com as pontas dos pés levemente voltadas para fora. Mantenha a cabeça erguida o tempo todo e a coluna reta. Esta será sua posição inicial. (Observação: para esta explicação usaremos a base média descrita, que trabalha o desenvolvimento geral; no entanto, você pode escolher qualquer uma das três bases de pés descritas na seção de posições dos pés).\nComece a abaixar a barra lentamente flexionando os joelhos e os quadris, mantendo a postura reta com a cabeça erguida. Continue descendo até que o ângulo entre a coxa e a panturrilha fique um pouco menor que 90 graus. Inspire durante esta parte do movimento. Dica: se você fez o exercício corretamente, a frente dos joelhos deve formar uma linha reta imaginária com as pontas dos pés, perpendicular à frente. Se os joelhos passarem dessa linha imaginária (se ultrapassarem as pontas dos pés), você está colocando estresse excessivo no joelho e o exercício foi feito de forma incorreta.\nComece a subir a barra enquanto expira, empurrando o chão com os calcanhares, e estenda as pernas novamente até voltar à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Barbell Squat To A Bench':
    'Este exercício é melhor realizado dentro de um rack de agachamento, por segurança. Para começar, coloque primeiro um banco reto ou uma caixa atrás de você. O banco reto serve para ensiná-lo a levar o quadril para trás e atingir a profundidade.\nEm seguida, posicione a barra no rack na altura que melhor se ajuste à sua estatura. Depois de escolher a altura correta e carregar a barra, entre embaixo dela e apoie-a na parte de trás dos ombros (um pouco abaixo do pescoço).\nSegure a barra com os dois braços ao lado do corpo e retire-a do rack empurrando primeiro com as pernas e, ao mesmo tempo, endireitando o tronco.\nAfaste-se do rack e posicione as pernas em uma base média, na largura dos ombros, com as pontas dos pés levemente voltadas para fora. Mantenha a cabeça erguida o tempo todo, pois olhar para baixo faz você perder o equilíbrio, e mantenha a coluna reta. Esta será sua posição inicial. (Observação: para esta explicação usaremos a base média descrita, que trabalha o desenvolvimento geral; no entanto, você pode escolher qualquer uma das três bases de pés descritas na seção de posições dos pés).\nComece a abaixar a barra lentamente flexionando os joelhos e levando o quadril para trás, mantendo a postura reta com a cabeça erguida. Continue descendo até tocar levemente o banco atrás de você. Inspire durante esta parte do movimento. Dica: se você fez o exercício corretamente, a frente dos joelhos deve formar uma linha reta imaginária com as pontas dos pés, perpendicular à frente. Se os joelhos passarem dessa linha imaginária (se ultrapassarem as pontas dos pés), você está colocando estresse excessivo no joelho e o exercício foi feito de forma incorreta.\nComece a subir a barra enquanto expira, empurrando o chão com os calcanhares, e estenda as pernas e os quadris para voltar à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Barbell Step Ups':
    'Fique em pé, com a coluna reta, segurando uma barra apoiada na parte de trás dos ombros (um pouco abaixo do pescoço), atrás de uma plataforma elevada (como a usada para dar apoio atrás de um banco reto). Esta é sua posição inicial.\nColoque o pé direito sobre a plataforma. Suba na plataforma estendendo o quadril e o joelho da perna direita. Use principalmente o calcanhar para elevar o restante do corpo e coloque também o pé esquerdo na plataforma. Expire enquanto faz a força necessária para subir.\nDesça com a perna esquerda flexionando o quadril e o joelho da perna direita enquanto inspira. Volte à posição original em pé colocando o pé direito ao lado do esquerdo, na posição inicial.\nRepita com a perna direita pelo número de repetições recomendado e depois realize com a perna esquerda.',
  'Barbell Walking Lunge':
    'Comece em pé, com os pés na largura dos ombros e uma barra apoiada na parte superior das costas.\nDê um passo à frente com uma perna, flexionando os joelhos para abaixar o quadril. Desça até que o joelho de trás quase toque o chão. Sua postura deve permanecer ereta e o joelho da frente deve ficar sobre o pé da frente.\nEmpurre com o calcanhar do pé da frente e estenda os dois joelhos para se levantar.\nDê um passo à frente com o pé de trás, repetindo o avanço com a perna oposta.',
  'Battling Ropes':
    'Para este exercício você precisará de uma corda pesada ancorada pelo centro a cerca de 5 a 6 metros (15-20 pés) de distância. Em pé, de frente para a corda, segure uma ponta em cada mão com os braços estendidos ao lado do corpo. Esta será sua posição inicial.\nInicie o movimento elevando rapidamente um braço até a altura do ombro, o mais rápido que puder.\nEnquanto deixa esse braço voltar à posição inicial, eleve o do lado oposto.\nContinue alternando os braços esquerdo e direito, chicoteando as cordas para cima e para baixo o mais rápido que puder.',
  'Bear Crawl Sled Drags':
    'Usando um arnês ou um cinto de peso folgado, prenda a corrente na parte de trás de modo que você fique de costas para o trenó. Agache-se de modo que as mãos fiquem no chão. Suas costas devem ficar retas e os joelhos flexionados. Esta é sua posição inicial.\nComece se impulsionando com as pernas, alternando esquerda e direita. Use as mãos para manter o equilíbrio e ajudar a puxar. Tente manter as costas retas enquanto avança uma determinada distância.',
  'Behind Head Chest Stretch':
    'Sente-se ereto no chão com seu parceiro atrás de você.\nColoque as mãos atrás da cabeça e leve os cotovelos para trás o máximo que puder. Seu parceiro deve segurar seus cotovelos. Esta será sua posição inicial.\nTente puxar suavemente os cotovelos para a frente, com as mãos ainda atrás da cabeça, por 10 segundos ou mais. Seu parceiro deve impedir que os cotovelos se movam.\nAgora relaxe os músculos e peça ao seu parceiro que puxe suavemente os cotovelos para trás até onde for confortável para você. Avise seu parceiro quando o alongamento estiver adequado, para evitar alongamento excessivo ou lesão.',
  'Bench Dips':
    'Para este exercício, você deve posicionar um banco atrás das costas. Com o banco perpendicular ao seu corpo e de costas para ele, segure a borda do banco com as mãos totalmente estendidas, separadas na largura dos ombros. As pernas ficam estendidas à frente, flexionadas na cintura e perpendiculares ao tronco. Esta será sua posição inicial.\nAbaixe o corpo lentamente enquanto inspira, flexionando os cotovelos até formar um ângulo um pouco menor que 90 graus entre o braço e o antebraço. Dica: mantenha os cotovelos o mais próximos possível durante todo o movimento. Os antebraços devem apontar sempre para baixo.\nUsando os tríceps para subir o tronco, empurre-se de volta à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Bench Jump':
    'Comece com uma caixa ou banco a 30-60 cm (1-2 pés) à sua frente. Fique em pé com os pés na largura dos ombros. Esta será sua posição inicial.\nFaça um agachamento curto como preparação para o salto; balance os braços para trás.\nReaja a partir dessa posição, estendendo quadris, joelhos e tornozelos para saltar o mais alto possível. Balance os braços para a frente e para cima.\nSalte sobre o banco, aterrissando com os joelhos flexionados e absorvendo o impacto com as pernas.\nVire-se para o lado oposto e depois salte de volta sobre o banco.',
  'Bench Press - Powerlifting':
    'Comece deitando-se no banco, posicionando a cabeça além da barra, se possível. Coloque os pés embaixo de você e arqueie as costas. Usando a barra para ajudar a sustentar seu peso, tire os ombros do banco e retraia-os, juntando as escápulas. Use os pés para cravar o trapézio no banco. Mantenha essa posição firme do corpo durante todo o movimento.\nSeja qual for a largura da sua pegada, ela deve cobrir a marcação em anel da barra. Retire a barra do rack sem protrair os ombros. Concentre-se em apertar a barra e tentar parti-la ao meio.\nAbaixe a barra até a parte inferior do peito ou a parte superior do abdômen. A barra, o punho e o cotovelo devem permanecer alinhados o tempo todo.\nFaça uma pausa quando a barra tocar o tronco e depois empurre a barra para cima com a maior força possível. Os cotovelos devem ficar junto ao corpo até a extensão completa.',
  'Bench Press - With Bands':
    'Usando um banco reto, prenda uma faixa elástica embaixo da perna do banco mais próxima da sua cabeça.\nDepois de prender bem a faixa, segure-a pelas duas alças e deite-se no banco.\nEstenda os braços de modo a segurar as alças da faixa à sua frente, na largura dos ombros.\nEstando na largura dos ombros, gire os punhos para a frente de modo que as palmas das mãos fiquem voltadas para longe de você. Esta será sua posição inicial.\nAbaixe as alças lentamente até que o cotovelo forme um ângulo de 90 graus. Mantenha o controle total o tempo todo.\nEnquanto expira, suba as alças usando os peitorais. Trave os braços na posição de contração, aperte o peito, segure por um segundo e depois comece a descer lentamente. Dica: a descida deve durar pelo menos o dobro do tempo da subida.\nRepita o movimento pelo número de repetições prescrito no seu programa de treino.',
  'Bench Press with Chains':
    'Ajuste a corrente guia, encurtando-a até o comprimento desejado. Coloque as correntes nas extremidades da barra.\nDeitado no banco, posicione a cabeça além da barra, se possível. Coloque os pés embaixo de você e arqueie as costas. Usando a barra para ajudar a sustentar seu peso, tire os ombros do banco e retraia-os, juntando as escápulas. Use os pés para cravar o trapézio no banco. Mantenha essa posição firme do corpo durante todo o movimento. Seja qual for a largura da sua pegada, ela deve cobrir a marcação em anel da barra.\nRetire a barra do rack sem protrair os ombros. Concentre-se em apertar a barra e tentar parti-la ao meio. Abaixe a barra até a parte inferior do peito ou a parte superior do abdômen. A barra, o punho e o cotovelo devem permanecer alinhados o tempo todo.\nFaça uma pausa quando a barra tocar o tronco e depois empurre a barra para cima com a maior força possível. Os cotovelos devem ficar junto ao corpo até a extensão completa.',
  'Bench Sprint':
    'Fique em pé no chão com um pé apoiado em um banco ou caixa, com o calcanhar próximo à borda.\nImpulsione-se com o pé que está em cima do banco, estendendo o quadril e o joelho.\nAterrisse com o pé oposto em cima da caixa, retornando o outro pé à posição inicial.\nContinue alternando um pé com o outro até completar a série.',
  'Bent Over Barbell Row':
    'Segurando uma barra com pegada pronada (palmas voltadas para baixo), flexione levemente os joelhos e incline o tronco para a frente a partir da cintura, mantendo as costas retas até ficarem quase paralelas ao chão. Dica: mantenha a cabeça erguida. A barra deve ficar pendurada bem à sua frente, com os braços perpendiculares ao chão e ao tronco. Esta é sua posição inicial.\nAgora, mantendo o tronco parado, expire e puxe a barra em direção ao corpo. Mantenha os cotovelos junto ao corpo e use apenas os antebraços para segurar o peso. Na posição superior de contração, aperte os músculos das costas e faça uma breve pausa.\nDepois inspire e abaixe lentamente a barra de volta à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Bent Over Dumbbell Rear Delt Raise With Head On Bench':
    'Fique em pé, com a coluna reta, segurando um halter em cada mão, com um banco inclinado à sua frente.\nMantendo as costas retas e a curvatura natural da coluna, incline-se para a frente até a testa tocar o banco à sua frente. Deixe os braços pendurados à sua frente, perpendiculares ao chão. As palmas das mãos devem ficar voltadas uma para a outra e o tronco deve ficar paralelo ao chão. Esta será sua posição inicial.\nMantendo o tronco inclinado e parado, e os braços retos com uma leve flexão nos cotovelos, levante os halteres diretamente para os lados até que os dois braços fiquem paralelos ao chão. Expire enquanto levanta os pesos. Cuidado: evite balançar o tronco ou levar os braços para trás em vez de para os lados.\nApós uma contração de um segundo no topo, abaixe lentamente os halteres de volta à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Bent Over Low-Pulley Side Lateral':
    'Selecione uma carga e segure o pegador da polia baixa com a mão direita.\nIncline-se a partir da cintura até que o tronco fique quase paralelo ao chão. As pernas devem ficar levemente flexionadas, com a mão esquerda apoiada na parte inferior da coxa esquerda. O braço direito deve ficar pendurado a partir do ombro à sua frente, com uma leve flexão no cotovelo. Esta será sua posição inicial.\nEleve o braço direito, com o cotovelo levemente flexionado, para o lado até que fique paralelo ao chão e alinhado com a orelha direita. Expire enquanto realiza este passo.\nAbaixe lentamente o peso de volta à posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado e depois repita o movimento com o outro braço.',
  'Bent Over One-Arm Long Bar Row':
    'Coloque peso em uma das extremidades de uma barra olímpica. Certifique-se de colocar a outra extremidade da barra no canto formado por duas paredes, ou de colocar um objeto pesado no chão para que a barra não deslize para trás.\nIncline-se para a frente até que o tronco fique o mais paralelo possível ao chão e mantenha os joelhos levemente flexionados.\nAgora segure a barra com um braço logo atrás dos anilhas, do lado em que o peso foi colocado, e apoie a outra mão no joelho. Esta será sua posição inicial.\nPuxe a barra diretamente para cima com o cotovelo junto ao corpo (para maximizar o estímulo nas costas) até que as anilhas toquem a parte inferior do peito. Aperte os músculos das costas enquanto levanta o peso e segure por um segundo no topo do movimento. Expire enquanto levanta o peso. Dica: não permita nenhum balanço do tronco. Somente o braço deve se mover.\nAbaixe lentamente a barra até a posição inicial, sentindo um bom alongamento nos dorsais. Dica: não deixe as anilhas tocarem o chão. Para garantir a melhor amplitude de movimento, recomendo usar anilhas pequenas (de 25 lb) em vez de anilhas maiores (como as de 35-45 lb).\nRepita pelo número de repetições recomendado e troque de braço.',
  'Bent Over Two-Arm Long Bar Row':
    'Coloque peso em uma das extremidades de uma barra olímpica. Certifique-se de colocar a outra extremidade da barra no canto formado por duas paredes, ou de colocar um objeto pesado no chão para que a barra não deslize para trás.\nIncline-se para a frente até que o tronco fique o mais paralelo possível ao chão e mantenha os joelhos levemente flexionados.\nAgora segure a barra com os dois braços logo atrás das anilhas, do lado em que o peso foi colocado, e apoie a outra mão no joelho. Esta será sua posição inicial.\nPuxe a barra diretamente para cima com os cotovelos junto ao corpo (para maximizar o estímulo nas costas) até que as anilhas toquem a parte inferior do peito. Aperte os músculos das costas enquanto levanta o peso e segure por um segundo no topo do movimento. Expire enquanto levanta o peso. Dica: use um acessório de estribo ou de pegada dupla de polia, encaixando-o embaixo da extremidade da barra.\nAbaixe lentamente a barra até a posição inicial, sentindo um bom alongamento nos dorsais. Dica: não deixe as anilhas tocarem o chão. Para garantir a melhor amplitude de movimento, recomendo usar anilhas pequenas (de 25 lb) em vez de anilhas maiores (como as de 35-45 lb).\nRepita pelo número de repetições recomendado.',
  'Bent Over Two-Dumbbell Row':
    'Com um halter em cada mão (palmas voltadas para o tronco), flexione levemente os joelhos e incline o tronco para a frente a partir da cintura; ao se inclinar, mantenha as costas retas até ficarem quase paralelas ao chão. Dica: mantenha a cabeça erguida. Os pesos devem ficar pendurados bem à sua frente, com os braços perpendiculares ao chão e ao tronco. Esta é sua posição inicial.\nMantendo o tronco parado, levante os halteres em direção às laterais do corpo (enquanto expira), mantendo os cotovelos junto ao corpo (não exerça força com o antebraço além de segurar os pesos). Na posição superior de contração, aperte os músculos das costas e segure por um segundo.\nAbaixe lentamente o peso de volta à posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado.',
  'Bent Over Two-Dumbbell Row With Palms In':
    'Com um halter em cada mão (palmas voltadas uma para a outra), flexione levemente os joelhos e incline o tronco para a frente a partir da cintura, mantendo as costas retas até ficarem quase paralelas ao chão. Dica: mantenha a cabeça erguida. Os pesos devem ficar pendurados bem à sua frente, com os braços perpendiculares ao chão e ao tronco. Esta é sua posição inicial.\nMantendo o tronco parado, levante os halteres em direção às laterais do corpo enquanto expira, juntando as escápulas. Na posição superior de contração, aperte os músculos das costas e segure por um segundo.\nAbaixe lentamente o peso de volta à posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado.',
  'Bent Press':
    'Leve um kettlebell até o ombro com um clean. Faça isso estendendo as pernas e os quadris enquanto eleva o kettlebell em direção ao ombro. O punho deve girar enquanto você faz isso. Esta será sua posição inicial.\nComece inclinando-se para o lado oposto ao kettlebell, até conseguir tocar o chão com a mão livre, mantendo os olhos no kettlebell. Ao fazer isso, empurre o peso na vertical estendendo o cotovelo, mantendo o braço perpendicular ao chão.\nVolte a uma posição ereta, com o kettlebell acima da cabeça. Leve o kettlebell de volta ao ombro e repita pelo número de repetições desejado.',
  'Bent-Arm Barbell Pullover':
    'Deite-se em um banco reto com uma barra, usando uma pegada na largura dos ombros.\nSegure a barra reta sobre o peito com os braços flexionados. Esta será sua posição inicial.\nMantendo os braços na posição flexionada, abaixe o peso lentamente em arco atrás da cabeça enquanto inspira, até sentir um alongamento no peito.\nNesse ponto, traga a barra de volta à posição inicial percorrendo o mesmo arco pelo qual o peso desceu e expire enquanto realiza este movimento.\nMantenha o peso na posição inicial por um segundo e repita o movimento pelo número de repetições prescrito.',
  'Bent-Arm Dumbbell Pullover':
    'Coloque um halter em pé sobre um banco reto.\nGarantindo que o halter fique bem posicionado na extremidade do banco, deite-se perpendicular ao banco (com o tronco atravessado formando uma cruz), com apenas os ombros apoiados na superfície. Os quadris devem ficar abaixo do banco e as pernas flexionadas com os pés firmes no chão. A cabeça também ficará fora do banco.\nSegure o halter com as duas mãos e mantenha-o reto sobre o peito com os braços flexionados. Ambas as palmas devem pressionar a parte inferior de um dos lados do halter. Esta será sua posição inicial. Cuidado: sempre se certifique de que o halter usado neste exercício esteja bem preso. Usar um halter com anilhas soltas pode fazer com que ele se desmonte e caia no seu rosto.\nMantendo os braços travados na posição flexionada, abaixe o peso lentamente em arco atrás da cabeça enquanto inspira, até sentir um alongamento no peito.\nNesse ponto, traga o halter de volta à posição inicial percorrendo o mesmo arco pelo qual o peso desceu e expire enquanto realiza este movimento.\nMantenha o peso na posição inicial por um segundo e repita o movimento pelo número de repetições prescrito.',
  'Bent-Knee Hip Raise':
    'Deite-se de costas no chão com os braços ao lado do corpo.\nAgora flexione os joelhos em um ângulo de cerca de 75 graus e levante os pés do chão cerca de 2 polegadas.\nUsando a parte inferior dos abdominais, traga os joelhos em direção a você mantendo o ângulo de 75 graus nas pernas. Continue esse movimento até elevar o quadril do chão girando a pelve para trás. Expire enquanto realiza esta parte do movimento. Dica: ao final do movimento, seus joelhos ficarão sobre o peito.\nAperte os abdominais no topo do movimento por um segundo e depois volte lentamente à posição inicial enquanto inspira. Dica: mantenha um movimento controlado o tempo todo.\nRepita pelo número de repetições recomendado.',
  Bicycling:
    'Para começar, sente-se na bicicleta e ajuste o selim à sua altura.',
  'Bicycling, Stationary':
    'Para começar, sente-se na bicicleta e ajuste o selim à sua altura.\nSelecione a opção desejada no menu. Talvez seja necessário começar a pedalar para ligá-la. Você pode usar o modo manual ou escolher um programa. Normalmente é possível informar sua idade e peso para estimar a quantidade de calorias queimadas durante o exercício. O nível de resistência pode ser alterado ao longo do treino. As manoplas podem ser usadas para monitorar sua frequência cardíaca e ajudar a manter uma intensidade adequada.',
  'Board Press':
    'Comece deitando-se no banco, posicionando a cabeça além da barra, se possível. De uma a cinco tábuas, feitas de 2x6, podem ser parafusadas juntas e seguradas por um parceiro de treino, por faixas elásticas, ou simplesmente colocadas por baixo da camiseta.\nColoque os pés embaixo de você e arqueie as costas. Usando a barra para ajudar a sustentar seu peso, tire os ombros do banco e retraia-os, juntando as escápulas. Use os pés para cravar o trapézio no banco. Mantenha essa posição firme do corpo durante todo o movimento.\nVocê pode usar uma pegada padrão de supino, ou na largura dos ombros para focar nos tríceps. Retire a barra do rack sem protrair os ombros. A barra, o punho e o cotovelo devem permanecer alinhados o tempo todo. Concentre-se em apertar a barra e tentar parti-la ao meio.\nAbaixe a barra até as tábuas e depois empurre a barra para cima com a maior força possível. Os cotovelos devem ficar junto ao corpo até a extensão completa.',
  'Body Tricep Press':
    'Posicione uma barra em um rack na altura do peito.\nEm pé, segure a barra com pegada na largura dos ombros e dê um ou dois passos para trás, com os pés juntos e os braços estendidos, de modo que você fique apoiado na barra. Esta será sua posição inicial.\nComece flexionando os cotovelos, abaixando o corpo em direção à barra.\nFaça uma pausa e depois inverta o movimento estendendo os cotovelos.\nProgrida a partir do peso corporal adicionando correntes sobre os ombros.',
  'Body-Up':
    'Assuma uma posição de prancha no chão. Você deve sustentar o peso do corpo sobre os dedos dos pés e os antebraços, mantendo o tronco reto. Os antebraços devem ficar separados na largura dos ombros. Esta será sua posição inicial.\nPressionando firmemente as palmas das mãos contra o chão, estenda os cotovelos para elevar o corpo do chão. Mantenha o tronco rígido enquanto realiza o movimento.\nAbaixe lentamente os antebraços de volta ao chão, permitindo que os cotovelos se flexionem.\nRepita.',
  'Bodyweight Flyes':
    'Coloque duas barras W igualmente carregadas no chão, uma ao lado da outra. Certifique-se de que elas consigam rolar.\nAssuma uma posição de flexão de braço sobre as barras, sustentando o peso nos dedos dos pés e nas mãos, com os braços estendidos e o corpo reto.\nColoque as mãos sobre as barras. Esta será sua posição inicial.\nCom um movimento lento e controlado, afaste as mãos da linha média do corpo, fazendo as barras rolarem para os lados. Inspire durante esta parte do movimento.\nDepois de afastar as barras o máximo que puder, volte à posição inicial puxando-as de volta para o centro. Expire enquanto realiza este movimento.',
  'Bodyweight Mid Row':
    'Comece segurando uma barra fixa com pegada média a larga e as palmas das mãos voltadas para longe de você. A partir da posição pendurada, leve os joelhos ao peito, inclinando-se para trás e passando as pernas pelo seu lado da barra fixa. Esta será sua posição inicial.\nComeçando com os braços retos, flexione os cotovelos e retraia as escápulas para elevar o corpo até que as pernas encostem na barra fixa.\nApós uma breve pausa, volte à posição inicial.',
  'Bodyweight Squat':
    'Fique em pé com os pés na largura dos ombros. Você pode colocar as mãos atrás da cabeça. Esta será sua posição inicial.\nComece o movimento flexionando os joelhos e os quadris, levando o quadril para trás.\nContinue descendo até a profundidade máxima, se conseguir, e inverta rapidamente o movimento até voltar à posição inicial. Enquanto agacha, mantenha a cabeça e o peito erguidos e empurre os joelhos para fora.',
  'Bodyweight Walking Lunge':
    'Comece em pé, com os pés na largura dos ombros e as mãos nos quadris.\nDê um passo à frente com uma perna, flexionando os joelhos para abaixar o quadril. Desça até que o joelho de trás quase toque o chão. Sua postura deve permanecer ereta e o joelho da frente deve ficar sobre o pé da frente.\nEmpurre com o calcanhar do pé da frente e estenda os dois joelhos para se levantar.\nDê um passo à frente com o pé de trás, repetindo o avanço com a perna oposta.',
  'Bosu Ball Cable Crunch With Side Bends':
    'Conecte um pegador padrão em cada braço de uma máquina de polia e posicione-os na posição mais baixa.\nPegue uma bola Bosu e posicione-a à frente e no centro da máquina de polia.\nDeite-se sobre a Bosu com a parte inferior das costas arqueada ao redor da bola. Seu bumbum deve ficar perto do chão, sem tocá-lo.\nCom as duas mãos, estenda os braços para trás e segure o pegador de cada cabo.\nCom os pés em uma base ampla, estenda os braços retos à sua frente e entre os joelhos. Suas mãos devem ficar na altura dos joelhos.\nMantenha os braços retos e alinhados com o ângulo ascendente do cabo. Eleve o tronco em um movimento de abdominal (crunch) sem deixar os braços caírem nem flexionarem.\nMantenha a posição rígida dos braços. Desça lentamente até a posição inicial com as costas arqueadas ao redor da Bosu e os abdominais alongados.\nRepita a mesma série de movimentos até a falha.\nAo chegar à falha, mantenha os abdominais contraídos e eleve o tronco até a posição de prancha, de modo que as costas fiquem fora da Bosu.\nAbaixe os braços ao lado do corpo, mantendo-os retos. Comece a fazer flexões laterais alternadas; tente alcançar os calcanhares! Este movimento final vai trabalhar os oblíquos.',
  'Bottoms Up':
    'Comece deitado de costas no chão. As pernas devem ficar retas e os braços ao lado do corpo. Esta será sua posição inicial.\nPara realizar o movimento, leve os joelhos em direção ao peito flexionando os quadris e os joelhos. Em seguida, estenda as pernas diretamente acima de você, de modo que fiquem perpendiculares ao chão. Rotacione e eleve a pelve para tirar os glúteos do chão.\nApós uma breve pausa, volte à posição inicial.',
  'Bottoms-Up Clean From The Hang Position':
    'Inicie o exercício em pé, ereto, com um kettlebell em uma das mãos.\nBalance o kettlebell para trás com força e depois inverta o movimento com força. Esmague a alça do kettlebell o mais forte que puder e eleve o kettlebell até o ombro.',
  'Box Jump (Multiple Response)':
    'Assuma uma postura relaxada de frente para a caixa ou plataforma, a aproximadamente um braço de distância. Os braços devem ficar abaixados ao lado do corpo e as pernas levemente flexionadas.\nUsando os braços para ajudar no impulso inicial, salte para cima e para a frente, aterrissando com os dois pés ao mesmo tempo sobre a caixa ou plataforma.\nImediatamente desça ou salte de volta ao ponto de partida original; depois repita a sequência.',
  'Box Skip':
    'Você precisará de várias caixas alinhadas a cerca de 2,5 metros (8 pés) de distância umas das outras.\nComece de frente para a primeira caixa com uma perna um pouco atrás da outra.\nImpulsione-se com a perna de trás, tentando ganhar o máximo de altura possível com o quadril.\nImediatamente ao aterrissar na caixa, impulsione a outra perna para a frente e para cima para ganhar altura e distância, saltando da caixa. Aterrisse entre as duas primeiras caixas com a mesma perna que aterrissou na primeira caixa.\nDepois, avance para a próxima caixa e repita.',
  'Box Squat':
    'O agachamento na caixa permite agachar até a profundidade desejada e desenvolver força explosiva no movimento do agachamento. Comece em um power rack com uma caixa na altura adequada atrás de você. Normalmente, busca-se uma altura de caixa que leve você a um agachamento paralelo, mas você pode treinar mais alto ou mais baixo, se quiser.\nComece entrando embaixo da barra e apoiando-a na parte de trás dos ombros. Junte as escápulas e gire os cotovelos para a frente, tentando envergar a barra sobre os ombros. Retire a barra do rack, criando um arco firme na lombar, e dê um passo para trás até ficar em posição. Posicione os pés mais afastados para dar mais ênfase às costas, glúteos, adutores e posteriores de coxa, ou mais próximos para maior desenvolvimento dos quadríceps. Mantenha a cabeça voltada para a frente.\nCom as costas, os ombros e o core firmes, empurre os joelhos e o bumbum para fora ao iniciar a descida. Leve o quadril para trás até ficar sentado na caixa. Idealmente, as canelas devem ficar perpendiculares ao chão. Faça uma pausa ao chegar na caixa e relaxe os flexores do quadril. Nunca quique na caixa.\nMantendo o peso nos calcanhares e empurrando os pés e os joelhos para fora, impulsione-se para cima saindo da caixa enquanto lidera o movimento com a cabeça. Continue subindo, mantendo a tensão da cabeça aos pés.',
  'Box Squat with Bands':
    'Comece em um power rack com uma caixa na altura adequada atrás de você. Prenda as faixas elásticas nas extremidades da barra, fixadas nos suportes para faixas, no rack ou em halteres, de modo a obter a tensão adequada. Se usar halteres, fixe-os para que não se movam. Além disso, certifique-se de que os halteres usados sejam pesados o suficiente para as faixas empregadas. Anilhas adicionais podem ser usadas para manter os halteres no lugar. Se precisar de mais tensão, você pode alargar a base no chão ou encurtar as faixas. Normalmente, busca-se uma altura de caixa que leve você a um agachamento paralelo, mas você pode treinar mais alto ou mais baixo, se quiser.\nComece entrando embaixo da barra e apoiando-a na parte de trás dos ombros. Junte as escápulas e gire os cotovelos para a frente, tentando envergar a barra sobre os ombros. Retire a barra do rack, criando um arco firme na lombar, e dê um passo para trás até ficar em posição. Posicione os pés mais afastados para dar mais ênfase às costas, glúteos, adutores e posteriores de coxa, ou mais próximos para maior desenvolvimento dos quadríceps. Mantenha a cabeça voltada para a frente.\nCom as costas, os ombros e o core firmes, empurre os joelhos e o bumbum para fora ao iniciar a descida. Leve o quadril para trás até ficar sentado na caixa. Idealmente, as canelas devem ficar perpendiculares ao chão. Faça uma pausa ao chegar na caixa e relaxe os flexores do quadril. Nunca quique na caixa.\nMantendo o peso nos calcanhares e empurrando os pés e os joelhos para fora, impulsione-se para cima saindo da caixa enquanto lidera o movimento com a cabeça. Continue subindo, mantendo a tensão da cabeça aos pés. Tome cuidado ao devolver a barra ao rack.',
  'Box Squat with Chains':
    'Comece em um power rack com uma caixa na altura adequada atrás de você. Normalmente, busca-se uma altura de caixa que leve você a um agachamento paralelo, mas você pode treinar mais alto ou mais baixo, se quiser.\nPara montar as correntes, comece passando a corrente guia sobre as extremidades da barra. A corrente pesada deve ser presa com um mosquetão. Ajuste o comprimento da corrente guia de modo que alguns elos ainda fiquem no chão no topo do movimento.\nComece entrando embaixo da barra e apoiando-a na parte de trás dos ombros. Junte as escápulas e gire os cotovelos para a frente, tentando envergar a barra sobre os ombros. Retire a barra do rack, criando um arco firme na lombar, e dê um passo para trás até ficar em posição. Posicione os pés mais afastados para dar mais ênfase às costas, glúteos, adutores e posteriores de coxa, ou mais próximos para maior desenvolvimento dos quadríceps. Mantenha a cabeça voltada para a frente.\nCom as costas, os ombros e o core firmes, empurre os joelhos e o bumbum para fora ao iniciar a descida. Leve o quadril para trás até ficar sentado na caixa. Idealmente, as canelas devem ficar perpendiculares ao chão. Faça uma pausa ao chegar na caixa e relaxe os flexores do quadril. Nunca quique na caixa.\nMantendo o peso nos calcanhares e empurrando os pés e os joelhos para fora, impulsione-se para cima saindo da caixa enquanto lidera o movimento com a cabeça. Continue subindo, mantendo a tensão da cabeça aos pés.',
  'Brachialis-SMR':
    'Deite-se de lado, com a parte superior do braço contra o rolo de espuma. O braço deve ficar mais ou menos alinhado com o corpo, com a parte externa do bíceps pressionada contra o rolo de espuma.\nEleve o quadril do chão, sustentando o peso no braço e nos pés. Mantenha por 10 a 30 segundos e depois troque de lado.',
  'Bradford/Rocky Presses':
    'Sente-se em um banco de desenvolvimento militar com uma barra na altura dos ombros, com pegada pronada (palmas voltadas para a frente). Dica: sua pegada deve ser mais larga que os ombros e deve formar um ângulo de 90 graus entre o antebraço e o braço quando a barra desce. Esta é sua posição inicial.\nDepois de pegar a barra com a pegada correta, levante-a acima da cabeça estendendo os braços.\nAgora abaixe a barra lentamente até atrás da cabeça enquanto inspira.\nLevante a barra de volta à posição inicial enquanto expira.\nAbaixe a barra lentamente até a posição inicial enquanto inspira. Isto é uma repetição.\nAlterne dessa maneira até completar o número de repetições recomendado.',
  'Butt Lift (Bridge)':
    'Deite-se de costas no chão com as mãos ao lado do corpo e os joelhos flexionados. Os pés devem ficar separados aproximadamente na largura dos ombros. Esta será sua posição inicial.\nEmpurrando principalmente com os calcanhares, eleve o quadril do chão mantendo as costas retas. Expire enquanto realiza esta parte do movimento e segure no topo por um segundo.\nVolte lentamente à posição inicial enquanto inspira.',
  'Butt-Ups':
    'Comece em uma posição de flexão de braço, mas com os cotovelos no chão, apoiado sobre os antebraços. Seus braços devem ficar flexionados em um ângulo de 90 graus.\nArqueie levemente as costas para cima em vez de mantê-las completamente retas.\nEleve os glúteos em direção ao teto, contraindo firmemente os abdominais para diminuir a distância entre a caixa torácica e o quadril. O resultado final será você ficar em uma posição de ponte alta. Expire enquanto realiza esta parte do movimento.\nAbaixe lentamente de volta à posição inicial enquanto inspira. Dica: não deixe as costas cederem para baixo.\nRepita pelo número de repetições recomendado.',
  Butterfly:
    'Sente-se na máquina com as costas retas encostadas no apoio.\nSegure as manoplas. Dica: a parte superior dos braços deve ficar paralela ao chão; ajuste a máquina de acordo. Esta será sua posição inicial.\nJunte as manoplas lentamente enquanto aperta o peito no centro. Expire durante esta parte do movimento e segure a contração por um segundo.\nVolte lentamente à posição inicial enquanto inspira, até que os músculos do peito estejam totalmente alongados.\nRepita pelo número de repetições recomendado.',
  'Cable Chest Press':
    'Ajuste a carga para um valor adequado e sente-se, segurando as manoplas. A parte superior dos braços deve formar cerca de 45 graus com o corpo, com a cabeça e o peito erguidos. Os cotovelos devem estar flexionados a cerca de 90 graus. Esta será sua posição inicial.\nComece estendendo os cotovelos, empurrando as manoplas juntas diretamente à sua frente. Mantenha as escápulas retraídas enquanto executa o movimento.\nApós uma pausa na extensão completa, volte à posição inicial, mantendo a tensão nos cabos.\nVocê também pode executar este movimento com as costas afastadas do apoio, em inclinação ou declinação, ou alternando as mãos.',
  'Cable Crossover':
    'Para assumir a posição inicial, coloque as polias na posição alta (acima da cabeça), selecione a resistência que será usada e segure as manoplas, uma em cada mão.\nDê um passo à frente, ficando à frente de uma linha reta imaginária entre as duas polias, enquanto junta os braços à sua frente. Seu tronco deve ter uma leve inclinação para a frente a partir da cintura. Esta será sua posição inicial.\nCom uma leve flexão dos cotovelos para evitar tensão no tendão do bíceps, estenda os braços para os lados (retos para fora, dos dois lados) em um arco amplo até sentir um alongamento no peitoral. Inspire enquanto realiza esta parte do movimento. Dica: Lembre-se de que, durante todo o movimento, os braços e o tronco devem permanecer parados; o movimento deve ocorrer apenas na articulação do ombro.\nRetorne os braços à posição inicial enquanto expira. Certifique-se de usar o mesmo arco de movimento usado para baixar os pesos.\nSegure por um segundo na posição inicial e repita o movimento pelo número de repetições prescrito.',
  'Cable Crunch':
    'Ajoelhe-se debaixo de uma polia alta com uma corda.\nSegure a corda e abaixe-a até que suas mãos fiquem ao lado do rosto.\nFlexione levemente os quadris e deixe o peso hiperestender a região lombar. Esta será sua posição inicial.\nCom os quadris parados, flexione a cintura enquanto contrai os abdominais, de modo que os cotovelos se movam em direção ao meio das coxas. Expire enquanto realiza esta parte do movimento e segure a contração por um segundo.\nRetorne lentamente à posição inicial enquanto inspira. Dica: Certifique-se de manter tensão constante nos abdominais durante todo o movimento. Além disso, não escolha uma carga tão pesada que a lombar faça a maior parte do trabalho.\nRepita pelo número de repetições recomendado.',
  'Cable Deadlifts':
    'Mova os cabos para a parte inferior das torres e selecione uma carga adequada. Fique em pé exatamente entre os suportes verticais.\nPara começar, agache flexionando quadris e joelhos até alcançar as manoplas.\nDepois de segurá-las, comece a subir. Empurrando pelos calcanhares, estenda quadris e joelhos mantendo as mãos penduradas ao lado do corpo. Mantenha a cabeça e o peito erguidos durante todo o movimento.\nDepois de chegar à posição em pé completa, retorne à posição inicial e repita.',
  'Cable Hammer Curls - Rope Attachment':
    'Prenda uma corda em uma polia baixa e fique de frente para a máquina, a cerca de 30 cm de distância.\nSegure a corda com pegada neutra (palmas voltadas para dentro) e fique em pé, ereto, mantendo a curvatura natural da coluna e o tronco parado.\nEncoste os cotovelos ao lado do corpo e mantenha-os parados durante todo o movimento. Dica: Apenas os antebraços devem se mover; não a parte superior dos braços. Esta será sua posição inicial.\nUsando os bíceps, puxe os braços para cima enquanto expira, até que os bíceps toquem os antebraços. Dica: Lembre-se de manter os cotovelos junto ao corpo e a parte superior dos braços parada.\nApós uma contração de 1 segundo, apertando os bíceps, comece a levar a carga lentamente de volta à posição original.\nRepita pelo número de repetições recomendado.',
  'Cable Hip Adduction':
    'Fique em pé de frente para uma polia baixa, olhando para a frente, com uma perna ao lado da polia e a outra afastada.\nPrenda a tornozeleira ao cabo e também ao tornozelo da perna que está ao lado da polia.\nAgora dê um passo para fora, afastando-se do peso, com uma base ampla, e segure a barra do sistema de polias.\nApoie-se no pé que não tem a tornozeleira (o pé distante) e deixe a perna com a tornozeleira ser puxada em direção à polia baixa. Esta será sua posição inicial.\nAgora realize o movimento levando a perna com a tornozeleira à frente da perna distante, usando a parte interna das coxas para aduzir o quadril. Expire durante esta parte do movimento.\nRetorne lentamente à posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado e depois faça o mesmo movimento com a perna oposta.',
  'Cable Incline Pushdown':
    'Deite-se em um banco inclinado de costas para uma máquina de polia alta com uma barra reta.\nSegure a barra reta acima da cabeça com pegada pronada (por cima; palmas para baixo) na largura dos ombros e estenda os braços à sua frente. A barra deve ficar a cerca de 5 cm da parte superior das coxas. Esta será sua posição inicial.\nMantendo a parte superior dos braços parada, leve os braços para trás em um semicírculo até que a barra fique bem acima da cabeça. Inspire durante esta parte do movimento.\nRetorne lentamente à posição inicial usando os dorsais e segure a contração ao chegar à posição inicial. Expire durante a execução deste movimento.\nRepita pelo número de repetições recomendado.',
  'Cable Incline Triceps Extension':
    'Deite-se em um banco inclinado de costas para uma máquina de polia alta com uma barra reta.\nSegure a barra reta acima da cabeça com pegada pronada (por cima; palmas para baixo) fechada (menor que a largura dos ombros) e mantenha os cotovelos junto ao corpo. A parte superior dos braços deve formar um ângulo de cerca de 25 graus medido a partir do chão.\nMantendo a parte superior dos braços parada, estenda os braços enquanto contrai os tríceps. Expire durante esta parte do movimento e segure a contração por um segundo.\nRetorne lentamente à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Cable Internal Rotation':
    'Sente-se de lado ao lado de uma polia baixa (com as pernas esticadas à frente ou cruzadas) e segure a manopla simples com o braço mais próximo do cabo. Dica: Se puder ajustar a altura da polia, você pode se sentar em um banco reto.\nPosicione o cotovelo junto ao corpo, flexionado a 90° e com o braço apontando para a polia. Esta será sua posição inicial.\nPuxe a manopla em direção ao corpo rotacionando internamente o ombro até que o antebraço fique cruzado sobre os abdominais. Você desenhará um semicírculo imaginário. Dica: O antebraço deve permanecer perpendicular ao tronco o tempo todo.\nRetorne lentamente à posição inicial.\nRepita pelo número de repetições recomendado e depois repita o movimento com o outro braço.',
  'Cable Iron Cross':
    'Comece movendo as polias para a posição alta, selecione a resistência que será usada e segure uma manopla em cada mão.\nFique em pé exatamente entre as duas polias com os braços estendidos para os lados. A cabeça e o peito devem estar erguidos e seus braços formando um "T". Esta será sua posição inicial.\nMantendo os cotovelos estendidos, puxe os braços retos para os lados.\nRetorne os braços à posição inicial após uma pausa na contração máxima.\nContinue o movimento pelo número de repetições prescrito.',
  'Cable Judo Flip':
    'Conecte uma corda a uma torre e mova o cabo para a posição de polia mais baixa. Fique de lado para o cabo com uma base ampla e segure a corda com as duas mãos.\nGire o corpo para longe da polia enquanto leva a corda por cima do ombro, como se estivesse executando uma projeção de judô.\nTransfira o peso entre os pés enquanto gira e faz um abdominal para a frente, puxando o cabo para baixo.\nRetorne à posição inicial e repita até a falha.\nDepois, reposicione-se e repita a mesma série de movimentos do lado oposto.',
  'Cable Lying Triceps Extension':
    'Deite-se em um banco reto e segure a barra reta de uma polia baixa com pegada pronada fechada. Dica: A maneira mais fácil é pedir que alguém lhe entregue a barra enquanto você se deita.\nCom os braços estendidos, posicione a barra sobre o tronco. Seus braços e seu tronco devem formar um ângulo de 90 graus. Esta será sua posição inicial.\nAbaixe a barra flexionando os cotovelos, mantendo a parte superior dos braços parada e os cotovelos junto ao corpo. Desça até que a barra toque de leve a testa. Inspire enquanto realiza esta parte do movimento.\nContraia os tríceps enquanto levanta a barra de volta à posição inicial. Expire enquanto realiza esta parte do movimento.\nSegure por um segundo na posição contraída e repita pelo número de repetições recomendado.',
  'Cable One Arm Tricep Extension':
    'Com a mão direita, segure uma manopla simples presa à polia alta com pegada supinada (por baixo; palmas voltadas para cima). Você deve estar em pé bem em frente ao peso.\nAgora puxe a manopla para baixo de modo que a parte superior do braço e o cotovelo fiquem fixos junto ao lado do corpo. O braço e o antebraço devem formar um ângulo agudo (menos de 90 graus). Você pode manter o outro braço na cintura e colocar uma perna à frente e a outra atrás para maior equilíbrio. Esta será sua posição inicial.\nEnquanto contrai o tríceps, mova a manopla para baixo, ao lado do corpo, até que o braço fique reto. Expire enquanto realiza este movimento. Dica: Apenas os antebraços devem se mover. A parte superior dos braços deve permanecer parada o tempo todo.\nAperte o tríceps e segure por um segundo nesta posição contraída.\nRetorne lentamente a manopla à posição inicial.\nRepita pelo número de repetições recomendado e depois faça o mesmo movimento com o outro braço.',
  'Cable Preacher Curl':
    'Posicione um banco Scott a cerca de 60 cm à frente de uma máquina de polia.\nPrenda uma barra reta à polia baixa.\nSente-se no banco Scott com o cotovelo e a parte superior dos braços firmemente apoiados no estofado do banco e peça a alguém que lhe entregue a barra da polia baixa.\nSegure a barra e estenda completamente os braços sobre o estofado do banco Scott. Esta será sua posição inicial.\nAgora comece a puxar o peso em direção aos ombros e aperte forte os bíceps no topo do movimento. Expire enquanto realiza este movimento. Além disso, segure por um segundo no topo.\nAgora abaixe lentamente o peso até a posição inicial.\nRepita pelo número de repetições recomendado.',
  'Cable Rear Delt Fly':
    'Ajuste as polias na altura adequada e ajuste a carga. As polias devem ficar acima da cabeça.\nSegure a polia esquerda com a mão direita e a polia direita com a mão esquerda, cruzando-as à sua frente. Esta será sua posição inicial.\nInicie o movimento levando os braços para trás e para fora, mantendo-os retos durante a execução.\nFaça uma pausa no final do movimento antes de retornar as manoplas à posição inicial.',
  'Cable Reverse Crunch':
    'Conecte uma tornozeleira a um cabo de polia baixa e posicione um colchonete no chão à sua frente.\nSente-se com os pés voltados para a polia e prenda o cabo aos tornozelos.\nDeite-se, eleve as pernas e flexione os joelhos em um ângulo de 90 graus. Suas pernas e o cabo devem estar alinhados. Se não estiverem, ajuste a polia para cima ou para baixo até que estejam.\nCom as mãos atrás da cabeça, leve os joelhos em direção ao tronco e eleve o quadril do chão.\nFaça uma pausa por um momento e, de forma lenta e controlada, abaixe o quadril e retorne as pernas ao ângulo inicial de 90 graus. Você ainda deve sentir tensão nos abdominais na posição de repouso.\nRepita o mesmo movimento até a falha.',
  'Cable Rope Overhead Triceps Extension':
    'Prenda uma corda à polia inferior da máquina de polias.\nSegurando a corda com as duas mãos, estenda os braços com as mãos diretamente acima da cabeça usando pegada neutra (palmas voltadas uma para a outra). Seus cotovelos devem ficar próximos da cabeça e os braços perpendiculares ao chão, com os nós dos dedos apontando para o teto. Esta será sua posição inicial.\nAbaixe lentamente a corda atrás da cabeça enquanto mantém a parte superior dos braços parada. Inspire enquanto realiza este movimento e faça uma pausa quando os tríceps estiverem completamente alongados.\nRetorne à posição inicial contraindo os tríceps enquanto expira.\nRepita pelo número de repetições recomendado.',
  'Cable Rope Rear-Delt Rows':
    'Sente-se na mesma posição em uma estação de remada com polia baixa, como faria na remada sentada no cabo para as costas.\nPrenda uma corda à polia e segure-a com pegada pronada. Seus braços devem estar estendidos e paralelos ao chão, com os cotovelos abertos para fora.\nMantenha a lombar ereta e deslize o quadril para trás de modo que os joelhos fiquem levemente flexionados. Esta será sua posição inicial.\nPuxe o acessório do cabo em direção à parte superior do peito, logo abaixo do pescoço, mantendo os cotovelos elevados e para os lados. Continue esse movimento enquanto expira até que os cotovelos passem levemente por trás das costas. Dica: Mantenha a parte superior dos braços na horizontal, perpendicular ao tronco e paralela ao chão durante todo o movimento.\nRetorne à posição inicial, com os braços estendidos e os ombros alongados para a frente. Inspire enquanto realiza esta parte do movimento.\nRepita pelo número de repetições recomendado.',
  'Cable Russian Twists':
    'Conecte uma manopla padrão e posicione o cabo em uma altura média da polia.\nDeite-se sobre uma bola de estabilidade perpendicular ao cabo e segure a manopla com uma mão. Você deve estar aproximadamente à distância de um braço da polia, com a tensão da carga no cabo.\nSegure a manopla com as duas mãos e estenda completamente os braços acima do peito. Suas mãos devem estar alinhadas com a polia. Se não estiverem, ajuste a polia para cima ou para baixo até que estejam.\nMantenha o quadril elevado e os abdominais contraídos. Gire o tronco para longe da polia em um quarto de volta completo. Seu corpo deve ficar reto da cabeça aos joelhos.\nFaça uma pausa por um momento e, de forma lenta e controlada, retorne à posição inicial. Você ainda deve sentir tensão lateral no cabo na posição de repouso.\nRepita o mesmo movimento até a falha.\nDepois, reposicione-se e repita a mesma série de movimentos do lado oposto.',
  'Cable Seated Crunch':
    'Sente-se em um banco reto de costas para uma polia alta.\nSegure a corda com as duas mãos (com as palmas voltadas uma para a outra) e posicione as mãos firmemente sobre os ombros. Dica: Deixe o peso hiperestender levemente a região lombar. Esta será sua posição inicial.\nCom os quadris parados, flexione a cintura de modo que os cotovelos se movam em direção aos quadris. Expire enquanto realiza este passo.\nAo inspirar, retorne lentamente à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Cable Seated Lateral Raise':
    'Fique em pé no meio de duas polias baixas opostas entre si e coloque um banco reto logo atrás de você (perpendicular a você; a extremidade estreita do banco deve ser a que fica atrás de você). Selecione a carga a ser usada em cada polia.\nAgora sente-se na beira do banco reto atrás de você, com os pés posicionados à frente dos joelhos.\nIncline-se para a frente mantendo as costas retas e apoie o tronco sobre as coxas.\nPeça a alguém que lhe entregue as manoplas simples presas às polias. Segure a polia esquerda com a mão direita e a polia direita com a mão esquerda depois de selecionar a carga. Os cabos devem passar por baixo dos joelhos e seus braços ficarão estendidos, com as palmas voltadas uma para a outra e uma leve flexão nos cotovelos. Esta será a posição inicial.\nMantendo os braços parados, eleve a parte superior dos braços para os lados até que fiquem paralelos ao chão, na altura dos ombros. Expire durante a execução deste movimento e segure a contração por um segundo.\nAbaixe lentamente os braços até a posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado. Dica: Mantenha a parte superior dos braços perpendicular ao tronco e uma posição fixa dos cotovelos (ângulo de 10 a 30 graus) durante todo o exercício.',
  'Cable Shoulder Press':
    'Mova os cabos para a parte inferior das torres e selecione uma carga adequada.\nFique em pé exatamente entre os suportes verticais. Segure os cabos e mantenha-os na altura dos ombros, com as palmas voltadas para a frente. Esta será sua posição inicial.\nMantendo a cabeça e o peito erguidos, estenda os cotovelos para empurrar as manoplas diretamente acima da cabeça.\nApós uma pausa no topo, retorne à posição inicial e repita.',
  'Cable Shrugs':
    'Segure uma barra presa a uma polia baixa com pegada pronada (palmas para baixo) na largura dos ombros ou ligeiramente mais aberta.\nFique em pé, ereto, perto da polia, com os braços estendidos à sua frente segurando a barra. Esta será sua posição inicial.\nLevante a barra elevando os ombros o mais alto possível enquanto expira. Segure a contração no topo por um segundo. Dica: Os braços devem permanecer estendidos o tempo todo. Evite usar os bíceps para ajudar a levantar a barra. Apenas os ombros devem subir e descer.\nAbaixe a barra de volta à posição original.\nRepita pelo número de repetições recomendado.',
  'Cable Wrist Curl':
    'Comece posicionando um banco reto à frente de uma polia baixa com uma barra reta.\nUse os braços para segurar a barra do cabo com pegada supinada (palmas para cima), fechada até a largura dos ombros, e leve-os para cima de modo que os antebraços fiquem apoiados na parte superior das coxas. Seus punhos devem ficar pendurados logo além dos joelhos.\nComece flexionando os punhos para cima enquanto expira. Segure a contração por um segundo.\nAbaixe lentamente os punhos de volta à posição inicial enquanto inspira.\nSeus antebraços devem permanecer parados, pois o punho é o único movimento necessário para realizar este exercício.\nRepita pelo número de repetições recomendado.',
  'Calf Press':
    'Ajuste o assento de modo que suas pernas fiquem apenas levemente flexionadas na posição inicial. A parte da frente dos pés deve estar firme na plataforma.\nSelecione uma carga adequada e segure as manoplas. Esta será sua posição inicial.\nEstenda as pernas esticando os joelhos, levantando apenas de leve a carga do peso. Seu tornozelo deve estar totalmente flexionado, com os dedos apontando para cima. Execute o movimento empurrando para baixo com a parte da frente dos pés o máximo possível.\nApós uma breve pausa, inverta o movimento e repita.',
  'Calf Press On The Leg Press Machine':
    'Usando uma máquina de leg press, sente-se na máquina e coloque os pés na plataforma diretamente à sua frente, com uma base média (na largura dos ombros).\nAbaixe as barras de segurança que seguram a plataforma com carga e empurre a plataforma até o alto, até que as pernas fiquem totalmente estendidas à sua frente sem travar os joelhos. (Nota: Em alguns leg presses você pode deixar as barras de segurança acionadas para maior segurança. Se o seu aparelho permitir, esse é o método preferido para realizar o exercício.) Seu tronco e suas pernas devem formar um ângulo perfeito de 90 graus. Agora posicione com cuidado os dedos e a parte da frente dos pés na parte inferior da plataforma, com os calcanhares para fora. Os dedos devem apontar para a frente, para fora ou para dentro, conforme descrito no início do capítulo. Esta será sua posição inicial.\nEmpurre a plataforma elevando os calcanhares enquanto expira, estendendo os tornozelos o mais alto possível e contraindo a panturrilha. Certifique-se de manter o joelho parado o tempo todo. Não deve haver flexão em nenhum momento. Segure a posição contraída por um segundo antes de começar a descer.\nRetorne lentamente à posição inicial enquanto inspira, abaixando os calcanhares e flexionando os tornozelos até que as panturrilhas estejam alongadas.\nRepita pelo número de repetições recomendado.',
  'Calf Raise On A Dumbbell':
    'Segure-se em um objeto firme para manter o equilíbrio e fique em pé sobre o cabo de um halter, de preferência um com anilhas redondas para que ele role; assim você terá que se esforçar mais para se estabilizar, aumentando a eficácia do exercício.\nAgora role o pé levemente para a frente para conseguir um bom alongamento da panturrilha. Esta será sua posição inicial.\nEleve a panturrilha enquanto rola o pé sobre a parte superior do cabo para obter uma extensão completa. Expire durante a execução deste movimento. Contraia forte a panturrilha no topo e segure por um segundo. Dica: Ao subir, role o halter levemente para trás.\nAgora inspire enquanto rola o halter levemente para a frente ao descer, para obter um melhor alongamento.\nRepita pelo número de repetições recomendado.',
  'Calf Raises - With Bands':
    'Pegue uma faixa elástica e pise nela com a parte da frente dos pés, certificando-se de que o comprimento da faixa entre o pé e os braços seja o mesmo dos dois lados.\nSegurando as alças da faixa, eleve os braços ao lado da cabeça como se estivesse se preparando para fazer um desenvolvimento de ombros. As palmas devem ficar voltadas para a frente, com os cotovelos flexionados e para os lados. Esse movimento criará tensão na faixa. Esta será sua posição inicial.\nMantendo as mãos junto aos ombros, suba na ponta dos pés enquanto expira e contraia forte as panturrilhas no topo do movimento.\nApós uma contração de um segundo, desça lentamente até a posição inicial.\nRepita pelo número de repetições recomendado.',
  'Calf Stretch Elbows Against Wall':
    'Fique em pé de frente para uma parede, a cerca de meio metro de distância.\nIncline-se contra a parede, apoiando o peso nos antebraços.\nTente manter os calcanhares no chão. Segure por 10 a 20 segundos. Você pode se afastar ou se aproximar da parede para tornar o exercício mais ou menos difícil, respectivamente.',
  'Calf Stretch Hands Against Wall':
    'Fique em pé de frente para uma parede, a cerca de um metro ou mais de distância. Escalone a base, colocando um pé à frente.\nIncline-se para a frente e apoie as mãos na parede, mantendo o calcanhar, o quadril e a cabeça em linha reta.\nTente manter o calcanhar no chão. Segure por 10 a 20 segundos e depois troque de lado.',
  'Calf-Machine Shoulder Shrug':
    'Posicione-se na máquina de panturrilha de modo que as almofadas fiquem sobre os ombros. Seu tronco deve estar reto, com os braços estendidos naturalmente ao lado do corpo. Esta será sua posição inicial.\nEleve os ombros em direção às orelhas enquanto expira e segure a contração por um segundo completo.\nRetorne lentamente à posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado.',
  'Calves-SMR':
    'Comece sentado no chão. Coloque um rolo de espuma debaixo da parte inferior da perna. A outra perna pode ficar cruzada sobre a oposta ou apoiada no chão, sustentando parte do seu peso. Esta será sua posição inicial.\nColoque as mãos ao lado do corpo ou um pouco atrás de você e empurre para elevar o quadril do chão, apoiando grande parte do peso contra a panturrilha. Role de baixo do joelho até acima do tornozelo, fazendo pausas nos pontos de tensão por 10 a 30 segundos. Repita com a outra perna.',
  'Car Deadlift':
    'Este aparelho de competição normalmente tem manoplas de pegada neutra, embora alguns tenham uma barra reta que você pode abordar como em um levantamento terra normal. O aparelho pode ser carregado com um veículo ou outros objetos pesados, como pneus de trator ou barris.\nCentralize-se entre as manoplas se você for forte no agachamento, ou recue alguns centímetros se for forte no levantamento terra. Seus pés devem ficar afastados aproximadamente na largura do quadril. Flexione o quadril para segurar as manoplas. Com os pés e a pegada firmes, inspire fundo e depois abaixe o quadril e flexione os joelhos.\nOlhe para a frente, mantenha o peito erguido e as costas arqueadas, e comece a empurrar pelos calcanhares para levantar a carga. À medida que a carga sobe, junte as escápulas enquanto leva o quadril para a frente.\nAbaixe a carga flexionando o quadril e guiando-a até o chão.',
  'Car Drivers':
    'Em pé e ereto, segure um disco de barra com as duas mãos nas posições de 3 e 9 horas. As palmas devem ficar voltadas uma para a outra e os braços estendidos retos à sua frente. Esta será sua posição inicial.\nInicie o movimento girando o disco o máximo possível para um lado. Use o mesmo tipo de movimento que usaria para girar um volante para um lado.\nInverta o movimento, girando-o completamente para o lado oposto.\nRepita pelo número de repetições recomendado.',
  'Carioca Quick Step':
    'Comece com os pés afastados alguns centímetros e o braço esquerdo elevado, em uma posição atlética e relaxada.\nCom o pé direito, dê um passo rápido por trás e eleve o joelho.\nLance os braços para cima quando elevar o joelho direito, certificando-se de que o joelho suba e desça em linha reta. Evite girar os pés enquanto se move e continue olhando para a frente enquanto se desloca para o lado.',
  'Cat Stretch':
    'Posicione-se no chão de quatro apoios, sobre as mãos e os joelhos.\nContraia a barriga e arredonde a coluna, a lombar, os ombros e o pescoço, deixando a cabeça cair.\nSegure por 15 segundos.',
  'Catch and Overhead Throw':
    'Comece em pé de frente para uma parede ou um parceiro.\nCom as duas mãos, posicione a bola atrás da cabeça, alongando-se o máximo possível, e arremesse a bola para a frente com força.\nCertifique-se de completar o movimento após o arremesso, preparando-se para receber o rebote. Se estiver arremessando contra a parede, fique perto o suficiente para receber o rebote e mire um pouco mais alto do que faria com um parceiro.',
  'Chain Handle Extension':
    'Você precisará de duas manoplas de cabo, um banco reto e correntes para este exercício. Prenda o meio das correntes às manoplas e posicione-se no banco reto. Seus cotovelos devem apontar retos para cima.\nComece estendendo os cotovelos, mantendo a parte superior do braço parada, com os punhos em pronação.\nFaça uma pausa na extensão completa e inverta o movimento para retornar à posição inicial.',
  'Chain Press':
    'Comece conectando as correntes às manoplas de cabo. Posicione-se no banco reto na mesma posição de um supino com halteres. Seus punhos devem estar em pronação e os braços perpendiculares ao chão. Esta será sua posição inicial.\nAbaixe as correntes flexionando os cotovelos, deixando parte da corrente apoiada no chão.\nContinue até que o cotovelo forme um ângulo de 90 graus e depois inverta o movimento estendendo os cotovelos até a extensão completa.',
  'Chair Leg Extended Stretch':
    'Sente-se ereto em uma cadeira e segure o assento pelas laterais.\nLevante uma perna, estendendo o joelho e flexionando o tornozelo ao fazer isso.\nMova lentamente essa perna para o lado o máximo que puder, depois de volta ao centro e para baixo.\nRepita com a outra perna.',
  'Chair Lower Back Stretch':
    'Sente-se ereto em uma cadeira.\nIncline-se para um lado com o braço acima da cabeça. Você pode se segurar na cadeira com a mão livre.\nSegure por 10 segundos e repita para o outro lado.',
  'Chair Squat':
    'Para começar, primeiro ajuste a barra em uma posição adequada à sua altura. Com a barra carregada, entre debaixo dela e posicione-a sobre a parte de trás dos ombros.\nSegure a barra com as mãos voltadas para a frente, destrave-a e tire-a do rack estendendo as pernas.\nMova os pés cerca de 45 cm à frente da barra. Posicione as pernas com uma base na largura dos ombros e os pés levemente voltados para fora. Olhe para a frente o tempo todo e mantenha a coluna neutra ou levemente arqueada. Esta será sua posição inicial.\nAbaixe lentamente a barra flexionando os joelhos, mantendo uma postura ereta com a cabeça erguida. Continue descendo até que o ângulo entre a parte superior e a inferior da perna passe de 90 graus.\nComece a subir a barra enquanto expira, empurrando o chão com os calcanhares, estendendo os joelhos e retornando à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Chair Upper Body Stretch':
    'Sente-se na beira de uma cadeira, segurando o encosto.\nEstique os braços, mantendo as costas retas, e puxe a parte superior do corpo para a frente até sentir um alongamento. Segure por 20 a 30 segundos.',
  'Chest And Front Of Shoulder Stretch':
    'Comece em pé com as pernas juntas, segurando uma barra leve ou um cabo de vassoura.\nSegure o bastão com uma pegada ligeiramente mais aberta que a largura dos ombros e mantenha-o à sua frente com as palmas voltadas para baixo.\nLevante com cuidado o bastão para cima e para trás da cabeça.',
  'Chest Push (multiple response)':
    'Comece na posição ajoelhada de frente para uma parede ou use um parceiro. Segure a bola com as duas mãos firmemente contra o peito.\nExecute o passe explodindo para a frente e para fora com o quadril enquanto empurra a bola com a maior força possível.\nComplete o movimento caindo para a frente, amparando-se com as mãos.\nRetorne imediatamente à posição ereta. Repita pelo número de repetições desejado.',
  'Chest Push (single response)':
    'Comece na posição ajoelhada segurando a bola medicinal com as duas mãos firmemente contra o peito.\nExecute o passe explodindo para a frente e para fora com o quadril enquanto empurra a bola o mais longe possível.\nComplete o movimento caindo para a frente, amparando-se com as mãos.',
  'Chest Push from 3 point stance':
    'Comece em uma posição de três apoios, agachado com as costas retas e uma mão no chão. Coloque a bola medicinal diretamente à sua frente.\nPara começar, dê o primeiro passo enquanto puxa a bola até o peito, posicionando as duas mãos para preparar o arremesso.\nAo dar o segundo passo, solte a bola para a frente de forma explosiva com a maior força possível.',
  'Chest Push with Run Release':
    'Comece em uma postura atlética com os joelhos flexionados, o quadril para trás e as costas retas. Segure a bola medicinal perto das pernas. Esta será sua posição inicial.\nAo dar o primeiro passo, traga a bola medicinal até o peito.\nAo dar o segundo passo, empurre a bola para a frente de forma explosiva, correndo imediatamente em velocidade máxima por 10 jardas após soltá-la. Se você for muito rápido, pode pegar seu próprio passe!',
  'Chest Stretch on Stability Ball':
    'Fique de quatro apoios ao lado de uma bola de exercício.\nColoque os cotovelos sobre a bola, mantendo o braço para o lado. Esta será sua posição inicial.\nAbaixe o tronco em direção ao chão, mantendo o cotovelo sobre a bola. Segure o alongamento por 20 a 30 segundos e repita com o outro braço.',
  "Child's Pose":
    'Fique de quatro apoios e caminhe com as mãos para a frente.\nAbaixe o bumbum para sentar-se sobre os calcanhares. Deixe os braços deslizarem pelo chão enquanto se senta para trás para alongar toda a coluna.\nDepois de se acomodar sobre os calcanhares, traga as mãos para junto dos pés e relaxe. "Respire" para dentro das costas. Apoie a testa no chão. Evite esta posição se tiver problemas nos joelhos.',
  'Chin To Chest Stretch':
    'Sente-se no chão.\nColoque as duas mãos na parte de trás da cabeça, com os dedos entrelaçados, os polegares apontando para baixo e os cotovelos apontando para a frente. Puxe lentamente a cabeça em direção ao peito. Segure por 20 a 30 segundos.',
  'Chin-Up':
    'Segure a barra fixa com as palmas voltadas para o tronco e uma pegada mais fechada que a largura dos ombros.\nCom os dois braços estendidos à sua frente segurando a barra na largura de pegada escolhida, mantenha o tronco o mais reto possível enquanto cria uma curvatura na lombar e projeta o peito para fora. Esta é sua posição inicial. Dica: Manter o tronco o mais reto possível maximiza a estimulação dos bíceps e minimiza o envolvimento das costas.\nAo expirar, puxe o tronco para cima até que a cabeça fique na altura da barra. Concentre-se em usar os bíceps para realizar o movimento. Mantenha os cotovelos próximos ao corpo. Dica: A parte superior do tronco deve permanecer parada enquanto se desloca no espaço e apenas os braços devem se mover. Os antebraços não devem fazer nenhum outro trabalho além de segurar a barra.\nApós um segundo apertando os bíceps na posição contraída, abaixe lentamente o tronco de volta à posição inicial, até que os braços estejam totalmente estendidos. Inspire enquanto realiza esta parte do movimento.\nRepita esse movimento pelo número de repetições prescrito.',
  'Circus Bell':
    'O circus bell é um halter de tamanho gigante com um cabo grosso. Comece com o halter entre os pés e segure o cabo com as duas mãos.\nFaça o clean do halter estendendo quadris e joelhos para levar o implemento até o ombro desejado, soltando com a mão que sobra.\nCertifique-se de que uma das cabeças do halter fique atrás do ombro para não perder o equilíbrio. Para levantá-lo acima da cabeça, flexione os joelhos e depois empurre para cima enquanto estende o halter acima da cabeça, inclinando-se levemente para longe dele ao fazer isso.\nGuie com cuidado o sino de volta ao chão, mantendo-o sob controle o máximo possível. O melhor é realizar este exercício sobre um tapete de borracha grosso para evitar danos ao piso.',
  Clean:
    'Com uma barra no chão perto das canelas, segure com pegada pronada (ou em gancho) logo por fora das pernas. Abaixe o quadril com o peso nos calcanhares, costas retas, cabeça voltada para a frente, peito erguido e os ombros logo à frente da barra. Esta será sua posição inicial.\nInicie a primeira puxada empurrando pelos calcanhares, estendendo os joelhos. O ângulo das costas deve permanecer o mesmo e os braços devem ficar retos. Mova a carga com controle até passar dos joelhos.\nEm seguida vem a segunda puxada, a principal fonte de aceleração do clean. Quando a barra se aproximar do meio da coxa, comece a estender o quadril. Em um movimento de salto, acelere estendendo quadris, joelhos e tornozelos, usando a velocidade para levar a barra para cima. Não deve ser necessário puxar ativamente com os braços para acelerar a carga; ao final da segunda puxada, o corpo deve estar totalmente estendido, inclinado levemente para trás, com os braços ainda estendidos.\nAo atingir a extensão completa, passe para a terceira puxada encolhendo os ombros com força e flexionando os braços com os cotovelos para cima e para fora. No pico da extensão, puxe-se para baixo com força, girando os cotovelos por baixo da barra. Receba a barra na posição de agachamento frontal, cuja profundidade depende da altura da barra ao final da terceira puxada. A barra deve ficar apoiada nos ombros protraídos, tocando levemente a garganta, com as mãos relaxadas. Continue descendo até a posição inferior do agachamento, o que ajudará na recuperação.\nRecupere-se imediatamente empurrando pelos calcanhares, mantendo o tronco ereto e os cotovelos elevados. Continue até ficar em pé.',
  'Clean Deadlift':
    'Comece em pé com uma barra perto das canelas. Seus pés devem ficar diretamente abaixo do quadril e levemente voltados para fora. Segure a barra com pegada pronada dupla ou em gancho, aproximadamente na largura dos ombros. Agache até a barra. Sua coluna deve estar em extensão completa, com um ângulo das costas que coloque os ombros à frente da barra e as costas o mais verticais possível.\nComece empurrando o chão pela parte da frente dos calcanhares. Conforme a barra sobe, mantenha um ângulo constante das costas. Abra os joelhos para os lados para mantê-los fora da trajetória da barra.\nDepois que a barra passar dos joelhos, complete o levantamento levando o quadril em direção à barra até que quadris e joelhos estejam estendidos.',
  'Clean Pull':
    'Com uma barra no chão perto das canelas, segure com pegada pronada ou em gancho logo por fora das pernas. Abaixe o quadril com o peso nos calcanhares, costas retas, cabeça voltada para a frente, peito erguido e os ombros logo à frente da barra. Esta será sua posição inicial.\nInicie a primeira puxada empurrando pelos calcanhares, estendendo os joelhos. O ângulo das costas deve permanecer o mesmo, e os braços devem ficar retos, com os cotovelos para fora. Mova a carga com controle até passar dos joelhos.\nEm seguida vem a segunda puxada, a principal fonte de aceleração do clean. Quando a barra se aproximar do meio da coxa, comece a estender o quadril. Em um movimento de salto, acelere estendendo quadris, joelhos e tornozelos, usando a velocidade para levar a barra para cima. Não deve ser necessário puxar ativamente com os braços para acelerar a carga; ao final da segunda puxada, o corpo deve estar totalmente estendido, inclinado levemente para trás, com os braços ainda estendidos. A extensão completa deve ser violenta e abrupta, e certifique-se de não prolongá-la por mais tempo do que o necessário.',
  'Clean Shrug':
    'Comece com uma pegada na largura dos ombros, pronada dupla ou em gancho, com a barra pendurada na altura do meio da coxa. Suas costas devem ficar retas e levemente inclinadas para a frente.\nEncolha os ombros em direção às orelhas. Embora este exercício normalmente permita mais carga do que um clean, evite sobrecarregar a ponto de a execução ficar lenta.',
  'Clean and Jerk':
    'Com a barra no chão, próxima às canelas, faça uma pegada pronada ou em gancho logo por fora das pernas. Abaixe o quadril com o peso nos calcanhares, costas retas, cabeça voltada para a frente, peito erguido e ombros logo à frente da barra. Esta será sua posição inicial.\nInicie a primeira puxada empurrando com os calcanhares e estendendo os joelhos. O ângulo das costas deve permanecer o mesmo e os braços devem ficar retos. Movimente o peso com controle até passar dos joelhos.\nEm seguida vem a segunda puxada, principal fonte de aceleração do clean. Quando a barra se aproximar do meio da coxa, comece a estender o quadril. Em um movimento de salto, acelere estendendo quadril, joelhos e tornozelos, usando a velocidade para subir a barra. Não deve ser necessário puxar ativamente com os braços para acelerar o peso; ao final da segunda puxada, o corpo deve estar totalmente estendido, levemente inclinado para trás, com os braços ainda estendidos.\nAo atingir a extensão completa, passe para a terceira puxada encolhendo os ombros com força e flexionando os braços, com os cotovelos para cima e para fora. No pico da extensão, puxe-se para baixo com força, girando os cotovelos por baixo da barra. Receba a barra na posição de agachamento frontal, cuja profundidade depende da altura da barra ao final da terceira puxada. A barra deve ficar apoiada sobre os ombros protraídos, encostando de leve na garganta, com as mãos relaxadas. Continue descendo até a posição baixa do agachamento, o que ajudará na recuperação.\nRecupere-se imediatamente empurrando com os calcanhares, mantendo o tronco ereto e os cotovelos para cima. Continue até ficar de pé.\nA segunda fase é o arremesso (jerk), que leva o peso acima da cabeça. De pé, com a barra apoiada na frente dos ombros, comece com o impulso para baixo. Com os pés diretamente sob o quadril, flexione os joelhos sem levar o quadril para trás. Desça apenas um pouco e inverta a direção da forma mais potente possível.\nEmpurre com os calcanhares para gerar o máximo de velocidade e força possível, e lembre-se de tirar a cabeça do caminho quando a barra sair dos ombros.\nNesse momento, quando os pés saem do chão, você deve posicioná-los na posição de recepção o mais rápido possível. No breve instante em que os pés não estão empurrando ativamente contra a plataforma, o esforço do atleta para subir a barra o levará para baixo. Os pés devem ficar afastados, um à frente e outro atrás. Receba a barra com os braços estendidos acima da cabeça. Volte para a posição em pé.',
  'Clean and Press':
    'Assuma uma postura na largura dos ombros, com os joelhos por dentro dos braços. Mantendo as costas retas, flexione joelhos e quadril para poder segurar a barra com os braços totalmente estendidos e uma pegada pronada ligeiramente mais larga que os ombros. Aponte os cotovelos para os lados. A barra deve ficar próxima às canelas. Posicione os ombros sobre a barra ou levemente à frente dela. Mantenha as costas retas. Esta será sua posição inicial.\nComece a puxar a barra estendendo os joelhos. Leve o quadril para a frente e suba os ombros no mesmo ritmo, mantendo o ângulo das costas constante; continue subindo a barra em linha reta, próxima ao corpo.\nQuando a barra passar dos joelhos, estenda com força tornozelos, joelhos e quadril, de forma semelhante a um salto. Enquanto faz isso, continue guiando a barra com as mãos, encolhendo os ombros e aproveitando o impulso do movimento para puxar a barra o mais alto possível. A barra deve subir próxima ao corpo e você deve manter os cotovelos para fora.\nNa elevação máxima, seus pés devem sair do chão e você deve começar a se posicionar por baixo da barra. A mecânica pode mudar ligeiramente dependendo da carga usada. Você deve descer para uma posição de agachamento enquanto se coloca sob a barra.\nQuando a barra atingir a altura máxima, gire os cotovelos para baixo da barra. Apoie a barra na frente dos ombros mantendo o tronco ereto e flexionando quadril e joelhos para absorver o peso da barra.\nLevante-se por completo, segurando a barra na posição de clean.\nSem mexer os pés, empurre a barra acima da cabeça enquanto expira. Abaixe a barra com controle.',
  'Clean from Blocks':
    'Com uma barra sobre caixas ou suportes da altura desejada, faça uma pegada pronada ou em gancho logo por fora das pernas. Abaixe o quadril com o peso nos calcanhares, costas retas, cabeça voltada para a frente, peito erguido e ombros logo à frente da barra. Esta será sua posição inicial.\nInicie a primeira puxada empurrando com os calcanhares e estendendo os joelhos. O ângulo das costas deve permanecer o mesmo e os braços devem ficar retos, com os cotovelos apontados para fora.\nAo atingir a extensão completa, passe para a posição de recepção encolhendo os ombros com força e flexionando os braços, com os cotovelos para cima e para fora. Puxe-se para baixo com força, girando os cotovelos por baixo da barra. Receba a barra na posição de agachamento frontal, cuja profundidade depende da altura da barra ao final da terceira puxada. A barra deve ficar apoiada sobre os ombros protraídos, encostando de leve na garganta, com as mãos relaxadas. Continue descendo até a posição baixa do agachamento, o que ajudará na recuperação.\nRecupere-se imediatamente empurrando com os calcanhares, mantendo o tronco ereto e os cotovelos para cima. Continue até ficar de pé. Devolva o peso às caixas para a próxima repetição.',
  'Clock Push-Up':
    'Posicione-se em decúbito ventral no chão, apoiando o peso nas mãos e na ponta dos pés.\nSeus braços devem estar totalmente estendidos, com as mãos aproximadamente na largura dos ombros. Mantenha o corpo reto durante todo o movimento. Esta será sua posição inicial.\nDesça flexionando os cotovelos, abaixando o peito em direção ao chão.\nEmbaixo, inverta o movimento empurrando-se para cima por meio da extensão dos cotovelos o mais rápido possível, até ficar no ar. Tente "saltar" de 12 a 18 polegadas para um lado.\nEnquanto acelera para cima, mova o pé de fora para longe da direção do deslocamento. Ao sair do chão, gire o corpo cerca de 30 graus para a próxima repetição.\nVolte à posição inicial e repita o exercício, avançando em círculo até voltar ao ponto de partida.',
  'Close-Grip Barbell Bench Press':
    'Deite-se em um banco reto. Com uma pegada fechada (aproximadamente na largura dos ombros), retire a barra do suporte e segure-a reta sobre você com os braços estendidos. Esta será sua posição inicial.\nAo inspirar, desça lentamente até sentir a barra na parte média do peito. Dica: diferente do supino comum, mantenha os cotovelos próximos ao tronco o tempo todo para maximizar o trabalho dos tríceps.\nApós uma pausa de um segundo, leve a barra de volta à posição inicial enquanto expira e empurra a barra com os tríceps. Estenda os braços na posição de contração, segure por um segundo e comece a descer lentamente de novo. Dica: descer deve levar pelo menos o dobro do tempo de subir.\nRepita o movimento pelo número de repetições prescrito.\nAo terminar, coloque a barra de volta no suporte.',
  'Close-Grip Dumbbell Press':
    'Coloque um halter em pé na vertical sobre um banco reto.\nCertificando-se de que o halter fique bem firme na parte superior do banco, deite-se perpendicularmente ao banco com apenas os ombros apoiados na superfície. O quadril deve ficar abaixo do banco e as pernas dobradas, com os pés firmes no chão.\nSegure o halter com as duas mãos e mantenha-o reto sobre o peito, com os braços estendidos. Ambas as palmas devem pressionar a parte inferior dos lados do halter. Esta será sua posição inicial.\nInicie o movimento abaixando o halter até o peito.\nVolte à posição inicial estendendo os cotovelos.',
  'Close-Grip EZ Bar Curl':
    'Fique em pé com o tronco ereto segurando uma barra W na pegada interna mais próxima. As palmas das mãos devem ficar voltadas para a frente e levemente inclinadas para dentro devido ao formato da barra. Os cotovelos devem ficar próximos ao tronco. Esta será sua posição inicial.\nMantendo os braços parados, faça a rosca levando o peso para a frente enquanto contrai os bíceps e expira. Dica: apenas os antebraços devem se mover.\nContinue o movimento até que os bíceps estejam totalmente contraídos e a barra esteja na altura dos ombros. Segure a contração por um segundo e aperte forte os bíceps.\nComece a levar lentamente a barra de volta à posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado.',
  'Close-Grip EZ-Bar Curl with Band':
    'Prenda uma faixa em cada extremidade da barra. Pegue a barra colocando um pé no meio da faixa. Fique em pé, ereto, com uma pegada estreita e supinada na barra W. Os cotovelos devem ficar próximos ao tronco. Esta será sua posição inicial.\nMantendo os braços no lugar, flexione os cotovelos para executar a rosca. Expire enquanto levanta o peso.\nContinue o movimento até que os bíceps estejam totalmente contraídos e a barra esteja na altura dos ombros. Segure a contração por um segundo e aperte forte os bíceps.\nComece a levar lentamente a barra de volta à posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado.',
  'Close-Grip EZ-Bar Press':
    'Deite-se em um banco reto com uma barra W carregada com um peso adequado.\nCom uma pegada estreita, levante a barra e segure-a reta sobre o tronco com os cotovelos para dentro. Os braços devem ficar perpendiculares ao chão. Esta será sua posição inicial.\nAgora abaixe a barra até a parte inferior do peito enquanto inspira. Mantenha os cotovelos junto ao corpo durante este movimento.\nUsando os tríceps para empurrar a barra para cima, pressione-a de volta à posição inicial estendendo os cotovelos enquanto expira.\nRepita.',
  'Close-Grip Front Lat Pulldown':
    'Sente-se em uma máquina de puxada com uma barra larga presa à polia alta. Certifique-se de ajustar o apoio para os joelhos da máquina à sua altura. Esses apoios impedem que a resistência presa à barra levante o seu corpo.\nSegure a barra com as palmas voltadas para a frente usando a pegada prescrita. Nota sobre as pegadas: para uma pegada aberta, as mãos devem ficar afastadas a uma distância maior que a largura dos ombros. Para uma pegada média, a uma distância igual à largura dos ombros, e para uma pegada fechada, a uma distância menor que a largura dos ombros.\nCom ambos os braços estendidos à sua frente, segurando a barra na largura de pegada escolhida, incline o tronco para trás cerca de 30 graus, criando uma curvatura na lombar e estufando o peito. Esta é sua posição inicial.\nAo expirar, leve a barra para baixo até tocar a parte superior do peito, puxando os ombros e os braços para baixo e para trás. Dica: concentre-se em contrair os músculos das costas ao chegar à contração completa. A parte superior do tronco deve permanecer parada (apenas os braços devem se mover). Os antebraços não devem fazer nenhum outro trabalho além de segurar a barra; portanto, não tente puxar a barra para baixo com os antebraços.\nApós um segundo na posição de contração, enquanto aproxima as escápulas, suba lentamente a barra de volta à posição inicial até que os braços estejam totalmente estendidos e os dorsais completamente alongados. Inspire durante esta parte do movimento.\n6. Repita este movimento pelo número de repetições prescrito.',
  'Close-Grip Push-Up off of a Dumbbell':
    'Deite-se no chão e coloque as mãos sobre um halter em pé na vertical. Apoiando o peso na ponta dos pés e nas mãos, mantenha o tronco rígido e os cotovelos próximos ao corpo, com os braços retos. Esta será sua posição inicial.\nAbaixe o corpo, permitindo que os cotovelos flexionem enquanto inspira. Mantenha o corpo reto, sem deixar o quadril subir ou cair.\nEmpurre-se de volta à posição inicial estendendo os cotovelos. Expire ao realizar este passo.\nApós uma pausa na posição de contração, repita o movimento pelo número de repetições prescrito.',
  'Close-Grip Standing Barbell Curl':
    'Segure uma barra com as duas mãos, com as palmas para cima e afastadas por poucos centímetros.\nFique em pé com o tronco reto e a cabeça erguida. Seus pés devem ficar aproximadamente na largura dos ombros e os cotovelos próximos ao tronco. Esta será sua posição inicial. Dica: você manterá os braços e os cotovelos parados durante todo o movimento.\nFaça a rosca da barra em um movimento semicircular até que os antebraços toquem os bíceps. Expire durante esta parte do movimento e contraia forte os bíceps por um segundo no topo. Dica: evite curvar as costas ou usar balanço ao levantar o peso. Apenas os antebraços devem se mover.\nVolte lentamente à posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado.',
  Cocoons:
    'Comece deitado de costas no chão. Suas pernas devem estar retas e os braços estendidos atrás da cabeça. Esta será sua posição inicial.\nPara realizar o movimento, leve os joelhos em direção ao peito, girando a pelve para tirar os glúteos do chão. Ao mesmo tempo, flexione a coluna trazendo os braços para cima da cabeça para realizar um abdominal simultâneo.\nApós uma breve pausa, volte à posição inicial.',
  "Conan's Wheel":
    'Com o peso carregado, faça a pegada zurcher na extremidade do implemento. Coloque a barra na dobra do cotovelo e segure o próprio pulso. Tente manter o peso fora dos antebraços.\nComece levantando o peso do chão. Mantenha uma postura firme e ereta ao começar a andar, dando passos curtos e rápidos. Olhe para cima e para longe enquanto gira em círculo. Não prenda a respiração durante a prova. Continue andando até completar uma ou mais voltas completas.',
  'Concentration Curls':
    'Sente-se em um banco reto com um halter à sua frente, entre as pernas. Suas pernas devem estar afastadas, com os joelhos dobrados e os pés no chão.\nUse o braço direito para pegar o halter. Apoie a parte de trás do braço direito na parte superior da coxa direita, pelo lado de dentro. Gire a palma da mão até ficar voltada para a frente, longe da coxa. Dica: seu braço deve estar estendido e o halter acima do chão. Esta será sua posição inicial.\nMantendo o braço parado, faça a rosca levando o peso para a frente enquanto contrai o bíceps e expira. Apenas o antebraço deve se mover. Continue o movimento até que o bíceps esteja totalmente contraído e o halter esteja na altura do ombro. Dica: no topo do movimento, certifique-se de que o dedo mindinho fique mais alto que o polegar. Isso garante uma boa contração. Segure a posição de contração por um segundo enquanto aperta o bíceps.\nComece a levar lentamente o halter de volta à posição inicial enquanto inspira. Cuidado: evite movimentos de balanço a qualquer momento.\nRepita pelo número de repetições recomendado. Depois repita o movimento com o braço esquerdo.',
  'Cross Body Hammer Curl':
    'Fique em pé, ereto, com um halter em cada mão. Suas mãos devem ficar ao lado do corpo com as palmas voltadas para dentro.\nMantendo as palmas voltadas para dentro e sem girar o braço, faça a rosca do halter do braço direito em direção ao ombro esquerdo enquanto expira. Encoste a parte de cima do halter no ombro e segure a contração por um segundo.\nAbaixe lentamente o halter pelo mesmo caminho enquanto inspira e então repita o mesmo movimento com o braço esquerdo.\nContinue alternando dessa forma até completar o número de repetições recomendado para cada braço.',
  'Cross Over - With Bands':
    'Prenda uma faixa elástica em um poste fixo.\nDe costas para o poste, segure as alças nas duas pontas da faixa e dê um passo à frente o suficiente para criar tensão na faixa.\nLevante os braços para os lados, paralelos ao chão e perpendiculares ao tronco (seu tronco e os braços devem formar a letra "T"), com as palmas voltadas para a frente. Mantenha-os estendidos com uma leve flexão nos cotovelos. Esta será sua posição inicial.\nMantendo os braços retos, traga-os à frente do peito em um movimento semicircular enquanto expira e contrai os peitorais. Segure a contração por um segundo.\nVolte lentamente à posição inicial enquanto inspira.\nRealize o número de repetições recomendado.',
  'Cross-Body Crunch':
    'Deite-se de costas e dobre os joelhos cerca de 60 graus.\nMantenha os pés apoiados no chão e coloque as mãos de leve atrás da cabeça. Esta será sua posição inicial.\nAgora suba e leve o cotovelo e o ombro direitos em diagonal pelo corpo enquanto leva o joelho esquerdo em direção ao ombro esquerdo ao mesmo tempo. Alcance com o cotovelo e tente tocar o joelho. Expire ao realizar este movimento. Dica: tente levar o ombro em direção ao joelho, e não apenas o cotovelo, e lembre-se de que o principal é contrair os abdominais ao fazer o movimento, e não apenas mover o cotovelo.\nAgora volte à posição inicial enquanto inspira e repita com o cotovelo esquerdo e o joelho direito.\nContinue alternando dessa forma até completar todas as repetições prescritas.',
  'Crossover Reverse Lunge':
    'Fique em pé com os pés afastados na largura dos ombros. Esta será sua posição inicial.\nRealize um afundo para trás dando um passo atrás com um pé e flexionando o quadril e o joelho da frente. Enquanto faz isso, gire o tronco sobre a perna da frente.\nApós uma breve pausa, volte à posição inicial e repita do outro lado, continuando de forma alternada.',
  Crucifix:
    'No crucifixo, você segura pesos de forma estática com os braços estendidos para os lados por tempo. Embora a prova possa ser praticada com halteres, o melhor é praticar com um dos implementos usados, como machados e martelos, pois a sensação é diferente.\nComece em pé e levante os braços para os lados segurando os implementos. Seus braços devem ficar paralelos ao chão. Em competição, juízes ou sensores avisam quando você perde o paralelo. Mantenha pelo maior tempo possível. Normalmente, os pesos devem ser pesados o bastante para que você falhe em 30-60 segundos.',
  'Crunch - Hands Overhead':
    'Deite-se no chão com as costas retas e os joelhos dobrados, com um ângulo de cerca de 60 graus entre os posteriores de coxa e as panturrilhas.\nMantenha os pés apoiados no chão e estique os braços acima da cabeça com as palmas cruzadas. Esta será sua posição inicial.\nEnrole a parte superior do corpo para a frente e tire as escápulas do chão, só um pouco. O tempo todo, mantenha os braços alinhados com a cabeça, o pescoço e os ombros. Não os mova para a frente a partir dessa posição. Expire durante esta parte do movimento e segure a contração por um segundo.\nDesça lentamente à posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado.',
  'Crunch - Legs On Exercise Ball':
    'Deite-se de costas com os pés apoiados em uma bola de exercício e os joelhos dobrados em um ângulo de 90 graus.\nPosicione os pés afastados de três a quatro polegadas e aponte os dedos dos pés para dentro, de modo que se toquem.\nColoque as mãos de leve dos dois lados da cabeça, mantendo os cotovelos para dentro. Dica: não entrelace os dedos atrás da cabeça.\nEmpurre a parte baixa das costas contra o chão para isolar melhor os abdominais. Esta será sua posição inicial.\nComece a tirar os ombros do chão e continue empurrando o mais forte que puder com a lombar. Os ombros devem subir apenas cerca de quatro polegadas do chão, e a lombar deve permanecer no chão. Expire ao executar esta parte do movimento. Aperte forte os abdominais no topo, no ponto máximo da contração, e segure por um segundo. Dica: concentre-se em um movimento lento e controlado. Evite usar impulso a qualquer momento.\nDesça lentamente à posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado.',
  Crunches:
    'Deite-se de costas com os pés apoiados no chão, ou apoiados em um banco com os joelhos dobrados em um ângulo de 90 graus. Se apoiar os pés em um banco, posicione-os afastados de três a quatro polegadas e aponte os dedos dos pés para dentro, de modo que se toquem.\nAgora coloque as mãos de leve dos dois lados da cabeça, mantendo os cotovelos para dentro. Dica: não entrelace os dedos atrás da cabeça.\nEnquanto empurra a parte baixa das costas contra o chão para isolar melhor os abdominais, comece a tirar os ombros do chão.\nContinue empurrando o mais forte que puder com a lombar enquanto contrai os abdominais e expira. Os ombros devem subir apenas cerca de quatro polegadas do chão, e a lombar deve permanecer no chão. No topo do movimento, contraia forte os abdominais e mantenha a contração por um segundo. Dica: concentre-se em um movimento lento e controlado; não se engane usando impulso.\nApós a contração de um segundo, comece a descer lentamente de novo à posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado.',
  'Cuban Press':
    'Pegue um halter em cada mão com uma pegada pronada, em pé. Levante os braços até que fiquem paralelos ao chão, deixando os antebraços pendurados na posição de "espantalho". Esta será sua posição inicial.\nPara iniciar o movimento, faça a rotação externa dos ombros para mover o braço 180 graus. Mantenha os braços no lugar, girando-os até que os punhos fiquem diretamente acima dos cotovelos e os antebraços perpendiculares ao chão.\nAgora empurre os halteres estendendo os cotovelos, esticando os braços acima da cabeça.\nVolte à posição inicial enquanto inspira, invertendo os passos.\nRepita pelo número de repetições recomendado.',
  "Dancer's Stretch":
    'Sente-se no chão.\nCruze a perna direita sobre a esquerda, mantendo o joelho dobrado. Sua perna esquerda fica reta e apoiada no chão.\nColoque o braço esquerdo sobre a perna direita e a mão direita no chão.\nGire a parte superior do corpo para a direita e segure por 10 a 20 segundos. Troque de lado.',
  'Dead Bug':
    'Comece deitado de costas com as mãos estendidas acima de você em direção ao teto.\nLeve os pés, os joelhos e o quadril até 90 graus.\nExpire com força para abaixar a caixa torácica e achatar as costas contra o chão, girando a pelve para cima e contraindo os glúteos. Mantenha essa posição durante todo o movimento. Esta será sua posição inicial.\nInicie o exercício estendendo uma perna, esticando o joelho e o quadril para levar a perna logo acima do chão.\nMantenha a posição da lombar e da pelve ao realizar o movimento, pois suas costas vão querer arquear.\nMantenha-se firme e leve a perna que trabalha de volta à posição inicial.\nRepita do lado oposto, alternando até completar a série.',
  'Deadlift with Bands':
    'Para fazer levantamento terra com faixas curtas, basta passá-las pela barra antes de começar e pisar nelas para se posicionar. As faixas longas precisam ser ancoradas em uma base segura, como halteres pesados ou um rack.\nCom os pés e a pegada posicionados, respire fundo e então abaixe o quadril e flexione os joelhos até que as canelas encostem na barra. Olhe para a frente, mantenha o peito erguido e as costas arqueadas, e comece a empurrar com os calcanhares para subir o peso. Depois que a barra passar dos joelhos, puxe a barra para trás com força, juntando as escápulas enquanto leva o quadril para a frente contra a barra.\nAbaixe a barra flexionando o quadril e guiando-a até o chão.',
  'Deadlift with Chains':
    'Você pode prender as correntes nas extremidades da barra, ou simplesmente apoiar o meio delas sobre a barra para que haja um maior aumento de carga conforme você levanta.\nAproxime-se da barra de modo que fique centralizada sobre seus pés. Seus pés devem ficar afastados aproximadamente na largura do quadril. Flexione o quadril para segurar a barra na largura dos ombros, permitindo que as escápulas protraiam. Normalmente usa-se uma pegada pronada ou uma pegada mista nas séries mais pesadas. Com os pés e a pegada posicionados, respire fundo e então abaixe o quadril e flexione os joelhos até que as canelas encostem na barra.\nOlhe para a frente, mantenha o peito erguido e as costas arqueadas, e comece a empurrar com os calcanhares para subir o peso. Depois que a barra passar dos joelhos, puxe a barra para trás com força, juntando as escápulas enquanto leva o quadril para a frente contra a barra.\nAbaixe a barra flexionando o quadril e guiando-a até o chão.',
  'Decline Barbell Bench Press':
    'Prenda as pernas na extremidade do banco declinado e deite-se lentamente no banco.\nUsando uma pegada de largura média (uma pegada que forme um ângulo de 90 graus entre os antebraços e os braços no meio do movimento), retire a barra do suporte e segure-a reta sobre você com os braços estendidos. Os braços devem ficar perpendiculares ao chão. Esta será sua posição inicial. Dica: para proteger o manguito rotador, é melhor ter um auxiliar para ajudar a tirar a barra do suporte.\nAo inspirar, desça lentamente até sentir a barra na parte inferior do peito.\nApós uma pausa de um segundo, leve a barra de volta à posição inicial enquanto expira e empurra a barra com os músculos do peito. Estenda os braços e aperte o peito na posição de contração, segure por um segundo e comece a descer lentamente de novo. Dica: descer deve levar pelo menos o dobro do tempo de subir.\nRepita o movimento pelo número de repetições prescrito.\nAo terminar, coloque a barra de volta no suporte.',
  'Decline Close-Grip Bench To Skull Crusher':
    'Prenda as pernas na extremidade do banco declinado e deite-se lentamente no banco.\nUsando uma pegada fechada (uma pegada ligeiramente menor que a largura dos ombros), retire a barra do suporte e segure-a reta sobre você com os braços estendidos e os cotovelos para dentro. Os braços devem ficar perpendiculares ao chão. Esta será sua posição inicial. Dica: para proteger o manguito rotador, é melhor ter um auxiliar para ajudar a tirar a barra do suporte.\nAgora abaixe a barra até a parte inferior do peito enquanto inspira. Mantenha os cotovelos junto ao corpo durante este movimento.\nUsando os tríceps para empurrar a barra para cima, pressione-a de volta à posição inicial enquanto expira.\nAo inspirar e manter os braços parados, abaixe lentamente a barra movendo os antebraços em um movimento semicircular em sua direção até sentir a barra encostar de leve na testa. Inspire durante esta parte do movimento.\nLevante a barra de volta à posição inicial contraindo os tríceps e expirando.\nRepita os passos 3-6 até completar o número de repetições recomendado.',
  'Decline Crunch':
    'Prenda as pernas na extremidade do banco declinado e deite-se.\nAgora coloque as mãos de leve dos dois lados da cabeça, mantendo os cotovelos para dentro. Dica: não entrelace os dedos atrás da cabeça.\nEnquanto empurra a parte baixa das costas contra o banco para isolar melhor os abdominais, comece a tirar os ombros do banco.\nContinue empurrando o mais forte que puder com a lombar enquanto contrai os abdominais e expira. Os ombros devem subir apenas cerca de quatro polegadas do banco, e a lombar deve permanecer no banco. No topo do movimento, contraia forte os abdominais e mantenha a contração por um segundo. Dica: concentre-se em um movimento lento e controlado; não se engane usando impulso.\nApós a contração de um segundo, comece a descer lentamente de novo à posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado.',
  'Decline Dumbbell Bench Press':
    'Prenda as pernas na extremidade do banco declinado e deite-se com um halter em cada mão sobre as coxas. As palmas das mãos ficarão voltadas uma para a outra.\nDepois de deitado, leve os halteres à sua frente na largura dos ombros.\nUma vez na largura dos ombros, gire os punhos para a frente de modo que as palmas das mãos fiquem voltadas para longe de você. Esta será sua posição inicial.\nAbaixe lentamente os pesos para os lados enquanto expira. Mantenha o controle total dos halteres o tempo todo. Dica: durante todo o movimento, os antebraços devem ficar sempre perpendiculares ao chão.\nAo expirar, empurre os halteres para cima usando os músculos peitorais. Estenda os braços na posição de contração, aperte o peito, segure por um segundo e comece a descer lentamente. Dica: descer deve levar pelo menos o dobro do tempo de subir.\nRepita o movimento pelo número de repetições prescrito no seu programa de treino.',
  'Decline Dumbbell Flyes':
    'Prenda as pernas na extremidade do banco declinado e deite-se com um halter em cada mão sobre as coxas. As palmas das mãos ficarão voltadas uma para a outra.\nDepois de deitado, leve os halteres à sua frente na largura dos ombros. As palmas das mãos devem ficar voltadas uma para a outra e os braços devem ficar perpendiculares ao chão e totalmente estendidos. Esta será sua posição inicial.\nCom uma leve flexão nos cotovelos para evitar tensão no tendão do bíceps, abaixe os braços para os dois lados em um arco amplo até sentir um alongamento no peito. Inspire durante esta parte do movimento. Dica: lembre-se de que, durante todo o movimento, os braços devem permanecer parados; o movimento deve ocorrer apenas na articulação do ombro.\nLeve os braços de volta à posição inicial enquanto aperta os músculos do peito e expira. Dica: use o mesmo arco de movimento usado para abaixar os pesos.\nSegure por um segundo na posição de contração e repita o movimento pelo número de repetições prescrito.',
  'Decline Dumbbell Triceps Extension':
    'Prenda as pernas na extremidade do banco declinado e deite-se com um halter em cada mão sobre as coxas. As palmas das mãos ficarão voltadas uma para a outra.\nDepois de deitado, leve os halteres à sua frente na largura dos ombros. As palmas das mãos devem ficar voltadas uma para a outra e os braços devem ficar perpendiculares ao chão e totalmente estendidos. Esta será sua posição inicial.\nAo inspirar e manter os braços parados (e os cotovelos para dentro), abaixe lentamente os halteres movendo os antebraços em um movimento semicircular em sua direção até que os polegares fiquem ao lado das orelhas. Inspire durante esta parte do movimento.\nLevante os halteres de volta à posição inicial contraindo os tríceps e expirando.\nRepita pelo número de repetições recomendado.',
  'Decline EZ Bar Triceps Extension':
    'Prenda as pernas na extremidade do banco declinado e deite-se lentamente no banco.\nUsando uma pegada fechada (uma pegada ligeiramente menor que a largura dos ombros), retire a barra W do suporte e segure-a reta sobre você com os braços estendidos e os cotovelos para dentro. Os braços devem ficar perpendiculares ao chão. Esta será sua posição inicial. Dica: para proteger o manguito rotador, é melhor ter um auxiliar para ajudar a tirar a barra do suporte.\nAo inspirar e manter os braços parados, abaixe lentamente a barra movendo os antebraços em um movimento semicircular em sua direção até sentir a barra encostar de leve na testa. Inspire durante esta parte do movimento.\nLevante a barra de volta à posição inicial contraindo os tríceps e expirando.\nRepita até completar o número de repetições recomendado.',
  'Decline Oblique Crunch':
    'Prenda as pernas na extremidade do banco declinado e deite-se lentamente no banco.\nLevante a parte superior do corpo do banco até que o tronco fique a cerca de 35-45 graus em relação ao chão.\nColoque uma mão ao lado da cabeça e a outra sobre a coxa. Esta será sua posição inicial.\nLevante lentamente a parte superior do corpo a partir da posição inicial enquanto gira o tronco para a esquerda. Continue subindo no abdominal enquanto expira até que o cotovelo direito toque o joelho esquerdo. Segure essa posição de contração por um segundo. Dica: concentre-se em manter os abdominais contraídos e o movimento lento e controlado.\nAbaixe lentamente o corpo de volta à posição inicial enquanto inspira.\nApós completar uma série do lado direito com o número de repetições recomendado, troque para o lado esquerdo. Dica: concentre-se em girar de verdade o tronco e sentir a contração quando estiver na posição alta.',
  'Decline Push-Up':
    'Deite-se de bruços no chão e coloque as mãos afastadas cerca de 36 polegadas, sustentando o tronco com os braços estendidos. Apoie os pés em uma caixa ou banco. Esta será sua posição inicial.\nEm seguida, desça o corpo até que o peito quase toque o chão enquanto inspira.\nAgora expire e empurre a parte superior do corpo de volta à posição inicial enquanto aperta o peito.\nApós uma breve pausa no topo, na posição de contração, você pode começar a descer novamente pelo número de repetições necessário.',
  'Decline Reverse Crunch':
    'Deite-se de costas em um banco declinado e segure a parte superior do banco com as duas mãos. Não deixe o corpo escorregar para baixo a partir dessa posição.\nMantenha as pernas paralelas ao chão usando os abdominais para sustentá-las ali, com os joelhos e os pés juntos. Dica: suas pernas devem estar totalmente estendidas com uma leve flexão nos joelhos. Esta será sua posição inicial.\nAo expirar, leve as pernas em direção ao tronco enquanto gira a pelve para trás e tira o quadril do banco. Ao final deste movimento, seus joelhos estarão tocando o peito.\nSegure a contração por um segundo e leve as pernas de volta à posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado.',
  'Decline Smith Press':
    'Coloque um banco declinado embaixo da máquina Smith. Agora posicione a barra em uma altura que você alcance deitado com os braços quase totalmente estendidos. Usando uma pegada pronada mais larga que os ombros, destrave a barra do suporte e segure-a reta sobre você com os braços estendidos. Esta será sua posição inicial.\nAo inspirar, abaixe a barra com controle permitindo que os cotovelos flexionem, encostando de leve no tronco.\nApós uma breve pausa, leve a barra de volta à posição inicial estendendo os cotovelos enquanto expira.\nRepita o movimento pelo número de repetições prescrito.\nAo terminar a série, trave a barra de volta no suporte.',
  'Deficit Deadlift':
    'Comece tendo uma plataforma ou anilhas sobre as quais você possa ficar em pé, normalmente com 1 a 3 polegadas de altura. Aproxime-se da barra de modo que fique centralizada sobre seus pés. Seus pés devem ficar afastados aproximadamente na largura do quadril. Flexione o quadril para segurar a barra na largura dos ombros, permitindo que as escápulas protraiam. Normalmente usa-se uma pegada pronada ou uma pegada mista nas séries mais pesadas.\nCom os pés e a pegada posicionados, respire fundo e então abaixe o quadril e flexione os joelhos até que as canelas encostem na barra. Olhe para a frente, mantenha o peito erguido e as costas arqueadas, e comece a empurrar com os calcanhares para subir o peso. Depois que a barra passar dos joelhos, puxe a barra para trás com força, juntando as escápulas enquanto leva o quadril para a frente contra a barra.\nAbaixe a barra flexionando o quadril e guiando-a até o chão.',
  'Depth Jump Leap':
    'Para este exercício você precisará de duas caixas ou bancos, um com 12 a 16 polegadas de altura e outro com 22 a 26 polegadas.\nFique em pé sobre uma das duas caixas com os braços ao lado do corpo; os pés devem ficar juntos e ligeiramente para fora da borda, como no salto em profundidade. Coloque a outra caixa a aproximadamente dois ou três pés à frente de quem realiza o exercício e voltada para ele.\nComece se deixando cair da primeira caixa, aterrissando e decolando simultaneamente com os dois pés.\nRebata impulsionando-se para cima e para a frente com a maior intensidade possível, usando os braços e a extensão completa do corpo para saltar sobre a caixa mais alta. Novamente, deixe as pernas absorverem o impacto.',
  'Dip Machine':
    'Sente-se com firmeza em uma máquina de paralelas, selecione a carga e segure firmemente as alças.\nAgora mantenha os cotovelos junto aos lados do corpo para dar ênfase aos tríceps. Os cotovelos devem estar dobrados em um ângulo de 90 graus.\nAo contrair os tríceps, estenda os braços para baixo enquanto expira. Dica: na parte baixa do movimento, concentre-se em manter uma leve flexão nos braços para manter a tensão no músculo tríceps.\nAgora deixe os braços voltarem lentamente à posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado.',
  'Dips - Chest Version':
    'Para este exercício você precisará de acesso a barras paralelas. Para chegar à posição inicial, sustente o corpo com os braços estendidos (braços travados) acima das barras.\nAo inspirar, desça lentamente com o tronco inclinado para a frente cerca de 30 graus e os cotovelos ligeiramente abertos para fora, até sentir um leve alongamento no peito.\nAssim que sentir o alongamento, use o peito para levar o corpo de volta à posição inicial enquanto expira. Dica: lembre-se de apertar o peito no topo do movimento por um segundo.\nRepita o movimento pelo número de repetições prescrito.',
  'Dips - Triceps Version':
    'Para chegar à posição inicial, sustente o corpo com os braços estendidos, quase travados, acima das barras.\nAgora, inspire e desça lentamente. Seu tronco deve permanecer ereto e os cotovelos devem ficar próximos ao corpo. Isso ajuda a focar melhor o trabalho dos tríceps. Desça até formar um ângulo de 90 graus entre o braço e o antebraço.\nEntão, expire e empurre o tronco para cima usando os tríceps para levar o corpo de volta à posição inicial.\nRepita o movimento pelo número de repetições prescrito.',
  'Donkey Calf Raises':
    'Para este exercício você precisará de acesso a uma máquina de elevação de panturrilhas tipo burro. Comece posicionando a lombar e o quadril sob a alavanca acolchoada. A região do cóccix deve ser a que faz contato com o apoio.\nColoque ambos os braços nas alças laterais e apoie a parte da frente dos pés no bloco de panturrilha, com os calcanhares para fora. Alinhe os dedos dos pés para a frente, para dentro ou para fora, dependendo da área que deseja trabalhar, e estique os joelhos sem travá-los. Esta será sua posição inicial.\nLevante os calcanhares enquanto expira, estendendo os tornozelos o mais alto possível e contraindo a panturrilha. Certifique-se de manter o joelho parado o tempo todo. Não deve haver flexão em nenhum momento. Segure a posição de contração por um segundo antes de começar a descer.\nVolte lentamente à posição inicial enquanto inspira, abaixando os calcanhares e flexionando os tornozelos até que as panturrilhas estejam alongadas.\nRepita pelo número de repetições recomendado.',
  'Double Kettlebell Alternating Hang Clean':
    'Coloque dois kettlebells entre os pés. Para chegar à posição inicial, leve o quadril para trás e olhe para a frente.\nFaça um clean de um kettlebell até o ombro e segure o outro kettlebell.\nCom um movimento fluido, abaixe o kettlebell de cima enquanto sobe o de baixo.',
  'Double Kettlebell Jerk':
    'Segure um kettlebell pela alça em cada mão.\nLeve os kettlebells até os ombros estendendo pernas e quadril enquanto puxa os kettlebells em direção aos ombros. Gire os punhos ao fazer isso, de modo que as palmas fiquem voltadas para a frente. Esta será sua posição inicial.\nDesça o corpo flexionando os joelhos, mantendo o tronco ereto.\nImediatamente inverta a direção, empurrando com os calcanhares, essencialmente saltando para gerar impulso.\nAo fazer isso, empurre os kettlebells acima da cabeça até estender os braços, usando o impulso do corpo para mover os pesos.\nLeve os pés de volta ao chão em posição dividida, com um pé à frente e outro atrás.\nMantendo os pesos acima da cabeça, volte à posição em pé, juntando os pés. Abaixe os pesos para realizar a próxima repetição.',
  'Double Kettlebell Push Press':
    'Leve dois kettlebells até os ombros.\nAgache alguns centímetros e inverta o movimento rapidamente. Use o impulso das pernas para levar os kettlebells acima da cabeça.\nQuando os kettlebells estiverem travados no alto, abaixe-os até os ombros e repita.',
  'Double Kettlebell Snatch':
    'Coloque dois kettlebells atrás dos pés. Flexione os joelhos e leve o quadril para trás para pegar os kettlebells.\nBalance os kettlebells com força entre as pernas e inverta a direção.\nEmpurre com o quadril e trave os kettlebells acima da cabeça em um único movimento contínuo.',
  'Double Kettlebell Windmill':
    'Coloque um kettlebell à frente do pé da frente e faça um clean e desenvolvimento de um kettlebell acima da cabeça com o braço oposto. Leve o kettlebell até o ombro estendendo pernas e quadril enquanto puxa o kettlebell em direção ao ombro. Gire o punho ao fazer isso, de modo que a palma fique voltada para a frente.\nMantendo o kettlebell travado no alto o tempo todo, empurre o quadril para fora na direção do kettlebell travado. Gire os pés para fora em um ângulo de quarenta e cinco graus em relação ao braço com o kettlebell travado.\nFlexionando o quadril para um lado e empurrando-o para fora, incline-se lentamente até conseguir pegar o kettlebell do chão. Mantenha os olhos no kettlebell que você segura acima da cabeça o tempo todo.\nFaça uma pausa de um segundo depois de pegar o kettlebell do chão e inverta o movimento de volta à posição inicial.',
  'Double Leg Butt Kick':
    'Comece em pé com os joelhos ligeiramente flexionados.\nAgache rapidamente uma curta distância, flexionando quadril e joelhos, e imediatamente estenda para saltar na máxima altura vertical.\nEnquanto sobe, leve os calcanhares para trás flexionando os joelhos, tentando tocar os glúteos.\nTermine o movimento aterrissando com os joelhos apenas parcialmente flexionados, usando as pernas para absorver o impacto.',
  'Downward Facing Balance':
    'Deite-se de bruços sobre uma bola de exercício.\nEnquanto se apoia com o abdômen na bola, caminhe com as mãos para a frente pelo chão e levante as pernas, estendendo os cotovelos e os joelhos.',
  'Drag Curl':
    'Segure uma barra com uma pegada supinada (palmas para a frente) e leve os cotovelos para perto do tronco e para trás. Esta será sua posição inicial.\nAo expirar, faça a rosca da barra para cima mantendo os cotovelos para trás, "arrastando" a barra para cima enquanto a mantém em contato com o tronco. Dica: como você pode ver, você não manterá os cotovelos colados aos lados do corpo, mas sim os levará para trás. Além disso, não levante os ombros.\nVolte lentamente à posição inicial mantendo a barra em contato com o tronco o tempo todo.\nRepita pelo número de repetições recomendado.',
  'Drop Push':
    'Posicione caixas baixas ou outras plataformas afastadas de 2 a 3 pés.\nPosicione-se em posição de flexão entre elas, apoiando-se com as mãos sobre as caixas.\nCom boa postura, deixe-se cair das plataformas empurrando para cima e levando as mãos à largura dos ombros, amortecendo a aterrissagem ao absorver o impacto com os braços.',
  'Dumbbell Alternate Bicep Curl':
    'Fique em pé (tronco ereto) com um halter em cada mão, com os braços estendidos. Os cotovelos devem ficar próximos ao tronco e as palmas das mãos voltadas para as coxas.\nMantendo o braço parado, faça a rosca com o halter direito girando a palma da mão até ficar voltada para frente. Nesse ponto, continue contraindo o bíceps enquanto expira, até que o bíceps esteja totalmente contraído e o halter na altura do ombro. Mantenha a posição contraída por um segundo enquanto aperta o bíceps. Dica: apenas os antebraços devem se mover.\nComece a trazer lentamente o halter de volta à posição inicial enquanto inspira. Dica: lembre-se de girar a palma de volta à posição inicial (voltada para as coxas) ao descer.\nRepita o movimento com a mão esquerda. Isso equivale a uma repetição.\nContinue alternando dessa forma pelo número de repetições recomendado.',
  'Dumbbell Bench Press':
    'Deite-se em um banco reto com um halter em cada mão apoiado sobre as coxas. As palmas das mãos devem ficar voltadas uma para a outra.\nEm seguida, usando as coxas para ajudar a subir os halteres, levante-os um de cada vez para segurá-los à sua frente na largura dos ombros.\nNa largura dos ombros, gire os punhos para frente de modo que as palmas fiquem voltadas para longe de você. Os halteres devem ficar logo ao lado do peito, com o braço e o antebraço formando um ângulo de 90 graus. Mantenha o controle total dos halteres o tempo todo. Essa será sua posição inicial.\nEntão, ao expirar, use o peito para empurrar os halteres para cima. Estenda os braços no topo e aperte o peito, segure por um segundo e comece a descer lentamente. Dica: idealmente, descer o peso deve levar cerca do dobro do tempo de subir.\nRepita o movimento pelo número de repetições prescrito no seu programa de treino.',
  'Dumbbell Bench Press with Neutral Grip':
    'Pegue um halter em cada mão e deite-se em um banco reto. Os pés devem ficar apoiados no chão e as escápulas retraídas.\nMantendo uma pegada neutra, com as palmas voltadas uma para a outra, comece com os braços estendidos diretamente acima de você, perpendiculares ao chão. Essa será sua posição inicial.\nInicie o movimento flexionando os cotovelos e abaixando os braços para os lados. Desça até que os halteres fiquem na altura do tronco.\nFaça uma pausa, depois estenda os cotovelos e retorne à posição inicial.',
  'Dumbbell Bicep Curl':
    'Fique em pé com a coluna reta e um halter em cada mão, com os braços estendidos. Mantenha os cotovelos próximos ao tronco e gire as palmas das mãos até ficarem voltadas para frente. Essa será sua posição inicial.\nAgora, mantendo os braços parados, expire e faça a rosca com os halteres enquanto contrai os bíceps. Continue subindo os halteres até que os bíceps estejam totalmente contraídos e os halteres na altura dos ombros. Mantenha brevemente a posição contraída enquanto aperta os bíceps.\nDepois, inspire e comece a abaixar lentamente os halteres de volta à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Dumbbell Clean':
    'Comece em pé com um halter em cada mão e os pés afastados na largura dos ombros.\nAbaixe os halteres até o chão flexionando quadris e joelhos, empurrando o quadril para trás até que os halteres cheguem ao chão. Essa será sua posição inicial.\nPara iniciar o movimento, salte com força para cima estendendo quadris, joelhos e tornozelos para acelerar os halteres para cima. Mantendo uma pegada neutra nos halteres, mantenha os braços retos até atingir a extensão completa.\nApós a extensão completa, flexione novamente quadris e joelhos para receber o peso na posição de agachamento. Deixe os braços dobrarem, guiando os halteres até os ombros.\nAo receber o peso na posição de agachamento, estenda quadris e joelhos para terminar em pé com os halteres sobre os ombros.',
  'Dumbbell Floor Press':
    'Deite-se no chão segurando halteres nas mãos. Você pode manter os joelhos dobrados. Comece com os pesos totalmente estendidos acima de você.\nAbaixe os pesos até que a parte superior do braço toque o chão. Você pode manter os cotovelos junto ao corpo para enfatizar o tamanho e a força do tríceps, ou abrir os braços para os lados para focar no peito.\nFaça uma pausa embaixo e depois junte os pesos no topo estendendo os cotovelos.',
  'Dumbbell Flyes':
    'Deite-se em um banco reto com um halter em cada mão apoiado sobre as coxas. As palmas das mãos devem ficar voltadas uma para a outra.\nEm seguida, usando as coxas para ajudar a subir os halteres, levante-os um de cada vez para segurá-los à sua frente na largura dos ombros com as palmas voltadas uma para a outra. Suba os halteres como se estivesse fazendo um supino, mas pare e segure logo antes de estender completamente os cotovelos. Essa será sua posição inicial.\nCom uma leve flexão nos cotovelos para evitar estresse no tendão do bíceps, abaixe os braços para os dois lados em um arco amplo até sentir um alongamento no peito. Inspire durante esta parte do movimento. Dica: lembre-se de que durante todo o movimento os braços devem permanecer fixos; o movimento deve ocorrer apenas na articulação do ombro.\nRetorne os braços à posição inicial enquanto aperta os músculos do peito e expira. Dica: use o mesmo arco de movimento usado para abaixar os halteres.\nSegure por um segundo na posição contraída e repita o movimento pelo número de repetições prescrito.',
  'Dumbbell Incline Row':
    'Usando uma pegada neutra, apoie-se em um banco inclinado.\nPegue um halter em cada mão com pegada neutra, começando com os braços estendidos. Essa será sua posição inicial.\nRetraia as escápulas e flexione os cotovelos para fazer a remada, levando os halteres até a lateral do corpo.\nFaça uma pausa no topo do movimento e depois retorne à posição inicial.',
  'Dumbbell Incline Shoulder Raise':
    'Sente-se em um banco inclinado segurando um halter em cada mão sobre as coxas.\nLevante as pernas para impulsionar os halteres até os ombros e incline-se para trás. Posicione os halteres acima dos ombros com os braços estendidos. Os braços devem ficar perpendiculares ao chão, com as palmas voltadas para frente e os nós dos dedos apontando para o teto. Essa será sua posição inicial.\nMantendo os braços retos e travados, levante os halteres elevando os ombros do banco enquanto expira.\nTraga os halteres de volta à posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado.',
  'Dumbbell Lunges':
    'Fique em pé com o tronco ereto segurando dois halteres ao lado do corpo. Essa será sua posição inicial.\nDê um passo à frente com a perna direita, cerca de 60 cm do pé que permanece parado atrás, e abaixe o corpo mantendo o tronco ereto e o equilíbrio. Inspire ao descer. Nota: como em outros exercícios, não deixe o joelho avançar além dos dedos dos pés ao descer, pois isso gera estresse excessivo na articulação do joelho. Mantenha a canela da frente perpendicular ao chão.\nUsando principalmente o calcanhar, empurre para cima e volte à posição inicial enquanto expira.\nRepita o movimento pelo número de repetições recomendado e depois faça com a perna esquerda.',
  'Dumbbell Lying One-Arm Rear Lateral Raise':
    'Enquanto segura um halter em uma das mãos, deite-se de bruços em um banco ajustável levemente inclinado (cerca de 15 graus medidos a partir do chão). A outra mão pode segurar na perna do banco para maior estabilidade.\nPosicione a palma da mão que segura o halter de forma neutra (palma voltada para o tronco) mantendo o braço estendido com o cotovelo levemente flexionado. Essa será sua posição inicial.\nAgora levante o braço com o halter para o lado até que o cotovelo esteja na altura do ombro e o braço fique aproximadamente paralelo ao chão enquanto expira. Dica: mantenha o braço perpendicular ao tronco e estendido durante todo o movimento. Além disso, mantenha a contração no topo por um segundo.\nAbaixe lentamente o halter até a posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado.',
  'Dumbbell Lying Pronation':
    'Deite-se de bruços em um banco reto com um braço segurando um halter e a outra mão sobre o banco, dobrada para que você possa apoiar a cabeça nela.\nDobre o cotovelo do braço que segura o halter de modo a formar um ângulo de 90 graus entre o braço e o antebraço.\nAgora levante o braço de modo que o antebraço fique perpendicular ao chão e o braço perpendicular ao seu tronco. Dica: o braço deve ficar paralelo ao chão e também formar um ângulo de 90 graus com o tronco. Essa será sua posição inicial.\nAo expirar, rotacione externamente o antebraço de modo que o halter seja levantado para frente, mantendo o ângulo de 90 graus entre o braço e o antebraço. Continue essa rotação externa até que o antebraço fique paralelo ao chão. Nesse ponto, mantenha a contração por um segundo.\nAo inspirar, volte lentamente à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Dumbbell Lying Rear Lateral Raise':
    'Enquanto segura um halter em cada mão, deite-se de bruços em um banco ajustável levemente inclinado (cerca de 15 graus medidos a partir do chão).\nPosicione as palmas das mãos de forma neutra (palmas voltadas para o tronco) mantendo os braços estendidos com os cotovelos levemente flexionados. Essa será sua posição inicial.\nAgora levante os braços para os lados até que os cotovelos estejam na altura dos ombros e os braços fiquem aproximadamente paralelos ao chão enquanto expira. Dica: mantenha os braços perpendiculares ao tronco e estendidos durante todo o movimento. Além disso, mantenha a contração no topo por um segundo.\nAbaixe lentamente os halteres até a posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado e depois troque para o outro braço.',
  'Dumbbell Lying Supination':
    'Deite-se de lado em um banco reto com um braço segurando um halter e a outra mão sobre o banco, dobrada para que você possa apoiar a cabeça nela.\nDobre o cotovelo do braço que segura o halter de modo a formar um ângulo de 90 graus entre o braço e o antebraço.\nAgora levante o braço de modo que o antebraço fique paralelo ao chão e perpendicular ao seu tronco (Dica: o antebraço ficará diretamente à sua frente). O braço permanecerá parado junto ao tronco e deve ficar paralelo ao chão (alinhado com o tronco o tempo todo). Essa será sua posição inicial.\nAo expirar, rotacione externamente o antebraço de modo que o halter seja levantado em um movimento semicircular, mantendo o ângulo de 90 graus entre o braço e o antebraço. Continue essa rotação externa até que o antebraço fique perpendicular ao chão e apontando para o teto. Nesse ponto, mantenha a contração por um segundo.\nAo inspirar, volte lentamente à posição inicial.\nRepita pelo número de repetições recomendado e depois troque para o outro braço.',
  'Dumbbell One-Arm Shoulder Press':
    'Pegue um halter e sente-se em um banco de desenvolvimento militar ou em um banco utilitário com encosto, colocando o halter na vertical sobre a coxa, ou fique em pé com a coluna reta.\nFaça um clean com o halter para levá-lo à altura do ombro. A outra mão pode ficar totalmente estendida para o lado, junto à cintura ou segurando uma superfície fixa.\nGire o punho de modo que a palma da mão fique voltada para frente. Essa é sua posição inicial.\nAo expirar, empurre o halter para cima até que o braço fique completamente estendido.\nApós uma pausa de um segundo, desça lentamente à posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado e depois troque de braço.',
  'Dumbbell One-Arm Triceps Extension':
    'Pegue um halter e sente-se em um banco de desenvolvimento militar ou em um banco utilitário com encosto, colocando o halter na vertical sobre a coxa, ou fique em pé com a coluna reta.\nFaça um clean com o halter para levá-lo à altura do ombro e depois estenda o braço acima da cabeça de modo que o braço inteiro fique perpendicular ao chão e junto à cabeça. O halter deve ficar acima de você. A outra mão pode ficar totalmente estendida para o lado, junto à cintura, apoiando o braço que segura o halter ou segurando uma superfície fixa.\nGire o punho de modo que a palma da mão fique voltada para frente e o dedo mínimo aponte para o teto. Essa será sua posição inicial.\nAbaixe lentamente o halter atrás da cabeça mantendo o braço parado. Inspire durante este movimento e faça uma pausa quando o tríceps estiver totalmente alongado.\nRetorne à posição inicial contraindo o tríceps enquanto expira. Dica: é imprescindível que apenas o antebraço se mova. O braço deve permanecer parado junto à cabeça o tempo todo.\nRepita pelo número de repetições recomendado e troque de braço.',
  'Dumbbell One-Arm Upright Row':
    'Pegue um halter e fique em pé com a coluna reta e o braço estendido à sua frente com uma leve flexão no cotovelo. Essa será sua posição inicial. Dica: o halter deve ficar apoiado sobre a coxa com a palma da mão voltada para as coxas.\nMantenha a outra mão totalmente estendida para o lado, junto à cintura ou segurando uma superfície fixa. Essa será sua posição inicial.\nUse a parte lateral dos ombros para levantar o halter enquanto expira. O halter deve ficar próximo ao corpo ao subir. Continue levantando até que o halter esteja quase na altura do queixo. Dica: os cotovelos devem conduzir o movimento. Ao levantar o halter, o cotovelo deve estar sempre mais alto que o antebraço. Além disso, mantenha o tronco parado e faça uma pausa de um segundo no topo do movimento.\nAbaixe lentamente o halter de volta à posição inicial. Inspire durante esta parte do movimento.\nRepita pelo número de repetições recomendado e troque de braço.',
  'Dumbbell Prone Incline Curl':
    'Pegue um halter em cada mão e deite-se de bruços em um banco inclinado com os ombros próximos ao topo do encosto. Os joelhos podem ficar apoiados no assento ou você pode abrir as pernas para os lados (minha forma preferida).\nDeixe os braços se estenderem e pendurarem naturalmente à sua frente, de modo que fiquem perpendiculares ao chão.\nAgora mantenha os cotovelos junto às laterais do corpo e vire as palmas para frente. Essa será sua posição inicial.\nSuba os halteres contraindo os bíceps até que os braços estejam totalmente flexionados. Expire durante esta parte do movimento e certifique-se de que apenas os antebraços se movam. Os braços devem permanecer parados o tempo todo.\nAbaixe os halteres até que os braços estejam totalmente estendidos.\nRepita o número de vezes recomendado.',
  'Dumbbell Raise':
    'Pegue um halter em cada mão e fique em pé com a coluna reta e os braços estendidos ao lado do corpo com uma leve flexão nos cotovelos. Essa será sua posição inicial. Dica: os halteres devem ficar junto às coxas com as palmas das mãos voltadas para trás.\nUse a parte lateral dos ombros para levantar os halteres enquanto expira. Os halteres devem ficar ao lado do corpo ao subir. Continue levantando até que os halteres estejam quase na altura do queixo. Dica: os cotovelos devem conduzir o movimento. Ao levantar o halter, o cotovelo deve estar sempre mais alto que o antebraço. Além disso, mantenha o tronco parado e faça uma pausa de um segundo no topo do movimento.\nAbaixe lentamente os halteres de volta à posição inicial. Inspire durante esta parte do movimento.\nRepita pelo número de repetições recomendado.',
  'Dumbbell Rear Lunge':
    'Fique em pé com o tronco ereto segurando dois halteres ao lado do corpo. Essa será sua posição inicial.\nDê um passo para trás com a perna direita, cerca de 60 cm do pé esquerdo, e abaixe o corpo mantendo o tronco ereto e o equilíbrio. Inspire ao descer. Dica: como em outros exercícios, não deixe o joelho avançar além dos dedos dos pés ao descer, pois isso gera estresse excessivo na articulação do joelho. Mantenha a canela da frente perpendicular ao chão. Mantenha o tronco ereto durante o afundo; flexores do quadril flexíveis são importantes. Um afundo longo enfatiza o glúteo máximo; um afundo curto enfatiza os quadríceps.\nEmpurre para cima e volte à posição inicial enquanto expira. Dica: empurre com a parte da frente dos pés para acentuar os quadríceps. Para focar nos glúteos, empurre com os calcanhares.\nAgora repita com a perna oposta.',
  'Dumbbell Scaption':
    'Este exercício corretivo fortalece os músculos que estabilizam a escápula. Segure um peso leve em cada mão, pendendo ao lado do corpo. Os polegares devem apontar para cima.\nComece o movimento levantando os braços à sua frente, a cerca de 30 graus do centro. Os braços devem estar totalmente estendidos durante o movimento.\nContinue até que os braços fiquem paralelos ao chão e depois retorne à posição inicial.',
  'Dumbbell Seated Box Jump':
    'Posicione uma caixa a cerca de 60 cm ao lado de um banco. Segure um halter junto ao peito com as duas mãos e sente-se no banco de frente para a caixa. Essa será sua posição inicial.\nApoie firmemente os pés no chão enquanto se inclina para frente, estendendo quadris e joelhos para saltar para cima e para frente.\nAterrisse na caixa com os dois pés, absorvendo o impacto ao permitir que quadris e joelhos flexionem.\nDesça da caixa e retorne à posição inicial.',
  'Dumbbell Seated One-Leg Calf Raise':
    'Coloque um bloco no chão a cerca de 30 cm de um banco reto.\nSente-se em um banco reto e coloque um halter sobre a parte superior da coxa esquerda, cerca de 8 cm acima do joelho.\nAgora apoie a parte da frente do pé esquerdo no bloco. Essa será sua posição inicial.\nLevante os dedos dos pés o mais alto possível enquanto expira e contrai a panturrilha. Mantenha a contração por um segundo.\nRetorne lentamente à posição inicial, alongando o máximo possível para baixo.\nRepita pelo número de repetições prescrito e depois repita com a perna direita.',
  'Dumbbell Shoulder Press':
    'Enquanto segura um halter em cada mão, sente-se em um banco de desenvolvimento militar ou em um banco utilitário com encosto. Coloque os halteres na vertical sobre as coxas.\nAgora levante os halteres até a altura dos ombros um de cada vez, usando as coxas para ajudar a impulsioná-los até a posição.\nCertifique-se de girar os punhos para que as palmas das mãos fiquem voltadas para frente. Essa é sua posição inicial.\nAgora, expire e empurre os halteres para cima até que se toquem no topo.\nDepois, após uma breve pausa na posição contraída superior, abaixe lentamente os pesos de volta à posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado.',
  'Dumbbell Shrug':
    'Fique em pé, ereto, com um halter em cada mão (palmas voltadas para o tronco) e os braços estendidos ao lado do corpo.\nLevante os halteres elevando os ombros o mais alto possível enquanto expira. Mantenha a contração no topo por um segundo. Dica: os braços devem permanecer estendidos o tempo todo. Evite usar os bíceps para ajudar a levantar os halteres. Apenas os ombros devem subir e descer.\nAbaixe os halteres de volta à posição original.\nRepita pelo número de repetições recomendado.',
  'Dumbbell Side Bend':
    'Fique em pé com a coluna reta segurando um halter na mão esquerda (palma voltada para o tronco) enquanto a mão direita segura a cintura. Os pés devem ficar afastados na largura dos ombros. Essa será sua posição inicial.\nMantendo a coluna reta e a cabeça erguida, incline-se para a direita apenas a partir da cintura, o mais longe possível. Inspire enquanto se inclina para o lado. Depois segure por um segundo e volte à posição inicial enquanto expira. Dica: mantenha o resto do corpo parado.\nAgora repita o movimento, mas inclinando-se para a esquerda. Segure por um segundo e volte à posição inicial.\nRepita pelo número de repetições recomendado e depois troque de mão.',
  'Dumbbell Squat':
    'Fique em pé com a coluna reta segurando um halter em cada mão (palmas voltadas para as laterais das pernas).\nPosicione as pernas em uma base média na largura dos ombros com as pontas dos pés levemente para fora. Mantenha a cabeça erguida o tempo todo, pois olhar para baixo faz você perder o equilíbrio, e mantenha também a coluna reta. Essa será sua posição inicial. Nota: para fins desta explicação, usaremos a base média descrita acima, que trabalha o desenvolvimento geral; no entanto, você pode escolher qualquer uma das três bases descritas na seção de posições dos pés.\nComece a abaixar lentamente o tronco flexionando os joelhos enquanto mantém uma postura reta com a cabeça erguida. Continue descendo até que as coxas fiquem paralelas ao chão. Dica: se você executou o exercício corretamente, a frente dos joelhos deve formar uma linha reta imaginária com os dedos dos pés, perpendicular à frente. Se os joelhos passarem dessa linha imaginária (se ultrapassarem os dedos dos pés), você está gerando estresse excessivo no joelho e o exercício foi executado de forma incorreta.\nComece a subir o tronco enquanto expira, empurrando o chão principalmente com o calcanhar enquanto estende novamente as pernas e volta à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Dumbbell Squat To A Bench':
    'Fique em pé com a coluna reta e um banco reto atrás de você, segurando um halter em cada mão (palmas voltadas para as laterais das pernas).\nPosicione as pernas em uma base média na largura dos ombros com as pontas dos pés levemente para fora. Mantenha a cabeça erguida o tempo todo, pois olhar para baixo faz você perder o equilíbrio, e mantenha também a coluna reta. Essa será sua posição inicial. Nota: para fins desta explicação, usaremos a base média descrita acima, que trabalha o desenvolvimento geral; no entanto, você pode escolher qualquer uma das três bases descritas na seção de posições dos pés.\nComece a abaixar lentamente o tronco flexionando os joelhos enquanto mantém uma postura reta com a cabeça erguida. Continue descendo até tocar levemente o banco atrás de você. Inspire durante esta parte do movimento. Dica: se você executou o exercício corretamente, a frente dos joelhos deve formar uma linha reta imaginária com os dedos dos pés, perpendicular à frente. Se os joelhos passarem dessa linha imaginária (se ultrapassarem os dedos dos pés), você está gerando estresse excessivo no joelho e o exercício foi executado de forma incorreta.\nComece a subir enquanto expira, empurrando o chão principalmente com o calcanhar enquanto estende novamente as pernas e volta à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Dumbbell Step Ups':
    'Fique em pé com a coluna reta segurando um halter em cada mão (palmas voltadas para as laterais das pernas).\nColoque o pé direito na plataforma elevada. Suba na plataforma estendendo o quadril e o joelho da perna direita. Use principalmente o calcanhar para elevar o resto do corpo e coloque o pé da perna esquerda também na plataforma. Expire enquanto executa a força necessária para subir.\nDesça com a perna esquerda flexionando o quadril e o joelho da perna direita enquanto inspira. Retorne à posição original em pé colocando o pé direito ao lado do esquerdo na posição inicial.\nRepita com a perna direita pelo número de repetições recomendado e depois faça com a perna esquerda.',
  'Dumbbell Tricep Extension -Pronated Grip':
    'Deite-se em um banco reto segurando dois halteres diretamente acima dos ombros. Os braços devem estar totalmente estendidos e formar um ângulo de 90 graus entre o tronco e o chão.\nAs palmas das mãos devem ficar voltadas para frente e os cotovelos junto ao corpo. Essa será sua posição inicial.\nAgora, inspire e abaixe lentamente os halteres até ficarem próximos às orelhas. Mantenha os braços parados e os cotovelos junto ao corpo.\nDepois, expire e use os tríceps para retornar o peso à posição inicial.',
  'Dynamic Back Stretch':
    'Fique em pé com os pés afastados na largura dos ombros. Essa será sua posição inicial.\nMantendo os braços retos, balance-os para cima à sua frente de 5 a 10 vezes, aumentando a amplitude de movimento a cada vez até que os braços fiquem acima da cabeça.',
  'Dynamic Chest Stretch':
    'Fique em pé com as mãos juntas e os braços estendidos diretamente à sua frente. Essa será sua posição inicial.\nMantendo os braços retos, leve-os rapidamente para trás o mais longe possível e depois de volta para frente, de forma semelhante a uma palma exagerada. Repita de 5 a 10 vezes, aumentando a velocidade conforme avança.',
  'EZ-Bar Curl':
    'Fique em pé com a coluna reta segurando uma barra W na pegada externa larga. As palmas das mãos devem ficar voltadas para frente e levemente inclinadas para dentro devido ao formato da barra. Mantenha os cotovelos próximos ao tronco. Essa será sua posição inicial.\nAgora, mantendo os braços parados, expire e suba o peso para frente enquanto contrai os bíceps. Concentre-se em mover apenas os antebraços.\nContinue subindo o peso até que os bíceps estejam totalmente contraídos e a barra na altura dos ombros. Mantenha por um momento a posição contraída superior e aperte os bíceps.\nDepois inspire e abaixe lentamente a barra de volta à posição inicial.\nRepita pelo número de repetições recomendado.',
  'EZ-Bar Skullcrusher':
    'Usando uma pegada fechada, levante a barra W e segure-a com os cotovelos para dentro enquanto se deita no banco. Os braços devem ficar perpendiculares ao chão. Essa será sua posição inicial.\nMantendo os braços parados, abaixe a barra permitindo que os cotovelos flexionem. Inspire durante esta parte do movimento. Faça uma pausa quando a barra estiver diretamente acima da testa.\nLevante a barra de volta à posição inicial estendendo os cotovelos e expirando.\nRepita.',
  'Elbow Circles':
    'Sente-se ou fique em pé com os pés ligeiramente afastados.\nColoque as mãos sobre os ombros com os cotovelos na altura dos ombros e apontando para fora.\nFaça lentamente um círculo com os cotovelos. Expire ao iniciar o círculo e inspire ao completá-lo.',
  'Elbow to Knee':
    'Deite-se no chão, cruzando a perna direita sobre o joelho esquerdo flexionado. Entrelace as mãos atrás da cabeça, começando com as escápulas no chão. Essa será sua posição inicial.\nExecute o movimento flexionando a coluna e rotacionando o tronco para levar o cotovelo esquerdo em direção ao joelho direito.\nRetorne à posição inicial e repita o movimento pelo número de repetições desejado antes de trocar de lado.',
  'Elbows Back':
    'Fique em pé com a coluna reta.\nColoque as duas mãos na região lombar, com os dedos apontando para baixo e os cotovelos para fora.\nDepois leve suavemente os cotovelos para trás, tentando juntá-los.',
  'Elevated Back Lunge':
    'Posicione uma barra em um rack na altura dos ombros, carregada com um peso adequado. Coloque uma plataforma baixa e elevada atrás de você.\nRetire a barra do rack e apoie-a na parte superior das costas, mantendo as costas arqueadas e firmes. Suba na plataforma elevada com os dois pés. Essa será sua posição inicial.\nComece dando um passo para trás com uma perna. Desça flexionando quadris e joelhos até que o joelho toque o chão.\nFaça uma pausa e estenda quadris e joelhos para subir, retornando completamente à posição inicial antes de alternar.',
  'Elevated Cable Rows':
    'Arranje uma plataforma de algum tipo (pode ser uma plataforma de aeróbica ou de elevação de panturrilhas) com cerca de 10 a 15 cm de altura.\nColoque-a sobre o assento da máquina de remada na polia.\nSente-se na máquina e apoie os pés na plataforma frontal ou na barra transversal disponível, certificando-se de que os joelhos estejam levemente flexionados e não travados.\nIncline-se para frente mantendo o alinhamento natural da coluna e segure as pegadas em V.\nCom os braços estendidos, puxe para trás até que o tronco forme um ângulo de 90 graus com as pernas. As costas devem ficar levemente arqueadas e o peito estufado. Você deve sentir um bom alongamento nos dorsais enquanto segura a barra à sua frente. Essa é a posição inicial do exercício.\nMantendo o tronco parado, puxe as pegadas em direção ao tronco mantendo os braços próximos a ele até tocar os abdominais. Expire durante esse movimento. Nesse ponto, você deve estar contraindo os músculos das costas com força. Mantenha essa contração por um segundo e volte lentamente à posição original enquanto inspira.\nRepita pelo número de repetições recomendado.',
  'Elliptical Trainer':
    'Para começar, suba no elíptico e selecione a opção desejada no menu. A maioria dos elípticos tem um modo manual, ou você pode selecionar um programa. Normalmente, você pode inserir sua idade e peso para estimar a quantidade de calorias queimadas durante o exercício. A inclinação pode ser ajustada para alterar a intensidade do treino.\nAs alças podem ser usadas para monitorar sua frequência cardíaca e ajudar a manter uma intensidade adequada.',
  'Exercise Ball Crunch':
    'Deite-se sobre uma bola de exercício com a curvatura da lombar apoiada contra a superfície esférica da bola. Os joelhos devem estar flexionados e os pés firmemente apoiados no chão. A parte superior do tronco deve ficar pendendo sobre o topo da bola. Os braços devem ficar ao lado do corpo ou cruzados sobre o peito, pois essas posições evitam tensão no pescoço (ao contrário da posição com as mãos atrás da cabeça).\nAbaixe o tronco até uma posição de alongamento mantendo o pescoço parado o tempo todo. Essa será sua posição inicial.\nCom o quadril parado, flexione a cintura contraindo os abdominais e enrole os ombros e o tronco para cima até sentir uma boa contração nos abdominais. Os braços devem simplesmente deslizar pela lateral das pernas se estiverem ao lado do corpo, ou ficar sobre o peito se estiverem cruzados. A lombar deve permanecer sempre em contato com a bola. Expire durante este movimento e mantenha a contração por um segundo.\nAo inspirar, volte à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Exercise Ball Pull-In':
    'Coloque uma bola de exercício por perto e deite-se no chão de frente para ela, com as mãos no chão na largura dos ombros, em posição de flexão de braço.\nAgora coloque a parte inferior das canelas sobre a bola de exercício. Dica: neste ponto, as pernas devem estar totalmente estendidas com as canelas sobre a bola e a parte superior do corpo em uma posição de flexão, sustentada pelos dois braços estendidos à sua frente. Essa será sua posição inicial.\nMantendo a coluna completamente reta e a parte superior do corpo parada, puxe os joelhos em direção ao peito enquanto expira, deixando a bola rolar para frente sob os tornozelos. Contraia os abdominais e mantenha essa posição por um segundo.\nAgora estenda lentamente as pernas, rolando a bola de volta à posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado.',
  'Extended Range One-Arm Kettlebell Floor Press':
    'Deite-se no chão e posicione um kettlebell para empurrar com um braço. O kettlebell deve ser segurado pela alça. A perna do mesmo lado que está empurrando deve ficar flexionada, com o joelho cruzando a linha média do corpo.\nEmpurre o kettlebell estendendo o cotovelo e aduzindo o braço, empurrando-o acima do corpo. Retorne à posição inicial.',
  'External Rotation':
    'Deite-se de lado em um banco reto com um braço segurando um halter e a outra mão sobre o banco, dobrada para que você possa apoiar a cabeça nela.\nDobre o cotovelo do braço que segura o halter de modo a formar um ângulo de 90 graus entre o braço e o antebraço. Dica: mantenha o braço paralelo ao tronco.\nAgora dobre o cotovelo mantendo o braço parado. Dessa forma, o antebraço ficará paralelo ao chão e perpendicular ao seu tronco (Dica: o antebraço ficará diretamente à sua frente). O braço permanecerá parado junto ao tronco e deve ficar paralelo ao chão (alinhado com o tronco o tempo todo). Essa será sua posição inicial.\nAo expirar, rotacione externamente o antebraço de modo que o halter seja levantado em um movimento semicircular, mantendo o ângulo de 90 graus entre o braço e o antebraço. Continue essa rotação externa até que o antebraço fique perpendicular ao chão e apontando para o teto. Nesse ponto, mantenha a contração por um segundo.\nAo inspirar, volte lentamente à posição inicial.\nRepita pelo número de repetições recomendado e depois troque para o outro braço.',
  'External Rotation with Band':
    'Prenda a faixa em um poste. A faixa deve ficar na mesma altura do seu cotovelo. Fique em pé com o lado esquerdo voltado para a faixa, a alguns passos de distância.\nSegure a ponta da faixa com a mão direita e mantenha o cotovelo firmemente junto ao lado do corpo. Recomendamos segurar uma almofada ou rolo de espuma com o cotovelo para mantê-lo firmemente no lugar.\nCom o braço em posição, o cotovelo deve estar flexionado a 90 graus com a mão cruzando a frente do tronco. Essa será sua posição inicial.\nExecute o movimento rotacionando o braço em um movimento de backhand, mantendo o cotovelo no lugar.\nContinue o mais longe que conseguir, faça uma pausa e depois retorne à posição inicial.',
  'External Rotation with Cable':
    'Ajuste o cabo na mesma altura do seu cotovelo. Fique em pé com o lado esquerdo voltado para o cabo, a alguns passos de distância.\nSegure a pegada com a mão direita e mantenha o cotovelo firmemente junto ao lado do corpo. Recomendamos segurar uma almofada ou rolo de espuma com o cotovelo para mantê-lo firmemente no lugar.\nCom o braço em posição, o cotovelo deve estar flexionado a 90 graus com a mão cruzando a frente do tronco. Essa será sua posição inicial.\nExecute o movimento rotacionando o braço em um movimento de backhand, mantendo o cotovelo no lugar.',
  'Face Pull':
    'De frente para uma polia alta com uma corda ou pegadas duplas, puxe o peso diretamente em direção ao rosto, separando as mãos enquanto puxa. Mantenha os braços paralelos ao chão.',
  "Farmer's Walk":
    "Existem vários implementos que podem ser usados para o farmer's walk. Também pode ser feito com halteres pesados ou barras curtas se esses implementos não estiverem disponíveis. Comece em pé entre os implementos.\nDepois de segurar as alças, levante-os empurrando com os calcanhares, mantendo a coluna reta e a cabeça erguida.\nCaminhe dando passos curtos e rápidos, e não se esqueça de respirar. Avance por uma distância determinada, normalmente de 15 a 30 metros, o mais rápido possível.",
  'Fast Skipping':
    'Comece em uma posição relaxada com uma perna levemente à frente. Essa será sua posição inicial.\nFaça o skipping executando um padrão de passo e salto de direita-direita-passo para esquerda-esquerda-passo, e assim por diante, alternando de um lado para o outro.\nExecute o skipping rápido mantendo contato próximo com o chão e reduzindo o tempo no ar, movendo-se o mais rápido possível.',
  'Finger Curls':
    'Segure uma barra com as duas mãos e as palmas voltadas para cima; mãos afastadas aproximadamente na largura dos ombros.\nApoie os pés no chão, a uma distância ligeiramente maior que a largura dos ombros. Essa será sua posição inicial.\nAbaixe a barra o máximo possível estendendo os dedos. Deixando a barra rolar pelas mãos, segure-a com a última articulação dos dedos.\nAgora suba a barra o mais alto possível fechando as mãos enquanto expira. Mantenha a contração no topo.',
  'Flat Bench Cable Flyes':
    'Posicione um banco reto entre duas polias baixas de modo que, ao se deitar nele, seu peito fique alinhado com as polias.\nDeite-se de costas no banco e mantenha os pés no chão.\nPeça para alguém entregar as pegadas em cada mão. Você segurará cada pegada individual com as palmas voltadas para cima.\nEstenda os braços para os lados com uma leve flexão nos cotovelos. Dica: você manterá essa flexão constante durante todo o movimento. Os braços devem ficar paralelos ao chão. Essa é sua posição inicial.\nAgora comece a levantar os braços em um movimento semicircular diretamente à sua frente, puxando os cabos até que as duas mãos se encontrem no topo do movimento. Contraia o peito durante esse movimento e expire. Além disso, mantenha a contração por um segundo no topo. Dica: quando executado corretamente, na posição superior deste movimento, os braços devem ficar perpendiculares ao tronco e ao chão, tocando-se acima do peito.\nVolte lentamente à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Flat Bench Leg Pull-In':
    'Deite-se em um tapete de exercício ou em um banco reto com as pernas para fora da extremidade.\nColoque as mãos sob os glúteos com as palmas para baixo, ou ao lado do corpo segurando no banco (ou com as palmas para baixo ao lado do corpo se estiver em um tapete). Além disso, estenda as pernas retas. Essa será sua posição inicial.\nFlexione os joelhos e puxe a parte superior das coxas em direção ao abdômen enquanto expira. Continue esse movimento até que os joelhos estejam perto do peito. Mantenha a posição contraída por um segundo.\nAo inspirar, volte lentamente à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Flat Bench Lying Leg Raise':
    'Deite-se com as costas apoiadas em um banco e as pernas estendidas à sua frente, para fora da extremidade.\nColoque as mãos sob os glúteos com as palmas para baixo, ou ao lado do corpo segurando no banco. Essa será sua posição inicial.\nMantendo as pernas estendidas, o mais retas possível, com os joelhos levemente flexionados mas travados, levante as pernas até que formem um ângulo de 90 graus com o chão. Expire durante esta parte do movimento e mantenha a contração no topo por um segundo.\nAgora, ao inspirar, abaixe lentamente as pernas de volta à posição inicial.',
  'Flexor Incline Dumbbell Curls':
    'Segure o halter mais para o lado distante de você, de modo a ter mais peso no lado mais próximo. (Isso pode ser feito com bom efeito em todos os exercícios de bíceps com halteres.) Agora faça uma rosca inclinada normal com halteres, mas mantenha os punhos o mais para trás possível para neutralizar qualquer estresse sobre eles.\nSente-se em um banco inclinado a 45 graus segurando um halter em cada mão.\nDeixe os braços pendurados ao lado do corpo, com os cotovelos para dentro, e vire as palmas das mãos para frente com os polegares apontando para longe do corpo. Dica: você manterá essa posição das mãos durante todo o movimento, pois não deve haver rotação das mãos ao subir. Essa será sua posição inicial.\nSuba os dois halteres ao mesmo tempo até que os bíceps estejam totalmente contraídos e expire. Dica: não balance os braços nem use impulso. Mantenha um movimento controlado o tempo todo. Mantenha a posição contraída por um segundo no topo.\nAo inspirar, volte lentamente à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Floor Glute-Ham Raise':
    'Você pode usar um parceiro para este exercício ou prender os pés sob algo estável.\nComece de joelhos com a parte superior das pernas e o tronco eretos. Se usar um parceiro, ele segurará firmemente seus pés para mantê-lo em posição. Essa será sua posição inicial.\nAbaixe-se estendendo os joelhos, tomando cuidado para NÃO flexionar os quadris ao ir para frente.\nColoque as mãos à sua frente ao chegar ao chão. Este movimento é muito difícil e você pode não conseguir fazê-lo sem ajuda. Use os braços para empurrar levemente o chão e ajudar no retorno à posição inicial.',
  'Floor Press':
    'Ajuste os ganchos em J na altura adequada para apoiar a barra. Comece deitado no chão com a cabeça perto da extremidade de um rack de potência. Mantendo as escápulas unidas, retire a barra dos ganchos.\nAbaixe a barra em direção à parte inferior do peito ou à parte alta do abdômen, apertando a barra e tentando separá-la como se quisesse parti-la. Mantenha os cotovelos junto ao corpo durante todo o movimento. Abaixe a barra até que a parte superior do braço toque o chão e faça uma pausa, evitando que o peso bata ou quique.\nEmpurre a barra para cima o mais rápido que puder, mantendo a barra, os punhos e os cotovelos alinhados.',
  'Floor Press with Chains':
    'Ajuste os ganchos em J na altura adequada para apoiar a barra. Para este exercício, coloque as correntes diretamente sobre a extremidade da barra, tentando manter as pontas longe das anilhas.\nComece deitado no chão com a cabeça perto da extremidade de um rack de potência. Mantendo as escápulas unidas, retire a barra dos ganchos.\nAbaixe a barra em direção à parte inferior do peito ou à parte alta do abdômen, apertando a barra e tentando separá-la como se quisesse parti-la. Mantenha os cotovelos junto ao corpo durante todo o movimento. Abaixe a barra até que a parte superior do braço toque o chão e faça uma pausa, evitando que o peso bata ou quique.\nEmpurre a barra para cima o mais rápido que puder, mantendo a barra, os punhos e os cotovelos alinhados.',
  'Flutter Kicks':
    'Em um banco reto, deite-se de bruços com os quadris na borda do banco, as pernas retas com as pontas dos pés longe do chão e os braços sobre o banco segurando a borda da frente.\nContraia os glúteos e os posteriores de coxa e estique as pernas até ficarem na altura dos quadris. Esta será sua posição inicial.\nInicie o movimento levantando a perna esquerda mais alto que a direita.\nEm seguida, abaixe a perna esquerda enquanto levanta a direita.\nContinue alternando dessa forma (como se estivesse batendo pernas na água) até completar as repetições recomendadas para cada perna. Mantenha um movimento controlado o tempo todo. Dica: respire normalmente enquanto executa este movimento.',
  'Foot-SMR':
    'Este exercício alonga a fáscia dos músculos dos pés. Comece sentado sem sapatos. Usando um rolo para pés ou um objeto semelhante, como um pequeno pedaço de cano de PVC, apoie o pé sobre o rolo ao longo do arco do pé. Esta será sua posição inicial.\nPressione com firmeza, rolando ao longo do arco do pé. Mantenha por 10 a 30 segundos e depois troque de pé.',
  'Forward Drag with Press':
    'Prenda ao trenó um acessório de corrente ou corda com duas alças. Você deve ficar de costas para o trenó, segurando uma alça em cada mão.\nComece o movimento dando um passo à frente. Inclinando-se para a frente, estenda as pernas e os quadris para avançar, fazendo uma pausa a cada passo para estender os cotovelos, empurrando as mãos para a frente. Dê passos à frente até voltar à posição inicial, pronto para empurrar.',
  'Frankenstein Squat':
    'Este exercício ensina a posição correta da barra e do seu corpo durante o clean e o agachamento frontal.\nColoque a barra na parte da frente dos ombros, soltando a pegada e estendendo os braços à sua frente. Os ombros devem ser empurrados para a frente para criar uma prateleira, e a barra deve ficar em contato com a garganta. Mova apenas as escápulas para a frente; não arredonde a coluna torácica.\nAgache flexionando os joelhos e os quadris, sentando entre as pernas. Mantenha o tronco ereto, os braços elevados e os ombros para a frente, e a barra deve permanecer no lugar. Desça até o fundo do agachamento, até que os posteriores de coxa toquem as panturrilhas.\nVolte à posição em pé empurrando com a parte da frente do calcanhar e estendendo os joelhos e os quadris.',
  'Freehand Jump Squat':
    'Cruze os braços sobre o peito.\nCom a cabeça erguida e as costas retas, posicione os pés na largura dos ombros.\nMantendo as costas retas e o peito elevado, agache enquanto inspira até que a parte superior das coxas fique paralela ao chão, ou mais baixo.\nAgora, empurrando principalmente com a parte da frente dos pés, salte para cima o mais alto possível, usando as coxas como molas. Expire durante esta parte do movimento.\nQuando tocar o chão novamente, agache imediatamente e salte de novo.\nRepita pelo número de repetições recomendado.',
  'Frog Hops':
    'Fique em pé com as mãos atrás da cabeça e agache mantendo o tronco ereto e a cabeça erguida. Esta será sua posição inicial.\nSalte para a frente vários pés, evitando saltar alto sem necessidade. Quando os pés tocarem o chão, absorva o impacto com as pernas e salte novamente. Repita essa ação de 5 a 10 vezes.',
  'Frog Sit-Ups':
    'Deite-se com as costas apoiadas no chão (ou em um tapete) e as pernas estendidas à sua frente.\nAgora dobre os joelhos e aproxime a parte externa das coxas do chão (ou do tapete) enquanto une as solas dos pés.\nAgora tente empurrar as duas solas e trazê-las o mais perto possível de você, mantendo a parte externa das coxas no chão (ou quase tocando). Dica: nessa posição suas pernas devem formar um losango.\nAgora cruze os braços à sua frente tocando os ombros opostos. Esta será sua posição inicial.\nAo expirar, achate a lombar contra o chão enquanto enrola o tronco para cima. Dica: é como fazer o primeiro quarto do movimento de um abdominal. Segure um segundo na posição superior.\nAo inspirar, volte lentamente à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Front Barbell Squat':
    'Este exercício é melhor executado dentro de um rack de agachamento por segurança. Para começar, posicione a barra em um rack na altura que melhor corresponda à sua estatura. Depois de escolher a altura correta e carregar a barra, leve os braços por baixo da barra mantendo os cotovelos altos e a parte superior do braço levemente acima da paralela ao chão. Apoie a barra sobre os deltoides e cruze os braços segurando a barra para ter controle total.\nRetire a barra do rack empurrando primeiro com as pernas e endireitando o tronco ao mesmo tempo.\nAfaste-se do rack e posicione as pernas em uma base média, na largura dos ombros, com as pontas dos pés levemente voltadas para fora. Mantenha a cabeça erguida o tempo todo, pois olhar para baixo faz você perder o equilíbrio, e mantenha também as costas retas. Esta será sua posição inicial. (Nota: para esta explicação usaremos a base média descrita acima, que trabalha o desenvolvimento geral; porém, você pode escolher qualquer uma das três bases descritas na seção de posicionamento dos pés).\nComece a abaixar lentamente a barra dobrando os joelhos, mantendo uma postura reta com a cabeça erguida. Continue descendo até que o ângulo entre a coxa e a panturrilha fique ligeiramente menor que 90 graus (ponto em que as coxas ficam abaixo da paralela ao chão). Inspire durante esta parte do movimento. Dica: se você executou o exercício corretamente, a frente dos joelhos deve formar uma linha reta imaginária com as pontas dos pés, perpendicular à frente. Se os joelhos passarem dessa linha imaginária (se passarem dos pés), você está colocando estresse excessivo no joelho e o exercício foi executado de forma incorreta.\nComece a subir a barra enquanto expira, empurrando o chão principalmente com o meio do pé, enquanto estica as pernas novamente e volta à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Front Barbell Squat To A Bench':
    'Este exercício é melhor executado dentro de um rack de agachamento por segurança. Para começar, coloque um banco reto atrás de você e posicione a barra em um rack na altura que melhor corresponda à sua estatura. Depois de escolher a altura correta e carregar a barra, leve os braços por baixo da barra mantendo os cotovelos altos e a parte superior do braço levemente acima da paralela ao chão. Apoie a barra sobre os deltoides e cruze os braços segurando a barra para ter controle total.\nRetire a barra do rack empurrando primeiro com as pernas e endireitando o tronco ao mesmo tempo.\nAfaste-se do rack e posicione as pernas em uma base média, na largura dos ombros, com as pontas dos pés levemente voltadas para fora. Mantenha a cabeça erguida o tempo todo, pois olhar para baixo faz você perder o equilíbrio, e mantenha também as costas retas. Esta será sua posição inicial. (Nota: para esta explicação usaremos a base média descrita acima, que trabalha o desenvolvimento geral; porém, você pode escolher qualquer uma das três bases descritas na seção de posicionamento dos pés).\nComece a abaixar lentamente a barra dobrando os joelhos, mantendo uma postura reta com a cabeça erguida. Continue descendo até tocar o banco com os glúteos. Inspire durante esta parte do movimento. Dica: se você executou o exercício corretamente, a frente dos joelhos deve formar uma linha reta imaginária com as pontas dos pés, perpendicular à frente. Se os joelhos passarem dessa linha imaginária (se passarem dos pés), você está colocando estresse excessivo no joelho e o exercício foi executado de forma incorreta.\nComece a subir a barra enquanto expira, empurrando o chão principalmente com o calcanhar, enquanto estica as pernas novamente e volta à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Front Box Jump':
    'Comece com uma caixa de altura adequada a 1-2 pés à sua frente. Fique em pé com os pés afastados na largura dos ombros. Esta será sua posição inicial.\nFaça um agachamento curto como preparação para o salto, levando os braços para trás.\nRebata dessa posição, estendendo quadris, joelhos e tornozelos para saltar o mais alto possível. Leve os braços para a frente e para cima.\nAterrisse sobre a caixa com os joelhos flexionados, absorvendo o impacto com as pernas. Você pode saltar da caixa de volta ao chão, ou preferencialmente descer um pé de cada vez.',
  'Front Cable Raise':
    'Selecione a carga em uma polia baixa e segure com a mão esquerda o acessório de mão individual preso à polia baixa.\nFique de costas para a polia e deixe o braço estendido para baixo, com o acessório à frente das coxas na extensão do braço e com a palma da mão voltada para as coxas. Esta será sua posição inicial.\nMantendo o tronco estável (sem balançar), levante o braço esquerdo para a frente com uma leve flexão do cotovelo e a palma da mão sempre voltada para baixo. Continue subindo até o braço ficar levemente acima da paralela ao chão. Expire ao executar esta parte do movimento e faça uma pausa de um segundo no topo.\nAgora, ao inspirar, abaixe o braço lentamente até a posição inicial.\nDepois de completar todas as repetições recomendadas com este braço, troque de braço e execute o exercício com o direito.',
  'Front Cone Hops (or hurdle hops)':
    'Monte uma fileira de cones ou outras barreiras pequenas, colocando-os a alguns pés de distância um do outro.\nFique em pé diante do primeiro cone com os pés afastados na largura dos ombros. Esta será sua posição inicial.\nComece saltando com os dois pés sobre o primeiro cone, balançando os dois braços ao saltar.\nAbsorva o impacto da aterrissagem dobrando os joelhos e rebata do primeiro salto para saltar sobre o próximo cone.\nContinue até ter saltado sobre todos os cones.',
  'Front Dumbbell Raise':
    'Pegue um par de halteres e fique em pé com o tronco reto e os halteres à frente das coxas, na extensão dos braços, com as palmas das mãos voltadas para as coxas. Esta será sua posição inicial.\nMantendo o tronco estável (sem balançar), levante o halter esquerdo para a frente com uma leve flexão do cotovelo e as palmas das mãos sempre voltadas para baixo. Continue subindo até o braço ficar levemente acima da paralela ao chão. Expire ao executar esta parte do movimento e faça uma pausa de um segundo no topo. Inspire após a pausa.\nAgora abaixe lentamente o halter até a posição inicial enquanto levanta simultaneamente o halter direito.\nContinue alternando dessa forma até completar todas as repetições recomendadas com cada braço.',
  'Front Incline Dumbbell Raise':
    'Sente-se em um banco inclinado com a inclinação entre 30 e 60 graus, segurando um halter em cada mão. Dica: você pode mudar o ângulo para trabalhar o músculo de forma ligeiramente diferente a cada vez.\nEstenda os braços retos à sua frente com as palmas voltadas para baixo e os halteres a cerca de 1 polegada acima das coxas. Esta será sua posição inicial.\nLevante lentamente os halteres para cima até ficarem levemente acima dos ombros, mantendo os cotovelos travados. Contraia no topo por um segundo e expire durante esta parte do movimento. Dica: mantenha a cabeça apoiada no banco e as pernas no chão o tempo todo.\nAbaixe os braços até a posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado.',
  'Front Leg Raises':
    'Fique em pé ao lado de uma cadeira ou outro apoio, segurando-se com uma mão.\nBalance a perna para a frente, mantendo-a reta. Continue com um balanço para trás, levando a perna o mais atrás que sua flexibilidade permitir. Repita de 5 a 10 vezes e depois troque de perna.',
  'Front Plate Raise':
    'Em pé, com o corpo reto, segure uma anilha com as duas mãos nas posições de 3 e 9 horas. As palmas devem ficar voltadas uma para a outra, e os braços devem estar estendidos e travados com uma leve flexão nos cotovelos, com a anilha embaixo, perto da cintura e à sua frente o mais baixo possível. Dica: os braços permanecerão nessa posição durante todo o exercício. Esta será sua posição inicial.\nLevante lentamente a anilha enquanto expira até ficar um pouco acima do nível dos ombros. Mantenha a contração por um segundo. Dica: não balance o peso nem dobre os cotovelos. O tronco também deve permanecer estável durante todo o movimento.\nAo inspirar, abaixe lentamente a anilha até a posição inicial.\nRepita pelo número de repetições recomendado.',
  'Front Raise And Pullover':
    'Deite-se em um banco reto segurando uma barra com pegada pronada (palmas para baixo) com cerca de 15 polegadas de afastamento.\nColoque a barra sobre a parte alta das coxas, estenda os braços e trave-os mantendo uma leve flexão nos cotovelos. Esta será sua posição inicial.\nAgora levante o peso em um movimento semicircular mantendo os braços retos enquanto inspira. Continue o mesmo movimento até a barra ficar do outro lado, acima da cabeça. (Dica: a barra percorrerá aproximadamente 180 graus). Nesse ponto os braços devem estar paralelos ao chão com as palmas das mãos voltadas para o teto.\nAgora retorne a barra à posição inicial invertendo o movimento enquanto expira.\nRepita pelo número de repetições recomendado.',
  'Front Squat (Clean Grip)':
    'Para começar, posicione a barra em um rack levemente abaixo do nível dos ombros. Apoie a barra sobre os deltoides, pressionando as clavículas e tocando levemente a garganta. Suas mãos devem estar na pegada de clean, tocando a barra apenas com os dedos para ajudar a mantê-la em posição.\nRetire a barra do rack empurrando primeiro com as pernas e endireitando o tronco ao mesmo tempo. Afaste-se do rack e posicione as pernas em uma base média, na largura dos ombros, com as pontas dos pés levemente voltadas para fora. Mantenha a cabeça e os cotovelos elevados o tempo todo. Esta será sua posição inicial.\nDobre os joelhos, sentando entre as pernas. Continue descendo até que os posteriores de coxa toquem as panturrilhas. Mantenha os joelhos alinhados com os pés usando conscientemente os abdutores para empurrá-los para fora enquanto agacha.\nComece a subir a barra enquanto expira, empurrando o chão principalmente com o calcanhar ou o meio do pé, enquanto estica as pernas novamente e volta à posição inicial.',
  'Front Squats With Two Kettlebells':
    'Faça o clean de dois kettlebells até os ombros. Faça isso estendendo as pernas e os quadris enquanto puxa os kettlebells em direção aos ombros. Gire os punhos ao fazer isso.\nOlhando para a frente o tempo todo, agache o mais baixo que puder e faça uma pausa embaixo. Ao agachar, empurre os joelhos para fora. Você deve descer entre as pernas, mantendo o tronco ereto, com a cabeça e o peito erguidos.\nSuba novamente empurrando com os calcanhares e repita.',
  'Front Two-Dumbbell Raise':
    'Pegue um par de halteres e fique em pé com o tronco reto e os halteres à frente das coxas, na extensão dos braços, com as palmas das mãos voltadas para as coxas. Esta será sua posição inicial.\nMantendo o tronco estável (sem balançar), levante os halteres para a frente com uma leve flexão do cotovelo e as palmas das mãos sempre voltadas para baixo. Continue subindo até os braços ficarem levemente acima da paralela ao chão. Expire ao executar esta parte do movimento e faça uma pausa de um segundo no topo.\nAo inspirar, abaixe lentamente os halteres até a posição inicial.\nRepita pelo número de repetições recomendado.',
  'Full Range-Of-Motion Lat Pulldown':
    'Em pé ou sentado em um banco alto, segure dois estribos presos às polias altas. Segure com a mão oposta, de modo que os braços fiquem cruzados à sua frente e as palmas voltadas para a frente.\nMantendo o peito elevado e um leve arco na lombar, puxe as alças para baixo como em uma puxada normal. A amplitude de movimento será mais em forma de arco. Durante o movimento, gire as mãos para que, na posição inferior, as palmas fiquem voltadas uma para a outra em vez de para a frente. Retorne lentamente à posição inicial e repita.',
  'Gironda Sternum Chins':
    'Segure a barra fixa com pegada supinada (palmas voltadas para você) na largura dos ombros.\nAgora pendure-se com os braços totalmente estendidos, estufe o peito e incline-se para trás. Dica: você ficará inclinado para trás durante todo o movimento. Esta será sua posição inicial.\nComece a puxar-se em direção à barra com a coluna arqueada durante todo o movimento e a cabeça inclinada para trás, o mais longe possível da barra. Expire ao executar esta parte do movimento. Dica: na parte alta do movimento, seus quadris e pernas ficarão em um ângulo de cerca de 45 graus em relação ao chão.\nContinue puxando até que a clavícula passe da barra e a parte inferior do peito ou esterno a toque. Mantenha essa contração por um segundo. Dica: ao completar esta parte do movimento, sua cabeça estará paralela ao chão.\nComece a voltar lentamente à posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado.',
  'Glute Ham Raise':
    'Comece ajustando o equipamento ao seu corpo. Coloque os pés contra a plataforma, entre os rolos, enquanto se deita de bruços. Seus joelhos devem ficar logo atrás do apoio.\nComece pela parte inferior do movimento. Mantenha as costas arqueadas e inicie o movimento flexionando os joelhos. Empurre os dedos dos pés contra a plataforma ao fazer isso. Mantenha o tronco reto e continue até que seu corpo esteja ereto.\nRetorne à posição inicial, controlando a descida.',
  'Glute Kickback':
    'Ajoelhe-se no chão ou em um tapete e incline-se pela cintura com os braços estendidos à sua frente (perpendiculares ao tronco) para assumir uma posição de flexão de braço com os joelhos apoiados, mas com os braços na largura dos ombros. Sua cabeça deve olhar para a frente e a flexão dos joelhos deve formar um ângulo de 90 graus entre os posteriores de coxa e as panturrilhas. Esta será sua posição inicial.\nAo expirar, levante a perna direita até que os posteriores de coxa fiquem alinhados com as costas, mantendo o ângulo de 90 graus. Contraia os glúteos durante todo o movimento e mantenha a contração no topo por um segundo. Dica: no final do movimento a coxa deve ficar paralela ao chão enquanto a panturrilha fica perpendicular a ele.\nVolte à posição inicial ao inspirar e agora repita com a perna esquerda.\nContinue alternando as pernas até completar todas as repetições recomendadas.',
  'Goblet Squat':
    'Fique em pé segurando um kettlebell leve pelas alças laterais, perto do peito. Esta será sua posição inicial.\nAgache entre as pernas até que os posteriores de coxa toquem as panturrilhas. Mantenha o peito e a cabeça erguidos e as costas retas.\nNa posição inferior, faça uma pausa e use os cotovelos para empurrar os joelhos para fora. Volte à posição inicial e repita por 10 a 20 repetições.',
  'Good Morning':
    'Comece com uma barra em um rack na altura dos ombros. Apoie a barra na parte de trás dos ombros como em um agachamento de potência, não sobre o topo dos ombros. Mantenha as costas firmes, as escápulas unidas e os joelhos levemente flexionados. Dê um passo para trás para se afastar do rack.\nComece flexionando os quadris, levando-os para trás enquanto se inclina até ficar quase paralelo ao chão. Mantenha as costas arqueadas e a coluna cervical bem alinhada.\nInverta o movimento estendendo os quadris com os glúteos e os posteriores de coxa. Continue até voltar à posição inicial.',
  'Good Morning off Pins':
    'Comece com uma barra em um rack mais ou menos na altura do seu estômago. Incline-se por baixo da barra e apoie-a na parte de trás dos ombros como em um agachamento de potência, não sobre o topo dos ombros. Na altura correta, você deve ficar quase paralelo ao chão ao se inclinar. Mantenha as costas firmes, as escápulas unidas e os joelhos levemente flexionados. Mantenha as costas arqueadas e a coluna cervical bem alinhada.\nInicie o movimento estendendo os quadris com os glúteos e os posteriores de coxa, até ficar em pé com o peso. Abaixe lentamente o peso de volta aos pinos, retornando à posição inicial.',
  'Gorilla Chin/Crunch':
    'Pendure-se em uma barra fixa com pegada supinada (palmas voltadas para você) um pouco mais aberta que a largura dos ombros.\nAgora dobre os joelhos a 90 graus, de modo que as panturrilhas fiquem paralelas ao chão enquanto as coxas permanecem perpendiculares a ele. Esta será sua posição inicial.\nAo expirar, puxe-se para cima enquanto faz um crunch subindo os joelhos ao mesmo tempo, até os joelhos ficarem na altura do peito. Você para de subir assim que o nariz estiver na altura da barra. Dica: ao chegar a esse ponto você também deve estar terminando o crunch.\nComece a inspirar lentamente enquanto retorna à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Groin and Back Stretch':
    'Sente-se no chão com os joelhos dobrados e os pés juntos.\nEntrelace os dedos atrás da cabeça. Esta será sua posição inicial.\nEnrole o tronco para baixo, levando os cotovelos em direção à parte interna das coxas. Após uma breve pausa, volte à posição inicial com a cabeça erguida e as costas retas. Repita por 10 a 20 repetições.',
  Groiners:
    'Comece na posição de flexão de braço no chão. Esta será sua posição inicial.\nCom as duas pernas, salte para a frente aterrissando com os pés ao lado das mãos. Mantenha a cabeça erguida ao fazer isso.\nVolte à posição inicial e repita o movimento imediatamente, continuando por 10 a 20 repetições.',
  'Hack Squat':
    'Apoie a parte de trás do tronco contra o encosto da máquina e encaixe os ombros sob as almofadas apropriadas.\nPosicione as pernas na plataforma em uma base média, na largura dos ombros, com as pontas dos pés levemente voltadas para fora. Dica: mantenha a cabeça erguida e as costas apoiadas no encosto o tempo todo.\nColoque os braços nas alças laterais da máquina e destrave as barras de segurança (o que na maioria dos modelos é feito movendo as alças laterais de uma posição voltada para a frente para uma posição diagonal).\nAgora estique as pernas sem travar os joelhos. Esta será sua posição inicial. (Nota: para esta explicação usaremos a base média descrita acima, que trabalha o desenvolvimento geral; porém, você pode escolher qualquer uma das três bases descritas na seção de posicionamento dos pés).\nComece a abaixar lentamente a plataforma dobrando os joelhos, mantendo uma postura reta com a cabeça erguida (costas sempre apoiadas no encosto). Continue descendo até que o ângulo entre a coxa e a panturrilha fique ligeiramente menor que 90 graus (ponto em que as coxas ficam abaixo da paralela ao chão). Inspire durante esta parte do movimento. Dica: se você executou o exercício corretamente, a frente dos joelhos deve formar uma linha reta imaginária com as pontas dos pés, perpendicular à frente. Se os joelhos passarem dessa linha imaginária (se passarem dos pés), você está colocando estresse excessivo no joelho e o exercício foi executado de forma incorreta.\nComece a subir a plataforma enquanto expira, empurrando o chão principalmente com o calcanhar, enquanto estica as pernas novamente e volta à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Hammer Curls':
    'Fique em pé com o tronco ereto e um halter em cada mão, seguros na extensão dos braços. Os cotovelos devem ficar junto ao tronco.\nAs palmas das mãos devem ficar voltadas para o seu tronco. Esta será sua posição inicial.\nAgora, mantendo a parte superior do braço estável, expire e levante o peso para a frente contraindo os bíceps. Continue subindo o peso até os bíceps estarem totalmente contraídos e o halter estar na altura do ombro. Mantenha a posição contraída por um breve momento enquanto aperta os bíceps. Dica: concentre-se em manter o cotovelo estável e mover apenas o antebraço.\nApós a breve pausa, inspire e comece a abaixar lentamente os halteres até a posição inicial.\nRepita pelo número de repetições recomendado.',
  'Hammer Grip Incline DB Bench Press':
    'Deite-se em um banco inclinado com um halter em cada mão sobre as coxas. As palmas das mãos ficarão voltadas uma para a outra.\nUsando as coxas para ajudar a subir os halteres, leve-os para cima um braço de cada vez para poder segurá-los na largura dos ombros.\nNa largura dos ombros, mantenha as palmas das mãos em pegada neutra (palmas voltadas uma para a outra). Mantenha os cotovelos abertos com a parte superior dos braços alinhada com os ombros (perpendicular ao tronco) e os cotovelos dobrados formando um ângulo de 90 graus entre a parte superior do braço e o antebraço. Esta será sua posição inicial.\nAgora abaixe lentamente os pesos para as laterais do corpo enquanto inspira. Mantenha controle total dos halteres o tempo todo.\nAo expirar, empurre os halteres para cima usando os músculos peitorais. Trave os braços na posição contraída, segure por um segundo e depois comece a descer lentamente. Dica: a descida deve levar pelo menos o dobro do tempo da subida.\nRepita o movimento pelo número de repetições prescrito.\nAo terminar, apoie os halteres de volta nas coxas e depois no chão. Essa é a forma mais segura de descartar os halteres.',
  'Hamstring Stretch':
    'Deite-se de costas com uma perna estendida para cima, com o quadril a noventa graus. Mantenha a outra perna reta no chão.\nPasse um cinto, faixa ou corda pela parte da frente do pé. Esta será sua posição inicial.\nPuxe o cinto para criar tensão nas panturrilhas e nos posteriores de coxa. Mantenha este alongamento por 10 a 30 segundos e repita com a outra perna.',
  'Hamstring-SMR':
    'Sentado, estenda as pernas sobre um rolo de espuma de modo que ele fique na parte de trás das coxas. Coloque as mãos ao lado ou atrás de você para ajudar a sustentar seu peso. Esta será sua posição inicial.\nUsando as mãos, levante os quadris do chão e transfira seu peso sobre o rolo para uma perna. Relaxe os posteriores de coxa da perna que está alongando.\nRole sobre o rolo desde abaixo do quadril até acima da parte de trás do joelho, fazendo pausas de 10 a 30 segundos nos pontos de tensão. Repita com a outra perna.',
  'Handstand Push-Ups':
    'Com as costas voltadas para a parede, incline-se pela cintura e coloque as duas mãos no chão na largura dos ombros.\nImpulsione-se para cima contra a parede com os braços retos. Seu corpo deve ficar de cabeça para baixo com os braços e as pernas totalmente estendidos. Mantenha o corpo todo o mais reto possível. Dica: se estiver fazendo pela primeira vez, peça a um auxiliar para ajudar. Além disso, mantenha a cabeça voltada para a parede, em vez de olhar para baixo.\nDesça lentamente em direção ao chão enquanto inspira até a cabeça quase tocar o chão. Dica: é de extrema importância descer devagar para evitar lesões na cabeça.\nEmpurre-se de volta para cima lentamente enquanto expira até os cotovelos ficarem quase travados.\nRepita pelo número de repetições recomendado.',
  'Hang Clean':
    'Comece com uma pegada na largura dos ombros, pronada dupla ou em gancho, com a barra pendurada na altura do meio da coxa. Suas costas devem estar retas e levemente inclinadas para a frente.\nComece estendendo com força os quadris, joelhos e tornozelos, impulsionando o peso para cima. Ao fazer isso, encolha os ombros em direção às orelhas.\nRecupere-se imediatamente empurrando com os calcanhares, mantendo o tronco ereto e os cotovelos elevados. Continue até chegar à posição em pé.',
  'Hang Clean - Below the Knees':
    'Comece com uma pegada na largura dos ombros, pronada dupla ou em gancho, com a barra pendurada logo abaixo dos joelhos. Suas costas devem estar retas e levemente inclinadas para a frente.\nComece estendendo com força os quadris, joelhos e tornozelos, impulsionando o peso para cima. Ao fazer isso, encolha os ombros em direção às orelhas. Ao atingir a extensão completa, passe para a terceira puxada encolhendo os ombros com força e flexionando os braços com os cotovelos para cima e para fora.\nNo pico da extensão, puxe-se com força para baixo, girando os cotovelos por baixo da barra. Receba a barra em uma posição de agachamento frontal, cuja profundidade depende da altura da barra ao final da terceira puxada. A barra deve ficar apoiada nos ombros protraídos, tocando levemente a garganta com as mãos relaxadas. Continue descendo até a posição inferior do agachamento, o que ajudará na recuperação.\nRecupere-se imediatamente empurrando com os calcanhares, mantendo o tronco ereto e os cotovelos elevados. Continue até chegar à posição em pé.',
  'Hang Snatch':
    'Comece com uma pegada aberta na barra, pronada ou em gancho. Os pés devem ficar diretamente abaixo dos quadris e voltados para fora. Os joelhos devem estar levemente flexionados e o tronco inclinado para a frente. A coluna deve estar totalmente estendida e a cabeça voltada para a frente. A barra deve ficar na altura dos quadris. Esta será sua posição inicial.\nEstenda com força as pernas e os quadris. No pico da extensão, encolha os ombros e deixe os cotovelos flexionarem para os lados.\nEnquanto move os pés para a posição de recepção, puxe-se com força para baixo da barra enquanto eleva a barra acima da cabeça. Receba a barra com o corpo o mais baixo possível e os braços totalmente estendidos acima da cabeça.\nVolte à posição em pé com o peso acima da cabeça. Em seguida, devolva o peso ao chão de forma controlada.',
  'Hang Snatch - Below Knees':
    'Comece com uma pegada aberta na barra, pronada ou em gancho. Os pés devem ficar diretamente abaixo dos quadris e voltados para fora. Os joelhos devem estar levemente flexionados e o tronco inclinado para a frente. A coluna deve estar totalmente estendida e a cabeça voltada para a frente. A barra deve ficar logo abaixo dos joelhos. Esta será sua posição inicial.\nEstenda com força as pernas e os quadris. No pico da extensão, encolha os ombros e deixe os cotovelos flexionarem para os lados.\nEnquanto move os pés para a posição de recepção, puxe-se com força para baixo da barra enquanto eleva a barra acima da cabeça. Receba a barra com o corpo o mais baixo possível e os braços totalmente estendidos acima da cabeça.\nVolte à posição em pé com o peso acima da cabeça e depois devolva o peso ao chão de forma controlada.',
  'Hanging Bar Good Morning':
    'Comece com uma barra em um rack mais ou menos na altura do seu estômago. Suspenda a barra usando correntes ou tiras de suspensão.\nIncline-se por baixo da barra e apoie-a na parte de trás dos ombros como em um agachamento de potência, não sobre o trapézio. Na altura correta, você deve ficar quase paralelo ao chão ao se inclinar. Mantenha as costas firmes, as escápulas unidas e os joelhos levemente flexionados. Mantenha as costas arqueadas e a coluna cervical bem alinhada.\nInicie o movimento estendendo os quadris com os glúteos e os posteriores de coxa, até ficar em pé com o peso.\nAbaixe lentamente o peso até a posição inicial, onde ele fica sustentado pelas correntes.',
  'Hanging Leg Raise':
    'Pendure-se em uma barra fixa com os dois braços estendidos acima de você, com pegada aberta ou média. As pernas devem ficar retas para baixo com a pelve levemente retrovertida. Esta será sua posição inicial.\nLevante as pernas até o tronco formar um ângulo de 90 graus com elas. Expire ao executar este movimento e mantenha a contração por cerca de um segundo.\nVolte lentamente à posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado.',
  'Hanging Pike':
    'Pendure-se em uma barra fixa com as pernas e os pés juntos usando uma pegada pronada (palmas voltadas para longe de você) um pouco mais aberta que a largura dos ombros. Dica: você pode usar munhequeiras para facilitar a pegada na barra.\nAgora dobre os joelhos a 90 graus e leve as coxas para a frente de modo que as panturrilhas fiquem perpendiculares ao chão enquanto as coxas permanecem paralelas a ele. Esta será sua posição inicial.\nSuba as pernas enquanto expira até quase tocar a barra com as canelas. Dica: tente esticar as pernas o máximo possível quando estiver no topo.\nAbaixe as pernas o mais lentamente possível até chegar à posição inicial. Dica: evite balançar e usar impulso o tempo todo.\nRepita pelo número de repetições recomendado.',
  'Heaving Snatch Balance':
    'Este exercício ajuda a aprender o snatch. Comece segurando um peso leve na parte de trás dos ombros. Seus pés devem ficar um pouco mais afastados que a largura dos quadris e voltados para fora, a mesma posição que você usaria para um agachamento.\nComece flexionando levemente os joelhos e voltando a subir rapidamente para descarregar brevemente a barra. Impulsione-se para baixo da barra, elevando-a acima da cabeça enquanto desce em um agachamento completo.\nVolte à posição em pé.',
  'Heavy Bag Thrust':
    'Use um saco de pancada pesado para este exercício. Assuma uma postura ereta ao lado do saco, com os pés alternados e bem afastados. Coloque a mão no saco mais ou menos na altura do peito. Esta será sua posição inicial.\nComece girando pela cintura, empurrando o saco para a frente com a maior força possível. Execute este movimento rapidamente, afastando o saco do seu corpo.\nReceba o saco quando ele voltar balançando, invertendo esses passos.',
  'High Cable Curls':
    'Fique em pé entre um par de polias altas e segure uma alça em cada mão. Posicione a parte superior dos braços de modo que fiquem paralelas ao chão com as palmas das mãos voltadas para você. Esta será sua posição inicial.\nFlexione os braços levando as alças em sua direção até ficarem ao lado das orelhas. Contraia os bíceps e expire ao fazer isso. A parte superior dos braços deve permanecer estável e apenas os antebraços devem se mover. Mantenha por um segundo na posição contraída enquanto aperta os bíceps.\nVolte lentamente os braços à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Hip Circles (prone)':
    'Posicione-se de quatro apoios no chão, sobre as mãos e os joelhos. Mantendo uma boa postura, levante um joelho dobrado do chão. Esta será sua posição inicial.\nMantendo o joelho dobrado, gire o fêmur em um arco, tentando fazer um círculo grande com o joelho.\nExecute isso lentamente por algumas repetições e repita do outro lado.',
  'Hip Extension with Bands':
    'Prenda uma extremidade da faixa à parte baixa de um poste e prenda a outra a um tornozelo.\nDe frente para o ponto de fixação da faixa, segure-se na coluna para se estabilizar.\nMantendo a cabeça e o peito erguidos, leve a perna com resistência para trás o mais longe que puder mantendo o joelho reto.\nVolte a perna à posição inicial.',
  'Hip Flexion with Band':
    'Prenda uma extremidade da faixa à parte baixa de um poste e prenda a outra a um tornozelo.\nFique de costas para o ponto de fixação da faixa.\nMantendo a cabeça e o peito erguidos, levante o joelho até 90 graus e faça uma pausa.\nVolte a perna à posição inicial.',
  'Hip Lift with Band':
    'Depois de escolher uma faixa adequada, deite-se no meio do rack, após prender a faixa nos dois lados. Se o seu rack não tiver pinos, a faixa pode ser presa com halteres pesados ou objetos semelhantes; apenas garanta que não se movam.\nAjuste sua posição de modo que a faixa fique diretamente sobre os quadris. Dobre os joelhos e apoie os pés totalmente no chão. Suas mãos podem ficar no chão ou segurando a faixa no lugar.\nMantendo os ombros no chão, empurre com os calcanhares para elevar os quadris, empurrando contra a faixa o mais alto que puder.\nFaça uma pausa no topo do movimento e volte à posição inicial.',
  'Hug A Ball':
    'Sente-se no chão.\nPosicione uma bola de exercício entre as pernas e abaixe os quadris em direção ao chão.\nAbrace a bola com os braços para sustentar o corpo. Ajuste as pernas de modo que os pés fiquem totalmente apoiados no chão e os joelhos alinhados sobre os tornozelos. Mantenha uma boa pegada na bola para que ela não role para longe e faça você cair sentado.',
  'Hug Knees To Chest':
    'Deite-se de costas e leve os dois joelhos ao peito.\nSegure os joelhos com os braços por baixo, não por cima (isso colocaria pressão demais nas articulações do joelho).\nPuxe lentamente os joelhos em direção aos ombros. Isso também alonga os músculos dos glúteos.',
  'Hurdle Hops':
    'Monte uma fileira de barreiras ou outros obstáculos pequenos, colocando-os a alguns pés de distância um do outro.\nFique em pé diante da primeira barreira com os pés afastados na largura dos ombros. Esta será sua posição inicial.\nComece saltando com os dois pés sobre a primeira barreira, balançando os dois braços ao saltar.\nAbsorva o impacto da aterrissagem dobrando os joelhos e rebata do primeiro salto para saltar sobre a próxima barreira. Continue até ter saltado sobre todas as barreiras.',
  'Hyperextensions (Back Extensions)':
    'Deite-se de bruços em um banco de hiperextensão, prendendo os tornozelos com firmeza sob os apoios.\nSe possível, ajuste o apoio superior para que a parte de cima das coxas fique apoiada sobre o apoio largo, deixando espaço suficiente para flexionar o quadril sem restrições.\nCom o corpo reto, cruze os braços à sua frente ou coloque-os atrás da cabeça. Esta será a sua posição inicial. Dica: você também pode segurar um anilha à sua frente, sob os braços cruzados, para mais resistência.\nComece a se inclinar para a frente lentamente a partir do quadril, o mais longe que conseguir, mantendo as costas retas. Inspire enquanto realiza este movimento. Continue até sentir um bom alongamento nos posteriores de coxa e até não conseguir seguir sem arredondar as costas. Dica: nunca arredonde as costas neste exercício. Além disso, algumas pessoas conseguem ir mais longe que outras. O importante é descer até onde o seu corpo permitir sem arredondar as costas.\nSuba lentamente o tronco até a posição inicial enquanto inspira. Dica: evite a tentação de arquear as costas além de uma linha reta. Além disso, não balance o tronco em nenhum momento, para proteger as costas de lesões.\nRepita o número de repetições recomendado.',
  'Hyperextensions With No Hyperextension Bench':
    'Com alguém segurando suas pernas, deslize até a borda de um banco reto até que o quadril fique fora do banco. Dica: todo o tronco deve ficar pendurado em direção ao chão. Você estará na mesma posição que em um banco de hiperextensão, mas a amplitude de movimento será menor devido à altura do banco reto.\nCom o corpo reto, cruze os braços à sua frente ou coloque-os atrás da cabeça. Esta será a sua posição inicial. Dica: você também pode segurar uma anilha à sua frente, sob os braços cruzados, para mais resistência.\nComece a se inclinar para a frente lentamente a partir do quadril, o mais longe que conseguir, mantendo as costas retas. Inspire enquanto realiza este movimento. Continue até quase tocar o chão ou sentir um bom alongamento nos posteriores de coxa (o que ocorrer primeiro). Dica: nunca arredonde as costas neste exercício.\nSuba lentamente o tronco até a posição inicial enquanto expira. Dica: evite a tentação de arquear as costas além de uma linha reta. Além disso, não balance o tronco em nenhum momento, para proteger as costas de lesões.\nRepita o número de repetições recomendado.',
  'IT Band and Glute Stretch':
    'Passe um cinto, corda ou faixa em volta de um dos pés e leve essa perna cruzando o corpo para o lado oposto, mantendo-a estendida enquanto está deitado no chão. Esta será a sua posição inicial.\nMantendo o pé fora do chão, puxe o cinto usando a tensão para levar os dedos dos pés para cima. Segure por 10 a 20 segundos e repita do outro lado.',
  'Iliotibial Tract-SMR':
    'Deite-se de lado, com a perna de baixo apoiada sobre um rolo de espuma entre o quadril e o joelho. A outra perna pode ficar cruzada à sua frente.\nColoque sobre a perna de baixo o máximo de peso que conseguir tolerar; não é necessário que essa perna fique em contato com o chão. Certifique-se de relaxar os músculos da perna que está alongando.\nRole a perna sobre o rolo do quadril até o joelho, fazendo pausas de 10 a 30 segundos nos pontos de tensão. Repita com a perna oposta.',
  Inchworm:
    'Fique em pé com os pés juntos. Mantendo as pernas retas, incline-se para baixo e apoie as mãos no chão bem à sua frente. Esta será a sua posição inicial.\nComece caminhando lentamente com as mãos para a frente, alternando a esquerda e a direita. Enquanto faz isso, flexione apenas o quadril, mantendo as pernas retas.\nContinue até que o seu corpo fique paralelo ao chão na posição de flexão de braço.\nAgora, mantenha as mãos no lugar e dê passos curtos e lentos com os pés, avançando apenas alguns centímetros por vez.\nContinue caminhando até que os pés fiquem junto às mãos, mantendo as pernas retas.',
  'Incline Barbell Triceps Extension':
    'Segure uma barra com pegada pronada (palmas para baixo), com as mãos um pouco mais próximas que a largura dos ombros.\nDeite-se em um banco inclinado com um ângulo entre 45 e 75 graus.\nLeve a barra acima da cabeça com os braços estendidos e os cotovelos para dentro. Os braços devem ficar alinhados com o tronco, acima da cabeça. Esta será a sua posição inicial.\nAgora abaixe a barra em um movimento semicircular atrás da cabeça até que os antebraços toquem os bíceps. Inspire enquanto realiza este movimento. Dica: mantenha a parte superior dos braços parada e próxima da cabeça o tempo todo. Apenas os antebraços devem se mover.\nVolte à posição inicial enquanto expira e contrai os tríceps. Segure a contração por um segundo.\nRepita o número de repetições recomendado.',
  'Incline Bench Pull':
    'Pegue um halter em cada mão e deite-se de bruços em um banco inclinado a aproximadamente 30 graus.\nDeixe os braços pendurados ao lado do corpo, totalmente estendidos e apontando para o chão.\nGire os punhos até que as mãos fiquem com pegada pronada (palmas para baixo).\nAgora abra os cotovelos para fora. Esta será a sua posição inicial.\nEnquanto expira, comece a puxar os halteres para cima como se estivesse fazendo um supino invertido. Você faz isso flexionando os cotovelos e levando a parte superior dos braços para cima enquanto deixa os antebraços pendurados. Continue até que a parte superior dos braços fique na altura das costas. Dica: os cotovelos vão para os lados e a parte superior dos braços e o tronco devem formar um "T" no alto do movimento. Segure a contração no alto por um segundo.\nVolte lentamente à posição inicial enquanto inspira.\nRepita o número de repetições recomendado.',
  'Incline Cable Chest Press':
    'Ajuste a carga para uma quantidade adequada e sente-se, segurando as manoplas. A parte superior dos braços deve ficar a cerca de 45 graus do corpo, com a cabeça e o peito erguidos. Os cotovelos devem estar flexionados a cerca de 90 graus. Esta será a sua posição inicial.\nComece estendendo os cotovelos, empurrando as manoplas juntas à sua frente. Mantenha as escápulas retraídas enquanto executa o movimento.\nApós uma pausa com os braços totalmente estendidos, volte à posição inicial, mantendo a tensão nos cabos.',
  'Incline Cable Flye':
    'Para chegar à posição inicial, ajuste as polias na altura do chão (o nível mais baixo possível da máquina, abaixo do seu tronco).\nColoque um banco inclinado (a 45 graus) entre as polias, selecione uma carga em cada uma e segure uma manopla em cada mão.\nCom uma manopla em cada mão, deite-se no banco inclinado e junte as mãos com os braços estendidos à frente do rosto. Esta será a sua posição inicial.\nCom uma leve flexão dos cotovelos (para evitar tensão no tendão do bíceps), abra os braços para os lados em um arco amplo até sentir um alongamento no peitoral. Inspire enquanto realiza esta parte do movimento. Dica: lembre-se de que, durante todo o movimento, os braços devem permanecer parados. O movimento deve ocorrer apenas na articulação do ombro.\nVolte os braços à posição inicial enquanto contrai os músculos do peito e expira. Segure a posição contraída por um segundo. Dica: certifique-se de usar o mesmo arco de movimento usado para descer a carga.\nRepita o movimento pelo número de repetições prescrito.',
  'Incline Dumbbell Bench With Palms Facing In':
    'Deite-se em um banco inclinado com um halter em cada mão sobre as coxas. As palmas das mãos ficarão voltadas uma para a outra.\nUsando as coxas para ajudar a levantar os halteres, leve-os um braço de cada vez até conseguir segurá-los na altura dos ombros.\nUma vez na largura dos ombros, mantenha a pegada neutra (palmas voltadas uma para a outra). Mantenha os cotovelos abertos com a parte superior dos braços alinhada com os ombros (perpendicular ao tronco) e os cotovelos flexionados formando um ângulo de 90 graus entre o braço e o antebraço. Esta será a sua posição inicial.\nAgora abaixe os pesos lentamente para as laterais enquanto inspira. Mantenha o controle total dos halteres o tempo todo.\nEnquanto expira, empurre os halteres para cima usando os músculos peitorais. Trave os braços na posição contraída, segure por um segundo e depois comece a descer lentamente. Dica: a descida deve levar pelo menos o dobro do tempo da subida.\nRepita o movimento pelo número de repetições prescrito.\nQuando terminar, apoie os halteres de volta sobre as coxas e depois no chão. Essa é a forma mais segura de soltar os halteres.',
  'Incline Dumbbell Curl':
    'Sente-se em um banco inclinado com um halter em cada mão, com os braços estendidos. Mantenha os cotovelos próximos ao tronco e gire as palmas das mãos até ficarem voltadas para a frente. Esta será a sua posição inicial.\nMantendo a parte superior do braço parada, flexione os pesos para a frente contraindo os bíceps enquanto expira. Apenas os antebraços devem se mover. Continue o movimento até que os bíceps estejam totalmente contraídos e os halteres estejam na altura dos ombros. Segure a posição contraída por um segundo.\nLentamente comece a voltar os halteres à posição inicial enquanto inspira.\nRepita o número de repetições recomendado.',
  'Incline Dumbbell Flyes':
    'Segure um halter em cada mão e deite-se em um banco inclinado a no máximo 30 graus.\nEstenda os braços acima de você com uma leve flexão nos cotovelos.\nAgora gire os punhos para que as palmas das mãos fiquem voltadas para você. Dica: os dedos mínimos devem ficar um ao lado do outro. Esta será a sua posição inicial.\nEnquanto inspira, comece a abaixar lentamente os braços para os lados, mantendo-os estendidos e girando os punhos até que as palmas fiquem voltadas uma para a outra. Dica: no final do movimento os braços estarão ao lado do corpo com as palmas voltadas para o teto.\nEnquanto expira, comece a levar os halteres de volta à posição inicial invertendo o movimento e girando as mãos para que os dedos mínimos fiquem novamente um ao lado do outro. Dica: lembre-se de que o movimento ocorre apenas na articulação do ombro e no punho. Não há movimento na articulação do cotovelo.\nRepita o número de repetições recomendado.',
  'Incline Dumbbell Flyes - With A Twist':
    'Segure um halter em cada mão e deite-se em um banco inclinado a no máximo 30 graus.\nEstenda os braços acima de você com uma leve flexão nos cotovelos.\nAgora gire os punhos para que as palmas das mãos fiquem voltadas para você. Dica: os dedos mínimos devem ficar um ao lado do outro. Esta será a sua posição inicial.\nEnquanto inspira, comece a abaixar lentamente os braços para os lados, mantendo-os estendidos e girando os punhos até que as palmas fiquem voltadas uma para a outra. Dica: no final do movimento os braços estarão ao lado do corpo com as palmas voltadas para o teto.\nEnquanto expira, comece a levar os halteres de volta à posição inicial invertendo o movimento e girando as mãos para que os dedos mínimos fiquem novamente um ao lado do outro. Dica: lembre-se de que o movimento ocorre apenas na articulação do ombro e no punho. Não há movimento na articulação do cotovelo.\nRepita o número de repetições recomendado.',
  'Incline Dumbbell Press':
    'Deite-se em um banco inclinado com um halter em cada mão sobre as coxas. As palmas das mãos ficarão voltadas uma para a outra.\nEm seguida, usando as coxas para ajudar a empurrar os halteres para cima, levante-os um de cada vez até conseguir segurá-los na altura dos ombros.\nQuando os halteres estiverem na largura dos ombros, gire os punhos para a frente para que as palmas das mãos fiquem voltadas para longe de você. Esta será a sua posição inicial.\nCertifique-se de manter o controle total dos halteres o tempo todo. Depois expire e empurre os halteres para cima com o peito.\nTrave os braços no alto, segure por um segundo e depois comece a abaixar o peso lentamente. Dica: idealmente, a descida deve levar cerca do dobro do tempo da subida.\nRepita o movimento pelo número de repetições prescrito.\nQuando terminar, apoie os halteres de volta sobre as coxas e depois no chão. Essa é a forma mais segura de soltar os halteres.',
  'Incline Hammer Curls':
    'Sente-se em um banco inclinado com um halter em cada mão. Você deve estar bem apoiado no encosto, com os pés juntos. Deixe os halteres pendurados retos ao lado do corpo, segurando-os com pegada neutra. Esta será a sua posição inicial.\nInicie o movimento flexionando os cotovelos, tentando manter a parte superior do braço parada.\nContinue até o alto do movimento e faça uma pausa; depois volte lentamente à posição inicial.',
  'Incline Inner Biceps Curl':
    'Segure um halter em cada mão e deite-se em um banco inclinado.\nOs halteres devem ficar pendurados ao lado do corpo com os braços estendidos e as palmas voltadas para fora. Esta será a sua posição inicial.\nAgora, enquanto expira, flexione o peso para fora e para cima mantendo os antebraços alinhados com os deltoides laterais. Continue a rosca até que os halteres estejam na altura dos ombros e ao lado dos deltoides. Dica: o final do movimento deve se parecer com uma pose de duplo bíceps.\nApós uma contração de um segundo no alto, comece a inspirar e abaixe lentamente os pesos de volta à posição inicial pelo mesmo caminho usado para subi-los.\nRepita o número de repetições recomendado.',
  'Incline Push-Up':
    'Fique em pé de frente para um banco ou uma plataforma elevada resistente. Coloque as mãos na borda do banco ou da plataforma, um pouco mais afastadas que a largura dos ombros.\nPosicione a ponta dos pés para trás, afastados do banco ou da plataforma, com os braços e o corpo retos. Os braços devem ficar perpendiculares ao corpo. Mantendo o corpo reto, abaixe o peito até a borda da caixa ou da plataforma flexionando os braços.\nEmpurre o corpo para cima até estender os braços. Repita.',
  'Incline Push-Up Close-Grip':
    'Fique em pé de frente para a barra de um Smith ou uma plataforma elevada resistente em uma altura adequada.\nColoque as mãos juntas, uma ao lado da outra, sobre a barra.\nPosicione os pés para trás, afastados da barra, com os braços e o corpo retos. Esta será a sua posição inicial.\nMantendo o corpo reto, abaixe o peito até a barra flexionando os braços.\nVolte à posição inicial estendendo os cotovelos e empurrando-se para cima.',
  'Incline Push-Up Depth Jump':
    'Para este exercício você precisará de uma caixa com cerca de 30 cm de altura e dois colchonetes grossos ou steps de aeróbica.\nColoque os steps logo por fora dos seus ombros e apoie os pés sobre a caixa para ficar em posição de flexão inclinada, com as mãos logo por dentro dos steps. Esta será a sua posição inicial.\nComece flexionando os cotovelos para abaixar o corpo, revertendo rapidamente o movimento para se impulsionar para fora do chão. Ao sair do chão, leve as mãos para cima dos steps, flexionando os cotovelos para absorver o impacto.\nRepita o movimento para voltar à posição inicial.',
  'Incline Push-Up Medium':
    'Fique em pé de frente para a barra de um Smith ou uma plataforma elevada resistente em uma altura adequada.\nColoque as mãos sobre a barra, afastadas aproximadamente na largura dos ombros.\nPosicione os pés para trás, afastados da barra, com os braços e o corpo retos. Esta será a sua posição inicial.\nMantendo o corpo reto, abaixe o peito até a barra flexionando os braços.\nVolte à posição inicial estendendo os cotovelos e empurrando-se para cima.',
  'Incline Push-Up Reverse Grip':
    'Fique em pé de frente para a barra de um Smith ou uma plataforma elevada resistente em uma altura adequada.\nColoque as mãos sobre a barra com as palmas para cima, afastadas aproximadamente na largura dos ombros.\nPosicione os pés para trás, afastados da barra, com os braços e o corpo retos. Esta será a sua posição inicial.\nMantendo o corpo reto, abaixe o peito até a barra flexionando os braços.\nVolte à posição inicial estendendo os cotovelos e empurrando-se para cima.',
  'Incline Push-Up Wide':
    'Fique em pé de frente para a barra de um Smith ou uma plataforma elevada resistente em uma altura adequada.\nColoque as mãos sobre a barra, mais afastadas que a largura dos ombros.\nPosicione os pés para trás, afastados da barra, com os braços e o corpo retos. Os braços devem ficar perpendiculares ao corpo. Esta será a sua posição inicial.\nMantendo o corpo reto, abaixe o peito até a barra flexionando os braços.\nVolte à posição inicial estendendo os cotovelos e empurrando-se para cima.',
  'Intermediate Groin Stretch':
    'Deite-se de costas com as pernas estendidas. Passe um cinto, corda ou faixa em volta de um dos pés e leve essa perna para o lado o mais longe que conseguir. Esta será a sua posição inicial.\nPuxe suavemente o cinto para criar tensão na virilha e nos posteriores de coxa. Segure por 10 a 20 segundos e repita do outro lado.',
  'Intermediate Hip Flexor and Quad Stretch':
    'Deite-se de bruços no chão, com uma corda, cinto ou faixa passada em volta de um dos pés.\nFlexione o joelho e estenda o quadril da perna que será alongada, puxando o cinto com as duas mãos. O joelho e o quadril devem sair do chão, criando tensão nos flexores do quadril e nos quadríceps. Segure o alongamento por 10 a 20 segundos e repita com a outra perna.',
  'Internal Rotation with Band':
    'Passe a faixa em volta de um poste, prendendo-a bem. A faixa deve ficar na altura do seu cotovelo. Fique em pé com o lado direito voltado para a faixa, a uns dois passos de distância.\nSegure a ponta da faixa com a mão direita e mantenha o cotovelo firmemente junto ao corpo. Recomendamos segurar uma toalha ou um rolo de espuma com o cotovelo para mantê-lo firme no lugar.\nCom a parte superior do braço em posição, o cotovelo deve estar flexionado a 90 graus com a mão estendida para longe do tronco. Esta será a sua posição inicial.\nExecute o movimento girando o braço para dentro, como em uma pancada de direita, mantendo o cotovelo no lugar.\nContinue o mais longe que conseguir, faça uma pausa e depois volte à posição inicial.',
  'Inverted Row':
    'Posicione uma barra em um rack a aproximadamente a altura da cintura. Você também pode usar um Smith.\nSegure a barra com uma pegada mais larga que a largura dos ombros e posicione-se pendurado embaixo dela. Seu corpo deve estar reto, com os calcanhares no chão e os braços totalmente estendidos. Esta será a sua posição inicial.\nComece flexionando os cotovelos, puxando o peito em direção à barra. Retraia as escápulas enquanto realiza o movimento.\nFaça uma pausa no alto do movimento e volte à posição inicial.\nRepita o número de repetições desejado.',
  'Inverted Row with Straps':
    'Pendure uma corda ou fitas de suspensão em um rack ou outro objeto estável. Segure as pontas e posicione-se em posição supina, pendurado nas cordas. Seu corpo deve estar reto, com os calcanhares no chão e os braços totalmente estendidos. Esta será a sua posição inicial.\nComece flexionando os cotovelos, puxando o peito em direção às mãos. Retraia as escápulas enquanto realiza o movimento.\nFaça uma pausa no alto do movimento e volte à posição inicial.\nRepita o número de repetições desejado.',
  'Iron Crosses (stretch)':
    'Deite-se de bruços no chão, com os braços estendidos para os lados e as palmas apoiadas no chão. Esta será a sua posição inicial.\nPara começar, flexione um joelho e leve essa perna cruzando por trás do corpo, tentando tocar o chão perto da mão oposta.\nVolte rapidamente a perna à posição inicial e repita de imediato com a outra perna. Continue alternando por 10 a 20 repetições.',
  'Isometric Chest Squeezes':
    'Sentado ou em pé, flexione os braços a 90 graus e junte as palmas das mãos à frente do peito. Dica: as mãos devem estar abertas, com as palmas juntas e os dedos apontando para a frente (perpendiculares ao tronco).\nEmpurre as duas mãos uma contra a outra enquanto contrai o peito. Comece com uma tensão suave e aumente-a gradualmente. Continue respirando normalmente enquanto executa esta contração.\nSegure pelo número de segundos recomendado.\nAgora solte a tensão lentamente.\nDescanse pelo tempo recomendado e repita.',
  'Isometric Neck Exercise - Front And Back':
    'Com a cabeça e o pescoço em posição neutra (posição normal, com a cabeça erguida olhando para a frente), coloque as duas mãos na parte da frente da cabeça.\nAgora empurre suavemente para a frente enquanto contrai os músculos do pescoço, mas resistindo a qualquer movimento da cabeça. Comece com uma tensão suave e aumente-a gradualmente. Continue respirando normalmente enquanto executa esta contração.\nSegure pelo número de segundos recomendado.\nAgora solte a tensão lentamente.\nDescanse pelo tempo recomendado e repita com as mãos colocadas na parte de trás da cabeça.',
  'Isometric Neck Exercise - Sides':
    'Com a cabeça e o pescoço em posição neutra (posição normal, com a cabeça erguida olhando para a frente), coloque a mão esquerda no lado esquerdo da cabeça.\nAgora empurre suavemente para a esquerda enquanto contrai os músculos do lado esquerdo do pescoço, mas resistindo a qualquer movimento da cabeça. Comece com uma tensão suave e aumente-a gradualmente. Continue respirando normalmente enquanto executa esta contração.\nSegure pelo número de segundos recomendado.\nAgora solte a tensão lentamente.\nDescanse pelo tempo recomendado e repita com a mão direita colocada no lado direito da cabeça.',
  'Isometric Wipers':
    'Assuma a posição de flexão de braço, apoiando o peso nas mãos e nas pontas dos pés, com o corpo reto. As mãos devem ficar um pouco além da largura dos ombros. Esta será a sua posição inicial.\nComece deslocando o peso do corpo o máximo possível para um lado, deixando o cotovelo desse lado flexionar enquanto você abaixa o corpo.\nInverta o movimento estendendo o braço flexionado, empurrando-se para cima e depois descendo para o outro lado.\nRepita o número de repetições desejado.',
  'JM Press':
    'Comece o exercício da mesma forma que um supino de pegada fechada. Você vai se deitar em um banco reto segurando uma barra com os braços estendidos (totalmente esticados) e os cotovelos para dentro. No entanto, em vez de ter os braços perpendiculares ao tronco, certifique-se de que a barra fique em linha reta acima da parte superior do peito. Esta será a sua posição inicial.\nAgora, partindo da posição totalmente estendida, abaixe a barra como se estivesse fazendo uma extensão de tríceps deitado. Inspire enquanto realiza este movimento. Ao chegar na metade do caminho, deixe a barra rolar para trás cerca de 2,5 cm movendo a parte superior dos braços em direção às pernas até ficarem perpendiculares ao tronco. Dica: mantenha a flexão dos cotovelos constante enquanto leva os braços para a frente.\nEnquanto expira, empurre a barra para cima usando os tríceps para fazer um supino de pegada fechada.\nAgora volte à posição inicial e comece novamente.\nRepita o número de repetições recomendado.',
  'Jackknife Sit-Up':
    'Deite-se de costas no chão (ou em um colchonete) com os braços estendidos para trás acima da cabeça e as pernas também estendidas. Esta será a sua posição inicial.\nEnquanto expira, flexione o quadril e levante ao mesmo tempo as pernas e os braços até se encontrarem em posição de canivete. Dica: as pernas devem estar estendidas e elevadas em um ângulo aproximado de 35 a 45 graus em relação ao chão, e os braços estendidos e paralelos às pernas. A parte superior do tronco deve sair do chão.\nEnquanto inspira, abaixe os braços e as pernas de volta à posição inicial.\nRepita o número de repetições recomendado.',
  'Janda Sit-Up':
    'Posicione o corpo no chão na posição básica de abdominal: joelhos a noventa graus com os pés apoiados no chão e os braços cruzados sobre o peito ou ao lado do corpo. Esta será a sua posição inicial.\nEnquanto contrai com força os glúteos e os posteriores de coxa, encha os pulmões de ar e, em uma subida lenta (contagem de três a seis segundos), expire lentamente. Dica: é importante contrair os glúteos e os posteriores de coxa, pois isso inativa os flexores do quadril em um processo chamado inibição recíproca, que basicamente significa que os músculos opostos aos contraídos relaxam.\nEnquanto inspira, volte lentamente de forma controlada à posição inicial.\nRepita o número de repetições recomendado.',
  'Jefferson Squats':
    'Coloque uma barra no chão.\nFique em pé no meio da barra, no sentido do comprimento dela.\nAgache flexionando os joelhos e mantendo as costas retas e segure a parte da frente da barra com a mão direita. A palma deve ficar voltada para dentro (pegada neutra), virada para o lado esquerdo.\nSegure a parte de trás da barra com a mão esquerda. A palma da mão deve ficar em pegada neutra (palmas voltadas para o lado direito). Dica: certifique-se de que a pegada seja uniforme na barra. Seu tronco deve ficar bem no meio da barra e a distância entre o tronco e a mão direita (que deve estar à frente) deve ser a mesma que a distância entre o tronco e a mão esquerda (que deve estar atrás).\nAgora fique em pé com o peso. Dica: os pés devem estar afastados na largura dos ombros e as pontas ligeiramente voltadas para fora.\nAgache flexionando os joelhos e mantendo as costas retas até que a parte superior das coxas fique paralela ao chão. Dica: mantenha as costas o mais verticais possível em relação ao chão e a cabeça erguida. Lembre-se também de não deixar os joelhos passarem da ponta dos pés. Inspire durante esta parte do movimento.\nAgora impulsione-se de volta à posição inicial empurrando com os pés. Dica: mantenha a barra pendurada com os braços estendidos e os cotovelos travados com uma leve flexão. Os braços servem apenas como ganchos. Evite levantar o peso com eles. Faça o trabalho com as coxas, não com os braços.',
  'Jerk Balance':
    'Este exercício ajuda você a aprender a descer o suficiente durante o jerk e corrige quem se desloca para trás durante o movimento. Comece com a barra na posição de jerk sobre os ombros, com os ombros para a frente, o tronco ereto e os pés ligeiramente afastados em tesoura.\nInicie o movimento como em um jerk normal, flexionando os joelhos enquanto mantém o tronco vertical, e impulsione-se para cima com força, usando o impulso e não os braços para elevar o peso.\nMantenha o pé de trás no lugar, usando-o para impulsionar o corpo para a frente até uma tesoura completa enquanto executa o jerk com o peso. Recupere-se ficando em pé com o peso acima da cabeça.',
  'Jerk Dip Squat':
    'Este movimento fortalece a fase de flexão (dip) do jerk. Comece com a barra na posição de jerk sobre os ombros, com os ombros para a frente para criar uma prateleira e a barra tocando levemente a garganta. Os pés devem ficar diretamente sob o quadril, com as pontas voltadas para fora conforme for confortável.\nMantendo o tronco vertical, desça flexionando os joelhos, deixando-os avançar para a frente e sem mover o quadril para trás. A flexão não deve ser excessiva. Volte o peso à posição inicial impulsionando-se com força através dos pés.',
  'Jogging, Treadmill':
    'Para começar, suba na esteira e selecione a opção desejada no menu. A maioria das esteiras tem um modo manual, ou você pode selecionar um programa. Normalmente é possível informar sua idade e seu peso para estimar as calorias queimadas durante o exercício. A inclinação pode ser ajustada para mudar a intensidade do treino.\nAs esteiras oferecem conveniência, benefícios cardiovasculares e geralmente têm menos impacto que correr ao ar livre. Uma pessoa de 150 lb queima quase 250 calorias fazendo um trote de 30 minutos, contra mais de 450 calorias correndo. Mantenha a postura correta enquanto trota e segure nas barras apenas quando necessário, como ao descer ou ao verificar a frequência cardíaca.',
  'Keg Load':
    'Para carregar os barris, coloque o número desejado a certa distância da plataforma de carga, normalmente de 30 a 50 pés.\nComece segurando a alça mais próxima do primeiro barril, inclinando-o de lado para agarrar a borda oposta da base do barril. Levante o barril até o peito.\nQuanto mais alto você conseguir posicionar o barril, mais rápido deve conseguir se mover até a plataforma. Normalmente não é permitido apoiá-lo no ombro. Certifique-se de manter uma pegada firme no barril. Mova-se o mais rápido possível até a plataforma e carregue-o, estendendo o quadril, os joelhos e os tornozelos para levantá-lo o mais alto possível.\nVolte à posição inicial para pegar o próximo barril e repita até completar a prova.',
  'Kettlebell Arnold Press':
    'Faça um clean com o kettlebell até o ombro. Faça isso estendendo as pernas e o quadril enquanto sobe o kettlebell em direção ao ombro. A palma deve ficar voltada para dentro.\nOlhando para a frente, empurre o kettlebell para fora e acima da cabeça, girando o punho para que a palma fique voltada para a frente no alto do movimento.\nVolte o kettlebell à posição inicial, com a palma voltada para dentro.',
  'Kettlebell Dead Clean':
    'Coloque o kettlebell entre os pés. Para chegar à posição inicial, leve o quadril para trás e olhe para a frente.\nFaça um clean com o kettlebell até o ombro. Faça isso estendendo as pernas e o quadril enquanto sobe o kettlebell em direção ao ombro. O punho deve girar enquanto você faz isso.\nAbaixe o kettlebell, mantendo os posteriores de coxa carregados ao manter as costas retas e o quadril para trás.',
  'Kettlebell Figure 8':
    'Coloque um kettlebell entre as pernas e adote uma base mais larga que a largura dos ombros. Incline-se para a frente empurrando o quadril para trás e mantendo as costas retas.\nPegue o kettlebell e passe-o para a outra mão entre as pernas. A mão que recebe deve vir por trás das pernas. Vá e volte por várias repetições.',
  'Kettlebell Halo':
    'Fique em pé, ereto, com os pés afastados na largura do quadril. Segure um kettlebell de cabeça para baixo pelas alças, com o corpo do kettlebell acima das mãos e perto do peito. Contraia os abdominais e aperte os glúteos para que as costelas fiquem para baixo. Esta é a sua posição inicial.\nMantendo os cotovelos próximos à cabeça, leve o kettlebell para cima passando ao lado de uma orelha e contornando a parte de trás da cabeça.\nContinue o círculo passando pela orelha oposta e volte à posição inicial na frente do peito, deixando o kettlebell passar perto do corpo o tempo todo.\nComplete o número indicado de círculos em uma direção e depois repita a mesma quantidade na direção oposta.\nMova-se lentamente e mantenha a cabeça, o quadril e a lombar parados. Se a lombar arquear ou o kettlebell se afastar muito da cabeça, use um peso mais leve.',
  'Kettlebell Halo with Overhead Extension':
    'Fique em pé, ereto, com os pés afastados na largura do quadril. Segure um kettlebell de cabeça para baixo pelas alças, com o corpo do kettlebell acima das mãos e perto do peito. Contraia os abdominais e aperte os glúteos para que as costelas fiquem para baixo. Esta é a sua posição inicial.\nMantendo os cotovelos próximos à cabeça, leve o kettlebell para cima passando ao lado de uma orelha e contornando a cabeça até que fique atrás dela. Faça uma pausa aqui.\nA partir dessa posição, estenda os cotovelos para empurrar o kettlebell para cima, acima da cabeça, até que os braços fiquem retos, mantendo a parte superior dos braços ao lado da cabeça.\nFlexione os cotovelos para abaixar o kettlebell de volta à posição de pausa atrás da cabeça, com controle.\nContinue o círculo passando pela orelha oposta e volte à posição inicial na frente do peito para completar uma repetição.\nAlterne a direção do círculo a cada repetição. Mantenha a cabeça, o quadril e a lombar parados o tempo todo; se a lombar arquear ou você não conseguir chegar à posição acima da cabeça sem se inclinar para trás, use um peso mais leve ou faça o halo e a extensão como exercícios separados.',
  'Kettlebell Hang Clean':
    'Coloque o kettlebell entre os pés. Para chegar à posição inicial, leve o quadril para trás e olhe para a frente.\nFaça um clean com o kettlebell até o ombro. Faça isso estendendo as pernas e o quadril enquanto sobe o kettlebell em direção ao ombro. O punho deve girar enquanto você faz isso.\nAbaixe o kettlebell até uma posição pendurada entre as pernas mantendo os posteriores de coxa carregados. Mantenha a cabeça erguida o tempo todo.',
  'Kettlebell One-Legged Deadlift':
    'Segure um kettlebell pela alça com uma mão. Fique apoiado em uma perna, a do mesmo lado em que segura o kettlebell.\nMantendo esse joelho levemente flexionado, faça um levantamento terra com as pernas rígidas flexionando o quadril e estendendo a perna livre para trás para manter o equilíbrio.\nContinue abaixando o kettlebell até que o seu corpo fique paralelo ao chão e depois volte à posição ereta.',
  'Kettlebell Overhead Triceps Extension':
    'Fique em pé com os pés afastados na largura do quadril, segurando um kettlebell pelas alças com as duas mãos. Empurre-o acima da cabeça até estender os braços, com o corpo do kettlebell pendurado atrás das mãos.\nContraia os abdominais e mantenha a parte superior dos braços vertical e próxima da cabeça. Esta é a sua posição inicial.\nFlexione os cotovelos para abaixar o kettlebell atrás da cabeça, indo até onde a mobilidade dos ombros permitir sem que os cotovelos abram para fora.\nEstenda os cotovelos para empurrar o kettlebell de volta à posição inicial, mantendo a parte superior dos braços parada o tempo todo.\nMantenha as costelas para baixo e evite arquear a lombar ao estender.',
  'Kettlebell Pass Between The Legs':
    'Coloque um kettlebell entre as pernas e adote uma base confortável. Incline-se para a frente empurrando o quadril para trás e mantendo as costas retas.\nPegue o kettlebell e passe-o para a outra mão entre as pernas, no formato de um "W". Vá e volte por várias repetições.',
  'Kettlebell Pirate Ships':
    'Com uma base larga, segure um kettlebell com as duas mãos. Deixe-o pendurado na altura da cintura com os braços estendidos. Esta será a sua posição inicial.\nInicie o movimento girando para um lado, balançando o kettlebell até a altura da cabeça. Faça uma breve pausa no alto do movimento.\nDeixe o kettlebell descer enquanto gira para o lado oposto, levantando-o novamente até a altura da cabeça.\nRepita o número de repetições desejado.',
  'Kettlebell Pistol Squat':
    'Pegue um kettlebell com as duas mãos e segure-o pelas alças. Mantenha uma perna fora do chão e agache sobre a outra.\nAgache flexionando o joelho e levando o quadril para trás, segurando o kettlebell à sua frente.\nSegure a posição baixa por um segundo e depois inverta o movimento, empurrando pelo calcanhar e mantendo a cabeça e o peito erguidos.\nDesça novamente e repita.',
  'Kettlebell Seated Press':
    'Sente-se no chão e afaste as pernas de forma confortável.\nFaça um clean com um kettlebell até o ombro.\nEmpurre o kettlebell para cima e para fora até travá-lo acima da cabeça. Volte à posição inicial.',
  'Kettlebell Seesaw Press':
    'Faça um clean com dois kettlebells até os ombros.\nEmpurre um kettlebell para cima.\nAbaixe o kettlebell e imediatamente empurre o outro. Certifique-se de fazer o mesmo número de repetições nos dois lados.',
  'Kettlebell Sumo High Pull':
    'Coloque um kettlebell no chão entre os pés. Posicione os pés em uma base larga e segure o kettlebell com as duas mãos. Leve o quadril para trás o máximo possível, com os joelhos flexionados. Mantenha o peito e a cabeça erguidos. Esta será a sua posição inicial.\nComece estendendo o quadril e os joelhos, puxando ao mesmo tempo o kettlebell até os ombros e elevando os cotovelos enquanto faz isso. Inverta o movimento para voltar à posição inicial.',
  'Kettlebell Thruster':
    'Leve dois kettlebells aos ombros (clean). Estenda pernas e quadris enquanto puxa os kettlebells em direção aos ombros e gire os punhos ao fazer isso. Esta será sua posição inicial.\nComece o agachamento flexionando quadris e joelhos, abaixando o quadril entre as pernas. Mantenha as costas retas e eretas enquanto desce o máximo que conseguir.\nEmbaixo, inverta o movimento e suba estendendo joelhos e quadris, empurrando com os calcanhares. Ao fazer isso, empurre ambos os kettlebells acima da cabeça estendendo os braços para cima, usando o impulso do agachamento para ajudar a subir o peso.\nAo iniciar a próxima repetição, retorne os pesos aos ombros.',
  'Kettlebell Turkish Get-Up (Lunge style)':
    'Deite-se de costas no chão e empurre um kettlebell até a posição superior estendendo o cotovelo. Flexione o joelho do mesmo lado do kettlebell.\nMantendo o kettlebell com o braço travado o tempo todo, gire para o lado oposto e use o braço que não trabalha para ajudar a avançar até a posição de afundo. Com a mão livre, empurre-se até ficar sentado e depois passe para o apoio em um joelho.\nEnquanto olha para o kettlebell, levante-se lentamente. Inverta o movimento até a posição inicial e repita.',
  'Kettlebell Turkish Get-Up (Squat style)':
    'Deite-se de costas no chão e empurre um kettlebell até a posição superior estendendo o cotovelo. Flexione o joelho do mesmo lado do kettlebell.\nMantendo o kettlebell com o braço travado o tempo todo, gire para o lado oposto e use o braço que não trabalha para ajudar a avançar até a posição de afundo.\nCom a mão livre, empurre-se até ficar sentado e depois até ficar em pé. Enquanto olha para o kettlebell, levante-se lentamente. Inverta o movimento até a posição inicial e repita.',
  'Kettlebell Windmill':
    'Posicione um kettlebell à frente do pé dianteiro, leve-o aos ombros (clean) e empurre-o acima da cabeça com o braço oposto. Para o clean, estenda pernas e quadris enquanto puxa o kettlebell em direção ao ombro. Gire o punho ao fazer isso, de modo que a palma fique voltada para a frente. Empurre-o para cima estendendo o cotovelo.\nMantendo o kettlebell com o braço travado o tempo todo, empurre o quadril na direção do kettlebell estendido. Gire os pés para fora, cerca de quarenta e cinco graus em relação ao braço que sustenta o kettlebell. Flexionando o quadril para um lado e jogando o glúteo para fora, incline-se lentamente até conseguir tocar o chão com a mão livre. Mantenha os olhos no kettlebell acima da cabeça o tempo todo.\nFaça uma pausa de um segundo ao alcançar o chão e inverta o movimento até a posição inicial.',
  'Kipping Muscle Up':
    'Segure os anéis com pegada falsa, com a base das palmas sobre os anéis.\nComece balançando levemente as pernas para trás.\nContraponha esse movimento balançando as pernas para a frente e para cima, jogando o queixo e o peito para trás e puxando-se para cima com os dois braços. Ao chegar à posição superior da barra fixa, puxe os anéis até as axilas enquanto rola os ombros para a frente, deixando os cotovelos irem para trás. Isso coloca você na posição correta para continuar na fase de paralelas do movimento.\nMantendo controle e estabilidade, estenda os cotovelos para completar o movimento.\nTenha cuidado ao descer até o chão.',
  'Knee Across The Body':
    'Deite-se no chão com a perna direita estendida. Flexione a perna esquerda e abaixe-a cruzando o corpo, segurando o joelho em direção ao chão com a mão direita. (O joelho não precisa tocar o chão se você estiver tenso.)\nColoque o braço esquerdo confortavelmente ao seu lado e vire a cabeça para a esquerda. Imagine que há um peso amarrado ao seu cóccix. Deixe o cóccix cair em direção ao chão enquanto o peito alcança a direção oposta para alongar a lombar. Troque de lado.',
  'Knee Circles':
    'Fique em pé com as pernas juntas e as mãos na altura da cintura.\nAgora mova os joelhos em movimento circular enquanto respira normalmente.\nRepita pelo número de repetições recomendado.',
  'Knee Tuck Jump':
    'Comece em pé, em uma posição confortável, com os joelhos levemente flexionados. Mantenha as mãos à sua frente, com as palmas para baixo e as pontas dos dedos juntas na altura do peito. Esta será sua posição inicial.\nDesça rapidamente para um quarto de agachamento e salte imediatamente de forma explosiva. Leve os joelhos em direção ao peito, tentando tocar as palmas das mãos com eles.\nSalte o mais alto que puder, subindo os joelhos, e depois garanta uma boa aterrissagem estendendo novamente as pernas e absorvendo o impacto deixando os joelhos flexionarem.',
  'Knee/Hip Raise On Parallel Bars':
    'Posicione-se no banco de elevação de pernas vertical com os antebraços apoiados nas almofadas ao lado do tronco e segurando as manoplas. Seus braços ficarão flexionados a 90 graus.\nO tronco deve estar reto, com a lombar pressionada contra o encosto da máquina e as pernas estendidas apontando para o chão. Esta será sua posição inicial.\nAgora, ao expirar, levante as pernas mantendo-as estendidas. Continue o movimento até que as pernas estejam aproximadamente paralelas ao chão e mantenha a contração por um segundo. Dica: não use impulso nem balanço ao fazer este exercício.\nVolte lentamente à posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado.',
  'Kneeling Arm Drill':
    'Este exercício ajuda a melhorar a eficiência do movimento dos braços durante a corrida. Comece ajoelhado, com o pé esquerdo à frente e o joelho direito no chão. Pressione o calcanhar da frente para manter os glúteos e os posteriores de coxa ativados.\nComece movimentando os braços em balanços longos, como um pêndulo. Feche o ângulo dos braços, movimentando-os como ao trotar, progredindo para uma corrida e por fim um sprint.\nAssim que as mãos passarem pelo quadril, acelere-as para a frente durante o movimento de sprint para movê-las o mais rápido possível.\nTroque de joelho e repita.',
  'Kneeling Cable Crunch With Alternating Oblique Twists':
    'Conecte um acessório de corda a uma polia alta e posicione um colchonete no chão à frente dela.\nSegure a corda com as duas mãos e ajoelhe-se a aproximadamente sessenta centímetros da torre.\nPosicione a corda atrás da cabeça, com as mãos junto às orelhas.\nMantenha as mãos no mesmo lugar, contraia os abdominais e puxe a corda para baixo em um movimento de abdominal até que os cotovelos alcancem os joelhos.\nFaça uma breve pausa embaixo e suba de forma lenta e controlada até a posição inicial.\nRepita o mesmo movimento para baixo até chegar na metade, quando você começará a rotacionar um dos cotovelos em direção ao joelho oposto.\nNovamente, faça uma breve pausa embaixo e suba de forma lenta e controlada até a posição inicial.\nRepita o mesmo movimento de antes, mas alterne levando o outro cotovelo em direção ao joelho oposto.\nContinue essa série de movimentos até a falha.',
  'Kneeling Cable Triceps Extension':
    'Posicione um banco de lado em frente a uma polia alta.\nSegure uma barra reta acima da cabeça com as mãos afastadas cerca de 15 cm e as palmas voltadas para baixo.\nFique de costas para a máquina e ajoelhe-se.\nApoie a cabeça e a parte de trás dos braços no banco. Os cotovelos devem estar flexionados com os antebraços apontando para a polia alta. Esta será sua posição inicial.\nMantendo os braços próximos à cabeça o tempo todo e os cotovelos para dentro, empurre a barra para fora em um movimento semicircular até que os cotovelos fiquem estendidos e os braços paralelos ao chão. Contraia forte o tríceps e mantenha essa posição por um segundo. Expire ao fazer este movimento.\nVolte lentamente à posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado.',
  'Kneeling Forearm Stretch':
    'Comece ajoelhado sobre um colchonete com as palmas planas e os dedos apontando para trás, em direção aos joelhos.\nIncline-se lentamente para trás mantendo as palmas planas no chão até sentir um alongamento nos punhos e antebraços. Mantenha por 20 a 30 segundos.',
  'Kneeling High Pulley Row':
    'Selecione a carga adequada em uma polia acima da sua cabeça. Conecte uma corda ao cabo e ajoelhe-se a um ou dois passos de distância, segurando a corda à sua frente com os dois braços estendidos. Esta será sua posição inicial.\nInicie o movimento flexionando os cotovelos e retraindo completamente os ombros, puxando a corda em direção à parte superior do peito com os cotovelos para fora.\nApós uma breve pausa, volte lentamente à posição inicial.',
  'Kneeling Hip Flexor':
    'Ajoelhe-se sobre um colchonete e leve o joelho direito à frente, de modo que a sola do pé fique no chão, e estenda a perna esquerda para trás, de modo que o peito do pé fique no chão.\nDesloque seu peso para a frente até sentir um alongamento no quadril. Mantenha por 15 segundos e depois repita do outro lado.',
  'Kneeling Jump Squat':
    'Comece ajoelhado no chão com uma barra apoiada na parte de trás dos ombros, ou você pode usar o peso corporal neste exercício. Pode ser feito dentro de um rack de potência para facilitar a retirada da barra.\nSente-se para trás com o quadril até que os glúteos toquem os pés, mantendo a cabeça e o peito erguidos.\nSuba de forma explosiva com o quadril, gerando potência suficiente para aterrissar com os pés totalmente apoiados no chão.\nContinue o agachamento empurrando com os calcanhares e estendendo os joelhos até ficar em pé.',
  'Kneeling Single-Arm High Pulley Row':
    'Conecte uma manopla simples a uma polia alta e escolha a carga.\nAjoelhe-se de frente para a torre de cabos, segurando o cabo com uma mão e o braço estendido. Esta será sua posição inicial.\nComeçando com a palma voltada para a frente, puxe o peso em direção ao tronco flexionando o cotovelo e retraindo a escápula. Ao fazer isso, gire o punho de modo que, ao final do movimento, a palma fique voltada para você.\nApós uma breve pausa, volte à posição inicial.',
  'Kneeling Squat':
    'Ajuste a barra na altura adequada em um rack de potência. Ajoelhe-se atrás da barra; pode ser útil colocar um colchonete para amortecer os joelhos. Entre embaixo da barra, apoiando-a na parte de trás dos ombros. As escápulas devem estar retraídas e a barra firme sobre suas costas. Retire o peso do suporte.\nCom o olhar para a frente, sente-se para trás com os glúteos até tocar as panturrilhas.\nInverta o movimento, retornando o tronco a uma posição ereta.',
  "Landmine 180's":
    'Posicione uma barra em um landmine ou fixe-a com segurança em um canto. Carregue a barra com um peso adequado.\nLevante a barra do chão, levando-a à altura dos ombros com as duas mãos e os braços estendidos à sua frente. Adote uma base larga. Esta será sua posição inicial.\nExecute o movimento rotacionando o tronco e o quadril enquanto balança o peso até embaixo, para um lado. Mantenha os braços estendidos durante todo o exercício.\nInverta o movimento para balançar o peso até o lado oposto.\nContinue alternando o movimento até completar a série.',
  'Landmine Linear Jammer':
    'Posicione uma barra em um landmine ou, se não tiver um, fixe-a com segurança em um canto. Carregue a barra com um peso adequado e coloque o acessório de manoplas na barra.\nLevante a barra do chão, levando as manoplas aos ombros. Esta será sua posição inicial.\nEm uma postura atlética, agache flexionando o quadril e levando-o para trás, mantendo os braços flexionados.\nInverta o movimento estendendo com força quadris, joelhos e tornozelos, estendendo também os cotovelos para esticar os braços. Este movimento deve ser feito de forma explosiva, saindo do agachamento até a extensão completa com a maior potência possível.\nRetorne à posição inicial.',
  'Lateral Bound':
    'Assuma uma posição de meio agachamento, de frente a 90 graus em relação à direção do deslocamento. Esta será sua posição inicial.\nDeixe a perna da frente fazer um contramovimento para dentro enquanto transfere o peso para a perna de fora.\nImpulsione-se imediatamente e estenda o corpo, tentando saltar para o lado o mais longe possível.\nAo aterrissar, impulsione-se imediatamente na direção oposta, retornando à posição inicial original.\nContinue de um lado para o outro por várias repetições.',
  'Lateral Box Jump':
    'Assuma uma posição em pé confortável, com uma caixa baixa posicionada ao seu lado. Esta será sua posição inicial.\nDesça rapidamente para um quarto de agachamento para iniciar o reflexo de estiramento e inverta imediatamente a direção para saltar para cima e para o lado.\nSuba os joelhos o suficiente para garantir que os pés passem com boa folga sobre a caixa.\nAterrisse no centro da caixa, usando as pernas para absorver o impacto.\nSalte com cuidado para o outro lado da caixa e continue de um lado para o outro por várias repetições.',
  'Lateral Cone Hops':
    'Posicione vários cones em uma fileira, separados por alguns passos.\nFique em pé ao lado da extremidade dos cones, de frente a 90 graus em relação à direção do deslocamento. Esta será sua posição inicial.\nInicie o salto flexionando os joelhos para ativar o reflexo de estiramento e inverta imediatamente a direção para se impulsionar do chão, saltando para cima e para o lado sobre o cone.\nUse as pernas para absorver o impacto ao aterrissar e rebata para o próximo salto, continuando ao longo da fileira de cones.',
  'Lateral Raise - With Bands':
    'Para começar, fique em pé sobre uma faixa elástica de modo que a tensão comece com os braços estendidos. Segure as manoplas com pegada pronada (palmas voltadas para as coxas) um pouco menor que a largura dos ombros. As manoplas devem ficar ao lado das coxas. Os braços devem estar estendidos com uma leve flexão nos cotovelos e as costas retas. Esta será sua posição inicial.\nUse a parte lateral dos ombros para elevar as manoplas para os lados enquanto expira. Continue elevando até que estejam ligeiramente acima da paralela. Dica: ao elevar as manoplas, incline levemente a mão como se estivesse derramando água e mantenha os braços estendidos. Além disso, mantenha o tronco parado e faça uma pausa de um segundo no topo do movimento.\nAbaixe lentamente as manoplas até a posição inicial. Inspire durante esta parte do movimento.\nRepita pelo número de repetições recomendado.',
  'Latissimus Dorsi-SMR':
    'Deitado no chão, coloque um rolo de espuma sob as costas, mais para um lado, logo atrás da axila. Esta será sua posição inicial.\nMantenha o braço do lado que está sendo alongado atrás e ao lado do corpo enquanto transfere o peso para os dorsais, mantendo a parte superior do corpo afastada do chão. Mantenha por 10 a 30 segundos e troque de lado.',
  'Leg Extensions':
    'Para este exercício você precisará de uma cadeira extensora. Primeiro escolha a carga e sente-se na máquina com as pernas sob o apoio (pés apontando para a frente) e as mãos segurando as barras laterais. Esta será sua posição inicial. Dica: você precisará ajustar o apoio para que ele fique sobre a parte inferior da perna (logo acima dos pés). Além disso, certifique-se de que as pernas formem um ângulo de 90 graus entre a parte inferior e a superior. Se o ângulo for menor que 90 graus, significa que o joelho está passando dos dedos dos pés, o que gera estresse desnecessário na articulação do joelho. Se a máquina for projetada assim, procure outra máquina ou apenas certifique-se de parar de descer ao atingir o ângulo de 90 graus ao executar o exercício.\nUsando os quadríceps, estenda as pernas ao máximo enquanto expira. Certifique-se de que o restante do corpo permaneça parado no banco. Faça uma pausa de um segundo na posição de contração.\nAbaixe lentamente o peso até a posição original enquanto inspira, garantindo que não passe do limite de 90 graus.\nRepita pelo número de repetições recomendado.',
  'Leg Lift':
    'Em pé e ereto, com os dois pés juntos a aproximadamente a largura dos ombros, segure uma superfície firme, como as laterais de um rack de agachamento ou o encosto de uma cadeira, para se apoiar e manter o equilíbrio.\nCom ou sem caneleira, levante uma perna para trás como se estivesse fazendo uma flexão de perna, mas em pé, mantendo a outra perna reta. Expire ao fazer este movimento.\nAbaixe lentamente a perna elevada até o chão enquanto inspira.\nRepita pelo número de repetições recomendado.\nRepita o movimento com a perna oposta.',
  'Leg Press':
    'Em uma máquina de leg press, sente-se e coloque os pés na plataforma à sua frente, com afastamento médio (na largura dos ombros). (Nota: para esta explicação usaremos o afastamento médio descrito, que trabalha o desenvolvimento geral; no entanto, você pode escolher qualquer uma das três posições descritas na seção de posicionamento dos pés).\nAbaixe as barras de segurança que sustentam a plataforma com peso e empurre a plataforma até o alto, até que as pernas fiquem totalmente estendidas à sua frente. Dica: certifique-se de não travar os joelhos. O tronco e as pernas devem formar um ângulo perfeito de 90 graus. Esta será sua posição inicial.\nAo inspirar, abaixe lentamente a plataforma até que a parte superior e a inferior das pernas formem um ângulo de 90 graus.\nEmpurrando principalmente com os calcanhares e usando os quadríceps, volte à posição inicial enquanto expira.\nRepita pelo número de repetições recomendado e certifique-se de travar corretamente os pinos de segurança ao terminar. Você não quer que a plataforma carregada caia sobre você.',
  'Leg Pull-In':
    'Deite-se em um colchonete com as pernas estendidas e as mãos com as palmas para baixo ao lado do corpo ou sob os glúteos. Dica: minha preferência é com as mãos ao lado do corpo. Esta será sua posição inicial.\nFlexione os joelhos e puxe as coxas em direção ao abdômen enquanto expira. Continue o movimento até que os joelhos estejam aproximadamente na altura do peito. Contraia os abdominais ao executar este movimento e mantenha por um segundo no alto. Dica: durante o movimento, a parte inferior das pernas (panturrilhas) deve permanecer sempre paralela ao chão.\nVolte à posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado.',
  'Leg-Over Floor Press':
    'Deite-se no chão com um kettlebell sobre o peito, segurando-o pela alça. Cruze a perna do lado que trabalha sobre a perna do lado que não trabalha. O braço livre pode ficar estendido ao lado do corpo como apoio.\nEmpurre o kettlebell até travar o braço no alto.\nAbaixe o peso até o cotovelo tocar o chão, mantendo o kettlebell acima do cotovelo. Repita pelo número de repetições desejado.',
  'Leg-Up Hamstring Stretch':
    'Deite-se de costas, flexione um joelho e apoie esse pé totalmente no chão para estabilizar a coluna.\nEstenda a outra perna no ar. Se estiver tenso, não conseguirá esticá-la totalmente. Tudo bem. Estenda o joelho de modo que a sola do pé levantado fique voltada para o teto (ou o mais próximo que conseguir).\nEstique lentamente as pernas o máximo possível e depois puxe a perna em direção ao nariz. Troque de lado.',
  'Leverage Chest Press':
    'Coloque o pino em uma carga adequada e ajuste o assento para a sua altura. As manoplas devem ficar próximas à parte inferior ou média dos peitorais no início do movimento.\nO peito e a cabeça devem estar erguidos e as escápulas retraídas. Esta será sua posição inicial.\nEmpurre as manoplas para a frente estendendo os cotovelos.\nApós uma breve pausa no alto, retorne o peso até um pouco acima da posição inicial, mantendo a tensão nos músculos ao não apoiar o peso nos batentes até terminar a série.',
  'Leverage Deadlift':
    'Coloque o pino em uma carga adequada. Posicione-se exatamente entre as manoplas. Segure as manoplas inferiores com uma pegada confortável e depois abaixe o quadril enquanto inspira. Olhe para a frente com a cabeça e mantenha o peito erguido. Esta será sua posição inicial.\nRetorne o peso à posição inicial.',
  'Leverage Decline Chest Press':
    'Coloque o pino em uma carga adequada e ajuste o assento para a sua altura. As manoplas devem ficar próximas à parte inferior dos peitorais no início do movimento. O peito e a cabeça devem estar erguidos e as escápulas retraídas. Esta será sua posição inicial.\nEmpurre as manoplas para a frente estendendo os cotovelos.\nApós uma breve pausa no alto, retorne o peso até um pouco acima da posição inicial, mantendo a tensão nos músculos ao não apoiar o peso nos batentes até terminar a série.',
  'Leverage High Row':
    'Coloque o pino em uma carga adequada e ajuste a altura do assento para que você alcance as manoplas acima de você. Ajuste o apoio dos joelhos para ajudar a mantê-lo firme. Segure as manoplas com pegada pronada. Esta será sua posição inicial.\nPuxe as manoplas em direção ao tronco, retraindo as escápulas enquanto flexiona os cotovelos.\nFaça uma pausa na parte final do movimento e depois retorne lentamente as manoplas à posição inicial.\nEm várias repetições, evite retornar completamente o peso aos batentes para manter a tensão nos músculos trabalhados.',
  'Leverage Incline Chest Press':
    'Coloque o pino em uma carga adequada e ajuste o assento para a sua altura. As manoplas devem ficar próximas à parte superior dos peitorais no início do movimento. O peito e a cabeça devem estar erguidos e as escápulas retraídas. Esta será sua posição inicial.\nEmpurre as manoplas para a frente estendendo os cotovelos.\nApós uma breve pausa no alto, retorne o peso até um pouco acima da posição inicial, mantendo a tensão nos músculos ao não apoiar o peso nos batentes até terminar a série.',
  'Leverage Iso Row':
    'Coloque o pino em uma carga adequada e ajuste a altura do assento para que as manoplas fiquem na altura do peito. Segure as manoplas com pegada neutra ou pronada. Esta será sua posição inicial.\nPuxe as manoplas em direção ao tronco, retraindo as escápulas enquanto flexiona os cotovelos.\nFaça uma pausa na parte final do movimento e depois retorne lentamente as manoplas à posição inicial. Em várias repetições, evite retornar completamente o peso aos batentes para manter a tensão nos músculos trabalhados.',
  'Leverage Shoulder Press':
    'Coloque o pino em uma carga adequada e ajuste o assento para a sua altura. As manoplas devem ficar próximas à parte superior dos ombros no início do movimento. O peito e a cabeça devem estar erguidos e as manoplas seguradas com pegada pronada. Esta será sua posição inicial.\nEmpurre as manoplas para cima estendendo os cotovelos.\nApós uma breve pausa no alto, retorne o peso até um pouco acima da posição inicial, mantendo a tensão nos músculos ao não apoiar o peso nos batentes até terminar a série.',
  'Leverage Shrug':
    'Coloque o pino em uma carga adequada. Posicione-se exatamente entre as manoplas.\nSegure as manoplas superiores com uma pegada confortável e depois abaixe o quadril enquanto inspira. Olhe para a frente com a cabeça e mantenha o peito erguido.\nEmpurre o chão com os calcanhares, estendendo quadris e joelhos até ficar em pé. Mantenha os braços retos durante todo o movimento, terminando com os ombros para trás. Esta será sua posição inicial.\nEleve o peso encolhendo os ombros em direção às orelhas, movendo-se diretamente para cima e para baixo.\nFaça uma pausa no topo do movimento e depois retorne o peso à posição inicial.',
  'Linear 3-Part Start Technique':
    'Este exercício ajuda você a acelerar o mais rápido possível em um sprint a partir da posição parada. Ajuda usar uma linha de partida. Comece com os dois pés na linha. Posicione o pé esquerdo com a ponta junto ao tornozelo direito. Posicione o pé direito de 10 a 15 cm atrás do esquerdo.\nColoque a mão direita sobre a linha e depois aproxime o nariz do joelho esquerdo.\nAgache enquanto se inclina para a frente, com a cabeça mais baixa que o quadril e o peso carregado sobre a perna esquerda. Esta será sua posição inicial.\nLeve a mão esquerda para cima de modo que fique paralela ao chão, apontando para trás, e saia de forma explosiva quando estiver pronto.',
  'Linear Acceleration Wall Drill':
    'Incline-se a cerca de 45 graus contra uma parede. Os pés devem estar juntos e os glúteos contraídos.\nComece levantando rapidamente o joelho direito, fazendo uma pausa e depois levando-o diretamente para baixo, em direção ao chão.\nTroque de perna, levantando o joelho oposto e depois atacando o chão diretamente para baixo.\nRepita mais uma vez com a perna direita e, assim que o pé direito tocar o chão, martele o chão rapidamente, alternando esquerda e direita o mais rápido que puder.',
  'Linear Depth Jump':
    'Você precisará de duas caixas ou bancos separados por alguns passos. Comece em pé sobre uma caixa, de frente para a outra plataforma.\nPara iniciar o movimento, desça suavemente até o chão entre as plataformas, permitindo que joelhos e quadris flexionem.\nInverta o movimento de forma explosiva, estendendo quadris, joelhos e tornozelos para saltar sobre a outra plataforma.\nAterrisse suavemente, absorvendo o impacto com as pernas.',
  'Log Lift':
    'Comece em pé com o tronco (log) à sua frente. Segure as alças e comece a levar o log aos ombros (clean). Enquanto está inclinado para iniciar o clean, tente levar o log o mais alto possível, puxando-o contra o peito. Estenda quadris e joelhos para subi-lo e completar o clean.\nJogue a cabeça para trás e olhe para cima, criando uma prateleira no peito para apoiar o log. Inicie o desenvolvimento flexionando levemente os joelhos e invertendo o movimento. Este push press gerará o impulso para que o log comece a subir verticalmente. Continue estendendo os cotovelos para empurrar o log acima da cabeça. Não há regras rígidas de técnica, então use a que for mais eficiente para você. Ao empurrar o log, certifique-se de passar a cabeça para a frente a cada repetição, olhando para a frente.\nRepita quantas vezes for possível. Tente controlar a descida do log ao devolvê-lo ao chão.',
  'London Bridges':
    'Prenda uma corda de escalada a uma viga alta ou travessa. Embaixo, certifique-se de que a barra do smith esteja travada com os limitadores e não possa se mover. Alternativamente, também pode ser usada uma caixa firme.\nSuba na barra, usando a corda para se equilibrar. Esta será sua posição inicial.\nMantendo o corpo reto, incline-se para trás e abaixe o corpo avançando lentamente mão sobre mão pela corda. Continue até ficar perpendicular ao chão.\nMantendo o corpo reto, inverta o movimento, avançando mão sobre mão de volta à posição inicial.',
  'Looking At Ceiling':
    'Ajoelhe-se no chão, segurando os calcanhares com as duas mãos.\nLevante os glúteos para cima e para a frente enquanto leva a cabeça para trás para olhar para o teto, criando um arco nas costas.',
  'Low Cable Crossover':
    'Para entrar na posição inicial, coloque as polias na posição baixa, selecione a resistência a ser usada e segure uma manopla em cada mão.\nDê um passo à frente, gerando tensão nas polias. As palmas devem estar voltadas para a frente, as mãos abaixo da cintura e os braços retos. Esta será sua posição inicial.\nCom uma leve flexão nos braços, leve as mãos para cima e em direção à linha média do corpo. As mãos devem se juntar à frente do peito, com as palmas voltadas para cima.\nRetorne os braços à posição inicial após uma breve pausa.',
  'Low Cable Triceps Extension':
    'Selecione a carga desejada e deite-se de barriga para cima no banco de uma máquina de remada sentada que tenha uma corda conectada. A cabeça deve apontar para o acessório.\nSegure as extremidades da corda por fora com as palmas voltadas uma para a outra (pegada neutra).\nPosicione os cotovelos flexionados a 90 graus e os braços perpendiculares (90 graus) ao tronco. Dica: mantenha os cotovelos para dentro e certifique-se de que os braços apontem para o teto enquanto os antebraços apontam para a polia acima da cabeça. Esta será sua posição inicial.\nAo expirar, estenda os antebraços até ficarem retos e verticais. Os braços e os cotovelos permanecem parados durante todo o movimento. Apenas os antebraços devem se mover. Contraia forte o tríceps por um segundo.\nAo inspirar, retorne lentamente à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Low Pulley Row To Neck':
    'Sente-se em uma máquina de remada com polia baixa com um acessório de corda.\nSegure as pontas da corda com as palmas voltadas para baixo e sente-se com as costas retas e os joelhos levemente flexionados. Dica: mantenha as costas quase totalmente verticais e os braços totalmente estendidos à sua frente. Esta será sua posição inicial.\nMantendo o tronco parado, levante os cotovelos e comece a flexioná-los enquanto puxa a corda em direção ao pescoço, expirando. Durante todo o movimento, a parte superior dos braços deve permanecer paralela ao chão. Dica: continue esse movimento até que as mãos estejam quase ao lado das orelhas (os antebraços não ficarão paralelos ao chão no final do movimento, pois estarão um pouco inclinados para cima) e os cotovelos estejam para fora, afastados das laterais do corpo.\nApós manter por cerca de um segundo na posição de contração, volte lentamente à posição inicial enquanto inspira. Dica: novamente, em nenhum momento do movimento o tronco deve se mover.\nRepita pelo número de repetições recomendado.',
  'Lower Back Curl':
    'Deite-se de bruços com os braços estendidos para os lados. Esta será sua posição inicial.\nUsando os músculos da lombar, estenda a coluna levantando o peito do chão. Não use os braços para se impulsionar. Mantenha a cabeça erguida durante o movimento. Repita de 10 a 20 repetições.',
  'Lower Back-SMR':
    'Sentado, coloque um rolo de espuma sob a lombar. Cruze os braços à sua frente e protraia os ombros. Esta será sua posição inicial.\nLevante o quadril do chão e incline-se para trás, mantendo o peso sobre a lombar. Agora desloque o peso levemente para um lado, mantendo-o fora da coluna e sobre os músculos ao lado dela. Role sobre a lombar, mantendo os pontos de tensão por 10 a 30 segundos. Repita do outro lado.',
  'Lunge Pass Through':
    'Fique em pé com o tronco ereto segurando um kettlebell na mão direita. Esta será sua posição inicial.\nDê um passo à frente com o pé esquerdo e abaixe o corpo flexionando o quadril e o joelho, mantendo o tronco ereto. Abaixe o joelho de trás até quase tocar o chão.\nDurante o afundo, passe o kettlebell por baixo da perna da frente para a mão oposta.\nEmpurrando pelo calcanhar do pé, retorne à posição inicial.\nRepita o movimento pelo número de repetições recomendado, alternando as pernas.',
  'Lunge Sprint':
    'Ajuste uma barra no smith a uma altura adequada. Posicione-se sob a barra, apoiando-a na parte de trás dos ombros. Retire a barra do suporte e depois afaste os pés, levando um pé para a frente e outro para trás. Esta será sua posição inicial.\nAbaixe o joelho de trás quase até o chão, flexionando os joelhos e abaixando o quadril ao fazer isso.\nNo final da descida, inverta imediatamente a direção. Empurre de forma explosiva pelo calcanhar do pé da frente com leve pressão do pé de trás. Salte e inverta a posição das pernas.\nRepita pelo número de repetições recomendado.',
  'Lying Bent Leg Groin':
    'Deite-se de costas com os joelhos flexionados e as solas dos pés unidas. Peça para seu parceiro segurar seus joelhos. Esta será sua posição inicial.\nTente juntar os joelhos apertando, enquanto seu parceiro impede que qualquer movimento ocorra.\nApós 10 a 20 segundos, relaxe os músculos enquanto seu parceiro empurra suavemente seus joelhos em direção ao chão. Avise seu ajudante quando o alongamento for adequado para evitar lesões ou alongamento excessivo.',
  'Lying Cable Curl':
    'Segure com as duas mãos uma barra reta ou barra W conectada à polia baixa, com pegada supinada (palmas para cima) na largura dos ombros.\nDeite-se de costas sobre um colchonete em frente à pilha de pesos, com os pés apoiados contra a estrutura da máquina de polias e as pernas retas.\nCom os braços estendidos e os cotovelos próximos ao corpo, flexione levemente os braços. Esta será sua posição inicial.\nMantendo a parte superior dos braços parada e os cotovelos próximos ao corpo, suba a barra lentamente em direção ao peito enquanto expira e aperta os bíceps.\nApós um segundo de contração no topo do movimento, volte lentamente à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Lying Cambered Barbell Row':
    'Coloque uma barra cambered (curvada) sob um banco de exercícios.\nDeite-se de bruços no banco e segure a barra com pegada pronada (palmas para baixo) mais larga que os ombros. Esta será sua posição inicial.\nAo expirar, reme a barra para cima mantendo os cotovelos próximos ao corpo, seja em direção ao peito, para trabalhar a parte média superior das costas, ou em direção ao abdômen se o objetivo for trabalhar os dorsais.\nApós manter por um segundo no alto, abaixe lentamente até a posição inicial enquanto inspira.',
  'Lying Close-Grip Bar Curl On High Pulley':
    'Coloque um banco reto em frente a uma polia alta ou a uma máquina de puxada alta.\nSegure a barra reta com pegada supinada (palmas para cima) na largura aproximada dos ombros.\nDeite-se de costas com a cabeça para além da ponta do banco.\nAgora estenda os braços retos acima dos ombros. Seu tronco e seus braços devem formar um ângulo de 90 graus e os cotovelos devem ficar junto ao corpo. Esta será sua posição inicial.\nAo expirar, faça a rosca da barra para baixo em um movimento semicircular até tocar o queixo. Contraia os bíceps por um segundo na posição superior de contração. Dica: neste movimento, apenas os antebraços devem se mover. Em nenhum momento os braços devem se mover. Eles devem permanecer perpendiculares durante todo o movimento.\nVolte lentamente à posição inicial.\nRepita o número recomendado de repetições.',
  'Lying Close-Grip Barbell Triceps Extension Behind The Head':
    'Segurando uma barra reta ou uma barra W com pegada pronada (palmas para a frente), deite-se de costas em um banco reto com a cabeça perto da ponta do banco. Dica: se estiver usando uma barra reta, segure-a com uma pegada na largura dos ombros; se estiver usando uma barra W, segure-a pelas pegadas internas.\nEstenda os braços à sua frente e leve lentamente a barra para trás em um movimento semicircular (mantendo os braços estendidos) até uma posição acima da cabeça. Ao final deste passo, seus braços devem estar acima da cabeça e paralelos ao chão. Esta será sua posição inicial. Dica: mantenha os cotovelos junto ao corpo o tempo todo.\nAo inspirar, abaixe a barra flexionando os cotovelos e mantendo os braços parados. Continue abaixando a barra até que os antebraços fiquem perpendiculares ao chão.\nAo expirar, traga a barra de volta à posição inicial empurrando-a em um movimento semicircular até que os antebraços também fiquem paralelos ao chão. Contraia os tríceps com força na parte superior do movimento por um segundo. Dica: novamente, apenas os antebraços devem se mover. Os braços devem permanecer parados o tempo todo.\nRepita o número recomendado de repetições.',
  'Lying Close-Grip Barbell Triceps Press To Chin':
    'Segurando uma barra reta ou uma barra W com pegada pronada (palmas para a frente), deite-se de costas em um banco reto com a cabeça para além da ponta do banco. Dica: se estiver usando uma barra reta, segure-a com uma pegada na largura dos ombros; se estiver usando uma barra W, segure-a pelas pegadas internas.\nEstenda os braços à sua frente enquanto segura a barra sobre o peito. Os braços devem ficar perpendiculares ao tronco (ângulo de 90 graus). Esta será sua posição inicial.\nAo inspirar, abaixe a barra em um movimento semicircular flexionando os cotovelos, mantendo os braços parados e os cotovelos junto ao corpo. Continue abaixando a barra até que ela toque levemente o queixo.\nAo expirar, traga a barra de volta à posição inicial empurrando-a em um movimento semicircular. Contraia os tríceps com força na parte superior do movimento por um segundo. Dica: novamente, apenas os antebraços devem se mover. Os braços devem permanecer parados o tempo todo.\nRepita o número recomendado de repetições.',
  'Lying Crossover':
    'Deite-se de costas com as pernas estendidas.\nCruze uma perna sobre o corpo com o joelho flexionado, tentando tocar o joelho no chão. Seu parceiro deve se ajoelhar ao seu lado, segurando seu ombro no chão com uma mão e controlando a perna cruzada com a outra. Esta será sua posição inicial.\nTente levantar o joelho flexionado do chão enquanto seu parceiro impede qualquer movimento real.\nApós 10 a 20 segundos, relaxe a perna enquanto seu parceiro pressiona suavemente o joelho em direção ao chão. Repita com o outro lado.',
  'Lying Dumbbell Tricep Extension':
    'Deite-se em um banco reto segurando dois halteres diretamente à sua frente. Seus braços devem estar totalmente estendidos, formando um ângulo de 90 graus com o tronco e com o chão. As palmas devem ficar voltadas para dentro e os cotovelos junto ao corpo. Esta é a posição inicial.\nAo inspirar, e mantendo os braços parados com os cotovelos para dentro, abaixe lentamente o peso até que os halteres fiquem perto das orelhas.\nNesse ponto, mantendo os cotovelos para dentro e os braços parados, use os tríceps para levar o peso de volta à posição inicial enquanto expira.\nRepita o número recomendado de repetições.',
  'Lying Face Down Plate Neck Resistance':
    'Deite-se de bruços com o corpo todo reto em um banco reto, segurando um anilha atrás da cabeça. Dica: você precisará se posicionar de modo que os ombros fiquem ligeiramente além da ponta do banco, para que a parte superior do peito, o pescoço e o rosto fiquem fora do banco. Esta será sua posição inicial.\nMantendo a anilha firme na parte de trás da cabeça, abaixe lentamente a cabeça (como se dissesse "sim") enquanto inspira.\nLevante a cabeça de volta à posição inicial em um movimento semicircular enquanto expira. Segure a contração por um segundo.\nRepita o número recomendado de repetições.',
  'Lying Face Up Plate Neck Resistance':
    'Deite-se de barriga para cima com o corpo todo reto em um banco reto, segurando uma anilha sobre a testa. Dica: você precisará se posicionar de modo que os ombros fiquem ligeiramente além da ponta do banco, para que o trapézio, o pescoço e a cabeça fiquem fora do banco. Esta será sua posição inicial.\nMantendo a anilha firme na testa, abaixe lentamente a cabeça para trás em um movimento semicircular enquanto inspira.\nLevante a cabeça de volta à posição inicial em um movimento semicircular enquanto expira. Segure a contração por um segundo.\nRepita o número recomendado de repetições.',
  'Lying Glute':
    'Deite-se de costas com seu parceiro ajoelhado ao seu lado.\nFlexione o quadril de uma perna, levantando-a do chão. Gire a perna de modo que o pé fique sobre o quadril oposto e a parte inferior da perna fique perpendicular ao seu corpo. Seu parceiro deve segurar o joelho e o tornozelo no lugar. Esta será sua posição inicial.\nTente empurrar a perna em direção ao seu parceiro, que deve impedir qualquer movimento real da perna.\nApós 10 a 20 segundos, relaxe completamente enquanto seu parceiro empurra suavemente o tornozelo e o joelho em direção ao seu peito. Avise seu ajudante quando o alongamento for adequado, para evitar lesões ou alongamento excessivo.',
  'Lying Hamstring':
    'Deite-se de costas com as pernas estendidas. Seu parceiro deve estar ajoelhado ao seu lado. Levante uma perna em direção ao teto e peça ao parceiro que segure o tornozelo. Ele pode usar o ombro para apoiar sua perna, se necessário. Esta será sua posição inicial.\nCom seu parceiro segurando sua perna no lugar, tente flexionar o joelho, contraindo os posteriores de coxa por 10 a 20 segundos.\nDepois relaxe a perna, permitindo que seu parceiro a empurre suavemente em direção à sua cabeça. Avise seu ajudante quando o alongamento for adequado, para evitar lesões ou alongamento excessivo. Troque de lado ao terminar.',
  'Lying High Bench Barbell Curl':
    'Deite-se de bruços em um banco reto alto segurando uma barra com pegada supinada (palmas para cima). Dica: se estiver usando uma barra reta, segure-a com uma pegada na largura dos ombros; se estiver usando uma barra W, segure-a pelas pegadas internas. A parte superior do seu corpo deve ficar posicionada de modo que a parte superior do peito esteja além da ponta do banco e a barra fique pendurada à sua frente, com os braços estendidos e perpendiculares ao chão. Esta será sua posição inicial.\nMantendo os cotovelos junto ao corpo e os braços parados, suba o peso em um movimento semicircular enquanto contrai os bíceps e expira. Segure na parte superior do movimento por um segundo.\nAo inspirar, volte lentamente à posição inicial. Dica: mantenha controle total do peso o tempo todo e evite balançar o corpo. Lembre-se: apenas os antebraços devem se mover durante todo o movimento.\nRepita o número recomendado de repetições.',
  'Lying Leg Curls':
    'Ajuste a alavanca da máquina à sua altura e deite-se de bruços na mesa flexora com o rolo da alavanca na parte de trás das pernas (poucos centímetros abaixo das panturrilhas). Dica: de preferência use uma mesa flexora inclinada em vez de reta, pois a posição inclinada é mais favorável para o recrutamento dos posteriores de coxa.\nMantendo o tronco reto no banco, certifique-se de que as pernas estejam totalmente estendidas e segure as pegadas laterais da máquina. Posicione as pontas dos pés retas (ou use qualquer uma das outras duas posturas descritas na seção de posição dos pés). Esta será sua posição inicial.\nAo expirar, flexione as pernas para cima o máximo possível sem levantar as coxas do apoio. Ao chegar à posição de contração total, segure por um segundo.\nAo inspirar, leve as pernas de volta à posição inicial. Repita o número recomendado de repetições.',
  'Lying Machine Squat':
    'Ajuste a máquina de pernas a uma altura que permita entrar nela com os joelhos flexionados e as coxas ligeiramente abaixo da paralela.\nDepois de selecionar a carga, posicione-se dentro da máquina de barriga para cima, com os joelhos flexionados e as coxas ligeiramente abaixo da paralela em relação à plataforma. Certifique-se de que os joelhos não passem da ponta dos pés. O ângulo formado entre os posteriores de coxa e as panturrilhas deve ser ligeiramente menor que 90 graus (já que sua posição inicial exige começar ligeiramente abaixo da paralela). Suas costas e sua cabeça devem ficar apoiadas na máquina, enquanto os ombros ficam pressionados sob as almofadas.\nColoque as mãos nas pegadas e posicione os pés ligeiramente voltados para fora, na largura dos ombros. Esta será sua posição inicial.\nEnquanto empurra com a parte da frente dos pés e expira, estenda o corpo todo contraindo os quadríceps. Segure a posição de contração por um segundo. Dica: como você começa abaixo da paralela, pode optar por se ajudar com as mãos, pressionando as coxas, apenas na primeira repetição.\nAgache lentamente enquanto inspira, mas em vez de descer até a posição inicial, pare quando as coxas estiverem paralelas à plataforma. O ângulo entre os posteriores de coxa e as panturrilhas deve ser de 90 graus.\nRepita o número recomendado de repetições.',
  'Lying One-Arm Lateral Raise':
    'Segurando um halter em uma das mãos, deite-se com o peito para baixo em um banco reto. A outra mão pode segurar a perna do banco para maior estabilidade.\nPosicione a palma da mão que segura o halter em posição neutra (palma voltada para o tronco), mantendo o braço estendido com o cotovelo ligeiramente flexionado. Esta será sua posição inicial.\nAgora levante o braço com o halter para o lado até que o cotovelo fique na altura do ombro e o braço esteja aproximadamente paralelo ao chão, enquanto expira. Dica: mantenha o braço perpendicular ao tronco e estendido durante todo o movimento. Além disso, mantenha a contração na parte superior por um segundo.\nAbaixe lentamente o halter até a posição inicial enquanto inspira.\nRepita o número recomendado de repetições.',
  'Lying Prone Quadriceps':
    'Deite-se de bruços no chão com seu parceiro ajoelhado ao seu lado. Flexione um joelho e levante essa perna do chão, tentando tocar os glúteos com o pé. Seu parceiro deve segurar o joelho e o tornozelo. Esta será sua posição inicial.\nTente estender o joelho enquanto seu parceiro impede qualquer movimento real.\nApós 10 a 20 segundos, relaxe os músculos enquanto seu parceiro empurra suavemente o pé em direção aos glúteos, alongando ainda mais os quadríceps e os flexores do quadril.\nApós 10 a 20 segundos, troque de lado.',
  'Lying Rear Delt Raise':
    'Segurando um halter em cada mão, deite-se com o peito para baixo em um banco reto.\nPosicione as palmas das mãos em posição neutra (voltadas para o tronco), mantendo os braços estendidos com os cotovelos ligeiramente flexionados. Esta será sua posição inicial.\nAgora levante os braços para os lados até que os cotovelos fiquem na altura dos ombros e os braços estejam aproximadamente paralelos ao chão, enquanto expira. Dica: mantenha os braços perpendiculares ao tronco e estendidos durante todo o movimento. Além disso, mantenha a contração na parte superior por um segundo.\nAbaixe lentamente os halteres até a posição inicial enquanto inspira.\nRepita o número recomendado de repetições e depois troque para o outro braço.',
  'Lying Supine Dumbbell Curl':
    'Deite-se em um banco reto de barriga para cima, segurando um halter em cada mão sobre as coxas.\nLeve os halteres para as laterais com os braços estendidos e as palmas das mãos voltadas para as coxas (pegada neutra).\nMantendo os braços perto do tronco e os cotovelos para dentro, abaixe lentamente os braços (mantendo-os estendidos com uma leve flexão nos cotovelos) o mais para baixo que conseguir, em direção ao chão. Quando não puder descer mais, trave os braços nessa posição; essa será sua posição inicial.\nAo expirar, comece a subir lentamente os pesos na rosca enquanto gira os punhos ao mesmo tempo, de modo que as palmas fiquem voltadas para cima. Continue a rosca até que os bíceps estejam totalmente contraídos e contraia com força na posição superior por um segundo. Dica: apenas os antebraços devem se mover. Os braços devem permanecer parados e os cotovelos junto ao corpo durante todo o movimento.\nVolte à posição inicial bem lentamente.',
  'Lying T-Bar Row':
    'Carregue a máquina de remada em T com a carga desejada e ajuste a altura das pernas de modo que a parte superior do peito fique no topo do apoio. Dica: em algumas máquinas, basta subir no degrau adequado que deixe você em uma altura em que a parte superior do peito fique no topo do apoio.\nDeite-se de bruços no apoio e segure as pegadas. Você pode usar pegada com as palmas para baixo, para cima ou voltadas para dentro, dependendo da parte das costas que deseja enfatizar.\nRetire a barra do suporte e estenda os braços à sua frente. Esta será sua posição inicial.\nAo expirar, puxe lentamente o peso para cima e contraia as costas na parte superior do movimento. Dica: mantenha os braços o mais próximo possível do tronco durante todo o movimento para ativar melhor os músculos das costas. Além disso, não tire o corpo do apoio em nenhum momento e evite usar os bíceps para levantar o peso.\nApós uma contração de um segundo na parte superior do movimento, ao inspirar, volte lentamente à posição inicial.\nRepita o número recomendado de repetições.',
  'Lying Triceps Press':
    'Deite-se em um banco reto com uma barra W (minha preferida) ou uma barra reta apoiada no chão atrás da cabeça e com os pés no chão.\nSegure a barra atrás de você com pegada pronada (por cima) de largura média e levante-a à sua frente com os braços estendidos. Dica: os braços devem ficar perpendiculares ao tronco e ao chão. Os cotovelos devem ficar junto ao corpo. Esta é a posição inicial.\nAo inspirar, abaixe lentamente o peso até que a barra toque de leve a testa, mantendo parados os braços e os cotovelos.\nNesse ponto, use os tríceps para levar o peso de volta à posição inicial enquanto expira.\nRepita o número recomendado de repetições.',
  'Machine Bench Press':
    'Sente-se na máquina de supino e selecione a carga.\nPise na alavanca da máquina, pois ela ajudará a levar as pegadas para a frente, para que você possa segurá-las e estender totalmente os braços.\nSegure as pegadas com as palmas para baixo e levante os cotovelos de modo que os braços fiquem paralelos ao chão, ao lado do tronco. Dica: seus antebraços apontarão para a frente porque você está segurando as pegadas. Depois de levar as pegadas para a frente e estender os braços, você estará na posição inicial.\nAgora traga as pegadas de volta em sua direção enquanto inspira.\nEmpurre as pegadas para longe de você enquanto contrai os peitorais e expira. Segure a contração por um segundo antes de voltar à posição inicial.\nRepita o número recomendado de repetições.\nAo terminar, pise novamente na alavanca e devolva lentamente as pegadas ao lugar original.',
  'Machine Bicep Curl':
    'Ajuste o banco à altura adequada e selecione a carga. Apoie a parte superior dos braços nas almofadas e segure as pegadas. Esta será sua posição inicial.\nRealize o movimento flexionando o cotovelo, levando o antebraço em direção à parte superior do braço.\nFaça uma pausa na parte superior do movimento e depois volte lentamente com o peso à posição inicial.\nEvite levar o peso totalmente de volta até o fim do curso até terminar a série, para manter a tensão nos músculos trabalhados.',
  'Machine Preacher Curls':
    'Sente-se na máquina de rosca Scott e selecione a carga.\nApoie a parte de trás dos braços (os tríceps) no apoio da rosca Scott e segure as pegadas com pegada supinada (palmas para cima). Dica: ao apoiar os braços no suporte, mantenha os cotovelos para dentro. Esta será sua posição inicial.\nAgora suba as pegadas enquanto expira e contrai os bíceps. Na parte superior, segure a contração por um segundo. Dica: apenas os antebraços devem se mover. Os braços devem permanecer parados e apoiados no suporte o tempo todo.\nAbaixe lentamente as pegadas de volta à posição inicial enquanto inspira.\nRepita o número recomendado de repetições.',
  'Machine Shoulder (Military) Press':
    'Sente-se na máquina de desenvolvimento de ombros e selecione a carga.\nSegure as pegadas ao lado do corpo, mantendo os cotovelos flexionados e alinhados com o tronco. Esta será sua posição inicial.\nAgora suba as pegadas enquanto expira e estende totalmente os braços. Na parte superior, segure a contração por um segundo.\nAbaixe lentamente as pegadas de volta à posição inicial enquanto inspira.\nRepita o número recomendado de repetições.',
  'Machine Triceps Extension':
    'Ajuste o banco à altura adequada e selecione a carga. Apoie a parte superior dos braços nas almofadas e segure as pegadas. Esta será sua posição inicial.\nRealize o movimento estendendo o cotovelo, afastando o antebraço da parte superior do braço.\nFaça uma pausa ao completar o movimento e depois volte lentamente com o peso à posição inicial.\nEvite levar o peso totalmente de volta até o fim do curso até terminar a série, para manter a tensão nos músculos trabalhados.',
  'Medicine Ball Chest Pass':
    'Você precisará de um parceiro para este exercício. Se não tiver um, o movimento pode ser feito contra uma parede.\nComece de frente para seu parceiro segurando a medicine ball na altura do tronco com as duas mãos.\nTraga a bola ao peito e inverta o movimento estendendo os cotovelos. Para aplicações esportivas, você pode dar um passo ao arremessar.\nSeu parceiro deve pegar a bola e arremessá-la de volta para você.\nReceba o arremesso com as duas mãos na altura do peito.',
  'Medicine Ball Full Twist':
    'Para este exercício você precisará de uma medicine ball e de um parceiro. Fique de costas para seu parceiro, com cerca de 60 a 90 cm de distância. Esta será sua posição inicial.\nSegure a bola à frente do tronco. Abra os quadris e gire os ombros ao mesmo tempo que seu parceiro.\nPara uma rotação completa, você e seu parceiro devem girar na mesma direção, ou seja, no sentido anti-horário.\nPasse a bola ao seu parceiro, e agora ambos podem girar na direção oposta para repetir o procedimento.',
  'Medicine Ball Scoop Throw':
    'Assuma uma postura de meio agachamento com uma medicine ball nas mãos. Seus braços devem ficar pendurados de modo que a bola fique perto dos pés.\nComece projetando o quadril para a frente enquanto estende as pernas, saltando para cima.\nAo fazer isso, balance os braços para cima e por cima da cabeça, mantendo-os estendidos, e solte a bola no ponto mais alto do movimento. O objetivo é arremessar a bola a maior distância possível atrás de você.',
  'Middle Back Shrug':
    'Deite-se de bruços em um banco inclinado segurando um halter em cada mão. Seus braços devem estar totalmente estendidos, pendurados e apontando para o chão. As palmas das mãos devem ficar voltadas uma para a outra. Esta será sua posição inicial.\nAo expirar, aproxime as escápulas e segure a contração por um segundo completo. Dica: este movimento é como o inverso de um abraço, ou como tentar fazer elevações posteriores como se você não tivesse braços.\nAo inspirar, volte à posição inicial.\nRepita o número recomendado de repetições.',
  'Middle Back Stretch':
    'Fique em pé com os pés afastados na largura dos ombros e as mãos nos quadris.\nGire a cintura até sentir um alongamento. Segure por 10 a 15 segundos e depois gire para o outro lado.',
  'Mixed Grip Chin':
    'Com um espaçamento cerca de 2,5 cm mais largo que a largura dos ombros, segure uma barra fixa com a palma de uma mão voltada para a frente e a palma da outra mão voltada para você. Esta será sua posição inicial.\nAgora comece a se puxar para cima enquanto expira. Dica: com o braço que tem a palma voltada para cima, concentre-se em usar os músculos das costas para realizar o movimento. O cotovelo desse braço deve permanecer próximo ao tronco. Com o outro braço, que tem a palma voltada para a frente, o cotovelo ficará afastado, mas alinhado com o tronco. Você se concentrará em usar os dorsais para elevar o corpo.\nApós uma contração de um segundo na parte superior, comece a descer lentamente enquanto inspira.\nRepita o número recomendado de repetições.\nNa série seguinte, troque as pegadas; ou seja, se você estava com a mão direita com a palma voltada para você e a esquerda com a palma para a frente, na próxima série terá a palma para a frente na mão direita e voltada para você na esquerda.',
  'Monster Walk':
    'Coloque uma faixa ao redor dos dois tornozelos e outra ao redor dos dois joelhos. Deve haver tensão suficiente para que fiquem esticadas quando os pés estiverem afastados na largura dos ombros.\nPara começar, dê passos curtos para a frente, alternando o pé esquerdo e o direito.\nApós vários passos, faça exatamente o contrário e ande para trás até o ponto de partida.',
  'Mountain Climbers':
    'Comece na posição de flexão de braço, com o peso apoiado nas mãos e nas pontas dos pés. Flexionando o joelho e o quadril, leve uma perna à frente até que o joelho fique aproximadamente sob o quadril. Esta será sua posição inicial.\nDe forma explosiva, inverta a posição das pernas, estendendo a perna flexionada até que fique reta e apoiada na ponta do pé, e trazendo o outro pé à frente com o quadril e o joelho flexionados. Repita de forma alternada por 20 a 30 segundos.',
  'Moving Claw Series':
    'Este movimento ajuda a preparar sua técnica de corrida para que você se destaque nos sprints. Enquanto corre, flexione o joelho, buscando chutar os glúteos enquanto o quadril se estende.\nRecarregue o quadríceps enquanto a perna volta para a frente, atacando o solo no próximo passo.\nCertifique-se de que, enquanto corre, você bloqueie com os braços, socando para a frente em um movimento rápido de 1-2.',
  'Muscle Snatch':
    'Comece com uma barra carregada na altura da metade da coxa com pegada aberta. Os pés devem ficar diretamente abaixo dos quadris, com as pontas voltadas para fora conforme necessário. Abaixe os quadris, com o peito erguido e a cabeça olhando para a frente. Os ombros devem ficar logo à frente da barra. Esta será a posição inicial.\nInicie a puxada empurrando pela parte da frente dos calcanhares, elevando a barra. Passe para a segunda puxada estendendo quadris, joelhos e tornozelos, impulsionando a barra para cima o mais rápido possível. A barra deve ficar próxima ao corpo.\nContinue elevando a barra até a posição acima da cabeça, sem flexionar novamente os joelhos.',
  'Muscle Up':
    'Segure as argolas com pegada falsa, com a base das palmas sobre as argolas. Inicie uma barra fixa puxando os cotovelos para baixo, junto às laterais do corpo, flexionando os cotovelos.\nAo chegar à posição superior da barra fixa, puxe as argolas em direção às axilas enquanto gira os ombros para a frente, permitindo que os cotovelos se movam diretamente para trás. Isso coloca você na posição correta para continuar na parte de paralelas do movimento.\nMantendo o controle e a estabilidade, estenda os cotovelos para completar o movimento.\nTenha cuidado ao descer até o chão.',
  'Narrow Stance Hack Squats':
    'Apoie a parte de trás do tronco no encosto da máquina e encaixe os ombros sob as almofadas.\nPosicione as pernas na plataforma com uma base estreita, menor que a largura dos ombros, com as pontas dos pés ligeiramente voltadas para fora. Seus pés devem ficar a cerca de 7 cm ou menos de distância. Dica: mantenha a cabeça erguida o tempo todo e mantenha também as costas apoiadas no encosto o tempo todo.\nColoque as mãos nas pegadas laterais da máquina e libere as barras de segurança (o que, na maioria dos modelos, é feito movendo as pegadas laterais da posição frontal para uma posição diagonal).\nAgora estenda as pernas sem travar os joelhos. Esta será sua posição inicial.\nComece a abaixar lentamente a carga flexionando os joelhos, mantendo uma postura reta com a cabeça erguida (costas apoiadas o tempo todo). Continue descendo até que o ângulo entre a coxa e as panturrilhas fique ligeiramente menor que 90 graus (ponto em que as coxas ficam abaixo da paralela ao chão). Inspire durante esta parte do movimento.\nComece a subir a carga enquanto expira, empurrando o chão principalmente com os calcanhares, enquanto estende as pernas novamente e volta à posição inicial.\nRepita o número recomendado de repetições.',
  'Narrow Stance Leg Press':
    'Usando uma máquina de leg press, sente-se na máquina e posicione as pernas na plataforma diretamente à sua frente, com uma base estreita, menor que a largura dos ombros, com as pontas dos pés ligeiramente voltadas para fora. Seus pés devem ficar a cerca de 7 cm ou menos de distância. Dica: mantenha a cabeça erguida o tempo todo e mantenha também as costas apoiadas no encosto o tempo todo.\nAbaixe as barras de segurança que seguram a plataforma carregada e empurre a plataforma até o topo, até que as pernas estejam totalmente estendidas à sua frente. Dica: certifique-se de não travar os joelhos. Seu tronco e suas pernas devem formar um ângulo perfeito de 90 graus. Esta será sua posição inicial.\nAo inspirar, abaixe lentamente a plataforma até que a parte superior e a inferior das pernas formem um ângulo de 90 graus.\nEmpurrando principalmente com os calcanhares e usando os quadríceps, volte à posição inicial enquanto expira.\nRepita o número recomendado de repetições e trave bem os pinos de segurança ao terminar. Você não quer essa plataforma totalmente carregada caindo sobre você.',
  'Narrow Stance Squats':
    'Este exercício é melhor realizado dentro de um rack de agachamento, por segurança. Para começar, primeiro posicione a barra em um suporte que corresponda à sua altura. Depois de escolher a altura correta e carregar a barra, posicione-se sob a barra e apoie a parte de trás dos ombros (ligeiramente abaixo do pescoço) sobre ela.\nSegure a barra com as duas mãos, uma de cada lado, e retire-a do rack empurrando primeiro com as pernas e, ao mesmo tempo, endireitando o tronco.\nDê um passo para trás, afastando-se do rack, e posicione as pernas com uma base estreita, menor que a largura dos ombros, com as pontas dos pés ligeiramente voltadas para fora. Os pés devem ficar a cerca de 7 a 15 cm de distância. Mantenha a cabeça erguida o tempo todo (olhar para baixo faz você perder o equilíbrio) e mantenha as costas retas. Esta será sua posição inicial. (Nota: para efeitos desta explicação usaremos a base média descrita acima, que trabalha o desenvolvimento geral; no entanto, você pode escolher qualquer uma das três bases descritas na seção de posição dos pés).\nComece a abaixar lentamente a barra flexionando os joelhos, mantendo uma postura reta com a cabeça erguida. Continue descendo até que o ângulo entre a coxa e as panturrilhas fique ligeiramente menor que 90 graus (ponto em que as coxas ficam abaixo da paralela ao chão). Inspire durante esta parte do movimento. Dica: se você executou o exercício corretamente, a frente dos joelhos deve formar uma linha reta imaginária com as pontas dos pés, perpendicular à frente. Se os joelhos passarem dessa linha imaginária (se passarem da ponta dos pés), você está colocando estresse excessivo no joelho e o exercício foi feito de forma incorreta.\nComece a subir a barra enquanto expira, empurrando o chão principalmente com o calcanhar, enquanto estende as pernas novamente e volta à posição inicial.\nRepita o número recomendado de repetições.',
  'Natural Glute Ham Raise':
    'Usando o apoio de pernas de uma máquina de puxada alta ou um banco Scott, posicione-se de modo que os tornozelos fiquem sob os apoios, os joelhos no assento e você esteja de costas para a máquina. Você deve estar ereto e manter uma boa postura.\nEsta será sua posição inicial. Abaixe o corpo com controle até que os joelhos estejam quase totalmente retos.\nMantendo o controle, suba de volta à posição inicial.\nSe não conseguir completar uma repetição, use uma faixa, um parceiro ou se impulsione com as mãos em uma caixa para ajudar a completar a repetição.',
  'Neck Press':
    'Deite-se de costas em um banco reto. Usando uma pegada de largura média (uma pegada que forma um ângulo de 90 graus no meio do movimento entre os antebraços e os braços), retire a barra do suporte e segure-a reta sobre o pescoço com os braços travados. Esta será sua posição inicial.\nAo inspirar, desça lentamente até sentir a barra no pescoço.\nApós uma pausa de um segundo, leve a barra de volta à posição inicial enquanto expira e empurra a barra usando os músculos do peito. Trave os braços e contraia o peito na posição de contração, segure por um segundo e então comece a descer lentamente de novo. Dica: a descida deve levar pelo menos o dobro do tempo da subida.\nRepita o movimento pelo número prescrito de repetições.\nAo terminar, coloque a barra de volta no suporte.',
  'Neck-SMR':
    'Usando um rolo de massagem muscular ou um rolo de macarrão, coloque o rolo atrás da cabeça e contra o pescoço. Certifique-se de não posicionar o rolo diretamente contra a coluna, mas ligeiramente inclinado, para que o rolo pressione os músculos de ambos os lados da coluna. Esta será sua posição inicial.\nComeçando pela parte superior do pescoço, role lentamente sobre os músculos do pescoço, fazendo uma pausa nos pontos de tensão por 10 a 30 segundos.',
  'Oblique Crunches':
    'Deite-se de costas no chão com a parte inferior das costas pressionada contra o solo. Para este exercício, você precisará colocar uma mão ao lado da cabeça e a outra ao lado do corpo, contra o chão.\nCertifique-se de que os pés estejam elevados e apoiados em uma superfície plana.\nAgora levante o ombro do lado da mão que toca a cabeça.\nSimplesmente eleve o ombro e o corpo para cima até tocar o joelho. Por exemplo, se a mão direita está ao lado da cabeça, você deve elevar o corpo até que o cotovelo direito toque o joelho esquerdo. A mesma variação pode ser aplicada no sentido inverso, usando o cotovelo esquerdo para tocar o joelho direito.\nDepois que o joelho tocar o cotovelo, abaixe o corpo até voltar à posição inicial.\nLembre-se de inspirar durante a fase excêntrica (de descida) do exercício e de expirar durante a fase concêntrica (de subida) do exercício.\nContinue alternando dessa forma até completar todas as repetições recomendadas para cada lado.',
  'Oblique Crunches - On The Floor':
    'Comece deitado sobre o lado direito, com as pernas uma sobre a outra. Certifique-se de que os joelhos estejam um pouco flexionados.\nColoque a mão esquerda atrás da cabeça.\nNessa posição, comece levantando o cotovelo esquerdo como em um abdominal normal, só que desta vez a ênfase principal está nos oblíquos.\nSuba o mais alto que puder, segure a contração por um segundo e depois volte lentamente à posição inicial.\nLembre-se de inspirar durante a fase excêntrica (de descida) do exercício e de expirar durante a fase concêntrica (de elevação) do exercício.',
  'Olympic Squat':
    'Comece com uma barra apoiada sobre o trapézio. O peito deve estar erguido e a cabeça voltada para a frente. Adote uma base na largura do quadril com os pés voltados para fora conforme necessário.\nDesça flexionando os joelhos, evitando ao máximo levar o quadril para trás. Isso exige que os joelhos avancem; certifique-se de que permaneçam alinhados com os pés. O objetivo é manter o tronco o mais ereto possível. Continue descendo até o fim, mantendo o peso na parte da frente do calcanhar.\nNo momento em que a parte superior das pernas encostar na inferior, inverta o movimento, empurrando o peso para cima.',
  'On Your Side Quad Stretch':
    'Comece deitado sobre o lado direito, com o joelho direito flexionado em um ângulo de 90 graus apoiado no chão à sua frente (isso estabiliza o tronco).\nFlexione o joelho esquerdo para trás e segure o pé esquerdo com a mão esquerda. Para alongar o flexor do quadril, empurre o quadril esquerdo para a frente enquanto empurra o pé esquerdo para trás contra a mão. Troque de lado.',
  'On-Your-Back Quad Stretch':
    'Deite-se em um banco reto ou step e deixe uma perna e um braço pendurados para o lado.\nFlexione o joelho e segure o peito do pé. Ao fazer isso, tome cuidado para não arquear a lombar.\nPuxe o umbigo em direção à coluna para se manter em posição neutra. Pressione o pé para baixo e contra a mão. Para adicionar o alongamento do quadril, levante o quadril da perna que você está segurando em direção ao teto.\nTroque de lado.',
  'One Arm Against Wall':
    'Em pé, apoie um braço flexionado contra uma parede ou batente de porta.\nIncline-se lentamente em direção ao braço até sentir um alongamento nos dorsais.',
  'One Arm Chin-Up':
    'Para este exercício, comece colocando uma toalha ao redor de uma barra fixa.\nSegure a barra com a palma voltada para você. Uma mão segurará a barra e a outra segurará a toalha.\nIncline o tronco para trás cerca de 30 graus, criando uma curvatura na lombar e projetando o peito para a frente. Esta é sua posição inicial.\nPuxe o tronco para cima até que a barra toque a parte superior do peito, levando os ombros e os braços para baixo e para trás. Expire enquanto realiza esta parte do movimento. Dica: concentre-se em contrair os músculos das costas ao chegar à posição de contração total. A parte superior do tronco deve permanecer estável enquanto se move pelo espaço e apenas os braços devem se mover. Os antebraços não devem fazer outro trabalho além de segurar a barra.\nApós um segundo na posição de contração, comece a inspirar e abaixe lentamente o tronco até a posição inicial, quando os braços estiverem totalmente estendidos e os dorsais totalmente alongados.\nRepita este movimento pelo número prescrito de repetições.\nTroque de braço e repita o movimento.',
  'One Arm Dumbbell Bench Press':
    'Deite-se em um banco reto com um halter em uma das mãos sobre a coxa.\nUsando a coxa para ajudar a levantar o halter, leve-o para cima de modo que possa segurá-lo à sua frente na largura dos ombros. Use a mão que não está levantando para ajudar a posicionar o halter corretamente sobre você.\nUma vez na largura dos ombros, gire o punho para a frente de modo que a palma da mão fique voltada para longe de você. Esta será sua posição inicial.\nAbaixe o peso lentamente para o lado do corpo enquanto inspira. Mantenha controle total do halter o tempo todo. Dica: use a mão que não está levantando para ajudar a equilibrar o halter, pois pode ser um pouco difícil no início. Use a mão livre apenas se necessário. Caso contrário, mantenha-a descansando ao lado.\nAo expirar, empurre o halter para cima usando os músculos peitorais. Trave o braço na posição de contração, contraia o peito, segure por um segundo e então comece a descer lentamente. Dica: a descida deve levar pelo menos o dobro do tempo da subida.\nRepita o movimento pelo número prescrito de repetições do seu programa de treino.\nTroque de braço e repita o movimento.',
  'One Arm Dumbbell Preacher Curl':
    'Pegue um halter com o braço direito e apoie a parte superior do braço no banco Scott ou no banco inclinado. O halter deve ser segurado na altura do ombro. Esta será sua posição inicial.\nAo inspirar, abaixe lentamente o halter até que o braço esteja estendido e o bíceps totalmente alongado.\nAo expirar, use o bíceps para subir o peso na rosca até que o bíceps esteja totalmente contraído e o halter esteja na altura do ombro. Novamente, lembre-se de que, para garantir a contração total, você precisa levar o dedo mínimo mais alto que o polegar.\nContraia os bíceps com força por um segundo na posição de contração e repita o número recomendado de repetições.\nTroque de braço e repita o movimento.',
  'One Arm Floor Press':
    'Deite-se em uma superfície plana com as costas pressionadas contra o chão ou um colchonete de exercícios. Certifique-se de que os joelhos estejam flexionados.\nPeça a um parceiro que lhe entregue a barra em uma das mãos. No início, seu braço deve estar quase totalmente estendido, semelhante à posição inicial de um supino com barra. No entanto, desta vez sua pegada será neutra (palma voltada para o tronco).\nCertifique-se de que a mão que você não está usando para levantar o peso esteja posicionada ao lado do corpo.\nComece o exercício abaixando a barra até que o cotovelo toque o chão. Lembre-se de inspirar, pois esta é a fase excêntrica (de descida) do exercício.\nDepois comece a levantar a barra de volta à posição inicial original. Lembre-se de expirar durante a fase concêntrica (de subida) do exercício.\nRepita até completar as repetições recomendadas.\nTroque de braço e repita o movimento.',
  'One Arm Lat Pulldown':
    'Selecione uma carga adequada e ajuste o apoio de joelhos para ajudar a mantê-lo sentado. Segure a pegada com pegada pronada. Esta será sua posição inicial.\nPuxe a pegada para baixo, aproximando o cotovelo do lado do corpo enquanto flexiona o cotovelo.\nFaça uma pausa na parte inferior do movimento e depois volte lentamente com a pegada à posição inicial.\nPara várias repetições, evite devolver o peso completamente, para manter a tensão nos músculos trabalhados.',
  'One Arm Pronated Dumbbell Triceps Extension':
    'Deite-se em um banco reto segurando um halter com o braço estendido. Seu braço deve estar perpendicular ao corpo. A palma da mão deve ficar voltada para os pés, pois é necessária uma pegada pronada para realizar este exercício.\nColoque a mão que não está levantando sobre o bíceps para apoio.\nComece a abaixar lentamente o halter enquanto inspira.\nEm seguida, comece a levantar o halter para cima enquanto contrai os tríceps. Lembre-se de expirar durante a fase concêntrica (de subida) do exercício.\nRepita até completar as repetições da sua série.\nTroque de braço e repita o movimento.',
  'One Arm Supinated Dumbbell Triceps Extension':
    'Deite-se em um banco reto segurando um halter com o braço estendido. Seu braço deve estar perpendicular ao corpo. A palma da mão deve ficar voltada para o rosto, pois é necessária uma pegada supinada para realizar este exercício.\nColoque a mão que não está levantando sobre o bíceps para apoio.\nComece a abaixar lentamente o halter enquanto inspira.\nEm seguida, comece a levantar o halter para cima enquanto contrai os tríceps. Lembre-se de expirar durante a fase concêntrica (de subida) do exercício.\nRepita até completar as repetições da sua série.\nTroque de braço e repita o movimento.\nTroque de braço novamente e repita o movimento.',
  'One Half Locust':
    'Deite-se de bruços no chão.\nColoque a mão esquerda sob o osso do quadril esquerdo para amortecer o quadril e o osso púbico.\nFlexione o joelho direito para poder segurar o pé com a mão direita.\nLevante o pé no ar e ao mesmo tempo levante os ombros do chão. Isso também alonga o flexor do quadril direito, o peito e os ombros. Troque de lado. Se não incomodar suas costas, você pode tentar com os dois braços e as duas pernas ao mesmo tempo.',
  'One Handed Hang':
    'Segure uma barra fixa com uma mão, usando pegada pronada. Mantenha os pés no chão ou em um degrau. Deixe a maior parte do seu peso pendurada nessa mão, mantendo os pés no chão. Segure por 10 a 20 segundos e troque de lado.',
  'One Knee To Chest':
    'Comece deitado no chão.\nEstenda uma perna reta e leve o outro joelho em direção ao peito. Segure abaixo da articulação do joelho para proteger a patela.\nPuxe suavemente esse joelho em direção ao nariz.\nTroque de lado. Isso alonga os glúteos e a região lombar da perna flexionada e o flexor do quadril da perna estendida.',
  'One Leg Barbell Squat':
    'Comece em pé, a cerca de 60 a 90 cm à frente de um banco plano, de costas para ele. Deixe uma barra à sua frente no chão. Dica: seus pés devem estar afastados na largura dos ombros.\nFlexione os joelhos e use uma pegada pronada, com as mãos mais afastadas que a largura dos ombros, para levantar a barra até poder apoiá-la no peito.\nDepois levante a barra acima da cabeça e apoie-a na base do pescoço. Leve um pé para trás de modo que a ponta fique apoiada no banco plano. O outro pé deve ficar fixo à sua frente. Mantenha a cabeça erguida o tempo todo, pois olhar para baixo faz você perder o equilíbrio, e mantenha também as costas retas. Dica: certifique-se de manter as costas retas e o peito estufado durante o exercício.\nAo inspirar, abaixe lentamente a perna até a coxa ficar paralela ao chão. Nesse ponto, o joelho deve estar sobre os dedos do pé. Seu peito deve ficar diretamente acima do meio da coxa.\nConduzindo o movimento com o peito e o quadril e contraindo os quadríceps, eleve a perna de volta à posição inicial enquanto expira.\nRepita o número recomendado de repetições.\nTroque de perna e repita o movimento.',
  'One-Arm Dumbbell Row':
    'Escolha um banco plano e coloque um halter de cada lado dele.\nApoie o joelho direito na ponta do banco, incline o tronco para a frente a partir da cintura até a parte superior do corpo ficar paralela ao chão, e apoie a mão direita na outra ponta do banco para se firmar.\nCom a mão esquerda, pegue o halter do chão e segure o peso mantendo a lombar reta. A palma da mão deve ficar voltada para o tronco. Essa será sua posição inicial.\nPuxe o peso em linha reta até a lateral do peito, mantendo a parte superior do braço junto ao corpo e o tronco parado. Expire enquanto realiza este passo. Dica: concentre-se em apertar os músculos das costas ao chegar à posição de contração máxima. Além disso, certifique-se de que a força venha dos músculos das costas e não dos braços. Por fim, o tronco deve permanecer parado e apenas os braços devem se mover. Os antebraços não devem fazer nenhum trabalho além de segurar o halter; portanto, não tente levantar o halter usando os antebraços.\nAbaixe o peso em linha reta até a posição inicial. Inspire enquanto realiza este passo.\nRepita o movimento pelo número de repetições especificado.\nTroque de lado e repita com o outro braço.',
  'One-Arm Flat Bench Dumbbell Flye':
    'Deite-se em um banco plano com um halter em uma das mãos, apoiado sobre a coxa. A palma da mão que segura o halter deve estar em pegada neutra.\nUsando as coxas para ajudar a subir o halter, leve-o à sua frente com o braço que levanta totalmente estendido. Lembre-se de manter uma pegada neutra neste exercício. A mão que não levanta deve ficar ao lado, segurando o banco plano para ter melhor apoio. Essa será sua posição inicial.\nO braço com o peso deve ter uma leve flexão no cotovelo para evitar tensão no tendão do bíceps. Comece abaixando o braço com o peso em um arco amplo para fora até sentir um alongamento no peitoral. Inspire enquanto realiza esta parte do movimento. Dica: lembre-se de que, durante todo o movimento, o braço que levanta deve permanecer fixo; o movimento só deve ocorrer na articulação do ombro.\nVolte o braço à posição inicial enquanto aperta os músculos do peitoral e expira. Dica: certifique-se de usar o mesmo arco de movimento usado para abaixar o peso.\nSegure por um segundo na posição de contração e repita o movimento pelo número de repetições prescrito.\nTroque de braço e repita o exercício.',
  'One-Arm High-Pulley Cable Side Bends':
    'Conecte uma alça padrão à torre. Coloque o cabo na posição de polia mais alta.\nFique de lado para o cabo. Com uma das mãos, alcance para cima e segure a alça com pegada supinada.\nPuxe o cabo para baixo até o cotovelo tocar o seu lado e a alça ficar junto ao ombro.\nPosicione os pés afastados na largura do quadril. Coloque a mão livre no quadril para ajudar a identificar o ponto de rotação.\nMantenha o braço em posição estática. Contraia o oblíquo para baixar o peso em um abdominal lateral.\nAo atingir a contração máxima, solte lentamente o peso até a posição inicial. A pilha de pesos nunca deve descansar por completo. O objetivo é manter tensão constante durante a série.\nRepita até a falha.\nEm seguida, reposicione-se e repita a mesma sequência de movimentos do lado oposto.',
  'One-Arm Incline Lateral Raise':
    'Deite-se de lado em um banco inclinado com um halter na mão. Certifique-se de que o ombro esteja pressionado contra o banco inclinado e de que o braço esteja cruzado sobre o corpo, com a palma na altura do umbigo.\nSegure um halter com o braço de cima, mantendo-o estendido à sua frente, paralelo ao chão. Essa é sua posição inicial.\nMantendo o halter paralelo ao chão o tempo todo, realize uma elevação lateral. Seu braço deve subir em linha reta até apontar para o teto. Dica: expire enquanto realiza este movimento. Mantenha o halter nessa posição e sinta a contração nos ombros por um segundo.\nEnquanto inspira, abaixe o peso cruzando o corpo de volta à posição inicial.\nRepita o movimento pelo número de repetições prescrito.\nTroque de braço e repita o movimento.',
  'One-Arm Kettlebell Clean':
    'Coloque um kettlebell entre os pés. Ao se abaixar para pegá-lo, empurre o quadril para trás e mantenha o olhar para a frente.\nLeve o kettlebell até o ombro estendendo as pernas e o quadril enquanto o eleva em direção ao ombro. O punho deve girar durante o movimento.\nVolte o peso à posição inicial.',
  'One-Arm Kettlebell Clean and Jerk':
    'Segure um kettlebell pela alça.\nLeve o kettlebell até o ombro estendendo as pernas e o quadril enquanto o puxa em direção ao ombro. Gire o punho durante o movimento, de modo que a palma fique voltada para a frente.\nDesça o corpo flexionando os joelhos, mantendo o tronco ereto.\nInverta imediatamente o movimento, empurrando pelos calcanhares, basicamente saltando para gerar impulso. Ao fazer isso, empurre o kettlebell acima da cabeça até travar os braços, usando o impulso do corpo para mover o peso.\nReceba o peso acima da cabeça voltando a uma posição de agachamento por baixo dele.\nMantendo o peso acima da cabeça, volte à posição em pé. Abaixe o peso até o chão para realizar a próxima repetição.',
  'One-Arm Kettlebell Floor Press':
    'Deite-se no chão segurando um kettlebell com uma das mãos, com a parte superior do braço apoiada no chão. A palma deve ficar voltada para dentro.\nEmpurre o kettlebell em linha reta em direção ao teto, girando o punho.\nAbaixe o kettlebell de volta à posição inicial e repita.',
  'One-Arm Kettlebell Jerk':
    'Segure um kettlebell pela alça. Leve o kettlebell até o ombro estendendo as pernas e o quadril enquanto o puxa em direção ao ombro. Gire o punho durante o movimento, de modo que a palma fique voltada para a frente. Essa será sua posição inicial.\nDesça o corpo flexionando os joelhos, mantendo o tronco ereto.\nInverta imediatamente o movimento, empurrando pelos calcanhares, basicamente saltando para gerar impulso. Ao fazer isso, empurre o kettlebell acima da cabeça até travar os braços, usando o impulso do corpo para mover o peso. Receba o peso acima da cabeça voltando a uma posição de agachamento por baixo dele. Mantendo o peso acima da cabeça, volte à posição em pé.\nAbaixe o peso para realizar a próxima repetição.',
  'One-Arm Kettlebell Military Press To The Side':
    'Leve um kettlebell até o ombro. Eleve-o estendendo as pernas e o quadril enquanto o puxa em direção ao ombro. Gire o punho durante o movimento, de modo que a palma fique voltada para dentro. Essa será sua posição inicial.\nOlhe para o kettlebell e empurre-o para cima e para fora até travar o braço acima da cabeça.\nAbaixe o kettlebell de volta ao ombro de forma controlada e repita. Certifique-se de contrair com força o dorsal, os glúteos e o abdômen para ter mais estabilidade e força.',
  'One-Arm Kettlebell Para Press':
    'Leve um kettlebell até o ombro. Eleve-o estendendo as pernas e o quadril enquanto o puxa em direção ao ombro. Gire o punho durante o movimento, de modo que a palma fique voltada para a frente. Essa será sua posição inicial.\nSegure o kettlebell com o cotovelo para o lado e empurre-o para cima e para fora até travar o braço acima da cabeça.\nAbaixe o kettlebell de volta ao ombro de forma controlada e repita. Certifique-se de contrair com força o dorsal, os glúteos e o abdômen para ter mais estabilidade e força.',
  'One-Arm Kettlebell Push Press':
    'Segure um kettlebell pela alça. Leve o kettlebell até o ombro estendendo as pernas e o quadril enquanto o puxa em direção ao ombro. Gire o punho durante o movimento, de modo que a palma fique voltada para a frente. Essa será sua posição inicial.\nDesça o corpo flexionando os joelhos, mantendo o tronco ereto.\nInverta imediatamente o movimento, empurrando pelos calcanhares, basicamente saltando para gerar impulso. Ao fazer isso, empurre o kettlebell acima da cabeça até travar os braços, usando o impulso do corpo para mover o peso. Abaixe o peso para realizar a próxima repetição.',
  'One-Arm Kettlebell Row':
    'Coloque um kettlebell à frente dos pés. Flexione levemente os joelhos e depois empurre o quadril para trás o máximo possível ao se inclinar para assumir a posição inicial. Pegue o kettlebell e puxe-o em direção ao abdômen, retraindo a escápula e flexionando o cotovelo. Mantenha as costas retas. Abaixe e repita.',
  'One-Arm Kettlebell Snatch':
    'Coloque um kettlebell entre os pés. Flexione os joelhos e empurre o quadril para trás para assumir a posição inicial correta.\nOlhe para a frente e balance o kettlebell para trás, entre as pernas.\nInverta imediatamente o movimento e projete o quadril e os joelhos, acelerando o kettlebell para cima. Quando o kettlebell chegar à altura do ombro, gire a mão e empurre para cima, usando o impulso para receber o peso com o braço travado acima da cabeça.',
  'One-Arm Kettlebell Split Jerk':
    'Segure um kettlebell pela alça. Leve o kettlebell até o ombro estendendo as pernas e o quadril enquanto o puxa em direção ao ombro. Gire o punho durante o movimento, de modo que a palma fique voltada para a frente. Essa será sua posição inicial.\nDesça o corpo flexionando os joelhos, mantendo o tronco ereto.\nInverta imediatamente o movimento, empurrando pelos calcanhares, basicamente saltando para gerar impulso. Ao fazer isso, empurre o kettlebell acima da cabeça até travar os braços, usando o impulso do corpo para mover o peso.\nReceba o peso acima da cabeça voltando a uma posição de agachamento por baixo dele, posicionando uma perna à frente e outra atrás.\nMantendo o peso acima da cabeça, volte à posição em pé e junte os pés. Abaixe o peso para realizar a próxima repetição.',
  'One-Arm Kettlebell Split Snatch':
    'Segure um kettlebell em uma das mãos pela alça.\nAgache em direção ao chão e depois inverta o movimento, estendendo o quadril, os joelhos e, por fim, os tornozelos, para elevar o kettlebell acima da cabeça.\nDepois de estender completamente o corpo, desça para uma posição de afundo para receber o peso acima da cabeça, com uma perna à frente e outra atrás. Certifique-se de projetar o quadril e travar o kettlebell acima da cabeça em um único movimento contínuo.\nVolte à posição em pé, segurando o peso acima da cabeça, e junte os pés. Abaixe o peso para voltar à posição inicial.',
  'One-Arm Long Bar Row':
    'Posicione uma barra em um landmine ou em um canto para evitar que ela se mova. Coloque um peso adequado na sua ponta.\nFique ao lado da barra e segure-a com uma mão, perto do colar. Usando o quadril e as pernas, fique em pé.\nAssuma uma postura com os joelhos flexionados, o quadril para trás e o peito erguido. Seu braço deve estar estendido. Essa será sua posição inicial.\nPuxe o peso até o seu lado retraindo o ombro e flexionando o cotovelo. Não dê solavancos com o peso nem faça trapaça durante o movimento.\nApós uma breve pausa, volte à posição inicial.',
  'One-Arm Medicine Ball Slam':
    'Comece em pé, em uma postura atlética com um pé à frente. Segure uma bola medicinal em uma das mãos, do mesmo lado da perna de trás. Essa será sua posição inicial.\nComece girando o braço para trás e elevando a bola medicinal acima da cabeça. Ao fazer isso, estenda o quadril, os joelhos e os tornozelos para carregar o impulso da batida.\nNo ponto máximo de extensão, flexione os ombros, a coluna e o quadril para arremessar a bola com força no chão, bem à sua frente.\nPegue a bola no rebote e continue pelo número de repetições desejado.',
  'One-Arm Open Palm Kettlebell Clean':
    'Coloque um kettlebell entre os pés.\nSegure a alça com uma mão e eleve o kettlebell rapidamente, deixando-o girar de modo que a bola do kettlebell caia na palma da sua mão.\nLance o kettlebell para a frente e pegue a alça com uma mão.\nLeve o kettlebell ao chão e repita. Certifique-se de trabalhar ambos os braços.',
  'One-Arm Overhead Kettlebell Squats':
    'Faça um clean e press de um kettlebell com um braço. Leve o kettlebell até o ombro estendendo as pernas e o quadril enquanto o puxa em direção ao ombro. Gire o punho durante o movimento. Empurre o peso acima da cabeça estendendo o cotovelo. Essa será sua posição inicial.\nOlhando para a frente e mantendo o kettlebell travado acima de você, flexione os joelhos e o quadril e desça o tronco entre as pernas, mantendo a cabeça e o peito erguidos.\nFaça uma pausa de um segundo na posição inferior antes de subir novamente, empurrando pelos calcanhares.',
  'One-Arm Side Deadlift':
    'Fique em pé ao lado de uma barra, perto do centro dela. Flexione os joelhos e abaixe o corpo até conseguir alcançar a barra.\nSegure a barra como se estivesse pegando uma maleta (com as palmas voltadas para você, já que a barra está de lado). Pode ser necessário usar uma munhequeira se estiver usando bastante peso. Essa é sua posição inicial.\nUse as pernas para ajudar a levantar a barra enquanto expira. Seus braços devem estender por completo ao levantar a barra até ficar em pé.\nAbaixe lentamente a barra enquanto inspira. Dica: certifique-se de flexionar os joelhos ao abaixar o peso para evitar qualquer lesão.\nRepita o número recomendado de repetições.\nTroque de braço e repita o movimento.',
  'One-Arm Side Laterals':
    'Pegue um halter e segure-o em uma das mãos. A mão que não levanta deve se apoiar em algo estável, como um banco inclinado. Incline-se em direção ao braço que levanta e para longe da mão que segura o banco inclinado, pois isso ajuda a manter o equilíbrio.\nFique em pé com o tronco reto e o halter ao lado do corpo, com o braço estendido e a palma da mão voltada para você. Essa será sua posição inicial.\nMantendo o tronco parado (sem balançar), levante o halter para o lado com uma leve flexão no cotovelo e a mão ligeiramente inclinada para a frente, como se estivesse despejando água em um copo. Continue subindo até o braço ficar paralelo ao chão. Expire ao executar este movimento e faça uma pausa de um segundo no topo.\nAbaixe lentamente o halter até a posição inicial enquanto inspira.\nRepita o número recomendado de repetições.\nTroque de braço e repita o exercício.',
  'One-Legged Cable Kickback':
    'Prenda uma tornozeleira de couro a uma polia baixa e depois coloque-a no tornozelo.\nFique de frente para a pilha de pesos, a uma distância de cerca de 60 cm, segurando a estrutura de aço para se apoiar.\nMantendo os joelhos e o quadril levemente flexionados e o abdômen contraído, contraia os glúteos para "chutar" lentamente a perna de trabalho para trás em um arco semicircular, o mais alto que conseguir confortavelmente, enquanto expira. Dica: na extensão completa, aperte os glúteos por um segundo para obter uma contração máxima.\nAgora traga lentamente a perna de trabalho para a frente, resistindo à tração do cabo até chegar à posição inicial.\nRepita o número recomendado de repetições.\nTroque de perna e repita o movimento do outro lado.',
  'Open Palm Kettlebell Clean':
    'Coloque um kettlebell entre os pés. Leve o kettlebell para cima estendendo as pernas e o quadril enquanto o eleva em direção aos ombros.\nSolte o kettlebell enquanto ele sobe e deixe-o girar de modo que a bola do kettlebell caia nas palmas das suas mãos.\nSolte o kettlebell à sua frente e pegue a alça com as duas mãos. Abaixe o kettlebell até a posição inicial e repita.',
  'Otis-Up':
    'Prenda os pés e deite-se de costas no chão. Seus joelhos devem estar flexionados. Segure um peso com as duas mãos junto ao peito. Essa será sua posição inicial.\nInicie o movimento flexionando o quadril e a coluna para levantar o tronco do chão.\nAo subir, empurre o peso para cima de modo que fique acima da cabeça na parte alta do movimento.\nTraga o peso de volta ao peito enquanto inverte o movimento do abdominal, cuidando para não descer até o chão.',
  'Overhead Cable Curl':
    'Para começar, ajuste um peso confortável em cada lado da máquina de polia. Nota: certifique-se de que a carga selecionada seja a mesma nos dois lados.\nAgora ajuste a altura das polias de cada lado e certifique-se de que estejam posicionadas acima da altura dos ombros.\nFique no meio dos dois lados e use uma pegada supinada (palmas voltadas para o teto) para segurar cada alça. Seus braços devem estar totalmente estendidos e paralelos ao chão, com os pés afastados na largura dos ombros. Seu corpo deve estar alinhado com as alças. Essa é a posição inicial.\nEnquanto expira, contraia lentamente os bíceps de cada lado até que os antebraços e os bíceps se toquem.\nEnquanto inspira, leve os antebraços de volta à posição inicial. Nota: todo o seu corpo permanece parado durante este exercício, exceto os antebraços.\nRepita o número recomendado de repetições prescrito no seu programa.',
  'Overhead Lat':
    'Sente-se ereto no chão com seu parceiro atrás de você. Levante um braço reto para cima e flexione o cotovelo, tentando encostar a mão nas costas. Seu parceiro deve segurar seu tríceps e seu punho. Essa será sua posição inicial.\nTente puxar a parte superior do braço para o lado do corpo enquanto seu parceiro impede que você consiga.\nApós 10 a 20 segundos, relaxe o braço e permita que seu parceiro alongue ainda mais o dorsal aplicando uma pressão suave no tríceps. Segure por 10 a 20 segundos e depois troque de lado.',
  'Overhead Slam':
    'Segure uma bola medicinal com as duas mãos e fique com os pés afastados na largura dos ombros. Essa será sua posição inicial.\nInicie o contramovimento elevando a bola acima da cabeça e estendendo completamente o corpo.\nInverta o movimento, arremessando a bola no chão, bem à sua frente, o mais forte que puder.\nReceba a bola com as duas mãos no rebote e repita o movimento.',
  'Overhead Squat':
    'Comece com uma barra à sua frente no chão. Seus pés devem estar mais afastados que a largura dos ombros.\nFlexione os joelhos e use uma pegada pronada (palmas voltadas para você) para segurar a barra. Suas mãos devem estar mais afastadas que a largura dos ombros antes de levantar. Uma vez posicionado, levante a barra até poder apoiá-la no peito.\nLeve a barra para cima e ligeiramente atrás da cabeça e certifique-se de que os braços estejam totalmente estendidos. Mantenha a cabeça erguida o tempo todo e mantenha também as costas retas. Retraia as escápulas. Essa é sua posição inicial.\nAbaixe lentamente o peso flexionando os joelhos até as coxas ficarem paralelas ao chão enquanto inspira. Dica: mantenha as costas retas durante este exercício para evitar lesões, e seus braços devem permanecer estendidos e acima da cabeça o tempo todo.\nAgora use os pés e as pernas para ajudar a levar o peso de volta à posição inicial enquanto expira.\nRepita o número recomendado de repetições.',
  'Overhead Stretch':
    'Em pé e com o corpo reto, entrelace os dedos e abra as palmas voltadas para o teto. Mantenha os ombros para baixo enquanto estende os braços para cima.\nPara obter um alongamento completo do tronco, puxe o cóccix para baixo e estabilize o tronco enquanto faz isso. Alongue os músculos tanto da parte da frente quanto de trás do tronco.',
  'Overhead Triceps':
    'Sente-se ereto no chão com seu parceiro atrás de você. Levante um braço reto para cima e flexione o cotovelo, tentando encostar a mão nas costas. Seu parceiro deve segurar seu cotovelo e seu punho. Essa será sua posição inicial.\nTente estender o braço reto para o alto enquanto seu parceiro impede que você consiga.\nApós 10 a 20 segundos, relaxe o braço e permita que seu parceiro alongue ainda mais o tríceps aplicando uma pressão suave no punho. Segure por 10 a 20 segundos e depois troque de lado.',
  'Pallof Press':
    'Conecte uma alça padrão a uma torre e, se possível, posicione o cabo na altura dos ombros. Se não for possível, uma polia baixa serve.\nCom o lado do corpo voltado para o cabo, segure a alça com as duas mãos e afaste-se da torre. Você deve ficar aproximadamente a um braço de distância da polia, com a tensão do peso no cabo.\nCom os pés afastados na largura do quadril e os joelhos levemente flexionados, segure o cabo na altura do meio do peito. Essa será sua posição inicial.\nEmpurre o cabo para longe do peito, estendendo totalmente os dois braços. Seu core deve estar firme e ativado.\nSegure a repetição por vários segundos antes de voltar à posição inicial.\nAo final da série, repita virado para a direção oposta.',
  'Pallof Press With Rotation':
    'Conecte uma alça padrão a uma torre e posicione o cabo na altura dos ombros.\nCom o lado do corpo voltado para o cabo, segure a alça com uma mão e afaste-se da torre. Você deve ficar aproximadamente a um braço de distância da polia, com a tensão do peso no cabo. Alinhe o braço estendido com o cabo.\nCom os pés afastados na largura do quadril, puxe o cabo até o peito e segure a alça com a outra mão. As duas mãos devem estar na alça neste momento.\nDe frente, empurre o cabo para longe do peito. Seu core deve estar firme e ativado.\nMantendo o quadril reto, gire o tronco para longe da polia até completar um quarto de rotação.\nMantenha a postura firme e os braços retos. Volte à posição neutra de forma lenta e controlada. Seus braços devem estar estendidos à sua frente.\nCom a tensão lateral ainda ativando o core, leve as mãos ao peito e imediatamente empurre para fora até a extensão completa. Isso constitui uma repetição.\nRepita até a falha.\nEm seguida, reposicione-se e repita a mesma sequência de movimentos do lado oposto.',
  'Palms-Down Dumbbell Wrist Curl Over A Bench':
    'Comece colocando dois halteres em um dos lados de um banco plano.\nAjoelhe-se sobre os dois joelhos de modo que o corpo fique de frente para o banco plano.\nUse os braços para segurar os dois halteres com uma pegada pronada (palmas para baixo) e leve-os para cima até que os antebraços fiquem apoiados no banco plano. Seus punhos devem ficar pendurados para fora da borda.\nComece flexionando os punhos para cima enquanto expira.\nAbaixe lentamente os punhos de volta à posição inicial enquanto inspira.\nSeus antebraços devem permanecer parados, pois o punho é o único movimento necessário neste exercício.\nRepita o número recomendado de repetições.',
  'Palms-Down Wrist Curl Over A Bench':
    'Comece colocando uma barra em um dos lados de um banco plano.\nAjoelhe-se sobre os dois joelhos de modo que o corpo fique de frente para o banco plano.\nUse os braços para segurar a barra com uma pegada pronada (palmas para baixo) e leve-a para cima até que os antebraços fiquem apoiados no banco plano. Seus punhos devem ficar pendurados para fora da borda.\nComece flexionando os punhos para cima enquanto expira.\nAbaixe lentamente os punhos de volta à posição inicial enquanto inspira.\nSeus antebraços devem permanecer parados, pois o punho é o único movimento necessário neste exercício.\nRepita o número recomendado de repetições.',
  'Palms-Up Barbell Wrist Curl Over A Bench':
    'Comece colocando uma barra em um dos lados de um banco plano.\nAjoelhe-se sobre os dois joelhos de modo que o corpo fique de frente para o banco plano.\nUse os braços para segurar a barra com uma pegada supinada (palmas para cima) e leve-a para cima até que os antebraços fiquem apoiados no banco plano. Seus punhos devem ficar pendurados para fora da borda.\nComece flexionando os punhos para cima enquanto expira.\nAbaixe lentamente os punhos de volta à posição inicial enquanto inspira.\nSeus antebraços devem permanecer parados, pois o punho é o único movimento necessário neste exercício.\nRepita o número recomendado de repetições.',
  'Palms-Up Dumbbell Wrist Curl Over A Bench':
    'Comece colocando dois halteres em um dos lados de um banco plano.\nAjoelhe-se sobre os dois joelhos de modo que o corpo fique de frente para o banco plano.\nUse os braços para segurar os dois halteres com uma pegada supinada (palmas para cima) e leve-os para cima até que os antebraços fiquem apoiados no banco plano. Seus punhos devem ficar pendurados para fora da borda.\nComece flexionando os punhos para cima enquanto expira.\nAbaixe lentamente os punhos de volta à posição inicial enquanto inspira. Certifique-se de inspirar durante esta parte do exercício.\nSeus antebraços devem permanecer parados, pois o punho é o único movimento necessário neste exercício.\nRepita o número recomendado de repetições.',
  'Parallel Bar Dip':
    'Fique entre um par de barras paralelas. Apoie uma mão em cada barra e dê um pequeno salto para ajudar a chegar à posição inicial com os braços travados.\nComece flexionando os cotovelos, abaixando o corpo até que os braços passem de 90 graus. Evite balançar e mantenha uma boa postura durante toda a descida.\nInverta o movimento estendendo os cotovelos, empurrando-se de volta à posição inicial.\nRepita o número de repetições desejado.',
  'Pelvic Tilt Into Bridge':
    'Deite-se com os pés no chão e os calcanhares bem abaixo dos joelhos.\nLevante apenas o cóccix em direção ao teto para alongar a região lombar. (Ainda não levante toda a coluna.) Contraia o abdômen.\nPara passar para uma ponte, levante toda a coluna, exceto o pescoço.',
  'Peroneals Stretch':
    'Sentado, passe um cinto, uma corda ou uma faixa ao redor de um dos pés. Essa será sua posição inicial.\nCom a perna estendida e o calcanhar fora do chão, puxe o cinto de modo que o pé fique invertido, com a parte interna do pé sendo puxada em sua direção. Segure por 10 a 20 segundos e depois troque de lado.',
  'Peroneals-SMR':
    'Deite-se de lado, apoiando seu peso no antebraço e em um rolo de espuma posicionado na parte externa da perna de baixo. A perna de cima pode ficar sobre a perna de baixo, ou você pode cruzá-la à sua frente. Essa será sua posição inicial.\nLevante o quadril do chão e comece a rolar de baixo do joelho até acima do tornozelo, na lateral da perna, fazendo pausas de 10 a 30 segundos nos pontos de tensão. Repita na outra perna.',
  'Physioball Hip Bridge':
    'Deite-se sobre uma bola de modo que a parte superior das costas fique sobre a bola e o quadril sem apoio. Os dois pés devem estar apoiados no chão, afastados na largura do quadril ou mais. Essa será sua posição inicial.\nComece estendendo o quadril usando os glúteos e os posteriores de coxa, elevando o quadril para cima ao fazer a ponte.\nFaça uma pausa no topo do movimento e volte à posição inicial.',
  'Pin Presses':
    'O supino com pinos elimina a fase excêntrica do supino, desenvolvendo a força de arranque. Ele também permite treinar uma amplitude de movimento específica.\nO banco deve ser posicionado dentro de um power rack. Ajuste os pinos no ponto desejado da sua amplitude de movimento, seja apenas o travamento ou a uma polegada do peito. A barra deve ser colocada sobre os pinos e ficar pronta para ser levantada.\nComece deitado no banco, com a barra diretamente acima do ponto de contato do seu supino habitual. Recolha os pés para baixo de você e arqueie as costas. Usando a barra para ajudar a sustentar seu peso, tire os ombros do banco e retraia-os, apertando as escápulas. Use os pés para pressionar o trapézio contra o banco. Mantenha essa posição firme do corpo durante todo o movimento.\nVocê pode usar uma pegada padrão de supino, ou na largura dos ombros para enfatizar os tríceps. A barra, o punho e o cotovelo devem permanecer alinhados o tempo todo. Concentre-se em apertar a barra e tentar separá-la.\nEmpurre a barra para cima com o máximo de força possível. Os cotovelos devem ficar junto ao corpo até o travamento.\nDevolva a barra aos pinos, fazendo uma pausa antes de começar a próxima repetição.',
  'Piriformis-SMR':
    'Sente-se com os glúteos sobre um rolo de espuma. Flexione os joelhos e depois cruze uma perna de modo que o tornozelo fique sobre o joelho. Essa será sua posição inicial.\nTransfira o peso para o lado da perna cruzada, rolando sobre os glúteos até sentir tensão na parte superior do glúteo. Você pode auxiliar o alongamento usando uma mão para puxar o joelho flexionado em direção ao peito. Mantenha essa posição por 10 a 30 segundos e depois troque de lado.',
  Plank:
    'Fique em posição de bruços no chão, apoiando seu peso nos dedos dos pés e nos antebraços. Seus braços devem estar flexionados e diretamente abaixo dos ombros.\nMantenha o corpo reto o tempo todo e sustente essa posição pelo maior tempo possível. Para aumentar a dificuldade, é possível levantar um braço ou uma perna.',
  'Plate Pinch':
    'Pegue duas anilhas de borda larga e junte-as com os lados lisos voltados para fora.\nUse os dedos para segurar a parte externa da anilha e o polegar para o outro lado, mantendo assim as duas anilhas juntas. Essa é a posição inicial.\nAperte a anilha com os dedos e o polegar. Mantenha essa posição pelo maior tempo que conseguir.\nRepita o número recomendado de séries prescrito no seu programa.\nTroque de braço e repita o movimento.',
  'Plate Twist':
    'Sente-se no chão ou em um tapete de exercícios com as pernas totalmente estendidas e a parte superior do corpo ereta. Segure a anilha pelas laterais com as duas mãos à frente dos abdominais, com os braços levemente flexionados.\nCruze lentamente as pernas na altura dos tornozelos e levante-as do chão. Seus joelhos também devem estar levemente flexionados. Nota: incline um pouco o tronco para trás para ajudar a manter o equilíbrio durante este exercício. Essa é a posição inicial.\nLeve a anilha para o lado esquerdo e toque o chão com ela. Expire enquanto realiza esse movimento.\nVolte à posição inicial enquanto inspira e depois repita o movimento, desta vez para o lado direito do corpo. Dica: use sempre um movimento lento e controlado. Movimentos bruscos podem lesionar as costas.\nRepita o número recomendado de repetições.',
  'Platform Hamstring Slides':
    'Para este movimento é necessário um piso de madeira ou similar. Deite-se de costas com as pernas estendidas. Coloque uma toalha de academia ou um peso leve embaixo do calcanhar. Essa será sua posição inicial.\nComece o movimento flexionando o joelho, mantendo a outra perna reta.\nContinue trazendo o calcanhar para perto de você, deslizando-o pelo chão.\nNa flexão completa do joelho, inverta o movimento para voltar à posição inicial.',
  'Plie Dumbbell Squat':
    'Segure um halter pela base com as duas mãos e fique em pé, reto. Afaste as pernas mais que a largura dos ombros, com os joelhos levemente flexionados.\nAs pontas dos pés devem apontar para fora. Nota: seus braços devem permanecer parados enquanto você realiza o exercício. Essa é a posição inicial.\nFlexione lentamente os joelhos e abaixe as pernas até as coxas ficarem paralelas ao chão. Certifique-se de inspirar, pois essa é a parte excêntrica do exercício.\nEmpurre principalmente com o calcanhar para levar o corpo de volta à posição inicial enquanto expira.\nRepita o número recomendado de repetições.',
  'Plyo Kettlebell Pushups':
    'Coloque um kettlebell no chão. Posicione-se em posição de flexão, na ponta dos pés, com uma mão no chão e a outra segurando o kettlebell, com os cotovelos estendidos. Essa será sua posição inicial.\nComece descendo o máximo que puder, mantendo as costas retas.\nInverta a direção de forma rápida e explosiva, empurrando-se para cima até o outro lado do kettlebell, trocando de mão ao fazer isso. Continue o movimento descendo e repetindo de um lado para o outro.',
  'Plyo Push-up':
    'Fique em posição de bruços no chão, apoiando seu peso nas mãos e na ponta dos pés.\nSeus braços devem estar totalmente estendidos, com as mãos aproximadamente na largura dos ombros. Mantenha o corpo reto durante todo o movimento. Essa será sua posição inicial.\nDesça flexionando os cotovelos, abaixando o peito em direção ao chão.\nNa parte de baixo, inverta o movimento empurrando-se para cima por meio da extensão dos cotovelos o mais rápido possível. Tente empurrar a parte superior do corpo até que as mãos saiam do chão.\nVolte à posição inicial e repita o exercício.\nPara aumentar a dificuldade, acrescente palmas ao movimento enquanto estiver no ar.',
  'Posterior Tibialis Stretch':
    'Sentado, passe um cinto, uma corda ou uma faixa ao redor de um dos pés. Essa será sua posição inicial.\nCom a perna estendida e o calcanhar fora do chão, puxe o cinto de modo que o pé fique evertido, com a parte externa do pé sendo puxada em sua direção. Segure por 10 a 20 segundos e depois troque de lado.',
  'Power Clean':
    'Fique em pé com os pés um pouco mais afastados que a largura dos ombros e as pontas dos pés levemente para fora.\nAgache e segure a barra com uma pegada fechada e pronada. Suas mãos devem estar um pouco mais afastadas que a largura dos ombros, por fora dos joelhos, com os cotovelos totalmente estendidos.\nPosicione a barra a cerca de 2,5 cm à frente das canelas e sobre a parte da frente dos pés.\nSuas costas devem estar planas ou levemente arqueadas, o peito erguido e para fora e as escápulas retraídas.\nMantenha a cabeça em posição neutra (alinhada com a coluna vertebral, sem inclinar nem girar) com o olhar voltado para a frente. Inspire durante esta fase.\nLevante a barra do chão estendendo com força o quadril e os joelhos enquanto expira. Dica: a parte superior do tronco deve manter o mesmo ângulo. Ainda não flexione na cintura e não deixe o quadril subir antes dos ombros (isso empurraria os glúteos para cima e alongaria os posteriores de coxa).\nMantenha os cotovelos totalmente estendidos, a cabeça em posição neutra e os ombros sobre a barra.\nEnquanto a barra sobe, mantenha-a o mais próximo possível das canelas.\nQuando a barra passar pelos joelhos, projete o quadril para a frente e flexione levemente os joelhos para evitar travá-los. Dica: neste ponto as coxas devem estar encostadas na barra.\nMantenha as costas planas ou levemente arqueadas, os cotovelos totalmente estendidos e a cabeça neutra. Dica: você vai prender a respiração até a próxima fase.\nInspire e depois estenda com força e rapidez o quadril e os joelhos e fique na ponta dos pés.\nMantenha a barra o mais próxima possível do corpo. Dica: suas costas devem estar planas, com os cotovelos apontando para os lados e a cabeça em posição neutra. Além disso, mantenha os ombros sobre a barra e os braços retos pelo maior tempo possível.\nQuando as articulações da parte inferior do corpo estiverem totalmente estendidas, eleve os ombros rapidamente (encolhendo-os) sem flexionar ainda os cotovelos. Expire durante esta parte do movimento.\nQuando os ombros atingirem a elevação máxima, flexione os cotovelos para começar a puxar o corpo por baixo da barra.\nContinue puxando com os braços o mais alto e por o maior tempo possível. Dica: devido à natureza explosiva desta fase, seu tronco ficará ereto ou com as costas arqueadas, sua cabeça ficará levemente inclinada para trás e seus pés podem perder o contato com o chão.\nDepois que a parte inferior do corpo estiver totalmente estendida e a barra atingir quase a altura máxima, puxe o corpo para baixo da barra e gire os braços ao redor e por baixo da barra.\nAo mesmo tempo, flexione o quadril e os joelhos até uma posição de um quarto de agachamento.\nQuando os braços estiverem sob a barra, inspire e depois levante os cotovelos para posicionar a parte superior dos braços paralela ao chão. Apoie a barra na frente das clavículas e dos músculos anteriores dos ombros.\nReceba a barra com o tronco ereto e firme, a cabeça em posição neutra e os pés apoiados por inteiro no chão. Expire durante este movimento.\nFique em pé estendendo o quadril e os joelhos até uma posição totalmente ereta.\nAbaixe a barra reduzindo gradualmente a tensão muscular dos braços para permitir uma descida controlada da barra até as coxas. Inspire durante este movimento.\nAo mesmo tempo, flexione o quadril e os joelhos para amortecer o impacto da barra nas coxas.\nAgache com os cotovelos totalmente estendidos até a barra tocar o chão.\nRecomece na Fase 1 e repita o número recomendado de repetições.',
  'Power Clean from Blocks':
    'Com uma barra sobre caixas na altura desejada, segure a barra um pouco mais aberto que as pernas. Abaixe o quadril com o peso concentrado nos calcanhares, costas retas, cabeça voltada para a frente, peito erguido e ombros um pouco à frente da barra. Esta será sua posição inicial.\nComece a primeira puxada empurrando com os calcanhares e estendendo os joelhos. O ângulo das costas deve permanecer o mesmo e os braços devem continuar retos. Quando a barra se aproximar do meio da coxa, comece a estender o quadril.\nEm um movimento de salto, acelere estendendo quadril, joelhos e tornozelos, usando a velocidade para subir a barra. Não é necessário puxar ativamente com os braços para acelerar o peso. No final da segunda puxada, o corpo deve estar totalmente estendido, levemente inclinado para trás, com os braços ainda estendidos.\nAo atingir a extensão completa, passe para a terceira puxada encolhendo os ombros com força e flexionando os braços, com os cotovelos para cima e para fora. No pico da extensão, entre por baixo da barra o suficiente para apoiá-la sobre os ombros, girando os cotovelos por baixo da barra ao fazer isso. A barra deve ficar apoiada sobre os ombros protraídos, tocando levemente a garganta, com as mãos relaxadas.\nRecupere-se imediatamente empurrando com os calcanhares, mantendo o tronco ereto e os cotovelos para cima. Continue até ficar em pé e conclua a repetição devolvendo o peso às caixas.',
  'Power Jerk':
    'Em pé, com a barra apoiada na parte da frente dos ombros, comece com a flexão. Com os pés diretamente sob o quadril, flexione os joelhos sem levar o quadril para trás. Desça apenas um pouco e inverta o movimento com a maior potência possível.\nEmpurre com os calcanhares para gerar o máximo de velocidade e força possível e lembre-se de tirar a cabeça do caminho quando a barra sair dos ombros.\nNo momento em que os pés saem do chão, eles devem ser posicionados na posição de recepção o mais rápido possível. No breve instante em que os pés não estão empurrando ativamente contra a plataforma, o esforço do atleta para empurrar a barra para cima o levará para baixo. Os pés devem ir para uma base um pouco mais larga, com os joelhos parcialmente flexionados.\nReceba a barra com os braços totalmente estendidos acima da cabeça.\nVolte à posição em pé.',
  'Power Partials':
    'Fique em pé com o tronco ereto e um halter em cada mão, segurados com os braços estendidos. Os cotovelos devem ficar próximos ao tronco.\nAs palmas das mãos devem estar voltadas para o tronco. Seus pés devem ficar afastados na largura dos ombros. Esta será sua posição inicial.\nMantendo os braços retos e o tronco parado, levante os pesos para os lados até a altura dos ombros, expirando.\nSinta a contração por um segundo e comece a abaixar os pesos de volta à posição inicial, inspirando. Dica: mantenha as palmas voltadas para baixo com o dedo mínimo um pouco mais alto ao levantar e abaixar os pesos, pois isso concentra a tensão principalmente nos ombros.\nRepita pelo número de repetições recomendado.',
  'Power Snatch':
    'Comece com uma barra carregada no chão. A barra deve estar próxima das canelas ou tocando-as, e você deve segurá-la com uma pegada aberta. Os pés devem estar diretamente sob o quadril, com as pontas voltadas para fora conforme necessário. Abaixe o quadril, com o peito erguido e a cabeça olhando para a frente. Os ombros devem estar um pouco à frente da barra. Esta será a posição inicial.\nComece a primeira puxada empurrando com a parte da frente dos calcanhares, tirando a barra do chão. O ângulo das costas deve permanecer o mesmo até a barra passar pelos joelhos.\nPasse para a segunda puxada estendendo quadril, joelhos e tornozelos, subindo a barra o mais rápido possível. A barra deve ficar próxima ao corpo. No pico da extensão, encolha os ombros e deixe os cotovelos flexionarem para os lados.\nAo levar os pés para a posição de recepção, um pouco mais afastados, entre por baixo da barra enquanto a eleva acima da cabeça. A barra deve ser recebida em um agachamento parcial. Continue elevando a barra até a posição acima da cabeça, recebendo-a com os braços totalmente estendidos.\nVolte à posição em pé com o peso acima da cabeça.',
  'Power Snatch from Blocks':
    'Comece com uma barra carregada sobre caixas ou suportes na altura desejada. Você deve segurar a barra com uma pegada aberta. Os pés devem estar diretamente sob o quadril, com as pontas voltadas para fora conforme necessário. Abaixe o quadril, com o peito erguido e a cabeça olhando para a frente. Os ombros devem estar um pouco à frente da barra, com os cotovelos apontando para fora. Esta será a posição inicial.\nComece a primeira puxada empurrando com a parte da frente dos calcanhares, tirando a barra das caixas.\nPasse para a segunda puxada estendendo quadril, joelhos e tornozelos, subindo a barra o mais rápido possível. A barra deve ficar próxima ao corpo. No pico da extensão, encolha os ombros e deixe os cotovelos flexionarem para os lados.\nAo levar os pés para a posição de recepção, entre com força por baixo da barra enquanto a eleva acima da cabeça. Os pés devem ir para logo fora do quadril, com as pontas voltadas para fora conforme necessário. Receba a barra acima de um agachamento completo e com os braços totalmente estendidos acima da cabeça.\nMantendo a barra alinhada sobre a parte da frente dos calcanhares, com a cabeça e o peito erguidos, empurre com os calcanhares para ficar em pé. Devolva o peso com cuidado às caixas.',
  'Power Stairs':
    'Nas power stairs, os implementos são movidos escada acima. Para fins de treino, podem ser feitas com um pneu ou uma caixa.\nComece segurando o implemento com as duas mãos. Afaste bem os pés, com a cabeça e o peito erguidos. Empurre o chão com os calcanhares, estendendo joelhos e quadril para tirar o peso do chão.\nAo se inclinar para trás, tente lançar o peso sobre os degraus, que geralmente têm cerca de 16-18" de altura. Você pode usar as pernas para ajudar a empurrar o peso sobre o degrau.\nRepita por 3 a 5 repetições e continue com um peso maior, movendo-se o mais rápido possível.',
  'Preacher Curl':
    'Para realizar este movimento, você precisará de um banco Scott e de uma barra W. Segure a barra W pela pegada interna mais próxima (o ideal é que alguém a entregue a você, ou pegue-a no suporte frontal que a maioria dos bancos Scott tem). As palmas das mãos devem estar voltadas para a frente e ligeiramente inclinadas para dentro devido ao formato da barra.\nCom a parte superior dos braços apoiada no estofado do banco Scott e o peito encostado nele, segure a barra W na altura dos ombros. Esta será sua posição inicial.\nAo inspirar, abaixe lentamente a barra até que a parte superior do braço fique estendida e o bíceps totalmente alongado.\nAo expirar, use o bíceps para subir o peso na rosca até que o bíceps esteja totalmente contraído e a barra esteja na altura dos ombros. Aperte o bíceps com força e mantenha essa posição por um segundo.\nRepita pelo número de repetições recomendado.',
  'Preacher Hammer Dumbbell Curl':
    'Apoie a parte superior de ambos os braços sobre o banco Scott enquanto segura um halter em cada mão com as palmas voltadas uma para a outra (pegada neutra).\nAo inspirar, abaixe lentamente os halteres até que a parte superior do braço fique estendida e o bíceps totalmente alongado.\nAo expirar, use o bíceps para subir o peso na rosca até que o bíceps esteja totalmente contraído e os halteres estejam na altura dos ombros.\nAperte o bíceps com força por um segundo na posição de contração e repita pelo número de repetições recomendado.',
  'Press Sit-Up':
    'Para começar, deite-se em um banco com uma barra apoiada sobre o peito. Posicione as pernas de modo que fiquem firmes na extensão do banco abdominal. Esta é a posição inicial.\nAo inspirar, contraia os abdominais e os glúteos. Ao mesmo tempo, enrole o tronco como faz ao executar um abdominal e empurre a barra até a posição acima da cabeça, expirando. Dica: use os braços para empurrar a barra durante este exercício, sem deixar de focar nos músculos abdominais.\nAbaixe a parte superior do corpo de volta à posição inicial enquanto traz a barra de volta ao tronco. Lembre-se de inspirar ao abaixar o corpo.\nRepita pelo número de repetições recomendado.',
  'Prone Manual Hamstring':
    'Você precisará de um parceiro para este exercício. Deite-se de bruços com as pernas retas. Seu assistente colocará a mão sobre o seu calcanhar.\nPara começar, flexione o joelho para levar a perna para cima. Seu parceiro deve oferecer resistência, começando leve e aumentando a pressão conforme o movimento é concluído. Comunique-se com seu parceiro para controlar os níveis adequados de resistência.\nFaça uma pausa no topo e volte com a perna à posição inicial enquanto seu parceiro oferece resistência na direção oposta.',
  'Prowler Sprint':
    'Coloque o seu trenó em uma superfície adequada, carregado com um peso apropriado. O trenó deve oferecer resistência suficiente para exigir esforço, mas não ser tão pesado a ponto de deixar você significativamente lento.\nVocê pode usar as alças verticais ou as baixas para este exercício. Coloque as mãos nas alças com os braços estendidos, inclinando-se sobre o implemento.\nCom boa postura, empurre o chão com passos curtos e alternados. Mova-se o mais rápido que puder por uma distância curta.',
  'Pull Through':
    'Comece em pé, a alguns passos de frente para uma polia baixa com uma corda ou alça acoplada. Fique de costas para a máquina, com o cabo entre as pernas e os pés bem afastados.\nComece o movimento alcançando entre as pernas o mais longe possível, flexionando o quadril. Mantenha os joelhos levemente flexionados. Com os braços retos, estenda o quadril para ficar totalmente em pé. Evite puxar para cima com os ombros; todo o movimento deve se originar no quadril.',
  Pullups:
    'Segure a barra fixa com as palmas voltadas para a frente usando a pegada indicada. Nota sobre as pegadas: para uma pegada aberta, suas mãos devem ficar afastadas a uma distância maior que a largura dos ombros. Para uma pegada média, as mãos devem ficar afastadas a uma distância igual à largura dos ombros e, para uma pegada fechada, a uma distância menor que a largura dos ombros.\nCom os dois braços estendidos à sua frente segurando a barra na largura de pegada escolhida, incline o tronco para trás cerca de 30 graus, criando uma curvatura na lombar e projetando o peito para fora. Esta é sua posição inicial.\nPuxe o tronco para cima até que a barra toque a parte superior do peito, levando os ombros e a parte superior dos braços para baixo e para trás. Expire ao realizar esta parte do movimento. Dica: concentre-se em contrair os músculos das costas ao atingir a posição de contração total. A parte superior do tronco deve permanecer estável enquanto se desloca no espaço e somente os braços devem se mover. Os antebraços não devem fazer nenhum outro trabalho além de segurar a barra.\nApós um segundo na posição de contração, comece a inspirar e abaixe lentamente o tronco de volta à posição inicial, quando os braços estiverem totalmente estendidos e os dorsais totalmente alongados.\nRepita esse movimento pelo número de repetições indicado.',
  'Push Press - Behind the Neck':
    'Em pé, com a barra apoiada na parte de trás dos ombros, comece com a flexão. Com os pés diretamente sob o quadril, flexione os joelhos sem levar o quadril para trás. Desça apenas um pouco e inverta o movimento com a maior potência possível. Empurre com os calcanhares para gerar o máximo de velocidade e força possível, movendo a barra em uma trajetória vertical.\nAproveitando o impulso gerado, termine de empurrar o peso acima da cabeça estendendo os braços.\nVolte à posição inicial, usando as pernas para absorver o impacto.',
  'Push Up to Side Plank':
    'Assuma a posição de flexão de braço sobre as pontas dos pés, com as mãos um pouco além da largura dos ombros.\nFaça uma flexão de braço permitindo que os cotovelos flexionem. Ao descer, mantenha o corpo reto.\nFaça uma flexão e, ao subir, transfira o peso para o lado esquerdo do corpo e gire para o lado, levando o braço direito em direção ao teto em uma prancha lateral.\nAbaixe o braço de volta ao chão para fazer outra flexão e depois gire para o outro lado.\nRepita a série, alternando cada lado, por 10 repetições ou mais.',
  'Push-Up Wide':
    'Com as mãos bem afastadas, apoie o corpo sobre as pontas dos pés e as mãos em posição de prancha. Os cotovelos devem estar estendidos e o corpo reto. Não deixe o quadril cair. Esta será sua posição inicial.\nPara começar, permita que os cotovelos flexionem, abaixando o peito em direção ao chão enquanto inspira.\nUsando os músculos peitorais, empurre a parte superior do corpo de volta à posição inicial estendendo os cotovelos. Expire ao realizar este passo.\nDepois de uma pausa na posição de contração, repita o movimento pelo número de repetições indicado.',
  'Push-Ups - Close Triceps Position':
    'Deite-se de bruços no chão e coloque as mãos mais próximas que a largura dos ombros, para uma pegada fechada. Certifique-se de manter o tronco elevado com os braços estendidos.\nDesça até que o peito quase toque o chão, inspirando.\nUsando os tríceps e parte dos peitorais, empurre a parte superior do corpo de volta à posição inicial e contraia o peito. Expire ao realizar este passo.\nApós uma pausa de um segundo na posição de contração, repita o movimento pelo número de repetições indicado.',
  'Push-Ups With Feet Elevated':
    'Deite-se de bruços no chão e coloque as mãos afastadas cerca de 36 polegadas uma da outra, mantendo o tronco elevado com os braços estendidos.\nColoque os dedos dos pés sobre um banco reto. Isso permitirá que o corpo fique elevado. Nota: quanto maior a elevação do banco reto, maior a resistência do exercício.\nDesça até que o peito quase toque o chão, inspirando.\nUsando os músculos peitorais, empurre a parte superior do corpo de volta à posição inicial e contraia o peito. Expire ao realizar este passo.\nApós uma pausa de um segundo na posição de contração, repita o movimento pelo número de repetições indicado.',
  'Push-Ups With Feet On An Exercise Ball':
    'Deite-se de bruços no chão e coloque as mãos afastadas cerca de 36 polegadas uma da outra, mantendo o tronco elevado com os braços estendidos.\nColoque os dedos dos pés sobre uma bola de exercício. Isso permitirá que o corpo fique elevado.\nDesça até que o peito quase toque o chão, inspirando.\nUsando os músculos peitorais, empurre a parte superior do corpo de volta à posição inicial e contraia o peito. Expire ao realizar este passo.\nApós uma pausa de um segundo na posição de contração, repita o movimento pelo número de repetições indicado.',
  Pushups:
    'Deite-se de bruços no chão e coloque as mãos afastadas cerca de 36 polegadas uma da outra, mantendo o tronco elevado com os braços estendidos.\nEm seguida, abaixe o corpo até que o peito quase toque o chão, inspirando.\nAgora expire e empurre a parte superior do corpo de volta à posição inicial, contraindo o peito.\nApós uma breve pausa na posição superior de contração, você pode começar a descer novamente pelo número de repetições necessário.',
  'Pushups (Close and Wide Hand Positions)':
    'Deite-se de bruços no chão com o corpo reto e os dedos dos pés apoiados no chão, com as mãos mais afastadas que a largura dos ombros para uma pegada aberta e mais próximas que a largura dos ombros para uma pegada fechada. Certifique-se de manter o tronco elevado com os braços estendidos.\nDesça até que o peito quase toque o chão, inspirando.\nUsando os músculos peitorais, empurre a parte superior do corpo de volta à posição inicial e contraia o peito. Expire ao realizar este passo.\nApós uma pausa de um segundo na posição de contração, repita o movimento pelo número de repetições indicado.',
  Pyramid:
    'Comece rolando o tronco para a frente sobre a bola, de modo que o quadril fique apoiado sobre ela e se torne o ponto mais alto do seu corpo.\nApoie as mãos e os pés no chão. Os braços e as pernas podem ficar levemente flexionados ou retos, dependendo do tamanho da bola, da sua flexibilidade e do comprimento dos seus membros. Isso também ajuda a desenvolver força estabilizadora no tronco e nos ombros.',
  'Quad Stretch':
    'Deite-se de lado. Passe um cinto, uma corda ou uma faixa ao redor do pé de cima. Flexione o joelho e estenda o quadril, tentando tocar os glúteos com o pé e segurando o cinto com as mãos. Esta será sua posição inicial.\nCom o cinto segurado sobre o ombro ou acima da cabeça, puxe suavemente para aumentar o alongamento no quadríceps. Mantenha por 10 a 20 segundos e depois troque de lado.',
  'Quadriceps-SMR':
    'Deite-se de bruços no chão com o peso apoiado nas mãos ou nos antebraços. Coloque um rolo de espuma sob uma perna, sobre o quadríceps, e mantenha o pé fora do chão. Procure relaxar a perna o máximo possível. Esta será sua posição inicial.\nTransferindo o máximo de peso tolerável para a perna que será alongada, role sobre a espuma desde acima do joelho até abaixo do quadril, mantendo os pontos de tensão por 10 a 30 segundos. Troque de lado.',
  'Quick Leap':
    'Você precisará de uma caixa para este exercício.\nComece de frente para a caixa, em pé a 1-2 pés de distância da borda.\nUsando o quadril, salte sobre a caixa, aterrissando com as duas pernas. Certifique-se de aterrissar com as pernas flexionadas e os pés apoiados totalmente no chão.\nImediatamente ao aterrissar, estenda todo o corpo por completo e lance os braços acima da cabeça para saltar com explosão da caixa. Use as pernas para absorver o impacto da aterrissagem.',
  'Rack Delivery':
    'Este exercício de técnica ensina a levar a barra até a posição de rack sobre os ombros. Comece segurando uma barra na posição de espantalho, com a parte superior dos braços paralela ao chão e os antebraços pendendo para baixo. Use uma pegada em gancho, com os dedos envolvendo os polegares.\nComece girando os cotovelos ao redor da barra, levando-a até os ombros. À medida que os cotovelos avançam, relaxe a pegada. Os ombros devem estar protraídos, formando uma prateleira para a barra, que deve tocar levemente a garganta.\nÉ importante que a barra permaneça próxima ao corpo o tempo todo, pois, com uma carga mais pesada, qualquer distância resultará em uma colisão indesejada. À medida que o movimento ficar mais fluido, a velocidade e a carga podem ser aumentadas antes de avançar.',
  'Rack Pull with Bands':
    'Posicione-se em um rack de potência com a barra sobre os pinos. Os pinos devem estar ajustados no ponto desejado: logo abaixo dos joelhos, logo acima ou no meio da coxa. Prenda as faixas elásticas na base do rack ou fixe-as com halteres. Prenda a outra extremidade à barra. Pode ser necessário encurtar as faixas para gerar tensão.\nPosicione-se junto à barra na posição correta de levantamento terra. Seus pés devem estar sob o quadril, a pegada na largura dos ombros, as costas arqueadas e o quadril para trás para ativar os posteriores de coxa. Como o peso costuma ser elevado, você pode usar uma pegada mista, uma pegada em gancho ou usar straps para ajudar a segurar o peso.\nCom a cabeça voltada para a frente, estenda o quadril e os joelhos, puxando o peso para cima e para trás até a extensão completa. Lembre-se de levar os ombros para trás ao concluir o movimento. Devolva o peso aos pinos e repita.',
  'Rack Pulls':
    'Posicione-se em um rack de potência com a barra sobre os pinos. Os pinos devem estar ajustados no ponto desejado: logo abaixo dos joelhos, logo acima ou no meio da coxa. Posicione-se junto à barra na posição correta de levantamento terra. Seus pés devem estar sob o quadril, a pegada na largura dos ombros, as costas arqueadas e o quadril para trás para ativar os posteriores de coxa. Como o peso costuma ser elevado, você pode usar uma pegada mista, uma pegada em gancho ou usar straps para ajudar a segurar o peso.\nCom a cabeça voltada para a frente, estenda o quadril e os joelhos, puxando o peso para cima e para trás até a extensão completa. Lembre-se de levar os ombros para trás ao concluir o movimento.\nDevolva o peso aos pinos e repita.',
  'Rear Leg Raises':
    'Apoie-se sobre as mãos e os joelhos em um colchonete de exercício. Sua cabeça deve olhar para a frente e a flexão dos joelhos deve formar um ângulo de 90 graus entre os posteriores de coxa e as panturrilhas. Esta será sua posição inicial.\nEstenda uma perna para cima e para trás. O joelho e o quadril devem se estender. Repita por 5 a 10 repetições e depois troque de lado.',
  'Recumbent Bike':
    'Para começar, sente-se na bicicleta e ajuste o assento à sua altura.\nSelecione a opção desejada no menu. Talvez seja necessário começar a pedalar para ligá-la. Você pode usar o modo manual ou escolher um programa. Normalmente, é possível inserir sua idade e seu peso para estimar a quantidade de calorias queimadas durante o exercício. O nível de resistência pode ser alterado ao longo do treino. As alças podem ser usadas para monitorar a frequência cardíaca e ajudar você a manter uma intensidade adequada.\nAs bicicletas reclinadas oferecem conveniência, benefícios cardiovasculares e têm menos impacto que outras atividades. Uma pessoa de 150 lbs queima cerca de 230 calorias pedalando em ritmo moderado por 30 minutos, em comparação com 450 calorias ou mais correndo.',
  'Return Push from Stance':
    'Você precisará de um parceiro para este exercício.\nComece em uma postura atlética de 2 ou 3 apoios.\nAo sinal, mova-se para uma posição de receber o passe do seu parceiro.\nPegue a bola medicinal com as duas mãos e imediatamente arremesse-a de volta ao seu parceiro.\nVocê pode modificar este exercício correndo por trajetos diferentes.',
  'Reverse Band Bench Press':
    'Posicione um banco dentro de um rack de potência, com a barra ajustada na altura correta. Comece prendendo as faixas elásticas nos suportes para faixas ou na parte superior do rack. Certifique-se de que ficará posicionado corretamente sob as faixas. Prenda a outra extremidade à barra.\nDeite-se no banco, recolha os pés para baixo de você e arqueie as costas. Usando a barra para ajudar a sustentar seu peso, tire os ombros do banco e retraia-os, apertando as escápulas uma contra a outra. Use os pés para pressionar o trapézio contra o banco. Mantenha essa posição firme do corpo durante todo o movimento. Qualquer que seja a largura da sua pegada, ela deve cobrir o anel da barra.\nRetire a barra do rack sem protrair os ombros. Concentre-se em apertar a barra e tentar separá-la. Abaixe a barra até a parte inferior do peito ou a parte superior do abdômen. A barra, o punho e o cotovelo devem permanecer alinhados o tempo todo.\nFaça uma pausa quando a barra tocar o tronco e depois empurre a barra para cima com a maior força possível. Os cotovelos devem permanecer junto ao corpo até a extensão completa.',
  'Reverse Band Box Squat':
    'Comece em um rack de potência com uma caixa na altura adequada atrás de você. Prenda as faixas elásticas nos suportes para faixas ou na parte superior do rack, garantindo que fiquem diretamente acima da barra durante o agachamento. Prenda a outra extremidade à barra.\nComece entrando sob a barra e apoiando-a na parte de trás dos ombros. Aperte as escápulas e gire os cotovelos para a frente, tentando curvar a barra sobre os ombros. Retire a barra do rack, criando um arco firme na lombar, e dê um passo para trás até a sua posição. Posicione os pés mais afastados para dar mais ênfase às costas, aos glúteos, aos adutores e aos posteriores de coxa, ou mais próximos para maior desenvolvimento do quadríceps. Mantenha a cabeça voltada para a frente.\nCom as costas, os ombros e o core firmes, empurre os joelhos e o bumbum para fora e comece a descida. Sente-se para trás com o quadril até estar sentado na caixa. O ideal é que as canelas fiquem perpendiculares ao chão. Faça uma pausa ao chegar à caixa e relaxe os flexores do quadril. Nunca quique na caixa.\nMantendo o peso nos calcanhares e empurrando os pés e os joelhos para fora, suba da caixa conduzindo o movimento com a cabeça. Continue subindo, mantendo a firmeza da cabeça aos pés. Tenha cuidado ao devolver a barra ao rack.',
  'Reverse Band Deadlift':
    'Coloque a barra em um rack de potência. Prenda as faixas elásticas na parte superior do rack, usando suportes para faixas ou a própria estrutura. Prenda a outra extremidade das faixas à barra.\nAproxime-se da barra de modo que ela fique centralizada sobre os seus pés. Seus pés devem ficar afastados aproximadamente na largura do quadril. Flexione o quadril para segurar a barra na largura dos ombros, permitindo que as escápulas se protraiam. Normalmente usa-se uma pegada pronada ou uma pegada mista nas séries mais pesadas.\nCom os pés e a pegada posicionados, respire fundo e então abaixe o quadril e flexione os joelhos até que as canelas toquem a barra. Olhe para a frente, mantenha o peito erguido e as costas arqueadas e comece a empurrar com os calcanhares para subir o peso.\nDepois que a barra passar pelos joelhos, puxe-a para trás com força, juntando as escápulas enquanto leva o quadril para a frente contra a barra.\nAbaixe a barra flexionando o quadril e guiando-a até o chão.',
  'Reverse Band Power Squat':
    'Comece em um rack de potência com os pinos e a barra ajustados na altura adequada. Depois de carregar a barra, prenda as faixas elásticas na parte superior do rack, usando suportes ou a própria estrutura. Prenda a outra extremidade das faixas à barra.\nComece entrando sob a barra e apoiando-a na parte de trás dos ombros. Aperte as escápulas e gire os cotovelos para a frente, tentando curvar a barra sobre os ombros. Retire a barra do rack, criando um arco firme na lombar, e dê um passo para trás até a sua posição. Posicione os pés bem afastados para dar mais ênfase às costas, aos glúteos, aos adutores e aos posteriores de coxa.\nMantenha a cabeça voltada para a frente. Com as costas, os ombros e o core firmes, empurre os joelhos e o bumbum para fora e comece a descida. Sente-se para trás com o quadril o máximo possível. O ideal é que as canelas fiquem perpendiculares ao chão. Uma posição mais baixa da barra exige uma inclinação maior do tronco para manter a barra sobre os calcanhares. Continue até quebrar o paralelo, definido como a dobra do quadril alinhada com a parte superior do joelho.\nMantendo o peso nos calcanhares e empurrando os pés e os joelhos para fora, suba conduzindo o movimento com a cabeça. Continue subindo, mantendo a firmeza da cabeça aos pés, até voltar à posição inicial.',
  'Reverse Band Sumo Deadlift':
    'Comece com uma barra carregada no chão, dentro de um rack de potência. Prenda as faixas elásticas na parte superior do rack, usando suportes ou a própria estrutura. Prenda a outra extremidade à barra.\nAproxime-se da barra de modo que ela cruze o meio dos pés. Os pés devem ficar bem afastados, próximos aos colares. Flexione o quadril para segurar a barra. Os braços devem ficar diretamente abaixo dos ombros, por dentro das pernas, e você pode usar uma pegada pronada, uma pegada mista ou uma pegada em gancho. Relaxe os ombros, o que na prática alonga seus braços.\nRespire fundo e então abaixe o quadril, olhando para a frente com a cabeça e com o peito erguido. Empurre o chão, afastando os pés para os lados, com o peso na metade de trás dos pés. Estenda o quadril e os joelhos.\nQuando a barra passar pelos joelhos, incline-se para trás e leve o quadril contra a barra, juntando as escápulas.\nDevolva o peso ao chão flexionando o quadril e controlando o peso na descida.',
  'Reverse Barbell Curl':
    'Fique em pé com o tronco ereto segurando uma barra na largura dos ombros, com os cotovelos próximos ao tronco. As palmas das mãos devem estar voltadas para baixo (pegada pronada). Esta será sua posição inicial.\nMantendo a parte superior dos braços parada, suba o peso na rosca contraindo o bíceps ao expirar. Somente os antebraços devem se mover. Continue o movimento até que os bíceps estejam totalmente contraídos e a barra esteja na altura dos ombros. Mantenha a posição de contração por um segundo enquanto aperta o músculo.\nComece a trazer lentamente a barra de volta à posição inicial ao inspirar.\nRepita pelo número de repetições recomendado.',
  'Reverse Barbell Preacher Curls':
    'Segure uma barra W com uma pegada na largura dos ombros e com as palmas voltadas para baixo (pronada).\nAgora apoie a parte superior de ambos os braços sobre o banco Scott e mantenha os braços estendidos. Esta será sua posição inicial.\nAo expirar, use o bíceps para subir o peso na rosca até que os bíceps estejam totalmente contraídos e a barra esteja na altura dos ombros. Aperte o bíceps com força por um segundo na posição de contração.\nAo inspirar, abaixe lentamente a barra até que a parte superior dos braços fique estendida e o bíceps totalmente alongado.\nRepita pelo número de repetições recomendado.',
  'Reverse Cable Curl':
    'Fique em pé com o tronco ereto segurando um acessório de barra preso a uma polia baixa com uma pegada pronada (palmas para baixo) na largura dos ombros. Certifique-se também de manter os cotovelos próximos ao tronco. Esta será sua posição inicial.\nMantendo a parte superior dos braços parada, suba o peso na rosca contraindo o bíceps ao expirar. Somente os antebraços devem se mover. Continue o movimento até que os bíceps estejam totalmente contraídos e a barra esteja na altura dos ombros. Mantenha a posição de contração por um segundo enquanto aperta o músculo.\nComece a trazer lentamente a barra de volta à posição inicial ao inspirar.\nRepita pelo número de repetições recomendado.',
  'Reverse Crunch':
    'Deite-se no chão com as pernas totalmente estendidas e os braços ao lado do tronco com as palmas no chão. Seus braços devem permanecer parados durante todo o exercício.\nSuba as pernas de modo que as coxas fiquem perpendiculares ao chão e os pés juntos e paralelos ao chão. Esta é a posição inicial.\nAo inspirar, leve as pernas em direção ao tronco enquanto gira a pelve para trás e eleva o quadril do chão. Ao final desse movimento, seus joelhos estarão tocando o peito.\nMantenha a contração por um segundo e volte com as pernas à posição inicial, expirando.\nRepita pelo número de repetições recomendado.',
  'Reverse Flyes':
    'Para começar, deite-se de bruços em um banco inclinado, com o peito e o abdômen apoiados na inclinação. Segure os halteres em cada mão com as palmas voltadas uma para a outra (pegada neutra).\nEstenda os braços à sua frente de modo que fiquem perpendiculares ao ângulo do banco. As pernas devem permanecer paradas enquanto você pressiona com a ponta dos pés. Esta é a posição inicial.\nMantendo a leve flexão dos cotovelos, leve os pesos para fora, afastando-os um do outro (para os lados) em um movimento de arco, expirando. Dica: tente apertar as escápulas uma contra a outra para obter os melhores resultados deste exercício.\nOs braços devem ser elevados até ficarem paralelos ao chão.\nSinta a contração e abaixe lentamente os pesos de volta à posição inicial, inspirando.\nRepita pelo número de repetições recomendado.',
  'Reverse Flyes With External Rotation':
    'Para começar, deite-se de bruços em um banco inclinado a 30 graus, com o peito e o abdômen apoiados na inclinação.\nSegure os halteres em cada mão com as palmas voltadas para o chão. Seus braços devem estar à sua frente, perpendiculares ao ângulo do banco. Dica: seus cotovelos devem ter uma leve flexão. As pernas devem permanecer paradas enquanto você pressiona com a ponta dos pés (os calcanhares não devem tocar o chão). Esta é a posição inicial.\nMantendo a leve flexão dos cotovelos, leve os pesos para fora, afastando-os um do outro em um movimento de arco, expirando.\nAo levantar o peso, o punho deve girar externamente 90 graus, passando de uma pegada pronada (palmas para baixo) para uma pegada neutra (palmas voltadas uma para a outra). Dica: tente apertar as escápulas uma contra a outra para obter os melhores resultados deste exercício.\nOs braços devem ser elevados até ficarem na altura da cabeça.\nSinta a contração e abaixe lentamente os pesos de volta à posição inicial, inspirando.\nRepita pelo número de repetições recomendado.',
  'Reverse Grip Bent-Over Rows':
    'Fique em pé, ereto, segurando uma barra com uma pegada supinada (palmas voltadas para cima).\nFlexione levemente os joelhos e incline o tronco para a frente, flexionando na cintura e mantendo as costas retas até ficarem quase paralelas ao chão. Dica: certifique-se de manter a cabeça erguida. A barra deve ficar pendurada diretamente à sua frente, com os braços pendendo perpendiculares ao chão e ao tronco. Esta é sua posição inicial.\nMantendo o tronco parado, levante a barra ao expirar, com os cotovelos próximos ao corpo e sem fazer nenhuma força com o antebraço além de segurar o peso. Na posição superior de contração, aperte os músculos das costas e mantenha por um segundo.\nAbaixe lentamente o peso de volta à posição inicial ao inspirar.\nRepita pelo número de repetições recomendado.',
  'Reverse Grip Triceps Pushdown':
    'Comece prendendo um acessório de barra (reta ou W) em uma polia alta.\nDe frente para o acessório, segure-o com as palmas voltadas para cima (pegada supinada) na largura dos ombros. Abaixe a barra usando os dorsais até que os braços fiquem totalmente estendidos ao lado do corpo. Dica: os cotovelos devem ficar junto às laterais do corpo e os pés afastados na largura dos ombros. Esta é a posição inicial.\nSuba lentamente o acessório ao inspirar até alinhá-lo com o peito. Somente os antebraços devem se mover, e os cotovelos e a parte superior dos braços devem permanecer parados ao lado do corpo o tempo todo.\nEm seguida, comece a abaixar a barra do cabo de volta à posição inicial ao expirar e contraindo os tríceps com força.\nRepita pelo número de repetições recomendado.',
  'Reverse Hyperextension':
    'Coloque os pés entre as almofadas depois de carregar um peso apropriado. Deite-se sobre a almofada superior, deixando o quadril pendurado para trás, enquanto segura as alças para manter a posição.\nPara começar o movimento, flexione o quadril, levando as pernas para a frente.\nInverta o movimento estendendo o quadril, chutando a perna para trás. É muito importante não hiperestender o quadril neste movimento, parando antes da amplitude total de movimento.\nRetorne flexionando novamente o quadril, puxando o carrinho para a frente o máximo que puder.\nRepita pelo número de repetições desejado.',
  'Reverse Machine Flyes':
    'Ajuste as alças de modo que fiquem totalmente para trás. Selecione um peso apropriado e ajuste a altura do assento para que as alças fiquem na altura dos ombros. Segure as alças com as palmas voltadas para dentro. Esta será sua posição inicial.\nEm um movimento semicircular, leve as mãos para os lados e para trás, contraindo os deltoides posteriores.\nMantenha os braços levemente flexionados durante todo o movimento, com todo o movimento ocorrendo na articulação do ombro.\nFaça uma pausa na parte de trás do movimento e volte lentamente com o peso à posição inicial.',
  'Reverse Plate Curls':
    'Comece em pé e ereto, com um anilha segurada com as duas mãos e os braços totalmente estendidos. Use uma pegada pronada (palmas para baixo) e certifique-se de que os dedos segurem o lado áspero da anilha enquanto o polegar segura o lado liso. Nota: para obter os melhores resultados, segure a anilha nas posições de 11 e 1 hora do relógio.\nSeus pés devem ficar afastados na largura dos ombros e a anilha deve ficar próxima à região da virilha. Esta é a posição inicial.\nSuba lentamente a anilha mantendo os cotovelos junto ao corpo e a parte superior dos braços parada, até que os bíceps e os antebraços se toquem, expirando. Nesse ponto, a anilha deve ficar alinhada com o tronco.\nSinta a contração por um segundo e comece a abaixar o peso de volta à posição inicial ao inspirar.\nRepita pelo número de repetições recomendado.',
  'Reverse Triceps Bench Press':
    'Deite-se em um banco reto. Usando uma pegada fechada e supinada (aproximadamente na largura dos ombros), retire a barra do rack e segure-a reta acima de você, com os braços estendidos e travados à sua frente, perpendiculares ao chão. Esta será sua posição inicial.\nAo inspirar, desça lentamente até sentir a barra na parte média do peito. Dica: diferentemente de um supino normal, mantenha os cotovelos próximos ao tronco o tempo todo para maximizar a participação dos tríceps.\nApós uma pausa de um segundo, leve a barra de volta à posição inicial ao expirar e empurrando a barra com os tríceps. Trave os braços na posição de contração, mantenha por um segundo e depois comece a descer lentamente outra vez. Dica: descer deve levar pelo menos o dobro do tempo de subir.\nRepita o movimento pelo número de repetições indicado.\nAo terminar, coloque a barra de volta no rack.',
  'Rhomboids-SMR':
    'Deite-se de costas no chão. Coloque um rolo de espuma sob a parte superior das costas e cruze os braços à sua frente, protraindo os ombros. Esta será sua posição inicial.\nEleve o quadril do chão, transferindo o peso para o rolo de espuma. Transfira o peso para um lado de cada vez, rolando sobre a parte média e superior das costas. Faça uma pausa nos pontos de tensão por 10 a 30 segundos.',
  'Rickshaw Carry':
    'Posicione a estrutura no ponto de partida e carregue-a com o peso adequado. Em pé no centro da estrutura, comece segurando as alças e empurrando com os calcanhares para levantá-la. Certifique-se de manter o peito e a cabeça erguidos e as costas retas.\nComece imediatamente a caminhar rapidamente, com passos curtos e controlados. Mantenha o peito erguido e a cabeça voltada para a frente e continue respirando. Coloque a estrutura no chão ao chegar ao ponto final.',
  'Rickshaw Deadlift':
    'Carregue a estrutura com o peso desejado. Posicione-se centralizado entre as alças. Seus pés devem ficar afastados aproximadamente na largura do quadril. Flexione o quadril para segurar as alças, permitindo que as escápulas se protraiam.\nCom os pés e a pegada posicionados, respire fundo e então abaixe o quadril e flexione os joelhos. Olhe para a frente, mantenha o peito erguido e as costas arqueadas e comece a empurrar com os calcanhares para subir o peso. Conforme o peso sobe, junte as escápulas enquanto leva o quadril para a frente.\nAbaixe o peso flexionando o quadril e guiando-o até o chão.',
  'Ring Dips':
    'Segure uma argola em cada mão e depois dê um pequeno salto para ajudar a chegar à posição inicial com os braços estendidos.\nComece flexionando os cotovelos, abaixando o corpo até que os braços passem de 90 graus. Evite balançar e mantenha boa postura durante toda a descida.\nInverta o movimento estendendo os cotovelos, empurrando-se de volta à posição inicial.\nRepita pelo número de repetições desejado.',
  'Rocket Jump':
    'Comece em uma postura relaxada com os pés afastados na largura dos ombros e os braços junto ao corpo.\nPara iniciar o movimento, agache até a metade e salte com explosão o mais alto possível.\nEstenda completamente todo o corpo, alcançando o mais longe possível acima da cabeça. Ao aterrissar, absorva o impacto com as pernas.',
  'Rocking Standing Calf Raise':
    'Este exercício é melhor realizado dentro de um rack de agachamento por segurança. Para começar, ajuste primeiro a barra em um rack que corresponda à sua altura. Depois de escolhida a altura correta e carregada a barra, entre sob a barra e apoie-a na parte de trás dos ombros (um pouco abaixo do pescoço).\nSegure a barra com os dois braços, um de cada lado, e retire-a do rack empurrando primeiro com as pernas e, ao mesmo tempo, endireitando o tronco.\nAfaste-se do rack e posicione as pernas em uma base média, na largura dos ombros, com as pontas dos pés ligeiramente voltadas para fora. Mantenha a cabeça erguida o tempo todo, pois olhar para baixo fará você perder o equilíbrio. Mantenha também as costas retas e os joelhos com uma leve flexão; nunca travados. Esta será sua posição inicial.\nEleve os calcanhares ao expirar, estendendo os tornozelos o mais alto possível e contraindo as panturrilhas. Certifique-se de que os joelhos permaneçam parados o tempo todo. Não deve haver flexão (além da leve flexão inicial que criamos ao posicionar) em nenhum momento. Mantenha a posição de contração por um segundo antes de começar a descer.\nVolte lentamente à posição inicial ao inspirar, abaixando os calcanhares e flexionando os tornozelos até que as panturrilhas estejam alongadas.\nAgora eleve as pontas dos pés contraindo os músculos tibiais na parte da frente da perna ao expirar.\nMantenha por um segundo e volte a abaixá-las ao inspirar.\nRepita pelo número de repetições recomendado.',
  'Rocky Pull-Ups/Pulldowns':
    'Segure a barra fixa com as palmas das mãos voltadas para frente e uma pegada aberta.\nCom ambos os braços estendidos à sua frente segurando a barra na largura escolhida, incline o tronco para trás cerca de 30 graus, criando uma curvatura na lombar e projetando o peito. Esta é a posição inicial.\nPuxe o tronco para cima até a barra tocar a parte superior do peito, levando os ombros e a parte superior dos braços para baixo e para trás. Expire durante esta parte do movimento. Dica: Concentre-se em contrair os músculos das costas ao chegar à contração máxima. A parte superior do tronco deve permanecer estável enquanto se desloca e apenas os braços devem se mover. Os antebraços não devem fazer nenhum trabalho além de segurar a barra.\nApós um segundo na posição contraída, comece a inspirar e abaixe lentamente o tronco até a posição inicial, quando os braços estiverem totalmente estendidos e os dorsais totalmente alongados.\nAgora repita os mesmos movimentos, mas desta vez o tronco permanecerá reto na subida e a barra tocará a nuca em vez da parte superior do peito. Dica: Use a cabeça para se inclinar levemente para frente, pois isso ajudará a executar corretamente esta parte do exercício.\nDepois de voltar à posição inicial, repita o exercício pelo número de repetições prescrito no seu programa.',
  'Romanian Deadlift':
    'Coloque uma barra no chão à sua frente e segure-a com uma pegada pronada (palmas voltadas para baixo) um pouco mais aberta que a largura dos ombros. Dica: Dependendo da carga utilizada, você pode precisar de munhequeiras e de uma plataforma elevada para obter uma melhor amplitude de movimento.\nFlexione levemente os joelhos e mantenha as canelas verticais, o quadril para trás e as costas retas. Esta será sua posição inicial.\nMantendo as costas e os braços completamente retos o tempo todo, use o quadril para levantar a barra enquanto expira. Dica: O movimento não deve ser rápido, e sim constante e controlado.\nQuando estiver completamente em pé, abaixe a barra empurrando o quadril para trás, flexionando apenas levemente os joelhos, diferente de um agachamento. Dica: Respire fundo no início do movimento e mantenha o peito erguido. Prenda o ar enquanto abaixa e expire ao completar o movimento.\nRepita pelo número de repetições recomendado.',
  'Romanian Deadlift from Deficit':
    'Comece em pé segurando uma barra com os braços estendidos à sua frente. Você pode ficar sobre uma plataforma elevada para aumentar a amplitude de movimento.\nComece flexionando levemente os joelhos e depois flexione o quadril, levando o bumbum para trás o máximo possível e abaixando o tronco até onde sua flexibilidade permitir. As costas devem permanecer em extensão absoluta o tempo todo e a barra deve permanecer em contato com as pernas. Se feito corretamente, você sentirá uma forte tensão nos posteriores de coxa.\nInverta o movimento para voltar à posição inicial.',
  'Rope Climb':
    'Segure a corda com as duas mãos acima da cabeça. Puxe a corda para baixo enquanto dá um pequeno salto.\nEnrole a corda em uma perna, usando os pés para prendê-la. Estenda os braços para cima o mais alto possível, segurando a corda com firmeza.\nSolte a corda com os pés enquanto se puxa para cima com os braços, levando os joelhos em direção ao peito.\nPrenda novamente os pés na corda e depois fique em pé para pegar outra pegada alta. Continue até chegar ao topo da corda.\nPara descer, afrouxe a pegada dos pés na corda enquanto desliza usando um movimento de mão sobre mão.',
  'Rope Crunch':
    'Ajoelhe-se a 30-60 cm de frente para uma polia com uma corda acoplada.\nDepois de selecionar uma carga adequada, segure a corda com as duas mãos, levando-as acima da cabeça. O tronco deve estar ereto na posição inicial.\nPara começar, flexione a coluna tentando aproximar a caixa torácica das pernas enquanto puxa o cabo para baixo.\nFaça uma pausa na parte inferior do movimento e depois retorne lentamente à posição inicial.\nVocê pode fazê-los com rotações ou para o lado para trabalhar os oblíquos.',
  'Rope Jumping':
    'Segure uma ponta da corda em cada mão. Posicione a corda atrás de você no chão. Levante os braços e gire a corda sobre a cabeça, trazendo-a para a frente. Quando ela chegar ao chão, pule por cima. Encontre um ritmo de giro que você consiga manter. Diferentes velocidades e técnicas podem ser usadas para trazer variação.\nPular corda é empolgante, desafia sua coordenação e exige muita energia. Uma pessoa de 150 lb (68 kg) queima cerca de 350 calorias pulando corda por 30 minutos, em comparação com mais de 450 calorias correndo.',
  'Rope Straight-Arm Pulldown':
    'Acople uma corda a uma polia alta e selecione a carga. Fique a cerca de um metro da polia com os pés um à frente do outro e segure a corda com as duas mãos. Incline-se para a frente a partir do quadril, mantendo as costas retas, com os braços estendidos para cima à sua frente. Esta será sua posição inicial.\nMantendo os braços retos, estenda o ombro para puxar a corda até as coxas.\nFaça uma pausa na parte inferior do movimento, contraindo os dorsais.\nRetorne à posição inicial sem deixar a carga descansar totalmente na pilha.',
  'Round The World Shoulder Stretch':
    'Fique em pé, ereto, com as pernas juntas, segurando uma barra leve ou um cabo de vassoura.\nSegure o bastão atrás do quadril com uma pegada mais aberta que a largura dos ombros. As palmas devem ficar voltadas para baixo e os polegares para fora.\nLevante lentamente os braços por trás da cabeça. Não force se ficar difícil subir mais.',
  'Rowing, Stationary':
    'Para começar, sente-se no remo. Certifique-se de que os calcanhares estejam apoiados confortavelmente na base dos pedais e de que as correias estejam bem presas. Selecione o programa que deseja usar, se aplicável. Sente-se ereto e incline-se para a frente a partir do quadril.\nHá três fases de movimento ao usar um remo. A primeira fase é quando você se desloca para a frente. Seus joelhos estão flexionados junto ao peito. A parte superior do corpo está levemente inclinada para a frente, mantendo boa postura. Em seguida, empurre os pedais e estenda as pernas enquanto leva as mãos à região abdominal superior, levando os ombros para trás. Para evitar sobrecarregar as costas, use principalmente os músculos das pernas e do quadril.\nA fase de recuperação consiste simplesmente em estender os braços, flexionar os joelhos e trazer o corpo para a frente novamente enquanto faz a transição de volta para a primeira fase.',
  "Runner's Stretch":
    'É mais fácil entrar neste alongamento se você começar em pé, colocar uma perna para trás e abaixar lentamente o tronco em direção ao chão.\nMantenha o calcanhar da frente no chão (se ele levantar, leve a outra perna mais para trás).\nColoque as mãos dos dois lados da perna da frente. Para aproveitar mais este alongamento, empurre o bumbum em direção ao teto e depois abaixe-o gradualmente de volta para o chão. Você alongará o flexor do quadril da perna de trás e os posteriores de coxa e o glúteo da perna da frente.',
  'Running, Treadmill':
    'Para começar, suba na esteira e selecione a opção desejada no menu. A maioria das esteiras tem um modo manual, ou você pode selecionar um programa de corrida. Normalmente, é possível inserir sua idade e peso para estimar as calorias queimadas durante o exercício. A inclinação pode ser ajustada para mudar a intensidade do treino.\nAs esteiras oferecem praticidade, benefícios cardiovasculares e geralmente têm menos impacto do que correr ao ar livre. Uma pessoa de 150 lb (68 kg) queima mais de 450 calorias correndo a 8 milhas por hora por 30 minutos. Mantenha a postura adequada enquanto corre e só segure nas barras laterais quando necessário, como ao descer ou ao verificar a frequência cardíaca.',
  'Russian Twist':
    'Deite-se no chão colocando os pés embaixo de algo que não se mova ou pedindo a um parceiro que os segure. As pernas devem estar flexionadas nos joelhos.\nEleve a parte superior do corpo de modo a formar um V imaginário com as coxas. Os braços devem estar totalmente estendidos à sua frente, perpendiculares ao tronco, com as mãos entrelaçadas. Esta é a posição inicial.\nGire o tronco para o lado direito até os braços ficarem paralelos ao chão enquanto expira.\nMantenha a contração por um segundo e volte à posição inicial enquanto expira. Agora vá para o lado oposto aplicando a mesma técnica que usou no lado direito.\nRepita pelo número de repetições recomendado.',
  'Sandbag Load':
    'Para carregar sacos de areia ou outros objetos, comece com os implementos posicionados a certa distância da plataforma de carga, normalmente 50 pés (cerca de 15 m).\nComece levantando o saco de areia. Sacos de areia são extremamente desajeitados e a forma de levantá-los pode variar conforme o saco usado. Abrace-o o máximo possível, estendendo quadril e joelhos para erguê-lo alto. Normalmente não é permitido apoiá-lo no ombro.\nMova-se o mais rápido possível até a plataforma e carregue-o, estendendo quadril, joelhos e tornozelos para levá-lo o mais alto possível. Coloque-o sobre a plataforma, garantindo que não caia.\nVolte à posição inicial para pegar o próximo saco de areia e repita até concluir a prova.',
  'Scapular Pull-Up':
    'Segure a barra fixa com uma pegada pronada.\nA partir da posição pendurada, eleve-se alguns centímetros sem usar os braços. Faça isso deprimindo a cintura escapular em um movimento inverso ao de encolher os ombros.\nFaça uma pausa ao completar o movimento e depois retorne lentamente à posição inicial antes de realizar mais repetições.',
  'Scissor Kick':
    'Para começar, deite-se com as costas apoiadas no chão ou em um colchonete (opcional). Os braços devem estar totalmente estendidos ao lado do corpo com as palmas voltadas para baixo. Nota: Os braços devem permanecer imóveis o tempo todo.\nCom uma leve flexão dos joelhos, levante as pernas de modo que os calcanhares fiquem a cerca de 15 cm do chão. Esta é a posição inicial.\nAgora levante a perna esquerda até um ângulo de cerca de 45 graus enquanto a perna direita desce até o calcanhar ficar a cerca de 5-7 cm do chão.\nAlterne o movimento levantando a perna direita e abaixando a esquerda. Lembre-se de respirar durante este exercício.\nRepita pelo número de repetições recomendado.',
  'Scissors Jump':
    'Assuma a posição de afundo com um pé à frente e o joelho flexionado, e o joelho de trás quase tocando o chão.\nCertifique-se de que o joelho da frente esteja alinhado com o meio do pé. Estendendo ambas as pernas, salte o mais alto possível, balançando os braços para ganhar impulso.\nEnquanto salta o mais alto que conseguir, troque a posição das pernas, levando a perna da frente para trás e a perna de trás para a frente.\nAo aterrissar, absorva o impacto com as pernas adotando a posição de afundo, e repita.',
  'Seated Band Hamstring Curl':
    'Fixe uma faixa elástica perto do chão e coloque um banco a cerca de meio metro de distância.\nSente-se no banco e prenda a faixa atrás dos tornozelos, começando com as pernas retas. Esta será sua posição inicial.\nFlexione os joelhos, levando os pés em direção ao banco. Talvez seja necessário inclinar-se levemente para trás para evitar que os pés batam no chão.\nFaça uma pausa ao completar o movimento e depois retorne lentamente à posição inicial.',
  'Seated Barbell Military Press':
    'Sente-se em um banco de desenvolvimento militar com uma barra atrás da cabeça e peça a um parceiro que a entregue (é melhor para o manguito rotador) ou pegue-a você mesmo com cuidado com uma pegada pronada (palmas voltadas para frente). Dica: Sua pegada deve ser mais aberta que a largura dos ombros e formar um ângulo de 90 graus entre o antebraço e a parte superior do braço quando a barra desce.\nDepois de pegar a barra com a largura de pegada correta, levante-a acima da cabeça estendendo os braços. Mantenha-a aproximadamente na altura dos ombros e levemente à frente da cabeça. Esta é sua posição inicial.\nAbaixe a barra lentamente até a clavícula enquanto inspira.\nLevante a barra de volta à posição inicial enquanto expira.\nRepita pelo número de repetições recomendado.',
  'Seated Barbell Twist':
    'Comece sentado na ponta de um banco reto com uma barra apoiada sobre as coxas. Os pés devem ficar afastados na largura dos ombros.\nSegure a barra com as palmas voltadas para baixo e certifique-se de que as mãos estejam mais afastadas que a largura dos ombros. Comece a levantar a barra acima da cabeça até os braços ficarem totalmente estendidos.\nAgora abaixe a barra por trás da cabeça até ela ficar apoiada na base do pescoço. Esta é a posição inicial.\nMantendo os pés e a cabeça imóveis, mova a cintura de um lado para o outro para sentir a contração nos oblíquos. Vá de um lado para o outro apenas até onde sua cintura permitir. Forçar ou ir longe demais pode causar lesão. Dica: Use um movimento lento e controlado.\nLembre-se de expirar ao girar o corpo para o lado e inspirar ao voltar à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Seated Bent-Over One-Arm Dumbbell Triceps Extension':
    'Sente-se na ponta de um banco reto com um halter em um dos braços usando uma pegada neutra (palma da mão voltada para você).\nFlexione levemente os joelhos e incline o tronco para a frente, flexionando na cintura e mantendo as costas retas até ficarem quase paralelas ao chão. Certifique-se de manter a cabeça erguida.\nA parte superior do braço com o halter deve ficar próxima ao tronco e alinhada com ele (elevada até ficar paralela ao chão enquanto o antebraço aponta para o chão e a mão segura o peso). Dica: Deve haver um ângulo de 90 graus entre o antebraço e a parte superior do braço. Esta é sua posição inicial.\nMantendo a parte superior do braço imóvel, use o tríceps para levantar o peso enquanto expira até o antebraço ficar paralelo ao chão e o braço todo estar estendido. Como em muitos outros exercícios de braços, apenas o antebraço se move.\nApós uma contração de um segundo no topo, abaixe lentamente o halter até a posição inicial enquanto inspira.\nRepita o movimento pelo número de repetições prescrito.\nTroque de braço e repita o exercício.',
  'Seated Bent-Over Rear Delt Raise':
    'Coloque um par de halteres à frente de um banco reto, alinhados para a frente.\nSente-se na ponta do banco com as pernas juntas e os halteres atrás das panturrilhas.\nIncline-se a partir da cintura mantendo as costas retas para pegar os halteres. As palmas das mãos devem ficar voltadas uma para a outra ao pegá-los. Esta será sua posição inicial.\nMantendo o tronco inclinado para a frente e imóvel, e os braços levemente flexionados nos cotovelos, levante os halteres diretamente para os lados até ambos os braços ficarem paralelos ao chão. Expire ao levantar os pesos. (Nota: evite balançar o tronco ou levar os braços para trás em vez de para o lado.)\nApós uma contração de um segundo no topo, abaixe lentamente os halteres até a posição inicial.\nRepita pelo número de repetições recomendado.',
  'Seated Bent-Over Two-Arm Dumbbell Triceps Extension':
    'Sente-se na ponta de um banco reto com um halter em cada mão usando uma pegada neutra (palmas das mãos voltadas para você).\nFlexione levemente os joelhos e incline o tronco para a frente, flexionando na cintura e mantendo as costas retas até ficarem quase paralelas ao chão. Certifique-se de manter a cabeça erguida.\nA parte superior dos braços com os halteres deve ficar próxima ao tronco e alinhada com ele (elevada até ficar paralela ao chão enquanto os antebraços apontam para o chão e as mãos seguram os pesos). Dica: Deve haver um ângulo de 90 graus entre os antebraços e a parte superior dos braços. Esta é sua posição inicial.\nMantendo a parte superior dos braços imóvel, use os tríceps para levantar o peso enquanto expira até os antebraços ficarem paralelos ao chão e os braços estarem totalmente estendidos. Como em muitos outros exercícios de braços, apenas o antebraço se move.\nApós uma contração de um segundo no topo, abaixe lentamente os halteres até a posição inicial enquanto inspira.\nRepita o movimento pelo número de repetições prescrito.',
  'Seated Biceps':
    'Sente-se no chão com os joelhos flexionados e seu parceiro em pé atrás de você. Estenda os braços retos para trás com as palmas voltadas uma para a outra. Seu parceiro segurará seus punhos. Esta será a posição inicial.\nTente flexionar os cotovelos enquanto seu parceiro impede qualquer movimento real.\nApós 10-20 segundos, relaxe os braços enquanto seu parceiro puxa suavemente seus punhos para cima para alongar os bíceps. Avise seu parceiro quando o alongamento estiver adequado para evitar lesões ou alongamento excessivo.',
  'Seated Cable Rows':
    'Para este exercício, você precisará de uma máquina de remada com polia baixa e um triângulo (barra em V). Nota: O triângulo permitirá uma pegada neutra, com as palmas das mãos voltadas uma para a outra. Para chegar à posição inicial, primeiro sente-se na máquina e apoie os pés na plataforma frontal ou na barra transversal, certificando-se de que os joelhos estejam levemente flexionados e não travados.\nIncline-se para a frente mantendo o alinhamento natural das costas e segure as alças do triângulo.\nCom os braços estendidos, puxe para trás até o tronco formar um ângulo de 90 graus com as pernas. As costas devem estar levemente arqueadas e o peito projetado. Você deve sentir um bom alongamento nos dorsais enquanto segura a barra à sua frente. Esta é a posição inicial do exercício.\nMantendo o tronco imóvel, puxe as alças em direção ao tronco mantendo os braços próximos a ele até tocar os abdominais. Expire ao realizar esse movimento. Nesse ponto, você deve estar contraindo fortemente os músculos das costas. Mantenha essa contração por um segundo e volte lentamente à posição original enquanto inspira.\nRepita pelo número de repetições recomendado.',
  'Seated Cable Shoulder Press':
    'Ajuste a carga para um valor adequado e sente-se, segurando as alças. A parte superior dos braços deve formar cerca de 90 graus com o corpo, com a cabeça e o peito erguidos. Os cotovelos também devem estar flexionados a cerca de 90 graus. Esta será sua posição inicial.\nComece estendendo os cotovelos, empurrando as alças juntas acima da cabeça.\nApós uma pausa no topo, retorne as alças à posição inicial. Certifique-se de manter a tensão nos cabos.\nVocê também pode executar este movimento com as costas afastadas do encosto e alternando as mãos.',
  'Seated Calf Raise':
    'Sente-se na máquina e apoie a ponta dos pés na parte inferior da plataforma, com os calcanhares para fora. Escolha o posicionamento dos pés que preferir (para frente, para dentro ou para fora) conforme indicado no início deste capítulo.\nColoque a parte inferior das coxas sob o apoio da alavanca, que precisará ser ajustado conforme a altura das suas coxas. Agora coloque as mãos sobre o apoio da alavanca para evitar que ele deslize para a frente.\nLevante levemente a alavanca empurrando os calcanhares para cima e solte a trava de segurança. Esta será sua posição inicial.\nAbaixe lentamente os calcanhares flexionando os tornozelos até as panturrilhas ficarem totalmente alongadas. Inspire ao realizar este movimento.\nLevante os calcanhares estendendo os tornozelos o mais alto possível enquanto contrai as panturrilhas e expira. Mantenha a contração no topo por um segundo.\nRepita pelo número de repetições recomendado.',
  'Seated Calf Stretch':
    'Sente-se ereto em um colchonete.\nFlexione um joelho e apoie esse pé no chão para estabilizar o tronco.\nEstenda a outra perna e flexione o tornozelo.\nUsando uma faixa elástica, uma toalha ou a mão, se conseguir alcançar, puxe os dedos dos pés em sua direção. Mantenha por 10 a 20 segundos e depois troque de lado.',
  'Seated Close-Grip Concentration Barbell Curl':
    'Sente-se em um banco reto com uma barra ou barra W à sua frente, entre as pernas. As pernas devem estar afastadas com os joelhos flexionados e os pés no chão.\nUse os braços para pegar a barra e apoie a parte de trás da parte superior dos braços sobre a parte interna das coxas (a cerca de 9 cm da frente do joelho). É necessária uma pegada supinada mais fechada que a largura dos ombros para realizar este exercício. Dica: Seus braços devem estar totalmente estendidos e a barra deve ficar acima do chão. Esta será sua posição inicial.\nMantendo a parte superior dos braços imóvel, faça a rosca levando os pesos para a frente enquanto contrai os bíceps e expira. Apenas os antebraços devem se mover. Continue o movimento até os bíceps estarem totalmente contraídos e os halteres ficarem na altura dos ombros. Mantenha a posição contraída por um segundo enquanto aperta os bíceps.\nComece a trazer lentamente a barra de volta à posição inicial enquanto inspira. Dica: Evite movimentos de balanço em qualquer momento.\nRepita pelo número de repetições recomendado.',
  'Seated Dumbbell Curl':
    'Sente-se em um banco reto com um halter em cada mão, mantidos com os braços estendidos. Os cotovelos devem ficar próximos ao tronco.\nGire as palmas das mãos de modo que fiquem voltadas para o tronco. Esta será sua posição inicial.\nMantendo a parte superior do braço imóvel, faça a rosca com os pesos e comece a girar os punhos quando os halteres passarem pelas coxas, de modo que as palmas das mãos fiquem voltadas para a frente no final do movimento. Certifique-se de contrair os bíceps enquanto expira e de que apenas os antebraços se movam. Continue o movimento até os bíceps estarem totalmente contraídos e os halteres ficarem na altura dos ombros. Mantenha a posição contraída por um segundo enquanto aperta os bíceps.\nComece a trazer lentamente os halteres de volta à posição inicial enquanto inspira e gira os punhos de volta para uma pegada neutra.\nRepita pelo número de repetições recomendado.',
  'Seated Dumbbell Inner Biceps Curl':
    'Sente-se na ponta de um banco reto com um halter em cada mão, mantidos com os braços estendidos. Os cotovelos devem ficar próximos ao tronco.\nGire as palmas das mãos de modo que fiquem voltadas para dentro em posição neutra. Esta será sua posição inicial.\nMantendo a parte superior dos braços imóvel, faça a rosca com os halteres para fora e para cima, girando as palmas para fora ao levantar e mantendo os antebraços alinhados com os deltoides laterais. Dicas:\nApenas os antebraços devem se mover. Continue o movimento até os bíceps estarem totalmente contraídos e os halteres ficarem na altura dos ombros. Mantenha a posição contraída por um segundo enquanto aperta os bíceps.\nComece a trazer lentamente os halteres de volta à posição inicial enquanto inspira. Lembre-se de girar os braços ao abaixar os halteres para voltar a uma pegada neutra.\nRepita pelo número de repetições recomendado.',
  'Seated Dumbbell Palms-Down Wrist Curl':
    'Comece colocando dois halteres no chão à frente de um banco reto.\nSente-se na borda do banco reto com as pernas afastadas cerca da largura dos ombros. Certifique-se de manter os pés no chão.\nUse os braços para pegar os dois halteres e levante-os de modo que os antebraços fiquem apoiados nas coxas com as palmas das mãos voltadas para baixo. Os punhos devem ficar pendurados para fora da borda das coxas.\nComece fazendo a rosca de punho para cima enquanto expira.\nAbaixe lentamente os punhos até a posição inicial enquanto inspira. Certifique-se de inspirar durante esta parte do exercício. Dica: Os antebraços devem permanecer imóveis, pois o único movimento necessário para este exercício é o do punho.\nRepita pelo número de repetições recomendado.\nAo terminar, simplesmente abaixe os halteres até o chão.',
  'Seated Dumbbell Palms-Up Wrist Curl':
    'Comece colocando dois halteres no chão à frente de um banco reto.\nSente-se na borda do banco reto com as pernas afastadas cerca da largura dos ombros. Certifique-se de manter os pés no chão.\nUse os braços para pegar os dois halteres e levante-os de modo que os antebraços fiquem apoiados nas coxas com as palmas das mãos voltadas para cima. Os punhos devem ficar pendurados para fora da borda das coxas.\nComece fazendo a rosca de punho para cima enquanto expira.\nAbaixe lentamente os punhos até a posição inicial enquanto inspira. Certifique-se de inspirar durante esta parte do exercício. Dica: Os antebraços devem permanecer imóveis, pois o único movimento necessário para este exercício é o do punho.\nRepita pelo número de repetições recomendado.\nAo terminar, simplesmente abaixe os halteres até o chão.',
  'Seated Dumbbell Press':
    'Pegue um par de halteres e sente-se em um banco de desenvolvimento militar ou em um banco utilitário com encosto, apoiando os halteres na vertical sobre as coxas.\nLeve os halteres para cima um de cada vez, usando as coxas para impulsioná-los até a altura dos ombros de cada lado.\nGire os punhos de modo que as palmas das mãos fiquem voltadas para a frente. Esta é sua posição inicial.\nEnquanto expira, empurre os halteres para cima até se tocarem no topo.\nApós uma pausa de um segundo, desça lentamente até a posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado.',
  'Seated Flat Bench Leg Pull-In':
    'Sente-se em um banco com as pernas estendidas à sua frente, ligeiramente abaixo da paralela, e os braços segurando as laterais do banco. Seu tronco deve estar inclinado para trás em um ângulo de cerca de 45 graus em relação ao banco. Esta será sua posição inicial.\nTraga os joelhos em sua direção enquanto aproxima o tronco deles ao mesmo tempo. Expire ao realizar este movimento.\nApós uma pausa de um segundo, volte à posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado.',
  'Seated Floor Hamstring Stretch':
    'Sente-se em um colchonete com a perna direita estendida à sua frente e a perna esquerda flexionada com o pé contra a parte interna da coxa direita.\nIncline-se para a frente a partir do quadril e alcance o tornozelo até sentir um alongamento nos posteriores de coxa. Mantenha por 15 segundos e depois repita do outro lado.',
  'Seated Front Deltoid':
    'Sente-se ereto no chão com as pernas flexionadas e seu parceiro em pé atrás de você. Estenda os braços retos para os lados com as palmas voltadas para o chão. Tente levá-los o mais para trás possível enquanto seu auxiliar segura seus punhos. Esta será sua posição inicial.\nMantendo os cotovelos estendidos, tente mover os braços para a frente enquanto seu parceiro o contém suavemente para impedir qualquer movimento real por 10-20 segundos.\nAgora relaxe os músculos e deixe seu parceiro aumentar suavemente o alongamento nos ombros e no peito. Mantenha por 10 a 20 segundos.',
  'Seated Glute':
    'Em posição sentada com os joelhos flexionados, cruze um tornozelo sobre o joelho oposto. Seu parceiro ficará em pé atrás de você. Agora incline-se para a frente enquanto seu parceiro segura seus ombros com as mãos. Esta será sua posição inicial.\nTente empurrar o tronco para trás por 10-20 segundos enquanto seu parceiro impede qualquer movimento real do seu tronco.\nAgora relaxe os músculos enquanto seu parceiro aumenta o alongamento empurrando suavemente seu tronco para a frente por 10-20 segundos.',
  'Seated Good Mornings':
    'Posicione uma caixa dentro de um rack de agachamento. Os pinos devem estar ajustados a uma altura adequada. Comece entrando sob a barra e apoiando-a na parte de trás dos ombros, não sobre o trapézio. Junte as escápulas e gire os cotovelos para a frente, tentando envergar a barra sobre os ombros.\nRetire a barra do rack, criando um arco firme na lombar. Mantenha a cabeça voltada para a frente. Com as costas, os ombros e o core firmes, empurre os joelhos e o bumbum para fora e comece a descida. Sente-se para trás com o quadril até estar sentado na caixa. Esta será sua posição inicial.\nMantendo a barra firme, incline-se para a frente a partir do quadril o máximo possível. Se você ajustar os pinos para o que seria a paralela, não só tem uma segurança caso falhe, como também sabe quando parar.\nFaça uma pausa logo acima dos pinos e inverta o movimento até o tronco ficar ereto.',
  'Seated Hamstring':
    'Em posição sentada com as pernas estendidas, peça ao seu parceiro que fique em pé atrás de você. Agora incline-se para a frente enquanto seu parceiro segura seus ombros com as mãos. Esta será sua posição inicial.\nTente empurrar o tronco para trás por 10-20 segundos enquanto seu parceiro impede qualquer movimento real do seu tronco.\nAgora relaxe os músculos enquanto seu parceiro aumenta o alongamento empurrando suavemente seu tronco para a frente por 10-20 segundos.',
  'Seated Hamstring and Calf Stretch':
    'Passe um cinto, uma corda ou uma faixa elástica ao redor de um pé. Sente-se com as duas pernas estendidas. Esta será sua posição inicial.\nInclinando-se levemente para a frente, puxe o cinto para levar os dedos do pé para trás. Mantenha esta posição por 10 a 20 segundos e depois repita com a outra perna.',
  'Seated Head Harness Neck Resistance':
    'Coloque um arnês de pescoço no chão na extremidade de um banco reto. Depois de selecionar as cargas, sente-se na ponta do banco reto com os pés afastados mais que a largura dos ombros. As pontas dos pés devem apontar para fora.\nMova lentamente o tronco para a frente até ficar quase paralelo ao chão. Com as duas mãos, posicione firmemente o arnês ao redor da cabeça. Dica: Certifique-se de que os pesos ainda estejam apoiados no chão para evitar qualquer tensão no pescoço. Agora segure o peso com as duas mãos enquanto eleva o tronco até ficar quase perpendicular ao chão. Nota: A cabeça e o tronco precisam estar levemente inclinados para a frente para realizar este exercício.\nAgora coloque as duas mãos sobre os joelhos. Esta é a posição inicial.\nAbaixe lentamente o pescoço até o queixo tocar a parte superior do peito enquanto inspira.\nEnquanto expira, leve o pescoço de volta à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Seated Leg Curl':
    'Ajuste a alavanca da máquina à sua altura e sente-se nela com as costas apoiadas no encosto.\nColoque a parte de trás da perna sobre a alavanca acolchoada (poucos centímetros abaixo das panturrilhas) e prenda o apoio sobre as coxas, logo acima dos joelhos. Em seguida, segure as alças laterais da máquina enquanto aponta os pés retos (ou você pode usar qualquer uma das outras duas posições) e certifique-se de que as pernas estejam totalmente retas à sua frente. Esta será sua posição inicial.\nEnquanto expira, puxe a alavanca da máquina o máximo possível em direção à parte de trás das coxas flexionando os joelhos. Mantenha o tronco imóvel o tempo todo. Mantenha a posição contraída por um segundo.\nRetorne lentamente à posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado.',
  'Seated Leg Tucks':
    'Sente-se em um banco com as pernas estendidas à sua frente, ligeiramente abaixo da paralela, e os braços segurando as laterais do banco. Seu tronco deve estar inclinado para trás em um ângulo de cerca de 45 graus em relação ao banco. Esta será sua posição inicial.\nTraga os joelhos em sua direção enquanto aproxima o tronco deles ao mesmo tempo. Expire ao realizar este movimento.\nApós uma pausa de um segundo, volte à posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado.',
  'Seated One-Arm Dumbbell Palms-Down Wrist Curl':
    'Sente-se em um banco reto com um halter na mão direita.\nApoie os pés no chão, a uma distância ligeiramente maior que a largura dos ombros.\nIncline-se para a frente e apoie o antebraço direito sobre a parte superior da coxa direita com a palma voltada para baixo. Dica: Certifique-se de que a parte de trás do punho fique sobre os joelhos. Esta será sua posição inicial.\nAbaixe o halter o máximo possível mantendo uma pegada firme nele. Inspire ao realizar este movimento.\nAgora faça a rosca com o halter o mais alto possível enquanto contrai os antebraços e expira. Mantenha a contração por um segundo antes de abaixar novamente. Dica: O único movimento deve ocorrer no punho.\nRealize o número de repetições recomendado, troque de braço e repita o movimento.',
  'Seated One-Arm Dumbbell Palms-Up Wrist Curl':
    'Sente-se em um banco reto com um halter na mão direita.\nApoie os pés no chão, a uma distância ligeiramente maior que a largura dos ombros.\nIncline-se para a frente e apoie o antebraço direito sobre a parte superior da coxa direita com a palma voltada para cima. Dica: Certifique-se de que a parte da frente do punho fique sobre os joelhos. Esta será sua posição inicial.\nAbaixe o halter o máximo possível mantendo uma pegada firme nele. Inspire ao realizar este movimento.\nAgora faça a rosca com o halter o mais alto possível enquanto contrai os antebraços e expira. Mantenha a contração por um segundo antes de abaixar novamente. Dica: O único movimento deve ocorrer no punho.\nRealize o número de repetições recomendado, troque de braço e repita o movimento.',
  'Seated One-arm Cable Pulley Rows':
    'Para chegar à posição inicial, primeiro sente-se na máquina e apoie os pés na plataforma frontal ou na barra transversal, certificando-se de que os joelhos estejam levemente flexionados e não travados.\nIncline-se para a frente mantendo o alinhamento natural das costas e segure a alça simples com o braço esquerdo usando uma pegada com a palma voltada para baixo.\nCom o braço estendido, puxe para trás até o tronco formar um ângulo de 90 graus com as pernas. As costas devem estar levemente arqueadas e o peito projetado. Você deve sentir um bom alongamento no dorsal enquanto segura a barra à sua frente. O braço direito pode ficar junto à cintura. Esta é a posição inicial do exercício.\nMantendo o tronco imóvel, puxe as alças em direção ao tronco mantendo os braços próximos a ele enquanto gira o punho, de modo que, quando a mão estiver junto aos abdominais, esteja em posição neutra (palma voltada para o tronco). Expire ao realizar esse movimento. Nesse ponto, você deve estar contraindo fortemente os músculos das costas.\nMantenha essa contração por um segundo e volte lentamente à posição original enquanto inspira. Dica: Lembre-se de girar o punho ao voltar à posição inicial para que as palmas fiquem voltadas para baixo novamente.\nRepita pelo número de repetições recomendado e depois realize o mesmo movimento com a mão direita.',
  'Seated Overhead Stretch':
    'Sente-se ereto em um colchonete.\nJunte as solas dos pés com os pés a 15-20 cm à frente do quadril.\nApoie uma mão no chão ao seu lado e a outra atrás da cabeça.\nLevante o cotovelo em direção ao teto enquanto inclina o tronco para o outro lado. Mantenha por 10 a 20 segundos e depois troque de lado.',
  'Seated Palm-Up Barbell Wrist Curl':
    'Segure uma barra com as duas mãos e as palmas voltadas para cima; mãos afastadas cerca da largura dos ombros.\nApoie os pés no chão, a uma distância ligeiramente maior que a largura dos ombros.\nIncline-se para a frente e apoie os antebraços sobre a parte superior das coxas com as palmas voltadas para cima. Dica: Certifique-se de que a parte da frente dos punhos fique sobre os joelhos. Esta será sua posição inicial.\nAbaixe a barra o máximo possível enquanto inspira e mantém uma pegada firme.\nAgora faça a rosca com a barra o mais alto possível enquanto contrai os antebraços e expira. Mantenha a contração no topo por um segundo. Dica: Apenas o punho deve se mover.',
  'Seated Palms-Down Barbell Wrist Curl':
    'Segure uma barra com as duas mãos e as palmas voltadas para baixo; mãos afastadas cerca da largura dos ombros.\nApoie os pés no chão, a uma distância ligeiramente maior que a largura dos ombros.\nIncline-se para a frente e apoie os antebraços sobre a parte superior das coxas com as palmas voltadas para baixo. Dica: Certifique-se de que a parte de trás dos punhos fique sobre os joelhos. Esta será sua posição inicial.\nAbaixe a barra o máximo possível enquanto inspira e mantém uma pegada firme.\nAgora faça a rosca com a barra o mais alto possível enquanto contrai os antebraços e expira. Mantenha a contração no topo por um segundo. Dica: Apenas o punho deve se mover.',
  'Seated Side Lateral Raise':
    'Pegue um par de halteres e sente-se na ponta de um banco reto com os pés firmes no chão. Segure os halteres com as palmas voltadas para dentro e os braços retos para baixo ao lado do corpo, estendidos. Esta será sua posição inicial.\nMantendo o tronco imóvel (sem balançar), levante os halteres para os lados com uma leve flexão dos cotovelos e as mãos levemente inclinadas para a frente, como se estivesse despejando água em um copo. Continue subindo até os braços ficarem paralelos ao chão. Expire ao executar este movimento e faça uma pausa de um segundo no topo.\nAbaixe os halteres lentamente até a posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado.',
  'Seated Triceps Press':
    'Sente-se em um banco com encosto, segure um halter com as duas mãos e mantenha-o acima da cabeça com os braços estendidos. Dica: Uma forma melhor é pedir que alguém o entregue a você, especialmente se estiver muito pesado. A carga deve ficar apoiada nas palmas das mãos com os polegares em volta dela. As palmas das mãos devem ficar voltadas para dentro. Esta será sua posição inicial.\nMantendo a parte superior dos braços próxima à cabeça (cotovelos para dentro) e perpendicular ao chão, abaixe a carga em um movimento semicircular atrás da cabeça até os antebraços tocarem os bíceps. Dica: A parte superior dos braços deve permanecer imóvel e apenas os antebraços devem se mover. Inspire ao realizar este passo.\nVolte à posição inicial usando os tríceps para levantar o halter. Expire ao realizar este passo.\nRepita pelo número de repetições recomendado.',
  'Seated Two-Arm Palms-Up Low-Pulley Wrist Curl':
    'Coloque um banco à frente de uma máquina de polia baixa que tenha uma barra ou um acessório de barra W.\nAfaste o banco o suficiente para que, ao levar a alça até a parte superior das coxas, seja criada tensão no cabo devido ao movimento da pilha de pesos.\nAgora segure a alça com as duas mãos, palmas voltadas para cima, com uma pegada na largura dos ombros.\nDê um passo para trás e sente-se no banco com os pés afastados cerca da largura dos ombros, firmes no chão.\nIncline-se para a frente e apoie os antebraços nas coxas com a parte de trás dos punhos sobre os joelhos. Esta será sua posição inicial.\nAbaixe a barra o máximo possível, enquanto inspira e mantém uma pegada firme.\nAgora faça a rosca com a barra o mais alto possível enquanto contrai os antebraços. Dica: Apenas o punho deve se mover; não os antebraços.\nApós uma contração de um segundo no topo, volte à posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado.',
  'See-Saw Press (Alternating Side Press)':
    'Pegue um halter em cada mão e fique em pé, ereto.\nLeve (levante) os halteres até a altura do peito/ombros e depois gire os punhos de modo que as palmas fiquem voltadas para você, como se estivesse se preparando para fazer um desenvolvimento Arnold. Esta será sua posição inicial.\nAgora comece a estender o braço esquerdo acima da cabeça enquanto gira o punho de modo que a palma da mão fique voltada para a frente na subida. Os cotovelos também devem se abrir ao levantar o peso. Simultaneamente, você também se inclinará a partir do quadril para o lado oposto. Dica: Se você fizer o exercício corretamente, deve parecer que está tentando alcançar algo acima, do lado direito do corpo, mas com o braço esquerdo. Expire ao realizar este movimento.\nAo chegar à posição superior, inspire. Depois, com o peso totalmente estendido acima da cabeça e o corpo inclinado para o lado direito, inicie o movimento para o lado esquerdo.\nRepita pelo número de repetições recomendado.',
  'Shotgun Row':
    'Acople uma alça simples a uma polia baixa.\nDepois de selecionar a carga correta, posicione-se a cerca de meio metro de distância com uma base ampla, com as pernas afastadas. O braço deve estar estendido e o ombro para a frente. Esta será sua posição inicial.\nRealize o movimento retraindo o ombro e flexionando o cotovelo. Ao puxar, supine o punho, girando a palma para cima ao longo do movimento.\nApós uma breve pausa, retorne à posição inicial.',
  'Shoulder Circles':
    'Com os ombros relaxados e os braços soltos ao lado do corpo (ou no colo, se estiver sentado), role suavemente os ombros para a frente, para cima, para trás e para baixo.\nInverta a direção. Você pode fazer este exercício alternando os ombros ou os dois ao mesmo tempo.',
  'Shoulder Press - With Bands':
    'Para começar, fique em pé sobre uma faixa elástica de modo que a tensão comece com os braços estendidos. Segure as alças e levante-as de modo que as mãos fiquem na altura dos ombros, uma de cada lado.\nGire os punhos de modo que as palmas das mãos fiquem voltadas para a frente. Os cotovelos devem estar flexionados, com a parte superior dos braços e os antebraços alinhados com o tronco. Esta é a sua posição inicial.\nAo expirar, levante as alças até que os braços fiquem totalmente estendidos acima da cabeça.',
  'Shoulder Raise':
    'Relaxe os braços ao lado do corpo e eleve os ombros em direção às orelhas; depois abaixe-os novamente.',
  'Shoulder Stretch':
    'Leve o braço esquerdo através do corpo e mantenha-o esticado.',
  'Side Hop-Sprint':
    'Posicione-se ao lado de um cone ou barreira.\nComece o exercício saltando lateralmente sobre o obstáculo, aproveitando o impulso da aterrissagem para saltar de volta ao ponto de partida.\nSalte o número indicado de repetições o mais rápido possível e finalize o exercício correndo uma curta distância após aterrissar o último salto.',
  'Side Lateral Raise':
    'Pegue um par de halteres e fique em pé com o tronco reto e os halteres ao lado do corpo, com os braços estendidos e as palmas das mãos voltadas para você. Esta será a sua posição inicial.\nMantendo o tronco parado (sem balançar), levante os halteres para os lados com uma leve flexão dos cotovelos e as mãos ligeiramente inclinadas para a frente, como se estivesse despejando água em um copo. Continue subindo até que os braços fiquem paralelos ao chão. Expire ao executar este movimento e faça uma pausa de um segundo no topo.\nAbaixe lentamente os halteres até a posição inicial enquanto inspira.\nRepita o número de repetições recomendado.',
  'Side Laterals to Front Raise':
    'Em pé, segure um par de halteres ao lado do corpo. Esta será a sua posição inicial.\nMantendo os cotovelos levemente flexionados, levante os pesos diretamente à sua frente até a altura dos ombros, evitando balançar o corpo ou roubar no movimento.\nNo topo do exercício, mova os pesos para fora à sua frente, mantendo os braços estendidos.\nAbaixe os pesos com um movimento controlado.\nNa repetição seguinte, levante os pesos à sua frente até a altura dos ombros antes de movê-los lateralmente para os lados do corpo.\nAbaixe os pesos até a posição inicial.',
  'Side Leg Raises':
    'Fique em pé ao lado de uma cadeira, na qual você pode se segurar como apoio. Apoie-se em uma perna. Esta será a sua posição inicial.\nMantendo a perna esticada, levante-a o mais para o lado possível e balance-a de volta para baixo, permitindo que ela cruze a frente da perna oposta.\nRepita esse movimento de balanço de 5 a 10 vezes, aumentando a amplitude de movimento à medida que avança.',
  'Side Lying Groin Stretch':
    'Comece deitando-se sobre o lado direito e dobre o joelho direito à sua frente para estabilizar o tronco.\nApoie a cabeça na mão ou no ombro direito. Levante a perna esquerda e segure-a por trás do joelho (mais fácil) ou pelo pé (mais difícil).\nPuxe o joelho esquerdo em direção ao ombro esquerdo e, ao mesmo tempo, pressione o pé ou o joelho contra o chão. Para intensificar este alongamento, estique a perna esquerda. Troque de lado.',
  'Side Neck Stretch':
    'Comece com os ombros relaxados e incline suavemente a cabeça em direção ao ombro.\nAuxilie o alongamento com uma puxada suave na lateral da cabeça.',
  'Side Standing Long Jump':
    'Comece em pé com os pés afastados na largura do quadril, em uma postura atlética. A cabeça e o peito devem estar erguidos, com os joelhos e o quadril levemente flexionados. Esta será a sua posição inicial.\nInclinando-se para a direita, estenda o quadril, os joelhos e os tornozelos para saltar no ar. Use os braços para liderar o movimento, saltando o mais longe possível para a sua direita.\nAterrisse voltado para a mesma direção, com os pés afastados na largura do quadril, absorvendo o impacto com a parte inferior do corpo.',
  'Side To Side Chins':
    'Segure a barra fixa com as palmas das mãos voltadas para a frente e pegada aberta.\nCom os dois braços estendidos à sua frente segurando a barra em pegada aberta, incline o tronco para trás cerca de 30 graus, criando uma curvatura na lombar e projetando o peito para fora. Esta é a sua posição inicial.\nPuxe o tronco para cima inclinando-se para o lado esquerdo até que a barra quase toque a parte superior do peito, levando os ombros e a parte superior dos braços para baixo e para trás. Expire ao realizar esta parte do movimento. Dica: concentre-se em contrair as costas ao chegar à posição de contração máxima. A parte superior do tronco deve permanecer estável enquanto se desloca (sem balançar) e apenas os braços devem se mover. Os antebraços não devem fazer nenhum outro trabalho além de segurar a barra.\nApós um segundo de contração, inspire enquanto retorna à posição inicial.\nAgora, puxe o tronco para cima inclinando-se para o lado direito até que a barra quase toque a parte superior do peito, levando os ombros e a parte superior dos braços para baixo e para trás. Expire ao realizar esta parte do movimento. Dica: concentre-se em contrair as costas ao chegar à posição de contração máxima. A parte superior do tronco deve permanecer estável enquanto se desloca e apenas os braços devem se mover. Os antebraços não devem fazer nenhum outro trabalho além de segurar a barra.\nApós um segundo de contração, inspire enquanto retorna à posição inicial.\nRepita os passos 3 a 6 até completar o número indicado de repetições para cada lado.',
  'Side Wrist Pull':
    'Este alongamento funciona melhor em pé. Cruze o braço esquerdo sobre a linha média do corpo e segure o punho esquerdo com a mão direita, na altura do quadril. Comece o alongamento com o braço esquerdo flexionado.\nLentamente estique, puxe e levante o braço até a altura do ombro, como mostrado na imagem. Sinta esse alongamento se originar nas costas, não nos ombros, e não puxe com muita força a articulação do ombro. Troque de lado.',
  'Side to Side Box Shuffle':
    'Posicione-se ao lado da caixa com o pé esquerdo apoiado no meio dela.\nPara começar, salte por cima para o outro lado da caixa, aterrissando com o pé direito sobre a caixa e o pé esquerdo no chão. Balance os braços para ajudar no movimento.\nContinue se deslocando de um lado para o outro sobre a caixa.',
  'Side-Lying Floor Stretch':
    'Primeiro deite-se sobre o lado esquerdo, dobrando o joelho esquerdo à sua frente para estabilizar o tronco (use também os músculos abdominais para se manter firme).\nEstique a perna direita e apoie o pé direito no chão atrás do esquerdo. Estique o braço direito acima da cabeça e puxe suavemente o punho direito para alongar todo o lado direito do corpo. Troque de lado.',
  'Single Dumbbell Raise':
    'Com os pés afastados, segure um halter com as duas mãos, agarrando a cabeça do halter em vez da haste. Os braços devem estar estendidos e pendendo na altura da cintura. Esta será a sua posição inicial.\nLevante o peso até que fique acima do nível dos ombros, mantendo os braços estendidos. O tronco e o quadril devem permanecer parados durante todo o movimento.\nRetorne à posição inicial e repita o número de repetições recomendado.',
  'Single Leg Butt Kick':
    'Comece em pé sobre uma perna, com o joelho da outra flexionado e elevado. Esta será a sua posição inicial.\nUsando um salto com contramovimento, salte para cima estendendo o quadril, o joelho e o tornozelo da perna de apoio.\nImediatamente flexione o joelho e tente tocar o glúteo com o calcanhar da perna que está saltando.\nRetorne a perna a uma posição parcialmente flexionada sob o quadril e aterrisse. A perna oposta deve permanecer praticamente na mesma posição durante todo o exercício.',
  'Single Leg Glute Bridge':
    'Deite-se no chão com os pés apoiados e os joelhos flexionados.\nLevante uma perna do chão, trazendo o joelho em direção ao peito. Esta será a sua posição inicial.\nExecute o movimento empurrando com o calcanhar, estendendo o quadril para cima e tirando os glúteos do chão.\nEstenda o máximo possível, faça uma pausa e depois retorne à posição inicial.',
  'Single Leg Push-off':
    'Fique em pé no chão com um pé apoiado sobre a caixa, com o calcanhar perto da borda.\nImpulsione-se com o pé que está sobre a caixa, tentando ganhar o máximo de altura possível ao estender o quadril e o joelho.\nAterrisse com o mesmo pé sobre a caixa, retornando o outro pé à posição inicial.',
  'Single-Arm Cable Crossover':
    'Comece movendo as polias para a posição alta, selecione a resistência a ser usada e segure uma alça em cada mão.\nDê um passo à frente, posicionando-se diante das duas polias com os braços estendidos à sua frente e as mãos juntas. A cabeça e o peito devem estar erguidos enquanto você se inclina para a frente, e os pés devem ficar escalonados. Esta será a sua posição inicial.\nMantendo o braço esquerdo no lugar, deixe o braço direito se estender para o lado, mantendo uma leve flexão no cotovelo. O braço direito deve ficar perpendicular ao corpo, aproximadamente na altura dos ombros.\nRetorne o braço à posição inicial puxando a mão de volta à linha média do corpo.\nSegure por um segundo na posição inicial e repita o movimento do lado oposto. Continue alternando de um lado para o outro pelo número de repetições indicado.',
  'Single-Arm Linear Jammer':
    'Posicione uma barra em um landmine ou ancore-a firmemente em um canto. Carregue a barra com um peso adequado.\nLevante a barra do chão, levando-a até os ombros com uma ou as duas mãos. Adote uma postura ampla. Esta será a sua posição inicial.\nRealize o movimento estendendo o cotovelo e empurrando o peso para cima. Mova-se de forma explosiva, estendendo totalmente o quadril e os joelhos para gerar a máxima força.\nRetorne à posição inicial.',
  'Single-Arm Push-Up':
    'Comece deitado de bruços no chão. Coloque-se em uma posição que apoie o seu peso nas pontas dos pés e em um braço. O braço de trabalho deve ficar diretamente sob o ombro, totalmente estendido. As pernas devem estar estendidas e, para este movimento, pode ser necessária uma base mais ampla, com os pés mais afastados do que em uma flexão de braço normal.\nMantenha uma boa postura e coloque a mão livre atrás das costas. Esta será a sua posição inicial.\nAbaixe-se permitindo que o cotovelo flexione até tocar o chão.\nDesça lentamente e inverta a direção estendendo o braço para retornar à posição inicial.',
  'Single-Cone Sprint Drill':
    'Este exercício ensina agilidade dos pés. Você precisa de um único cone. Comece em pé ao lado do cone com um braço para trás e o outro para a frente.\nMovimente os pés o mais rápido possível com passos curtos, ajudando-se com os braços. Contorne o cone, mantenha os joelhos altos e faça um trabalho de pés vigoroso.\nDescanse após três voltas ao redor do cone.',
  'Single-Leg High Box Squat':
    'Posicione uma caixa em um rack. Fixe uma faixa ou corda em um ponto acima da caixa.\nEm pé diante dela, suba na caixa até ficar totalmente em pé, deixando a outra perna sem apoio. Segure a faixa para manter o equilíbrio.\n. Continue subindo e descendo com a mesma perna antes de trocar para o lado oposto.',
  'Single-Leg Hop Progression':
    'Disponha uma fileira de cones à sua frente. Assuma uma posição relaxada em pé, equilibrado sobre uma perna. Levante o joelho da perna oposta. Esta será a sua posição inicial.\nSalte para a frente, saltando e aterrissando com a mesma perna sobre o cone.\nUse um salto com contramovimento para saltar de cone em cone.\nNo final, dê meia-volta e retorne com a outra perna.',
  'Single-Leg Lateral Hop':
    'Posicione-se ao lado de um cone ou barreira. Para assumir a posição inicial, apoie-se em uma perna com o joelho levemente flexionado.\nPara começar, execute um salto com contramovimento para saltar lateralmente sobre o cone.\nAterrisse sobre a perna que saltou e imediatamente rebata saltando de volta à posição inicial.\nContinue saltando de um lado para o outro.',
  'Single-Leg Leg Extension':
    'Sente-se na máquina e ajuste-a para ficar bem posicionado. O apoio deve ficar contra a parte inferior da canela, sem encostar no tornozelo. Ajuste o assento de modo que o ponto de pivô fique alinhado com o joelho. Selecione uma carga adequada às suas capacidades.\nMantendo uma boa postura, estenda totalmente uma perna e faça uma pausa no topo do movimento.\nRetorne à posição inicial sem deixar o peso descansar, mantendo a tensão no músculo.\nRepita o número de repetições desejado.',
  'Single-Leg Stride Jump':
    'Posicione-se ao lado de uma caixa com o pé interno sobre ela, perto da borda.\nComece balançando os braços para cima enquanto empurra com a perna que está sobre a caixa, saltando o mais alto possível. Tente impulsionar o joelho oposto para cima.\nAterrisse na mesma posição em que começou, usando a perna interna para desacelerar o impacto.',
  'Sit Squats':
    'Fique em pé com os pés afastados na largura dos ombros. Esta será a sua posição inicial.\nComece o movimento flexionando os joelhos e o quadril, sentando para trás com o quadril.\nContinue até ter agachado parcialmente, ficando acima da paralela, e inverta rapidamente o movimento até retornar à posição inicial. Repita de 5 a 10 repetições.',
  'Sit-Up':
    'Deite-se no chão colocando os pés sob algo que não se mova ou pedindo a um parceiro que os segure. As pernas devem estar flexionadas nos joelhos.\nColoque as mãos atrás da cabeça e entrelace os dedos. Esta é a posição inicial.\nEleve a parte superior do corpo de modo que forme um V imaginário com as coxas. Expire ao realizar esta parte do exercício.\nDepois de sentir a contração por um segundo, abaixe a parte superior do corpo de volta à posição inicial enquanto inspira.\nRepita o número de repetições recomendado.',
  Skating:
    'Patinar sobre rodas é uma atividade divertida que pode ser eficaz para melhorar o condicionamento cardiorrespiratório e a resistência muscular. Exige bom equilíbrio e coordenação. É necessário aprender o básico do patinar, incluindo como fazer curvas e frear, e usar equipamentos de proteção para evitar possíveis lesões.\nVocê pode patinar em um ritmo confortável por 30 minutos seguidos. Se quiser um desafio cardiovascular, faça patinação em intervalos: patine rápido por dois minutos a cada cinco, usando os três minutos restantes para se recuperar. Uma pessoa de 150 lb normalmente queima cerca de 175 calorias em 30 minutos patinando em ritmo confortável, semelhante a uma caminhada rápida.',
  'Sled Drag - Harness':
    'Para começar, carregue o trenó com o peso desejado e prenda a correia de tração. Você pode puxar com alças, usar um arnês ou prender a correia a um cinto de peso.\nSeja puxando para a frente ou para trás, incline-se na direção do deslocamento e progrida estendendo o quadril e os joelhos.',
  'Sled Overhead Backward Walk':
    'Prenda duas alças a um trenó conectado por uma corda ou corrente. Carregue o trenó com um peso leve.\nVoltado para o trenó, ande de costas até que haja alguma tensão na linha. Mantenha as mãos diretamente acima da cabeça com os cotovelos estendidos. Esta será a sua posição inicial.\nCaminhe de costas, mantendo os braços elevados acima da cabeça. Evite movimentos bruscos.',
  'Sled Overhead Triceps Extension':
    'Prenda duas alças a um trenó usando uma corrente ou corda. Carregue o trenó com uma carga adequada.\nDe costas para o trenó, afaste-se até que haja tensão na linha. Levante as mãos acima da cabeça, mantendo-as juntas, com as palmas voltadas uma para a outra. Os cotovelos devem apontar para cima e estar flexionados. Esta será a sua posição inicial.\nEstenda o cotovelo para esticar o braço. Certifique-se de que a parte superior do braço permaneça na posição para isolar o tríceps.\nAo atingir a extensão completa, dê um passo à frente para tirar a folga da linha. Você pode manter os pés escalonados para maior estabilidade.',
  'Sled Push':
    'Carregue o seu trenó de empurrar com o peso desejado.\nAdote uma postura atlética, inclinando-se contra o trenó com os braços totalmente estendidos, segurando as alças. Empurre o trenó o mais rápido possível, concentrando-se em estender o quadril e os joelhos para fortalecer a cadeia posterior.',
  'Sled Reverse Flye':
    'Prenda duas alças a um trenó conectado por uma corda ou corrente. Carregue o trenó com um peso leve.\nVoltado para o trenó, ande de costas até que haja alguma tensão na linha. Segure as duas alças com os braços estendidos, aproximadamente na altura da cintura. Flexione levemente os joelhos e mantenha o peito e a cabeça erguidos. Esta será a sua posição inicial.\nSem flexionar os cotovelos, puxe as alças para cima e para os lados, realizando uma abertura inversa com alguma rotação externa. As palmas devem ficar voltadas para a frente enquanto você faz isso.\nRetorne à posição inicial, dando alguns passos para trás para tirar a folga da linha.',
  'Sled Row':
    'Prenda duas alças a um trenó conectado por uma corda ou corrente. Carregue o trenó com um peso adequado. Voltado para o trenó, ande de costas até que haja alguma tensão na linha.\nCom uma alça em cada mão, flexione levemente os joelhos, mantenha a cabeça e o peito erguidos e comece com os braços estendidos.\nPara iniciar o movimento, flexione os cotovelos enquanto retrai as escápulas, puxando o trenó em sua direção.\nDê um ou dois passos para trás para recuperar a tensão na linha e repita.',
  'Sledgehammer Swings':
    'Você precisará de um pneu e uma marreta para este exercício. Fique em pé diante do pneu, a cerca de dois pés de distância, com uma postura escalonada. Empunhe a marreta.\nSe você é destro, a mão esquerda deve ficar na parte de baixo do cabo e a direita mais acima, próxima à cabeça da marreta.\nAo levantar a marreta, a mão direita desliza em direção à cabeça; ao descer, a mão direita deslizará para baixo para se juntar à esquerda. Golpeie o pneu com toda a sua força. Controle o rebote da marreta no pneu.\nRepita do outro lado.',
  'Smith Incline Shoulder Raise':
    'Coloque um banco inclinado sob a máquina Smith. Posicione a barra em uma altura que você alcance deitado, com os braços quase totalmente estendidos. Depois de selecionar o peso necessário, deite-se no banco inclinado e certifique-se de que os ombros estejam alinhados logo abaixo da barra.\nUsando uma pegada pronada (palmas para a frente) na largura dos ombros, retire a barra do suporte e mantenha-a esticada acima de você, com uma leve flexão dos cotovelos. Esta será a sua posição inicial.\nAo expirar, levante a barra até que os braços fiquem totalmente estendidos. Nota: a contração deve ser sentida ao redor dos ombros.\nApós uma pausa de um segundo, abaixe a barra até a posição inicial enquanto inspira.\nRepita o movimento pelo número de repetições indicado.\nAo terminar, coloque a barra de volta no suporte.',
  'Smith Machine Behind the Back Shrug':
    'Com a barra na altura das coxas, carregue um peso adequado.\nFique em pé com a barra atrás de você, segure a barra com uma pegada pronada na largura dos ombros e destrave o peso. Você deve estar em pé, ereto, com a cabeça e o peito erguidos e os braços estendidos. Esta será a sua posição inicial.\nInicie o movimento elevando os ombros diretamente para cima. Não flexione os braços nem os punhos durante o movimento.\nApós uma breve pausa, retorne o peso à posição inicial.\nRepita o número de repetições desejado antes de acionar os ganchos para travar o peso no suporte.',
  'Smith Machine Bench Press':
    'Coloque um banco reto sob a máquina Smith. Agora posicione a barra em uma altura que você alcance deitado, com os braços quase totalmente estendidos. Depois de selecionar o peso necessário, deite-se no banco reto. Usando uma pegada pronada mais aberta que a largura dos ombros, destrave a barra do suporte e mantenha-a esticada acima de você, com os braços estendidos. Esta será a sua posição inicial.\nAo inspirar, desça lentamente até sentir a barra na parte média do peito.\nApós uma pausa de um segundo, retorne a barra à posição inicial enquanto expira e empurra a barra usando os músculos do peito. Estenda os braços na posição de contração, segure por um segundo e comece a descer lentamente de novo. Dica: a descida deve levar pelo menos o dobro do tempo da subida.\nRepita o movimento pelo número de repetições indicado.\nAo terminar, trave a barra de volta no suporte.',
  'Smith Machine Bent Over Row':
    'Ajuste a barra da máquina Smith a uma altura de cerca de 2 polegadas abaixo dos joelhos.\nFlexione levemente os joelhos e incline o tronco para a frente, dobrando na cintura e mantendo as costas retas até que fiquem quase paralelas ao chão. Dica: mantenha a cabeça erguida.\nAgora segure a barra com uma pegada pronada (por cima) e destrave-a do suporte da máquina Smith. Depois deixe-a pender diretamente à sua frente, com os braços estendidos perpendiculares ao chão e ao tronco. Esta é a sua posição inicial.\nMantendo o tronco parado, levante a barra enquanto expira, com os cotovelos próximos ao corpo e sem fazer nenhuma força com o antebraço além de segurar o peso. Na posição superior de contração, contraia os músculos das costas e segure por um segundo.\nAbaixe lentamente o peso de volta à posição inicial enquanto inspira.\nRepita o número de repetições recomendado.',
  'Smith Machine Calf Raise':
    'Coloque um bloco ou anilha abaixo da barra da máquina Smith. Ajuste a barra na posição que melhor corresponda à sua altura. Depois de escolhida a altura correta e carregada a barra, suba nas anilhas com a parte da frente dos pés e coloque a barra na parte de trás dos ombros.\nSegure a barra com as duas mãos voltadas para a frente. Gire a barra para destravá-la do suporte. Esta será a sua posição inicial.\nEleve os calcanhares o mais alto possível empurrando com a parte da frente dos pés, contraindo a panturrilha no topo. Os joelhos devem permanecer estendidos. Mantenha a posição de contração por um segundo antes de começar a descer.\nRetorne lentamente à posição inicial enquanto inspira e abaixa os calcanhares.\nRepita o número de repetições recomendado.',
  'Smith Machine Close-Grip Bench Press':
    'Coloque um banco reto sob a máquina Smith. Posicione a barra em uma altura que você alcance deitado, com os braços quase totalmente estendidos. Depois de selecionar o peso necessário, deite-se no banco reto. Usando uma pegada fechada e pronada (palmas para a frente) de aproximadamente a largura dos ombros, destrave a barra do suporte e mantenha-a esticada acima de você, com os braços estendidos. Esta será a sua posição inicial.\nAo inspirar, desça lentamente até sentir a barra na parte média do peito. Dica: ao contrário do supino normal, mantenha os cotovelos próximos ao tronco o tempo todo para maximizar a participação dos tríceps.\nApós uma pausa de um segundo, retorne a barra à posição inicial enquanto expira e empurra a barra usando os tríceps. Estenda os braços na posição de contração, segure por um segundo e comece a descer lentamente de novo. Dica: a descida deve levar pelo menos o dobro do tempo da subida.\nRepita o movimento pelo número de repetições indicado.\nAo terminar, trave a barra de volta no suporte.',
  'Smith Machine Decline Press':
    'Posicione um banco declinado no rack de modo que a barra fique acima do peito. Carregue um peso adequado e posicione-se no banco.\nGire a barra para destravá-la do suporte e estenda totalmente os braços. As costas devem estar levemente arqueadas e as escápulas retraídas. Esta será a sua posição inicial.\nComece o movimento flexionando os braços e abaixando a barra até o peito.\nFaça uma breve pausa e depois estenda os braços para empurrar o peso de volta à posição inicial.\nApós completar o número de repetições desejado, gire a barra para travar o peso no suporte.',
  'Smith Machine Hang Power Clean':
    'Posicione a barra na altura dos joelhos e carregue-a com um peso adequado.\nSegure a barra com uma pegada pronada mais aberta que a largura dos ombros e destrave a barra da máquina. Os braços devem estar totalmente estendidos, com a cabeça e o peito erguidos. Os cotovelos devem apontar para fora, com os ombros para trás e para baixo. O quadril deve estar para trás, levando a tensão para os posteriores de coxa. Esta será a sua posição inicial.\nInicie o movimento estendendo com força o quadril e os joelhos, acelerando em direção à barra. Certifique-se de manter os braços esticados durante esta parte do movimento.\nAo atingir a extensão completa, flexione novamente o quadril e os joelhos para baixar a sua posição de recepção.\nNeste ponto, permita que os braços flexionem, girando os cotovelos ao redor da barra para recebê-la sobre os ombros.\nEstenda o quadril e os joelhos até ficar em pé com a barra apoiada sobre os ombros para completar o movimento.',
  'Smith Machine Hip Raise':
    'Posicione um banco no rack e carregue a barra com um peso adequado. Deite-se no banco, colocando as solas dos pés contra a barra. Destrave a barra e estenda as pernas. Pode ser necessário usar as mãos para ajudar. Para maior estabilidade, segure as laterais da máquina Smith. Esta será a sua posição inicial.\nInicie o movimento rotacionando a pelve e flexionando a coluna para elevar o quadril do banco. Mantenha uma leve flexão nos joelhos durante todo o movimento.\nApós uma breve pausa, retorne o quadril ao banco.\nRepita o número de repetições desejado.',
  'Smith Machine Incline Bench Press':
    'Coloque um banco inclinado sob a máquina Smith. Posicione a barra em uma altura que você alcance deitado, com os braços quase totalmente estendidos. Depois de selecionar o peso necessário, deite-se no banco inclinado e certifique-se de que a parte superior do peito esteja alinhada com a barra. Usando uma pegada pronada (palmas para a frente) mais aberta que a largura dos ombros, destrave a barra do suporte e mantenha-a esticada acima de você, com os braços estendidos. Esta será a sua posição inicial.\nAo inspirar, desça lentamente até sentir a barra na parte superior do peito.\nApós uma pausa de um segundo, retorne a barra à posição inicial enquanto expira e empurra a barra usando os músculos do peito. Estenda os braços na posição de contração, segure por um segundo e comece a descer lentamente de novo. Dica: a descida deve levar pelo menos o dobro do tempo da subida.\nRepita o movimento pelo número de repetições indicado.\nAo terminar, coloque a barra de volta no suporte.',
  'Smith Machine Leg Press':
    'Posicione a barra da máquina Smith a alguns pés do chão. Certifique-se de que ela esteja apoiada nas travas de segurança. Depois de carregar a barra com um peso adequado, deite-se sob a barra. Coloque a parte média dos pés na barra, levando os joelhos em direção ao peito. Esta será a sua posição inicial.\nComece o movimento empurrando com os pés para mover a barra para cima, estendendo o quadril e os joelhos. Não trave os joelhos.\nNo topo do movimento, faça uma breve pausa antes de retornar à posição inicial.',
  'Smith Machine One-Arm Upright Row':
    'Com a barra na altura das coxas, carregue um peso adequado.\nSegure a barra com uma pegada aberta e destrave o peso, retirando a outra mão da barra. O braço deve estar estendido enquanto você fica em pé, ereto, com a cabeça e o peito erguidos. Esta será a sua posição inicial.\nComece o movimento flexionando o cotovelo e elevando a parte superior do braço com o cotovelo apontando para fora. Continue até que a parte superior do braço fique paralela ao chão.\nApós uma breve pausa, retorne o peso à posição inicial.\nRepita o número de repetições desejado antes de acionar os ganchos para travar o peso no suporte.',
  'Smith Machine Overhead Shoulder Press':
    'Para começar, coloque um banco reto (ou, de preferência, um com encosto) sob uma máquina Smith. Posicione a barra em uma altura tal que, sentado no banco, os braços precisem estar quase totalmente estendidos para alcançá-la.\nDepois de obter a altura correta, sente-se ligeiramente atrás da barra, de modo que exista uma linha reta imaginária da ponta do nariz até a barra. Os pés devem permanecer parados. Segure a barra com as palmas voltadas para a frente, destrave-a e levante-a até que os braços fiquem totalmente estendidos. Esta é a posição inicial.\nComece a abaixar lentamente a barra até que fique na altura do queixo enquanto inspira.\nDepois levante a barra de volta à posição inicial usando os ombros enquanto expira.\nRepita o número de repetições recomendado.',
  'Smith Machine Pistol Squat':
    'Para começar, primeiro ajuste a barra na posição que melhor corresponda à sua altura. Entre sob ela e posicione a barra na parte de trás dos ombros.\nSegure a barra com as mãos voltadas para a frente, destrave-a e retire-a do suporte estendendo as pernas. 3\nMova um pé para a frente, cerca de 12 polegadas à frente da barra. Estenda a outra perna à sua frente, mantendo-a no ar. Olhe para a frente o tempo todo e mantenha a coluna neutra ou levemente arqueada. Esta será a sua posição inicial.\nMantendo uma boa postura, desça flexionando o joelho e o quadril, indo até onde a flexibilidade permitir.\nFaça uma breve pausa embaixo e depois retorne à posição inicial empurrando com o calcanhar, estendendo o joelho e o quadril.',
  'Smith Machine Reverse Calf Raises':
    'Ajuste a barra da máquina Smith à sua altura e alinhe uma plataforma elevada logo abaixo da barra.\nFique em pé sobre a plataforma com os calcanhares firmes sobre ela e a parte da frente dos pés para fora. Posicione os dedos dos pés voltados para a frente, com os pés afastados na largura dos ombros.\nAgora coloque os ombros sob a barra, mantendo o posicionamento dos pés descrito, e empurre a barra para cima estendendo o quadril e os joelhos até que o tronco fique ereto. Os joelhos devem ser mantidos levemente flexionados, nunca travados. Esta será a sua posição inicial. Dica: a barra nas costas serve apenas para equilíbrio.\nEleve a parte da frente dos pés ao expirar, estendendo os dedos o mais alto possível e contraindo a panturrilha. Certifique-se de manter o joelho parado o tempo todo. Não deve haver flexão em nenhum momento. Mantenha a posição de contração por um segundo antes de começar a descer.\nRetorne lentamente à posição inicial enquanto inspira, abaixando a parte da frente dos pés e os dedos.\nRepita o número de repetições recomendado.',
  'Smith Machine Squat':
    'Para começar, primeiro ajuste a barra na altura que melhor corresponda à sua altura. Depois de escolhida a altura correta e carregada a barra, entre sob a barra e apoie a parte de trás dos ombros (ligeiramente abaixo do pescoço) sobre ela.\nSegure a barra com os dois braços ao lado do corpo (palmas para a frente), destrave-a e retire-a do suporte empurrando primeiro com as pernas e, ao mesmo tempo, endireitando o tronco.\nPosicione as pernas em uma base média, na largura dos ombros, com as pontas dos pés ligeiramente para fora. Mantenha a cabeça erguida o tempo todo e também as costas retas. Esta será a sua posição inicial. (Nota: para os fins desta explicação usaremos a base média, que trabalha o desenvolvimento geral; porém, você pode escolher qualquer uma das três posições de pés descritas na seção de posições dos pés).\nComece a abaixar lentamente a barra flexionando os joelhos enquanto mantém uma postura reta com a cabeça erguida. Continue descendo até que o ângulo entre a coxa e a panturrilha fique ligeiramente menor que 90 graus (ponto em que as coxas ficam abaixo da paralela ao chão). Inspire ao realizar esta parte do movimento. Dica: se você executou o exercício corretamente, a frente dos joelhos deve formar uma linha reta imaginária com os dedos dos pés, perpendicular à frente. Se os joelhos ultrapassarem essa linha imaginária (se passarem dos dedos dos pés), você estará colocando estresse excessivo no joelho e o exercício foi executado de forma incorreta.\nComece a levantar a barra enquanto expira, empurrando o chão com o calcanhar, endireitando as pernas novamente e retornando à posição inicial.\nRepita o número de repetições recomendado.',
  'Smith Machine Stiff-Legged Deadlift':
    'Para começar, ajuste a barra do Smith a uma altura próxima ao meio das coxas. Depois de escolher a altura correta e carregar a barra, segure-a com pegada pronada (palmas para a frente) na largura dos ombros. Talvez você precise de munhequeiras se usar muito peso.\nLevante a barra estendendo completamente os braços e mantendo as costas retas. Fique em pé com o tronco reto e as pernas afastadas na largura dos ombros ou mais próximas. Os joelhos devem estar levemente flexionados. Esta é a posição inicial.\nMantendo os joelhos parados, abaixe a barra por cima dos pés flexionando o quadril e mantendo as costas retas. Continue avançando como se fosse pegar algo no chão até sentir um alongamento nos posteriores de coxa. Expire ao realizar este movimento.\nComece a levantar o tronco novamente assim que sentir o alongamento dos posteriores de coxa, estendendo o quadril e a cintura até voltar à posição inicial. Inspire ao realizar este movimento.\nRepita o número recomendado de repetições.',
  'Smith Machine Upright Row':
    'Para começar, ajuste a barra do Smith a uma altura próxima ao meio das coxas. Depois de escolher a altura correta e carregar a barra, segure-a com pegada pronada (palmas para a frente) na largura dos ombros. Talvez você precise de munhequeiras se usar muito peso.\nLevante a barra e estenda completamente os braços com as costas retas. Deve haver uma leve flexão nos cotovelos. Esta é a posição inicial.\nUse a parte lateral dos ombros para subir a barra enquanto expira. A barra deve ficar próxima ao corpo durante a subida. Continue subindo até quase tocar o queixo. Dica: os cotovelos devem conduzir o movimento. Ao subir a barra, os cotovelos devem estar sempre mais altos que os antebraços. Além disso, mantenha o tronco parado e faça uma pausa de um segundo no topo do movimento.\nAbaixe a barra lentamente de volta à posição inicial. Inspire ao realizar esta parte do movimento.\nRepita o número recomendado de repetições.',
  'Smith Single-Leg Split Squat':
    'Para começar, coloque um banco reto a 60-90 cm atrás do Smith. Em seguida, ajuste a barra na altura que melhor combine com a sua estatura. Depois de escolher a altura correta e carregar a barra, posicione-se sob ela e apoie-a na parte de trás dos ombros (um pouco abaixo do pescoço).\nSegure a barra com os dois braços, um de cada lado (palmas para a frente), destrave-a e retire-a do suporte, empurrando primeiro com as pernas e endireitando o tronco ao mesmo tempo.\nPosicione as pernas: coloque um pé um pouco à frente, sob a barra, e estenda a outra perna para trás, apoiando o peito do pé no banco. Esta será a sua posição inicial.\nComece a abaixar a barra lentamente flexionando o joelho, mantendo a postura reta e a cabeça erguida. Continue descendo até que o ângulo entre a coxa e a panturrilha fique um pouco menor que 90 graus (ponto em que as coxas ficam abaixo da paralela ao chão). Inspire ao realizar esta parte do movimento. Dica: se você fez o exercício corretamente, a frente do joelho deve formar uma linha reta imaginária com os dedos dos pés, perpendicular à frente. Se o joelho passar dessa linha imaginária (ultrapassar os dedos dos pés), você estará colocando estresse desnecessário no joelho e o exercício foi feito de forma incorreta.\nComece a subir a barra enquanto expira, empurrando o chão principalmente com o calcanhar, endireitando a perna novamente e voltando à posição inicial.\nRepita o número recomendado de repetições.\nTroque de perna e repita o movimento.',
  Snatch:
    'Posicione os pés na largura dos ombros, com a barra logo acima da junção entre os dedos e o resto do pé.\nCom pegada pronada (palmas para baixo), flexione os joelhos e, mantendo as costas retas, segure a barra com uma pegada mais larga que os ombros. Abaixe o quadril e certifique-se de que seu corpo desça como se você fosse sentar em uma cadeira. Esta será a sua posição inicial.\nComece a empurrar o chão com os pés como se fosse uma plataforma em movimento e, ao mesmo tempo, comece a levantar a barra mantendo-a próxima às pernas.\nQuando a barra chegar ao meio das coxas, empurre o chão com as pernas e eleve o corpo até a extensão completa, em um movimento explosivo.\nLeve os ombros para trás em um movimento de encolhimento enquanto sobe a barra, elevando os cotovelos para os lados e mantendo-os acima da barra pelo maior tempo possível.\nAgora, em um movimento muito rápido, porém potente, você deve colocar o corpo sob a barra quando ela atingir uma altura suficiente para ser controlada, descendo enquanto trava os braços e segura a barra acima da cabeça, na posição de agachamento.\nFinalize o movimento levantando-se da posição de agachamento para completar a execução. No final, ambos os pés devem estar alinhados e os braços totalmente estendidos, segurando a barra acima da cabeça.',
  'Snatch Balance':
    'Comece com os pés na posição de puxada, a barra apoiada na parte de trás dos ombros e as mãos em uma pegada larga de snatch.\nImpulsione a barra com uma flexão e extensão bruscas dos joelhos e entre agressivamente sob a barra, levando os pés à posição de recepção.\nReceba a barra com os braços travados acima da cabeça, perto do fundo do agachamento. O tronco deve permanecer vertical, abaixando o quadril entre as pernas.\nContinue descendo até a profundidade completa e volte à posição em pé. Abaixe o peso com cuidado.',
  'Snatch Deadlift':
    'O levantamento terra de snatch fortalece a primeira puxada do snatch. Comece com uma pegada larga de snatch, com a barra apoiada na plataforma. Os pés devem estar diretamente sob o quadril, com as pontas voltadas para fora. Agache até a barra, mantendo as costas em extensão total e a cabeça olhando para a frente.\nInicie o movimento empurrando pelos calcanhares e elevando o quadril. O ângulo das costas deve permanecer o mesmo até a barra passar dos joelhos.\nNesse ponto, leve o quadril em direção à barra enquanto se inclina para trás. Devolva a barra à plataforma invertendo o movimento.',
  'Snatch Pull':
    'Com a barra no chão, próxima às canelas, faça uma pegada larga de snatch. Abaixe o quadril com o peso nos calcanhares, costas retas, cabeça olhando para a frente, peito erguido e ombros um pouco à frente da barra. Esta será a sua posição inicial.\nComece a primeira puxada empurrando pelos calcanhares e estendendo os joelhos. O ângulo das costas deve permanecer o mesmo e os braços devem ficar retos. Mova o peso com controle até passar dos joelhos.\nEm seguida vem a segunda puxada, a principal fonte de aceleração. Quando a barra se aproximar do meio da coxa, comece a estender o quadril. Em um movimento de salto, acelere estendendo quadris, joelhos e tornozelos, usando a velocidade para subir a barra.\nNão deve ser necessário puxar ativamente com os braços para acelerar o peso; ao final da segunda puxada, o corpo deve estar totalmente estendido, levemente inclinado para trás. A extensão completa deve ser violenta e abrupta, e você deve evitar prolongá-la mais do que o necessário.',
  'Snatch Shrug':
    'Comece com uma pegada larga, com a barra pendurada na altura do meio da coxa. Você pode usar pegada em gancho ou pronada. As costas devem estar retas e levemente inclinadas para a frente.\nEncolha os ombros em direção às orelhas. Embora este exercício geralmente permita mais carga que um snatch, evite sobrecarregar a ponto de a execução ficar lenta.',
  'Snatch from Blocks':
    'Comece com uma barra carregada sobre caixas ou suportes na altura desejada. Faça uma pegada larga na barra. Os pés devem estar diretamente sob o quadril, com as pontas voltadas para fora conforme necessário. Abaixe o quadril, com o peito erguido e a cabeça olhando para a frente. Os ombros devem estar um pouco à frente da barra, com os cotovelos apontando para fora. Esta será a posição inicial.\nComece a primeira puxada empurrando pela parte da frente dos calcanhares, levantando a barra das caixas.\nPasse para a segunda puxada estendendo quadris, joelhos e tornozelos, subindo a barra o mais rápido possível. A barra deve ficar próxima ao corpo. No pico da extensão, encolha os ombros e deixe os cotovelos flexionarem para os lados.\nAo mover os pés para a posição de recepção, puxe-se com força para baixo da barra enquanto a eleva acima da cabeça. Os pés devem se mover para logo fora do quadril, com as pontas voltadas para fora conforme necessário. Receba a barra com o corpo o mais baixo possível e os braços totalmente estendidos acima da cabeça.\nMantendo a barra alinhada sobre a frente dos calcanhares, com a cabeça e o peito erguidos, empurre pelos calcanhares para ficar em pé. Devolva o peso às caixas com cuidado.',
  'Speed Band Overhead Triceps':
    'Para este exercício, ancore uma faixa elástica no chão. Nós usamos um banco inclinado e ancoramos a faixa na base, ficando em pé sobre o banco. Como alternativa, você pode fazer o exercício em pé sobre a faixa.\nPara começar, puxe a faixa para trás da cabeça, segurando-a com pegada pronada e os cotovelos para cima. Esta será a sua posição inicial.\nPara realizar o movimento, estenda os cotovelos para esticar os braços, certificando-se de manter a parte superior do braço no lugar.\nFaça uma pausa e depois volte à posição inicial.',
  'Speed Box Squat':
    'Prenda faixas elásticas na barra, ancoradas firmemente perto do chão. Talvez seja necessário encurtar as faixas para obter a tensão adequada.\nUse uma caixa de altura apropriada para este exercício. Carregue a barra com um peso que ainda exija esforço, mas que não seja tão pesado a ponto de comprometer a velocidade. Normalmente, será entre 50 e 70% da sua repetição máxima.\nPosicione a barra na parte superior das costas, com as escápulas retraídas, as costas arqueadas e o corpo todo firme da cabeça aos pés. Esta será a posição inicial.\nRetire a barra do rack e posicione-se em frente à caixa. Sente-se para trás com o quadril até ficar sentado na caixa, garantindo que você desça com controle e sem despencar sobre a superfície.\nFaça uma breve pausa e saia explosivamente da caixa, estendendo quadris e joelhos.',
  'Speed Squats':
    'Este exercício é melhor realizado dentro de um rack de agachamento, por segurança. Para começar, ajuste a barra em um suporte na altura que melhor combine com a sua estatura. Depois de escolher a altura correta e carregar a barra, posicione-se sob ela e apoie-a na parte de trás dos ombros (um pouco abaixo do pescoço).\nSegure a barra com os dois braços, um de cada lado, e retire-a do suporte empurrando primeiro com as pernas e endireitando o tronco ao mesmo tempo.\nAfaste-se do rack e posicione as pernas em uma base média, na largura dos ombros, com as pontas dos pés levemente voltadas para fora. Mantenha a cabeça erguida o tempo todo, pois olhar para baixo faz você perder o equilíbrio, e mantenha também as costas retas. Esta será a sua posição inicial. (Nota: para esta explicação usaremos a base média, que trabalha o desenvolvimento geral; porém, você pode escolher qualquer uma das três bases de pés descritas na seção de posicionamento dos pés).\nComece a abaixar a barra flexionando os joelhos, mantendo a postura reta e a cabeça erguida. Continue descendo até que o ângulo entre a coxa e as panturrilhas fique um pouco menor que 90 graus (ponto em que as coxas ficam abaixo da paralela ao chão). Inspire ao realizar esta parte do movimento. Dica: se você fez o exercício corretamente, a frente dos joelhos deve formar uma linha reta imaginária com os dedos dos pés, perpendicular à frente. Se os joelhos passarem dessa linha imaginária (ultrapassarem os dedos dos pés), você estará colocando estresse desnecessário no joelho e o exercício foi feito de forma incorreta.\nComece a subir a barra o mais rápido possível, sem usar impulso, enquanto expira, empurrando o chão principalmente com o calcanhar e endireitando as pernas novamente até voltar à posição inicial. Nota: você deve fazer estes exercícios o mais rápido possível, mas sem perder a forma perfeita e sem usar impulso.\nRepita o número recomendado de repetições.',
  'Spell Caster':
    'Segure um halter em cada mão com pegada pronada. Os pés devem estar afastados, com o quadril e os joelhos estendidos. Esta será a sua posição inicial.\nComece o movimento levando os dois halteres para um lado, próximo ao quadril, girando o tronco.\nMantendo os braços retos e os halteres paralelos ao chão, gire o tronco para balançar os pesos para o lado oposto.\nContinue alternando, girando de um lado para o outro até completar a série.',
  'Spider Crawl':
    'Comece em posição de prancha de bruços no chão. Apoie o peso nas mãos e nas pontas dos pés, com os pés juntos e o corpo reto. Os braços devem estar flexionados a 90 graus. Esta será a sua posição inicial.\nInicie o movimento levantando um pé do chão. Gire a perna para fora e leve o joelho em direção ao cotovelo, o mais à frente possível.\nVolte essa perna à posição inicial e repita com o lado oposto.',
  'Spider Curl':
    'Comece colocando a barra na parte do banco Scott onde você normalmente se sentaria. Certifique-se de alinhar bem a barra para que fique equilibrada e não caia.\nVá para a frente do banco Scott (a parte onde os braços normalmente ficam apoiados) e posicione-se deitado em uma inclinação de 45 graus, com o tronco e o abdômen encostados na parte frontal do banco.\nCertifique-se de que os pés (especialmente os dedos) estejam bem apoiados no chão e coloque a parte superior dos braços sobre o apoio localizado na parte interna do banco Scott.\nUse os braços para segurar a barra com pegada supinada (palmas para cima), com as mãos afastadas aproximadamente na largura dos ombros ou um pouco mais próximas.\nComece a levantar a barra lentamente e expire. Mantenha a posição contraída por um segundo enquanto aperta os bíceps.\nComece a trazer a barra lentamente de volta à posição inicial enquanto inspira.\nRepita o número recomendado de repetições.',
  'Spinal Stretch':
    'Sente-se em uma cadeira com as costas retas e os pés apoiados no chão.\nEntrelace os dedos atrás da cabeça, com os cotovelos para fora e o queixo para baixo.\nGire a parte superior do corpo para um lado cerca de 3 vezes, o mais longe que conseguir. Depois incline-se para a frente e gire o tronco para levar o cotovelo ao chão, pelo lado de dentro do joelho.\nVolte à posição ereta e repita para o outro lado.',
  'Split Clean':
    'Com a barra no chão, próxima às canelas, faça uma pegada pronada logo por fora das pernas. Abaixe o quadril com o peso nos calcanhares, costas retas, cabeça olhando para a frente, peito erguido e ombros um pouco à frente da barra. Esta será a sua posição inicial.\nComece a primeira puxada empurrando pelos calcanhares e estendendo os joelhos. O ângulo das costas deve permanecer o mesmo e os braços devem ficar retos. Mova o peso com controle até passar dos joelhos.\nEm seguida vem a segunda puxada, a principal fonte de aceleração do clean. Quando a barra se aproximar do meio da coxa, comece a estender o quadril. Em um movimento de salto, acelere estendendo quadris, joelhos e tornozelos, usando a velocidade para subir a barra. Não deve ser necessário puxar ativamente com os braços para acelerar o peso; ao final da segunda puxada, o corpo deve estar totalmente estendido, levemente inclinado para trás, com os braços ainda estendidos.\nAo atingir a extensão completa, passe para a terceira puxada encolhendo os ombros com força e flexionando os braços, com os cotovelos para cima e para fora. No pico da extensão, puxe-se com força para baixo, girando os cotovelos por baixo da barra.\nReceba a barra com os pés em afundo, movendo com força um pé para a frente e o outro para trás. A barra deve ficar apoiada sobre os ombros protraídos, tocando levemente a garganta, com as mãos relaxadas. Continue descendo até a posição mais baixa, o que ajudará na recuperação.\nRecupere-se imediatamente empurrando pelos calcanhares, mantendo o tronco ereto e os cotovelos para cima. Junte os pés ao ficar em pé.',
  'Split Jerk':
    'Em pé, com o peso apoiado na frente dos ombros, comece com a flexão preparatória. Com os pés diretamente sob o quadril, flexione os joelhos sem mover o quadril para trás.\nDesça apenas um pouco e inverta a direção com a maior potência possível. Empurre pelos calcanhares para gerar o máximo de velocidade e força e certifique-se de tirar a cabeça do caminho quando a barra sair dos ombros. Nesse momento, quando os pés saem do chão, eles devem ser colocados na posição de recepção o mais rápido possível.\nNo breve momento em que os pés não estão empurrando ativamente contra a plataforma, o esforço do atleta para empurrar a barra para cima os levará para baixo. Os pés devem se mover para uma base em afundo, um pé à frente e o outro atrás, com os joelhos parcialmente flexionados. Receba a barra com os braços travados acima da cabeça.\nVolte à posição em pé, juntando os pés.',
  'Split Jump':
    'Adote a posição de afundo, com um pé à frente e o joelho flexionado, e o joelho de trás quase tocando o chão.\nCertifique-se de que o joelho da frente esteja alinhado com a linha média do pé.\nEstendendo as duas pernas, salte o mais alto possível, balançando os braços para ganhar impulso.\nDurante o salto, junte os pés e leve-os de volta às posições iniciais ao aterrissar.\nAbsorva o impacto voltando à posição inicial.',
  'Split Snatch':
    'Comece com uma barra carregada no chão. A barra deve estar próxima às canelas ou tocando-as, e você deve fazer uma pegada larga na barra. Os pés devem estar diretamente sob o quadril, com as pontas voltadas para fora conforme necessário. Abaixe o quadril, com o peito erguido e a cabeça olhando para a frente. Os ombros devem estar um pouco à frente da barra. Esta será a posição inicial.\nComece a primeira puxada empurrando pela parte da frente dos calcanhares, levantando a barra do chão. O ângulo das costas deve permanecer o mesmo até a barra passar dos joelhos.\nPasse para a segunda puxada estendendo quadris, joelhos e tornozelos, subindo a barra o mais rápido possível. A barra deve ficar próxima ao corpo. No pico da extensão, encolha os ombros e deixe os cotovelos flexionarem para os lados.\nAo mover os pés para a posição de recepção, puxe-se com força para baixo da barra enquanto a eleva acima da cabeça. Os pés devem se mover com força para uma posição em afundo, um pé à frente e o outro atrás. Receba a barra com o corpo o mais baixo possível e os braços totalmente estendidos acima da cabeça.\nMantendo a barra alinhada sobre a frente dos calcanhares, com a cabeça e o peito erguidos, empurre pelos calcanhares para ficar em pé, juntando os pés.\nDevolva o peso ao chão com cuidado.',
  'Split Squat with Dumbbells':
    'Posicione-se em uma base escalonada, com o pé de trás elevado e o pé da frente à frente.\nSegure um halter em cada mão, deixando-os pendurados ao lado do corpo. Esta será a sua posição inicial.\nComece descendo, flexionando o joelho e o quadril para abaixar o corpo. Mantenha uma boa postura durante todo o movimento. Mantenha o joelho da frente alinhado com o pé enquanto realiza o exercício.\nNa parte baixa do movimento, empurre pelo calcanhar para estender o joelho e o quadril e voltar à posição inicial.',
  'Split Squats':
    'Comece em pé. Salte para uma posição com as pernas afastadas, uma perna à frente e outra atrás, flexionando os joelhos e abaixando levemente o quadril ao fazer isso.\nAo descer, inverta imediatamente a direção, ficando em pé e saltando, trocando a posição das pernas. Repita de 5 a 10 vezes com cada perna.',
  'Squat Jerk':
    'Em pé, com o peso apoiado na frente dos ombros, comece com a flexão preparatória. Com os pés diretamente sob o quadril, flexione os joelhos sem mover o quadril para trás. Desça apenas um pouco e inverta a direção com a maior potência possível. Empurre pelos calcanhares para gerar o máximo de velocidade e força e certifique-se de tirar a cabeça do caminho quando a barra sair dos ombros.\nNesse momento, quando os pés saem do chão, eles devem ser colocados na posição de recepção o mais rápido possível. No breve momento em que os pés não estão empurrando ativamente contra a plataforma, o esforço do atleta para empurrar a barra para cima os levará para baixo. Os pés devem se mover com força para logo fora do quadril, com as pontas voltadas para fora conforme necessário. Receba a barra com o corpo em um agachamento completo e os braços totalmente estendidos acima da cabeça.\nMantendo a barra alinhada sobre a frente dos calcanhares, com a cabeça e o peito erguidos, empurre pelos calcanhares para ficar em pé. Devolva o peso ao chão com cuidado.',
  'Squat with Bands':
    'Prepare as faixas elásticas nas extremidades da barra, presas aos suportes para faixas, ao rack ou a halteres, de modo que haja a tensão adequada.\nComece posicionando-se sob a barra e apoiando-a na parte de trás dos ombros. Aperte as escápulas uma contra a outra e gire os cotovelos para a frente, tentando envergar a barra sobre os ombros. Retire a barra do rack, criando um arco firme na lombar, e dê um passo para trás até a sua posição. Posicione os pés mais afastados para dar mais ênfase às costas, glúteos, adutores e posteriores de coxa. Mantenha a cabeça olhando para a frente.\nCom as costas, os ombros e o core firmes, empurre os joelhos e o bumbum para fora e comece a descida. Sente para trás com o quadril o máximo possível. Idealmente, as canelas devem ficar perpendiculares ao chão. Uma posição mais baixa da barra exige maior inclinação do tronco para mantê-la sobre os calcanhares. Continue até passar da paralela, que é definida como a dobra do quadril alinhada com o topo do joelho.\nMantendo o peso nos calcanhares e empurrando os pés e os joelhos para fora, suba conduzindo o movimento com a cabeça. Continue subindo, mantendo a firmeza da cabeça aos pés, até voltar à posição inicial.',
  'Squat with Chains':
    'Para preparar as correntes, comece passando a corrente guia sobre as extremidades da barra. A corrente pesada deve ser presa com um mosquetão. Ajuste o comprimento da corrente guia de modo que alguns elos ainda fiquem no chão no topo do movimento.\nComece posicionando-se sob a barra e apoiando-a na parte de trás dos ombros. Aperte as escápulas uma contra a outra e gire os cotovelos para a frente, tentando envergar a barra sobre os ombros. Retire a barra do rack, criando um arco firme na lombar, e dê um passo para trás até a sua posição. Posicione os pés mais afastados para dar mais ênfase às costas, glúteos, adutores e posteriores de coxa. Mantenha a cabeça olhando para a frente.\nCom as costas, os ombros e o core firmes, empurre os joelhos e o bumbum para fora e comece a descida. Sente para trás com o quadril o máximo possível. Idealmente, as canelas devem ficar perpendiculares ao chão. Uma posição mais baixa da barra exige maior inclinação do tronco para mantê-la sobre os calcanhares. Continue até passar da paralela, que é definida como a dobra do quadril alinhada com o topo do joelho.\nMantendo o peso nos calcanhares e empurrando os pés e os joelhos para fora, suba conduzindo o movimento com a cabeça. Continue subindo, mantendo a firmeza da cabeça aos pés, até voltar à posição inicial.',
  'Squat with Plate Movers':
    'Para começar, ajuste a barra em um rack logo abaixo da altura dos ombros. Coloque uma anilha no chão, uns 60 cm atrás do rack. Depois de carregar a barra, posicione-se sob ela e apoie-a na parte de trás dos ombros.\nSegure a barra com as duas mãos e retire-a do suporte empurrando primeiro com as pernas e endireitando o tronco ao mesmo tempo.\nAfaste-se do rack e adote uma base larga, com as pontas dos pés levemente voltadas para fora e um pé sobre a anilha. Mantenha a cabeça erguida o tempo todo. Esta será a sua posição inicial.\nComece a abaixar a barra lentamente flexionando joelhos e quadril. Continue descendo até que o ângulo entre a coxa e as panturrilhas fique um pouco menor que 90 graus.\nSuba a barra enquanto expira, empurrando o chão com os calcanhares e estendendo quadril e joelhos.\nNo topo do movimento, dê um passo lateral, juntando os pés do outro lado da anilha.\nUsando o pé interno, empurre a anilha, deslizando-a pelo chão até o local onde você estava.\nColoque o pé interno sobre a anilha, adotando uma base larga para a próxima repetição.',
  'Squats - With Bands':
    'Para começar, certifique-se de que a faixa elástica esteja dividida de forma igual entre o lado esquerdo e o direito do corpo. Para isso, use as mãos para segurar os dois lados da faixa e coloque os dois pés no meio dela. Os pés devem estar afastados na largura dos ombros.\nAo segurar as faixas, elas devem ficar na mesma altura de cada lado. Você deve usar uma pegada pronada (palmas para a frente) e manter as alças das faixas próximas ao rosto neste exercício. Esta é a posição inicial.\nComece a flexionar lentamente os joelhos e abaixe o corpo até que as coxas fiquem paralelas ao chão, enquanto expira.\nUse o calcanhar dos pés para empurrar o corpo para cima até a posição inicial, enquanto expira.\nRepita o número recomendado de repetições.',
  Stairmaster:
    'Para começar, suba no stairmaster e selecione a opção desejada no menu. Você pode escolher uma configuração manual ou selecionar um programa. Normalmente, é possível inserir sua idade e peso para estimar a quantidade de calorias queimadas durante o exercício.\nMovimente as pernas para cima e para baixo em um ritmo constante, empurrando os pedais para baixo, mas sem chegar até o chão. Recomenda-se manter as mãos nas alças para não cair. As alças podem ser usadas para monitorar a frequência cardíaca e ajudar a manter uma intensidade adequada.\nOs stairmasters oferecem praticidade, benefícios cardiovasculares e geralmente têm menos impacto do que correr ao ar livre. Costumam ser muito mais difíceis do que outros equipamentos de cardio. Uma pessoa de 150 lb normalmente queima mais de 300 calorias em 30 minutos, em comparação com cerca de 175 calorias caminhando.',
  'Standing Alternating Dumbbell Press':
    'Fique em pé com um halter em cada mão. Leve os halteres até os ombros, com as palmas para a frente e os cotovelos apontando para fora. Esta será a sua posição inicial.\nEstenda um braço para empurrar o halter diretamente para cima, mantendo a outra mão no lugar. Não incline o corpo nem use impulso com o peso durante o movimento.\nApós uma breve pausa, devolva o peso à posição inicial.\nRepita com o lado oposto, continuando a alternar entre os braços.',
  'Standing Barbell Calf Raise':
    'Este exercício é melhor realizado dentro de um rack de agachamento, por segurança. Para começar, ajuste a barra em um suporte na altura que melhor combine com a sua estatura. Depois de escolher a altura correta e carregar a barra, posicione-se sob ela e apoie-a na parte de trás dos ombros (um pouco abaixo do pescoço).\nSegure a barra com os dois braços, um de cada lado, e retire-a do suporte empurrando primeiro com as pernas e endireitando o tronco ao mesmo tempo.\nAfaste-se do rack e posicione as pernas em uma base média, na largura dos ombros, com as pontas dos pés levemente voltadas para fora. Mantenha a cabeça erguida o tempo todo, pois olhar para baixo faz você perder o equilíbrio, e mantenha também as costas retas. Os joelhos devem ficar levemente flexionados, nunca travados. Esta será a sua posição inicial. Dica: para uma maior amplitude de movimento, você também pode apoiar a parte da frente dos pés sobre um bloco de madeira, mas tenha cuidado, pois essa opção exige mais equilíbrio e um bloco resistente.\nEleve os calcanhares enquanto expira, estendendo os tornozelos o máximo possível e contraindo as panturrilhas. Certifique-se de manter o joelho parado o tempo todo. Não deve haver flexão em nenhum momento. Mantenha a posição contraída por um segundo antes de começar a descer.\nVolte lentamente à posição inicial enquanto inspira, abaixando os calcanhares e flexionando os tornozelos até alongar as panturrilhas.\nRepita o número recomendado de repetições.',
  'Standing Barbell Press Behind Neck':
    'Este exercício é melhor realizado dentro de um rack de agachamento, para facilitar a retirada da barra. Para começar, ajuste a barra em um suporte na altura que melhor combine com a sua estatura. Depois de escolher a altura correta e carregar a barra, posicione-se sob ela e apoie-a na parte de trás dos ombros (um pouco abaixo do pescoço).\nSegure a barra com os dois braços, um de cada lado, e retire-a do suporte empurrando primeiro com as pernas e endireitando o tronco ao mesmo tempo.\nAfaste-se do rack e posicione as pernas em uma base média, na largura dos ombros, com as pontas dos pés levemente voltadas para fora. Você deve manter as costas retas durante este exercício. Esta será a sua posição inicial.\nEleve a barra acima da cabeça estendendo completamente os braços enquanto expira.\nMantenha a contração por um segundo e abaixe a barra de volta à posição inicial enquanto inspira.\nRepita o número recomendado de repetições.',
  'Standing Bent-Over One-Arm Dumbbell Triceps Extension':
    'Com um halter em uma mão e a palma voltada para o tronco, flexione levemente os joelhos e incline o tronco para a frente, flexionando o quadril e mantendo as costas retas, até ficar quase paralelo ao chão. Certifique-se de manter a cabeça erguida.\nA parte superior do braço deve ficar próxima ao tronco e paralela ao chão, enquanto o antebraço aponta para o chão e a mão segura o peso. Dica: deve haver um ângulo de 90 graus entre o antebraço e a parte superior do braço. Esta é a sua posição inicial.\nMantendo a parte superior do braço parada, use o tríceps para levantar o peso enquanto expira, até que o antebraço fique paralelo ao chão e o braço todo esteja estendido. Como em muitos outros exercícios de braço, apenas o antebraço se move.\nApós uma contração de um segundo no topo, abaixe lentamente o halter de volta à posição inicial enquanto inspira.\nRepita o movimento pelo número prescrito de repetições.\nTroque de braço e repita o exercício.',
  'Standing Bent-Over Two-Arm Dumbbell Triceps Extension':
    'Com um halter em cada mão e as palmas voltadas para o tronco, flexione levemente os joelhos e incline o tronco para a frente, flexionando o quadril e mantendo as costas retas, até ficar quase paralelo ao chão. Certifique-se de manter a cabeça erguida. A parte superior dos braços deve ficar próxima ao tronco e paralela ao chão, enquanto os antebraços apontam para o chão e as mãos seguram os pesos. Dica: deve haver um ângulo de 90 graus entre os antebraços e a parte superior dos braços. Esta é a sua posição inicial.\nMantendo a parte superior dos braços parada, use o tríceps para levantar os pesos enquanto expira, até que os antebraços fiquem paralelos ao chão e os braços estejam totalmente estendidos. Como em muitos outros exercícios de braço, apenas o antebraço se move.\nApós uma contração de um segundo no topo, abaixe lentamente os halteres de volta à posição inicial enquanto inspira.\nRepita o movimento pelo número prescrito de repetições.',
  'Standing Biceps Cable Curl':
    'Fique em pé com o tronco ereto, segurando uma barra de rosca conectada a uma polia baixa. Segure a barra na largura dos ombros e mantenha os cotovelos próximos ao tronco. As palmas das mãos devem estar voltadas para cima (pegada supinada). Esta será a sua posição inicial.\nMantendo a parte superior dos braços parada, flexione os cotovelos para subir o peso, contraindo os bíceps enquanto expira. Apenas os antebraços devem se mover. Continue o movimento até que os bíceps estejam totalmente contraídos e a barra esteja na altura dos ombros. Mantenha a posição contraída por um segundo enquanto aperta o músculo.\nComece a trazer lentamente a barra de volta à posição inicial enquanto inspira.\nRepita o número recomendado de repetições.',
  'Standing Biceps Stretch':
    'Entrelace as mãos atrás das costas com as palmas juntas, estique os braços e depois gire-os para que as palmas fiquem voltadas para baixo.\nLevante os braços e mantenha a posição até sentir um alongamento nos bíceps.',
  'Standing Bradford Press':
    'Coloque uma barra carregada na altura dos ombros em um rack. Com pegada pronada na largura dos ombros, comece com a barra apoiada na frente dos ombros. Esta é a sua posição inicial.\nInicie o levantamento estendendo os cotovelos para empurrar a barra acima da cabeça. Evite travar os cotovelos enquanto leva o peso para trás da cabeça.\nAbaixe a barra até a parte de trás da cabeça, até que o cotovelo forme um ângulo reto.\nLevante a barra de volta acima da cabeça estendendo os cotovelos.\nAbaixe a barra até a posição inicial.\nAlterne dessa maneira até completar o número recomendado de repetições.',
  'Standing Cable Chest Press':
    'Posicione as duas polias na altura do peito e selecione uma carga adequada. Fique em pé a cerca de 30-60 cm à frente dos cabos, segurando um em cada mão. Você pode escalonar a base para maior estabilidade.\nPosicione a parte superior do braço em um ângulo de 90 graus, com as escápulas unidas. Esta será a sua posição inicial.\nMantendo o resto do corpo parado, estenda os cotovelos para empurrar as alças para a frente, juntando-as à sua frente.\nFaça uma pausa no topo do movimento e volte à posição inicial.',
  'Standing Cable Lift':
    'Conecte uma alça padrão a uma torre e leve o cabo para a posição de polia mais baixa.\nCom o lado do corpo voltado para o cabo, segure a alça com uma mão e afaste-se da torre. Você deve ficar aproximadamente à distância de um braço da polia, com a tensão do peso no cabo. O braço estendido deve ficar alinhado com o cabo.\nCom os pés afastados na largura dos ombros, agache e segure a alça com as duas mãos. Os braços devem continuar totalmente estendidos.\nEm um único movimento, puxe a alça para cima e através do corpo até que os braços fiquem totalmente estendidos acima da cabeça.\nMantenha as costas retas e os braços próximos ao corpo enquanto gira o pé de trás e estende as pernas para obter a amplitude de movimento completa.\nRetraia os braços e depois o corpo. Volte à posição neutra de forma lenta e controlada.\nRepita até a falha.\nDepois, reposicione-se e repita a mesma sequência de movimentos do lado oposto.',
  'Standing Cable Wood Chop':
    'Conecte uma alça padrão a uma torre e leve o cabo para a posição de polia mais alta.\nCom o lado do corpo voltado para o cabo, segure a alça com uma mão e afaste-se da torre. Você deve ficar aproximadamente à distância de um braço da polia, com a tensão do peso no cabo. O braço estendido deve ficar alinhado com o cabo.\nCom os pés afastados na largura dos ombros, estenda a outra mão para cima e segure a alça com as duas mãos. Os braços devem continuar totalmente estendidos.\nEm um único movimento, puxe a alça para baixo e através do corpo até o joelho da frente, girando o tronco.\nMantenha as costas e os braços retos e o core firme enquanto gira o pé de trás e flexiona os joelhos para obter a amplitude de movimento completa.\nMantenha a base e os braços retos. Volte à posição neutra de forma lenta e controlada.\nRepita até a falha.\nDepois, reposicione-se e repita a mesma sequência de movimentos do lado oposto.',
  'Standing Calf Raises':
    'Ajuste a alavanca acolchoada da máquina de panturrilha à sua altura.\nColoque os ombros sob as almofadas e posicione as pontas dos pés para a frente (ou use qualquer uma das outras duas posições descritas no início do capítulo). A parte da frente dos pés deve ficar apoiada no bloco, com os calcanhares para fora. Empurre a alavanca para cima estendendo quadril e joelhos até que o tronco fique ereto. Os joelhos devem ficar levemente flexionados, nunca travados. As pontas dos pés devem apontar para a frente, para fora ou para dentro, conforme descrito no início do capítulo. Esta será a sua posição inicial.\nEleve os calcanhares enquanto expira, estendendo os tornozelos o máximo possível e contraindo as panturrilhas. Certifique-se de manter o joelho parado o tempo todo. Não deve haver flexão em nenhum momento. Mantenha a posição contraída por um segundo antes de começar a descer.\nVolte lentamente à posição inicial enquanto inspira, abaixando os calcanhares e flexionando os tornozelos até alongar as panturrilhas.\nRepita o número recomendado de repetições.',
  'Standing Concentration Curl':
    'Pegue um halter com a mão que vai trabalhar e incline-se para a frente. Deixe o braço que trabalha pendurado perpendicular ao chão, com o cotovelo apontando para fora. Esta será a sua posição inicial.\nFlexione o cotovelo para subir o peso, mantendo a parte superior do braço parada. No topo da repetição, contraia o bíceps e faça uma pausa.\nAbaixe o halter de volta à posição inicial.\nRepita o movimento pelo número prescrito de repetições.',
  'Standing Dumbbell Calf Raise':
    'Fique em pé com o tronco ereto, segurando dois halteres nas mãos, ao lado do corpo. Apoie a parte da frente do pé em uma tábua de madeira firme e estável (de cerca de 5-7 cm de altura), com os calcanhares para fora, tocando o chão. Esta será a sua posição inicial.\nCom as pontas dos pés apontando para a frente (para trabalhar todas as partes por igual), para dentro (para dar ênfase à cabeça lateral) ou para fora (para dar ênfase à cabeça medial), eleve os calcanhares do chão enquanto expira, contraindo as panturrilhas. Mantenha a contração no topo por um segundo.\nAo inspirar, volte à posição inicial abaixando lentamente os calcanhares.\nRepita o número recomendado de vezes.',
  'Standing Dumbbell Press':
    'Em pé, com os pés afastados na largura dos ombros, pegue um halter em cada mão. Leve os halteres até a altura da cabeça, com os cotovelos para fora e a cerca de 90 graus. Esta será a sua posição inicial.\nMantendo uma técnica estrita, sem impulso das pernas nem inclinar o corpo para trás, estenda os cotovelos para levantar os pesos juntos diretamente acima da cabeça.\nFaça uma pausa e devolva lentamente o peso à posição inicial.',
  'Standing Dumbbell Reverse Curl':
    'Para começar, fique em pé com a postura reta, com um halter em cada mão usando pegada pronada (palmas para baixo). Os braços devem estar totalmente estendidos e os pés afastados na largura dos ombros. Esta é a posição inicial.\nMantendo a parte superior dos braços parada, flexione os cotovelos para subir os pesos, contraindo os bíceps enquanto expira. Apenas os antebraços devem se mover. Continue o movimento até que os bíceps estejam totalmente contraídos e os halteres estejam na altura dos ombros. Mantenha a posição contraída por um segundo enquanto aperta o músculo.\nComece a trazer lentamente os halteres de volta à posição inicial enquanto inspira.\nRepita o número recomendado de repetições.',
  'Standing Dumbbell Straight-Arm Front Delt Raise Above Head':
    'Segure os halteres à frente das coxas, com as palmas voltadas para elas.\nMantenha os braços retos, com uma leve flexão nos cotovelos, sem travá-los. Esta será a sua posição inicial.\nLevante os halteres em um movimento semicircular até a extensão total dos braços acima da cabeça enquanto expira.\nVolte lentamente à posição inicial pelo mesmo trajeto enquanto inspira.\nRepita o número recomendado de repetições.',
  'Standing Dumbbell Triceps Extension':
    'Para começar, fique em pé segurando um halter com as duas mãos. Os pés devem estar afastados na largura dos ombros. Use lentamente as duas mãos para segurar o halter e levantá-lo acima da cabeça até que os dois braços estejam totalmente estendidos.\nA resistência deve ficar apoiada nas palmas das mãos, com os polegares ao redor. As palmas das mãos devem estar voltadas para o teto. Esta será a sua posição inicial.\nMantendo a parte superior dos braços próxima à cabeça, com os cotovelos para dentro e perpendiculares ao chão, abaixe a resistência em um movimento semicircular atrás da cabeça até que os antebraços toquem os bíceps. Dica: a parte superior dos braços deve permanecer parada e apenas os antebraços devem se mover. Inspire ao realizar esta etapa.\nVolte à posição inicial usando o tríceps para levantar o halter. Expire ao realizar esta etapa.\nRepita o número recomendado de repetições.',
  'Standing Dumbbell Upright Row':
    'Segure um halter em cada mão com pegada pronada (palmas para a frente) um pouco mais estreita que a largura dos ombros. Os halteres devem ficar apoiados sobre a parte superior das coxas. Os braços devem estar estendidos, com uma leve flexão nos cotovelos, e as costas devem estar retas. Esta será a sua posição inicial.\nUse a parte lateral dos ombros para subir os halteres enquanto expira. Os halteres devem ficar próximos ao corpo durante a subida e os cotovelos devem conduzir o movimento. Continue subindo até que quase toquem o queixo. Dica: os cotovelos devem conduzir o movimento. Ao subir os halteres, os cotovelos devem estar sempre mais altos que os antebraços. Além disso, mantenha o tronco parado e faça uma pausa de um segundo no topo do movimento.\nAbaixe os halteres lentamente de volta à posição inicial. Inspire ao realizar esta parte do movimento.\nRepita o número recomendado de repetições.',
  'Standing Elevated Quad Stretch':
    'Comece em pé, de costas para um banco ou degrau, a cerca de 60-90 cm de distância.\nLevante uma perna para trás e apoie o pé no degrau, seja no peito do pé ou na parte da frente do pé, o que for mais confortável para você.\nMantenha o joelho de apoio levemente flexionado e evite que esse joelho passe da ponta dos pés. Troque de lado.',
  'Standing Front Barbell Raise Over Head':
    'Para começar, fique em pé com a postura reta, segurando uma barra nas mãos. Segure a barra com as palmas para baixo e uma pegada mais estreita que a largura dos ombros.\nOs pés devem estar afastados na largura dos ombros. Os cotovelos devem estar levemente flexionados. Esta é a posição inicial.\nLevante a barra até que fique diretamente acima da cabeça enquanto expira. Certifique-se de manter os cotovelos levemente flexionados em cada repetição.\nQuando sentir a contração, comece a abaixar a barra de volta à posição inicial enquanto inspira.\nRepita o número recomendado de repetições.',
  'Standing Gastrocnemius Calf Stretch':
    'Coloque o calcanhar direito em um degrau, com o joelho estendido, e incline-se para a frente para segurar os dedos do pé direito com a mão direita. O joelho esquerdo deve estar levemente flexionado e as costas retas.\nApoie o peso na perna esquerda e coloque a mão esquerda sobre a coxa esquerda.\nPuxe os dedos do pé direito em direção ao joelho até sentir um alongamento na panturrilha.',
  'Standing Hamstring and Calf Stretch':
    'Comece passando um cinto, faixa ou corda ao redor de um pé. Em pé, coloque esse pé à frente.\nFlexione a perna de trás, mantendo a da frente esticada. Agora levante os dedos do pé da frente do chão e incline-se para a frente.\nUsando o cinto, puxe a parte de cima do pé para aumentar o alongamento na panturrilha. Mantenha por 10 a 20 segundos e repita com o outro pé.',
  'Standing Hip Circles':
    'Comece em pé sobre uma perna, segurando-se em um apoio vertical.\nEleve o joelho que não está apoiado a 90 graus. Esta será a sua posição inicial.\nAbra o quadril o máximo possível, tentando fazer um grande círculo com o joelho.\nRealize este movimento lentamente por algumas repetições e repita do outro lado.',
  'Standing Hip Flexors':
    'Fique em pé, ereto, com a coluna vertical e o pé esquerdo levemente à frente do direito.\nFlexione os dois joelhos e levante o calcanhar de trás do chão enquanto empurra o quadril direito para a frente. Nesta posição, porém, você não consegue um alongamento profundo e completo, porque é difícil relaxar o flexor do quadril e apoiar-se nele ao mesmo tempo. Troque de lado.',
  'Standing Inner-Biceps Curl':
    'Fique em pé com um halter em cada mão, seguros com os braços estendidos. Os cotovelos devem ficar próximos ao tronco. As pernas devem estar afastadas na largura dos ombros.\nGire as palmas das mãos para que fiquem voltadas para dentro, em posição neutra. Esta será a sua posição inicial.\nMantendo a parte superior dos braços parada, suba os pesos para fora, contraindo os bíceps enquanto expira. O punho deve girar de modo que, quando os pesos estiverem totalmente elevados, você fique com pegada supinada (palmas para cima).\nApenas os antebraços devem se mover. Continue o movimento até que os bíceps estejam totalmente contraídos e os halteres estejam na altura dos ombros. Dica: mantenha os antebraços alinhados com os deltoides laterais.\nMantenha a posição contraída por um segundo enquanto aperta os bíceps.\nComece a trazer lentamente os halteres de volta à posição inicial enquanto inspira. Lembre-se de girar os punhos ao abaixar o peso para voltar à pegada neutra.\nRepita o número recomendado de repetições.',
  'Standing Lateral Stretch':
    'Adote uma base um pouco mais larga que a distância do quadril, com os joelhos levemente flexionados.\nColoque a mão direita no quadril direito para apoiar a coluna.\nLevante o braço esquerdo em linha vertical e coloque a mão esquerda atrás da cabeça. Mantenha-a ali enquanto inclina o tronco para a direita.\nMantenha o peso distribuído de forma uniforme entre as duas pernas (não se apoie no quadril esquerdo). Troque de lado.',
  'Standing Leg Curl':
    'Ajuste a alavanca da máquina à sua altura e posicione-se com o tronco inclinado para a frente a partir da cintura, cerca de 30-45 graus (pois uma posição inclinada favorece mais o recrutamento dos posteriores de coxa), com o apoio da alavanca na parte de trás da perna direita (poucos centímetros abaixo das panturrilhas) e a parte da frente da perna direita sobre o apoio da máquina.\nMantendo o tronco inclinado para a frente, certifique-se de que a perna esteja totalmente estendida e segure as alças laterais da máquina. Mantenha as pontas dos pés retas. Esta será sua posição inicial.\nAo expirar, flexione a perna direita para cima o máximo possível sem tirar a parte superior da perna do apoio. Ao chegar à posição de contração total, segure por um segundo.\nAo inspirar, leve as pernas de volta à posição inicial. Repita o número recomendado de repetições.\nAgora faça o mesmo exercício com a perna esquerda.',
  'Standing Long Jump':
    'Este exercício é melhor feito na areia ou em outra superfície macia de aterrissagem. Certifique-se de conseguir medir a distância. Fique em pé em um meio agachamento com os pés na largura dos ombros.\nUsando um grande balanço dos braços e um contramovimento das pernas, salte para a frente o mais longe que puder.\nTente aterrissar com os pés estendidos à sua frente, alcançando o mais longe possível com as pernas.\nMeça a distância do ponto de aterrissagem até o ponto de partida e registre os resultados.',
  'Standing Low-Pulley Deltoid Raise':
    'Comece em pé ao lado direito de uma polia baixa. Com a mão esquerda, cruze o corpo e segure um puxador simples preso à polia baixa com pegada pronada (palmas para baixo). Deixe o braço descansando à sua frente. Sua mão direita deve segurar a máquina para ter melhor apoio e equilíbrio.\nMantenha as costas eretas e os pés afastados na largura dos ombros. Esta é a posição inicial.\nComece a mover a mão esquerda cruzando o corpo para fora até elevá-la à altura do ombro enquanto expira.\nSinta a contração no topo por um segundo e comece a baixar lentamente o puxador até a posição inicial enquanto inspira.\nRepita o número recomendado de repetições.\nTroque de braço e repita o exercício.',
  'Standing Low-Pulley One-Arm Triceps Extension':
    'Segure um puxador simples com o braço esquerdo ao lado da máquina de polia baixa. Vire-se de costas para a máquina mantendo o puxador ao lado do corpo com o braço totalmente estendido. Agora use as duas mãos para elevar o puxador diretamente acima da cabeça, com a palma voltada para a frente. Mantenha a parte superior do braço completamente vertical (perpendicular ao chão) e coloque a mão direita sobre o cotovelo esquerdo para ajudar a mantê-lo estável. Esta é a posição inicial.\nMantendo os braços próximos à cabeça (cotovelos para dentro) e perpendiculares ao chão, abaixe a resistência em um movimento semicircular atrás da cabeça até que os antebraços toquem os bíceps. Dica: a parte superior dos braços deve permanecer parada e somente os antebraços devem se mover. Inspire enquanto realiza este passo.\nVolte à posição inicial usando os tríceps para levantar o puxador. Expire enquanto realiza este passo.\nRepita o número recomendado de repetições.\nTroque de braço e repita o exercício.',
  'Standing Military Press':
    'Comece colocando uma barra mais ou menos na altura do peito em um rack de agachamento. Depois de selecionar o peso, segure a barra com pegada pronada (palmas para a frente). Certifique-se de segurar a barra mais afastada do que a largura dos ombros.\nFlexione levemente os joelhos e apoie a barra sobre a clavícula. Levante a barra mantendo-a apoiada no peito. Dê um passo para trás e posicione os pés afastados na largura dos ombros.\nDepois de pegar a barra com a pegada correta, levante-a acima da cabeça estendendo os braços. Mantenha-a mais ou menos na altura dos ombros e levemente à frente da cabeça. Esta é sua posição inicial.\nAbaixe a barra lentamente até a clavícula enquanto inspira.\nLevante a barra de volta à posição inicial enquanto expira.\nRepita o número recomendado de repetições.',
  'Standing Olympic Plate Hand Squeeze':
    'Para começar, fique em pé com as costas retas segurando um anilha pela borda com o braço estendido em cada mão, com pegada neutra (palmas voltadas para dentro). Seus pés devem estar afastados na largura dos ombros. Esta será sua posição inicial.\nAbaixe as anilhas até que os dedos estejam quase estendidos, mas ainda consigam segurar o peso. Inspire enquanto abaixa as anilhas.\nAgora levante as anilhas de volta à posição inicial enquanto expira, fechando as mãos.\nRepita o número recomendado de repetições indicado no seu programa.',
  'Standing One-Arm Cable Curl':
    'Comece segurando um puxador simples ao lado da máquina de polia baixa. Certifique-se de estar longe o suficiente da máquina para que seu braço sustente o peso.\nMantenha a parte superior do braço parada, perpendicular ao chão, com o cotovelo para dentro e a palma voltada para a frente. O braço que não está trabalhando deve segurar a cintura. Isso ajudará a manter o equilíbrio.\nComece a flexionar lentamente o puxador para cima mantendo o braço parado até que o antebraço toque o bíceps, enquanto expira. Dica: somente o antebraço deve se mover.\nSegure a posição de contração enquanto aperta o bíceps e depois abaixe o puxador de volta à posição inicial enquanto inspira.\nRepita o número recomendado de repetições.\nTroque de braço ao realizar este exercício.',
  'Standing One-Arm Dumbbell Curl Over Incline Bench':
    'Fique em pé atrás do encosto de um banco inclinado, como se fosse dar apoio a alguém. Segure um halter em uma das mãos e apoie-o sobre o banco inclinado com pegada supinada (palmas para cima).\nPosicione a mão que não está trabalhando no canto ou na lateral do banco inclinado. O peito deve ficar pressionado contra a parte de cima do banco e os pés firmes no chão, em posição afastada. Esta é a posição inicial.\nMantendo a parte superior do braço parada, flexione o halter para cima contraindo o bíceps enquanto expira. Somente os antebraços devem se mover. Continue o movimento até que o bíceps esteja totalmente contraído e o halter esteja na altura do ombro. Segure a posição contraída por um segundo.\nComece a trazer lentamente o halter de volta à posição inicial enquanto inspira.\nRepita o número recomendado de repetições.\nTroque de braço ao realizar este exercício.',
  'Standing One-Arm Dumbbell Triceps Extension':
    'Para começar, fique em pé com um halter em uma das mãos. Seus pés devem estar afastados aproximadamente na largura dos ombros. Agora estenda totalmente o braço com o halter acima da cabeça. Dica: o dedo mindinho deve apontar para o teto e a palma da mão deve ficar voltada para a frente. O halter deve ficar acima da cabeça.\nEsta será sua posição inicial.\nMantendo a parte superior do braço próxima à cabeça (cotovelo para dentro) e perpendicular ao chão, abaixe a resistência em um movimento semicircular atrás da cabeça até que o antebraço toque o bíceps. Dica: a parte superior do braço deve permanecer parada e somente o antebraço deve se mover. Inspire enquanto realiza este passo.\nVolte à posição inicial usando o tríceps para levantar o halter. Expire enquanto realiza este passo.\nRepita o número recomendado de repetições.\nTroque de braço e repita o exercício.',
  'Standing Overhead Barbell Triceps Extension':
    'Para começar, fique em pé segurando uma barra reta ou uma barra W com pegada pronada (palmas para a frente) e as mãos a uma distância menor que a largura dos ombros. Seus pés devem estar afastados aproximadamente na largura dos ombros.\nAgora eleve a barra acima da cabeça até que os braços estejam totalmente estendidos. Mantenha os cotovelos para dentro. Esta será sua posição inicial.\nMantendo a parte superior dos braços próxima à cabeça e os cotovelos para dentro, perpendiculares ao chão, abaixe a resistência em um movimento semicircular atrás da cabeça até que os antebraços toquem os bíceps. Dica: a parte superior dos braços deve permanecer parada e somente os antebraços devem se mover. Inspire enquanto realiza este passo.\nVolte à posição inicial usando os tríceps para levantar a barra. Expire enquanto realiza este passo.\nRepita o número recomendado de repetições.',
  'Standing Palm-In One-Arm Dumbbell Press':
    'Comece com um halter em uma das mãos e o braço totalmente estendido para o lado, com pegada neutra. Use o outro braço para se segurar em um banco inclinado e manter o equilíbrio.\nSeus pés devem estar afastados na largura dos ombros. Agora levante lentamente o halter até formar um ângulo de 90 graus com o braço. Nota: o antebraço deve ficar perpendicular ao chão. Mantenha a pegada neutra durante todo o exercício.\nLevante lentamente o halter até que o braço esteja totalmente estendido. Esta é a posição inicial.\nEnquanto inspira, abaixe o peso até que o braço esteja novamente em um ângulo de 90 graus.\nSinta a contração por um segundo e depois levante o peso de volta em direção à posição inicial enquanto expira. Lembre-se de se segurar no banco inclinado e manter os pés posicionados para conservar o equilíbrio durante o exercício.\nRepita o número recomendado de repetições.\nTroque de braço e repita o exercício.',
  'Standing Palms-In Dumbbell Press':
    'Comece com um halter em cada mão e os braços totalmente estendidos para os lados, com pegada neutra. Seus pés devem estar afastados na largura dos ombros. Agora levante lentamente os halteres até formar um ângulo de 90 graus com os braços. Nota: os antebraços devem ficar perpendiculares ao chão. Esta é a posição inicial.\nMantenha a pegada neutra durante todo o exercício. Levante lentamente os halteres até que os braços estejam totalmente estendidos.\nEnquanto inspira, abaixe os pesos até que os braços estejam novamente em um ângulo de 90 graus.\nRepita o número recomendado de repetições.',
  'Standing Palms-Up Barbell Behind The Back Wrist Curl':
    'Comece em pé com as costas retas segurando uma barra atrás dos glúteos com os braços estendidos, com pegada pronada (as palmas ficarão voltadas para trás, afastadas dos glúteos) e as mãos afastadas na largura dos ombros.\nVocê deve olhar para a frente enquanto os pés ficam afastados na largura dos ombros. Esta é a posição inicial.\nEnquanto expira, eleve lentamente a barra flexionando os punhos em um movimento semicircular em direção ao teto. Nota: os punhos devem ser a única parte do corpo a se mover neste exercício.\nSegure a contração por um segundo e abaixe a barra de volta à posição inicial enquanto inspira.\nRepita o número recomendado de repetições.\nAo terminar, abaixe a barra até o rack ou o chão flexionando os joelhos. Dica: o mais fácil é pegá-la em um rack ou pedir que um parceiro a entregue a você.',
  'Standing Pelvic Tilt':
    'Comece com os pés afastados na largura do quadril.\nFlexione levemente os joelhos para mantê-los soltos e elásticos.\nTalvez você queira mover a pelve para a frente e para trás algumas vezes antes de segurar o cóccix para a frente neste alongamento.',
  'Standing Rope Crunch':
    'Prenda uma corda a uma polia alta e selecione um peso adequado.\nFique em pé de costas para a torre de cabos. Segure a corda com as duas mãos acima dos ombros, mantendo-a junto à parte superior do peito. Esta será sua posição inicial.\nRealize o movimento flexionando a coluna, levando o peso para baixo com o abdominal o mais longe que puder.\nSegure a contração máxima por um momento antes de voltar à posição inicial.',
  'Standing Soleus And Achilles Stretch':
    'Fique em pé com os pés afastados na largura do quadril, um pé ligeiramente à frente do outro.\nFlexione os dois joelhos, mantendo o calcanhar de trás no chão. Troque de lado.',
  'Standing Toe Touches':
    'Fique em pé com um pouco de espaço à sua frente e atrás de você.\nIncline-se a partir da cintura, mantendo as pernas retas, até conseguir relaxar e deixar a parte superior do corpo pendurada à sua frente. Deixe os braços e as mãos pendurados naturalmente. Segure por 10 a 20 segundos.',
  'Standing Towel Triceps Extension':
    'Para começar, fique em pé com os dois braços totalmente estendidos acima da cabeça segurando uma ponta de uma toalha com as duas mãos. Seus cotovelos devem estar para dentro e os braços perpendiculares ao chão com as palmas voltadas uma para a outra, enquanto os pés ficam afastados na largura dos ombros. Esta é a posição inicial.\nAgora avise seu parceiro para que ele segure a outra ponta da toalha e aplique resistência. Mantendo a parte superior dos braços próxima à cabeça (cotovelos para dentro) e perpendicular ao chão, abaixe a resistência em um movimento semicircular atrás da cabeça até que os antebraços toquem os bíceps. Dica: a parte superior dos braços deve permanecer parada e somente os antebraços devem se mover. Inspire enquanto realiza este passo.\nVolte à posição inicial usando os tríceps para levantar a toalha. Expire enquanto realiza este passo.\nRepita o número recomendado de repetições.',
  'Standing Two-Arm Overhead Throw':
    'Fique em pé com os pés afastados na largura dos ombros segurando uma bola medicinal com as duas mãos. Para começar, leve a bola para trás, atrás da cabeça, enquanto flexiona levemente os joelhos e inclina o corpo para trás.\nArremesse a bola para a frente com força explosiva, flexionando o quadril e usando o corpo todo para completar o movimento.\nA bola medicinal pode ser arremessada para um parceiro ou contra uma parede, recebendo-a quando ela quicar de volta.',
  'Star Jump':
    'Comece em uma postura relaxada com os pés afastados na largura dos ombros e os braços próximos ao corpo.\nPara iniciar o movimento, agache até a metade e salte de forma explosiva para cima o mais alto possível. Estenda todo o corpo por completo, afastando pernas e braços do corpo.\nAo aterrissar, junte novamente os membros e absorva o impacto com as pernas.',
  'Step Mill':
    'Para começar, suba na escada rolante de step (stepmill) e selecione a opção desejada no menu. Você pode escolher uma configuração manual ou selecionar um programa. Normalmente é possível inserir sua idade e peso para estimar as calorias queimadas durante o exercício. Tenha cuidado para não tropeçar ao subir os degraus. Recomenda-se manter as mãos nas alças para não cair.\nAs stepmills oferecem conveniência, benefícios cardiovasculares e geralmente têm menos impacto do que correr ao ar livre, com um gasto calórico semelhante. Costumam ser muito mais difíceis do que outros aparelhos de cardio. Uma pessoa de 150 lb normalmente queima mais de 300 calorias em 30 minutos, em comparação com cerca de 175 calorias caminhando.',
  'Step-up with Knee Raise':
    'Fique em pé de frente para uma caixa ou banco de altura adequada com os pés juntos. Esta será sua posição inicial.\nComece o movimento subindo, colocando o pé esquerdo sobre o banco. Estenda o quadril e o joelho da perna da frente para ficar em pé sobre a caixa. Enquanto estiver em pé sobre a caixa com a perna esquerda, flexione o joelho e o quadril direitos, levando o joelho o mais alto que puder.\nInverta esse movimento para descer da caixa e depois repita a sequência com a perna oposta.',
  'Stiff Leg Barbell Good Morning':
    'Este exercício é melhor feito dentro de um rack de agachamento, por segurança. Para começar, posicione primeiro a barra em um rack que corresponda à sua altura. Depois de escolhida a altura correta e carregada a barra, entre debaixo dela e apoie a parte de trás dos ombros (ligeiramente abaixo do pescoço) sobre ela.\nSegure a barra com os dois braços, um de cada lado, e retire-a do rack empurrando primeiro com as pernas e endireitando o tronco ao mesmo tempo.\nAfaste-se do rack e posicione as pernas em uma base média, na largura dos ombros. Mantenha a cabeça erguida o tempo todo, pois olhar para baixo faz você perder o equilíbrio, e mantenha também as costas retas. Esta será sua posição inicial.\nMantendo as pernas paradas, incline o tronco para a frente flexionando o quadril enquanto inspira. Abaixe o tronco até que fique paralelo ao chão.\nComece a levantar a barra enquanto expira, elevando o tronco de volta à posição inicial.\nRepita o número recomendado de repetições.',
  'Stiff-Legged Barbell Deadlift':
    'Segure uma barra com pegada pronada (palmas para baixo). Você pode precisar de munhequeiras se estiver usando muito peso.\nFique em pé com o tronco reto e as pernas afastadas na largura dos ombros ou mais juntas. Os joelhos devem estar levemente flexionados. Esta é sua posição inicial.\nMantendo os joelhos parados, abaixe a barra até passar da parte de cima dos pés flexionando o quadril e mantendo as costas retas. Continue avançando como se fosse pegar algo no chão até sentir um alongamento nos posteriores de coxa. Inspire enquanto realiza este movimento.\nComece a endireitar o tronco novamente estendendo o quadril até voltar à posição inicial. Expire enquanto realiza este movimento.\nRepita o número recomendado de repetições.',
  'Stiff-Legged Dumbbell Deadlift':
    'Pegue um par de halteres segurando-os ao lado do corpo com os braços estendidos.\nFique em pé com o tronco reto e as pernas afastadas na largura dos ombros ou mais juntas. Os joelhos devem estar levemente flexionados. Esta é sua posição inicial.\nMantendo os joelhos parados, abaixe os halteres até passar da parte de cima dos pés flexionando a cintura e mantendo as costas retas. Continue avançando como se fosse pegar algo no chão até sentir um alongamento nos posteriores de coxa. Expire enquanto realiza este movimento.\nComece a endireitar o tronco novamente estendendo o quadril e a cintura até voltar à posição inicial. Inspire enquanto realiza este movimento.\nRepita o número recomendado de repetições.',
  'Stomach Vacuum':
    'Para começar, fique em pé com as costas retas e os pés afastados na largura dos ombros. Coloque as mãos nos quadris. Esta é a posição inicial.\nAgora inspire lentamente todo o ar que conseguir e então comece a expirar o máximo possível enquanto puxa o abdômen para dentro o máximo que puder e segure essa posição. Tente visualizar o umbigo encostando na coluna.\nUma contração isométrica dura cerca de 20 segundos. Durante os 20 segundos, tente respirar normalmente. Depois inspire e leve o abdômen de volta à posição inicial.\nDepois de praticar este exercício, tente realizá-lo por mais de 20 segundos. Dica: você pode ir aumentando até 40-60 segundos.\nRepita o número recomendado de séries.',
  'Straight Bar Bench Mid Rows':
    'Coloque uma barra carregada na extremidade de um banco. Em pé sobre o banco, atrás da barra, segure-a com uma pegada pronada média. Mantenha o quadril para trás e o peito erguido, com a coluna neutra. Esta será sua posição inicial.\nPuxe a barra em direção ao tronco retraindo as escápulas e flexionando os cotovelos. Use um movimento controlado, sem impulso.\nApós uma breve pausa, volte lentamente com a barra à posição inicial, certificando-se de descer por completo.',
  'Straight Raises on Incline Bench':
    'Coloque uma barra no chão atrás da parte de cima de um banco inclinado.\nDeite-se de bruços no banco. Com pegada pronada, pegue a barra do chão, mantendo os braços retos. Deixe a barra pendurada para baixo. Esta será sua posição inicial.\nPara começar, eleve a barra à frente da cabeça mantendo os braços estendidos.\nVolte à posição inicial.',
  'Straight-Arm Dumbbell Pullover':
    'Coloque um halter em pé sobre um banco reto.\nCertificando-se de que o halter fique bem posicionado na parte de cima do banco, deite-se perpendicularmente ao banco (com o tronco atravessado, formando uma cruz), com apenas os ombros apoiados na superfície. O quadril deve ficar abaixo do banco e as pernas flexionadas com os pés firmes no chão. A cabeça também ficará fora do banco.\nSegure o halter com as duas mãos e mantenha-o reto acima do peito, com os braços estendidos. As duas palmas devem pressionar a parte inferior de um dos lados do halter. Esta será sua posição inicial.\nCuidado: sempre certifique-se de que o halter usado neste exercício esteja seguro. Usar um halter com anilhas soltas pode fazer com que ele se desmonte e caia no seu rosto.\nMantendo os braços retos, abaixe o peso lentamente em um arco atrás da cabeça enquanto inspira, até sentir um alongamento no peito.\nNesse ponto, traga o halter de volta à posição inicial pelo mesmo arco pelo qual o peso desceu e expire enquanto realiza este movimento.\nSegure o peso na posição inicial por um segundo e repita o movimento pelo número prescrito de repetições.',
  'Straight-Arm Pulldown':
    'Comece segurando a barra larga da polia alta de uma máquina de puxada, com pegada pronada (palmas para baixo) mais aberta que a largura dos ombros. Dê cerca de dois pés de passo para trás.\nIncline o tronco para a frente a partir da cintura cerca de 30 graus, com os braços totalmente estendidos à frente e uma leve flexão nos cotovelos. Se os braços não estiverem totalmente estendidos, você precisa dar mais um passo para trás até que fiquem. Quando os braços estiverem totalmente estendidos e o tronco levemente inclinado a partir da cintura, contraia os dorsais e você estará pronto para começar.\nMantendo os braços retos, puxe a barra para baixo contraindo os dorsais até que suas mãos fiquem ao lado das coxas. Expire enquanto realiza este passo.\nMantendo os braços retos, volte à posição inicial enquanto inspira.\nRepita o número recomendado de repetições.',
  'Stride Jump Crossover':
    'Fique em pé ao lado de uma caixa com o pé de dentro sobre ela, perto da borda.\nComece balançando os braços para cima enquanto empurra com a perna que está em cima, saltando o mais alto possível. Tente impulsionar o joelho oposto para cima.\nAterrisse na posição oposta à que começou, do outro lado da caixa. O pé que estava inicialmente sobre a caixa agora ficará no chão, e o pé oposto ficará sobre a caixa.\nRepita o movimento, cruzando de volta para o outro lado.',
  'Sumo Deadlift':
    'Comece com uma barra carregada no chão. Aproxime-se da barra de modo que ela fique sobre o meio dos pés. Os pés devem estar bem afastados, perto dos colares. Flexione o quadril para segurar a barra. Os braços devem ficar diretamente abaixo dos ombros, por dentro das pernas, e você pode usar pegada pronada, pegada mista ou pegada em gancho. Relaxe os ombros, o que na prática alonga seus braços.\nRespire fundo e então abaixe o quadril, olhando para a frente com a cabeça e o peito erguido. Empurre o chão, afastando os pés para os lados, com o peso na metade de trás dos pés. Estenda o quadril e os joelhos.\nQuando a barra passar pelos joelhos, incline-se para trás e leve o quadril em direção à barra, juntando as escápulas.\nDevolva o peso ao chão flexionando o quadril e controlando o peso na descida.',
  'Sumo Deadlift with Bands':
    'Para fazer levantamento terra com faixas curtas, basta passá-las pela barra antes de começar e pisar dentro delas para se preparar. Certifique-se de que fiquem sob a metade de trás do pé, exatamente onde você empurra o chão.\nComece com uma barra carregada no chão. Aproxime-se da barra de modo que ela fique sobre o meio dos pés. Os pés devem estar bem afastados, perto dos colares. Flexione o quadril para segurar a barra. Os braços devem ficar diretamente abaixo dos ombros, por dentro das pernas, e você pode usar pegada pronada, pegada mista ou pegada em gancho.\nRespire fundo e então abaixe o quadril, olhando para a frente com a cabeça e o peito erguido. Empurre o chão, afastando os pés para os lados, com o peso na metade de trás dos pés. Estenda o quadril e os joelhos.\nQuando a barra passar pelos joelhos, incline-se para trás e leve o quadril em direção à barra, juntando as escápulas.\nDevolva o peso ao chão flexionando o quadril e controlando o peso na descida.',
  'Sumo Deadlift with Chains':
    'Você pode prender as correntes nas pontas da barra, ou simplesmente apoiar a parte do meio sobre a barra, para que haja um aumento maior de peso à medida que você levanta. Procure manter as pontas das correntes longe das anilhas para não bater nelas ao abaixar o peso.\nComece com uma barra carregada no chão. Aproxime-se da barra de modo que ela fique sobre o meio dos pés. Os pés devem estar bem afastados, perto dos colares. Flexione o quadril para segurar a barra. Os braços devem ficar diretamente abaixo dos ombros, por dentro das pernas, e você pode usar pegada pronada, pegada mista ou pegada em gancho. Relaxe os ombros, o que na prática alonga seus braços.\nRespire fundo e então abaixe o quadril, olhando para a frente com a cabeça e o peito erguido. Empurre o chão, afastando os pés para os lados, com o peso na metade de trás dos pés. Estenda o quadril e os joelhos.\nQuando a barra passar pelos joelhos, incline-se para trás e leve o quadril em direção à barra, juntando as escápulas.\nDevolva o peso ao chão flexionando o quadril e controlando o peso na descida.',
  Superman:
    'Para começar, deite-se de bruços, esticado, no chão ou em um colchonete. Seus braços devem estar totalmente estendidos à frente. Esta é a posição inicial.\nLevante simultaneamente os braços, as pernas e o peito do chão e segure essa contração por 2 segundos. Dica: contraia a lombar para obter os melhores resultados deste exercício. Lembre-se de expirar durante este movimento. Nota: ao segurar a posição contraída, você deve se parecer com o Superman voando.\nComece a abaixar lentamente os braços, as pernas e o peito de volta à posição inicial enquanto inspira.\nRepita o número recomendado de repetições indicado no seu programa.',
  'Supine Chest Throw':
    'Este exercício é ótimo para passes de peito quando você não tem um parceiro ou uma parede resistente o suficiente. Deite-se no chão de costas com os joelhos flexionados.\nComece com a bola sobre o peito, segurada com as duas mãos por baixo.\nExplode para cima, estendendo os cotovelos para arremessar a bola diretamente acima de você o mais alto possível.\nSegure a bola com as duas mãos quando ela descer.',
  'Supine One-Arm Overhead Throw':
    'Deite-se no chão de costas com os joelhos flexionados. Segure a bola com uma mão, estendendo totalmente o braço atrás da cabeça. Esta será sua posição inicial.\nInicie o movimento a partir do ombro, arremessando a bola diretamente para a frente enquanto se senta, tentando alcançar a distância máxima.\nA bola pode ser arremessada para um parceiro ou quicada contra uma parede.',
  'Supine Two-Arm Overhead Throw':
    'Deite-se no chão de costas com os joelhos flexionados.\nSegure a bola com as duas mãos, estendendo totalmente os braços atrás da cabeça. Esta será sua posição inicial.\nInicie o movimento a partir do ombro, arremessando a bola diretamente para a frente enquanto se senta, tentando alcançar a distância máxima.\nA bola pode ser arremessada para um parceiro ou quicada contra uma parede.',
  'Suspended Fallout':
    'Ajuste as tiras para que as alças fiquem em uma altura adequada, abaixo da cintura.\nComece em pé segurando as alças. Incline-se para as tiras, passando para uma posição de flexão de braço inclinada. Esta será sua posição inicial.\nMantendo os braços retos, incline-se mais para as tiras de suspensão, aproximando o corpo do chão, permitindo que os ombros se estendam e elevando os braços acima da cabeça.\nMantenha a coluna neutra e o resto do corpo reto, sendo os ombros as únicas articulações autorizadas a se mover.\nFaça uma pausa na contração máxima e depois volte à posição inicial.',
  'Suspended Push-Up':
    'Ancore as tiras de suspensão firmemente na parte de cima de um rack ou outro objeto.\nInclinando-se para as tiras, segure uma alça em cada mão e assuma a posição de prancha de flexão. Você deve ficar o mais paralelo ao chão que conseguir, com os braços totalmente estendidos, mantendo uma boa postura.\nMantendo o tronco reto e rígido, desça lentamente permitindo que os cotovelos flexionem.\nContinue até que os cotovelos passem dos 90 graus, fazendo uma pausa antes de estender para voltar à posição inicial.',
  'Suspended Reverse Crunch':
    'Fixe um conjunto de tiras de suspensão com as alças penduradas a cerca de 30 cm do chão. Posicione-se em prancha de flexão de costas para o rack.\nColoque os pés nas alças. Você deve manter uma postura reta, sem deixar o quadril cair. Esta será sua posição inicial.\nComece o movimento flexionando os joelhos e o quadril, trazendo os joelhos em direção ao tronco. Ao fazer isso, incline a pelve para a frente, permitindo que a coluna flexione.\nNo topo do movimento controlado, volte à posição inicial.',
  'Suspended Row':
    'Suspenda as tiras mais ou menos na altura do peito. Segure uma alça em cada mão e incline-se para trás. Mantenha o corpo ereto e a cabeça e o peito erguidos. Os braços devem estar totalmente estendidos. Esta será sua posição inicial.\nComece flexionando os cotovelos para iniciar o movimento. Protraia as escápulas ao fazer isso.\nAo completar o movimento, faça uma pausa e depois volte à posição inicial.',
  'Suspended Split Squat':
    'Suspenda as tiras de modo que as alças fiquem a 18-30 polegadas do chão.\nDe costas para a estrutura, coloque o pé de trás na alça atrás de você. Mantenha a cabeça olhando para a frente e o peito erguido, com o joelho levemente flexionado. Esta será sua posição inicial.\nDesça flexionando o joelho e o quadril, abaixando-se em direção ao chão. Mantenha o peso sobre o calcanhar do pé e conserve a postura durante todo o exercício.\nNa parte de baixo do movimento, inverta o movimento, estendendo o quadril e o joelho para voltar à posição inicial.',
  'Svend Press':
    'Comece em pé.\nPressione duas anilhas leves uma contra a outra com as mãos. Segure as anilhas juntas perto do peito para criar uma contração isométrica nos músculos peitorais. Seus dedos devem apontar para a frente. Esta é sua posição inicial.\nAperte as anilhas entre as palmas e estenda os braços diretamente à frente em um movimento controlado.\nFaça uma pausa no topo do movimento e depois volte lentamente à posição inicial.',
  'T-Bar Row with Handle':
    'Posicione uma barra em um landmine ou em um canto para evitar que ela se mova. Carregue um peso adequado na sua ponta.\nFique sobre a barra e posicione uma pegada de remada Double D ao redor da barra, junto ao colar. Usando o quadril e as pernas, levante-se até ficar em pé.\nAssuma uma postura ampla com o quadril para trás e o peito erguido. Seus braços devem estar estendidos. Esta será sua posição inicial.\nPuxe o peso em direção à parte superior do abdômen retraindo as escápulas e flexionando os cotovelos. Não use impulso nem faça trapaça durante o movimento.\nApós uma breve pausa, volte à posição inicial.',
  'Tate Press':
    'Deite-se em um banco reto com um halter em cada mão sobre as coxas. As palmas das mãos ficarão voltadas uma para a outra.\nUsando as coxas para ajudar a levantar os halteres, leve-os um braço de cada vez até segurá-los à sua frente na largura dos ombros. Nota: ao segurar os halteres à sua frente, certifique-se de que os braços estejam mais afastados que a largura dos ombros, com pegada pronada (palmas para a frente). Deixe os cotovelos apontarem para fora. Esta é sua posição inicial.\nMantendo a parte superior dos braços parada, mova lentamente os halteres para dentro e para baixo em um movimento semicircular até que toquem a parte superior do peito, enquanto inspira. Mantenha o controle total dos halteres o tempo todo e não mova os braços nem apoie os halteres no peito.\nAo expirar, levante os halteres usando os tríceps com o mesmo movimento semicircular, mas invertido. Tente manter os halteres juntos enquanto sobem. Trave os braços na posição contraída, segure por um segundo e comece a descer novamente, devagar. Dica: descer deve levar pelo menos o dobro do tempo que subir.\nRepita o movimento pelo número prescrito de repetições do seu programa de treino.',
  'The Straddle':
    'Comece sentado, com a coluna ereta. Comece estendendo as pernas à sua frente em forma de V.\nCom as mãos no chão, incline-se para a frente o máximo que puder. Segure por 10 a 20 segundos.',
  'Thigh Abductor':
    'Para começar, sente-se na máquina abdutora e selecione um peso com o qual se sinta confortável. Quando as pernas estiverem bem posicionadas, segure as alças de cada lado. Todo o tronco (da cintura para cima) deve permanecer parado. Esta é a posição inicial.\nPressione lentamente contra a máquina com as pernas para afastá-las uma da outra enquanto expira.\nSinta a contração por um segundo e comece a levar as pernas de volta à posição inicial enquanto inspira. Nota: lembre-se de manter a parte superior do corpo parada para evitar lesões.\nRepita o número recomendado de repetições.',
  'Thigh Adductor':
    'Para começar, sente-se na máquina adutora e selecione um peso com o qual se sinta confortável. Quando as pernas estiverem bem posicionadas nos apoios da máquina, segure as alças de cada lado. Todo o tronco (da cintura para cima) deve permanecer parado. Esta é a posição inicial.\nPressione lentamente contra a máquina com as pernas para juntá-las uma em direção à outra enquanto expira.\nSinta a contração por um segundo e comece a levar as pernas de volta à posição inicial enquanto inspira. Nota: lembre-se de manter a parte superior do corpo parada e evitar movimentos bruscos para prevenir lesões.\nRepita o número recomendado de repetições.',
  'Tire Flip':
    'Comece segurando a parte de baixo do pneu pela banda de rodagem e posicione os pés um pouco para trás. Seu peito deve empurrar contra o pneu.\nPara levantar o pneu, estenda o quadril, os joelhos e os tornozelos, empurrando contra o pneu e para cima.\nQuando o pneu chegar a um ângulo de 45 graus, dê um passo à frente e empurre um joelho contra o pneu. Ao fazer isso, ajuste a pegada para a parte de cima do pneu e empurre-o para a frente com toda a força para completar o giro. Repita conforme necessário.',
  'Toe Touchers':
    'Para começar, deite-se no chão ou em um colchonete com as costas pressionadas contra o chão. Seus braços devem ficar ao lado do corpo com as palmas voltadas para baixo.\nSuas pernas devem estar juntas. Eleve lentamente as pernas no ar até que fiquem quase perpendiculares ao chão, com uma leve flexão nos joelhos. Seus pés devem ficar paralelos ao chão.\nMova os braços para que fiquem totalmente estendidos em um ângulo de 45 graus em relação ao chão. Esta é a posição inicial.\nMantendo a lombar pressionada contra o chão, levante lentamente o tronco e use as mãos para tentar tocar os dedos dos pés. Lembre-se de expirar durante esta parte do exercício.\nComece a abaixar lentamente o tronco e os braços de volta à posição inicial enquanto inspira. Lembre-se de manter os braços retos apontando para os dedos dos pés.\nRepita o número recomendado de repetições.',
  'Torso Rotation':
    'Fique em pé com a coluna ereta segurando uma bola suíça com as duas mãos. Estenda os braços para que a bola fique reta à sua frente. Esta será sua posição inicial.\nGire o tronco para um lado, mantendo os olhos na bola enquanto se move. Agora, gire de volta para o lado oposto. Repita por 10 a 20 repetições.',
  'Trail Running/Walking':
    'Correr ou caminhar em trilhas faz o sangue circular e o coração bater quase de imediato. Certifique-se de usar bons calçados. Enquanto você usa os músculos das panturrilhas e dos glúteos para subir uma ladeira, os joelhos, as articulações e os tornozelos absorvem a maior parte do impacto na descida. Dê passos menores ao descer, mantenha os joelhos flexionados para reduzir o impacto e diminua o ritmo para evitar quedas.\nUma pessoa de 150 lb pode queimar mais de 200 calorias em 30 minutos caminhando em subida, em comparação com 175 em uma superfície plana. Se correr na trilha, uma pessoa de 150 lb pode queimar bem mais de 500 calorias em 30 minutos.',
  'Trap Bar Deadlift':
    'Para este exercício, carregue uma barra hexagonal, também conhecida como trap bar, com um peso adequado apoiada no chão. Fique em pé no centro do aparelho e segure as duas alças.\nAbaixe o quadril, olhe para a frente com a cabeça e mantenha o peito erguido.\nComece o movimento empurrando com os calcanhares e estendendo o quadril e os joelhos. Evite arredondar as costas o tempo todo.\nAo completar o movimento, abaixe o peso de volta ao chão de forma controlada.',
  'Tricep Dumbbell Kickback':
    'Comece com um halter em cada mão e as palmas voltadas para o tronco. Mantenha as costas retas com uma leve flexão nos joelhos e incline-se para a frente a partir da cintura. Seu tronco deve ficar quase paralelo ao chão. Certifique-se de manter a cabeça erguida. A parte superior dos braços deve ficar próxima ao tronco e paralela ao chão. Os antebraços devem apontar para o chão enquanto você segura os pesos. Deve se formar um ângulo de 90 graus entre o antebraço e a parte superior do braço. Esta é sua posição inicial.\nAgora, mantendo a parte superior dos braços parada, expire e use os tríceps para levantar os pesos até que o braço fique totalmente estendido. Concentre-se em mover o antebraço.\nApós uma breve pausa na contração máxima, inspire e abaixe lentamente os halteres de volta à posição inicial.\nRepita o movimento pelo número prescrito de repetições.',
  'Tricep Side Stretch':
    'Leve o braço direito através do corpo, por cima do ombro esquerdo, segurando o cotovelo com a mão esquerda, até sentir um alongamento no tríceps. Depois repita com o outro braço.',
  'Triceps Overhead Extension with Rope':
    'Prenda uma corda a uma polia baixa. Depois de selecionar uma carga adequada, segure a corda com as duas mãos e fique de costas para o cabo.\nPosicione as mãos atrás da cabeça com os cotovelos apontando para cima. Os cotovelos devem começar flexionados, e você pode escalonar a postura e se inclinar levemente para longe da máquina para ter mais estabilidade. Esta será sua posição inicial.\nPara realizar o movimento, estenda os cotovelos mantendo o braço no lugar e eleve as mãos acima da cabeça.\nContraia o tríceps no topo do movimento e abaixe lentamente a carga de volta à posição inicial.',
  'Triceps Pushdown':
    'Prenda uma barra reta ou angulada a uma polia alta e segure com pegada pronada (palmas para baixo) na largura dos ombros.\nEm pé, com o tronco reto e uma inclinação muito pequena para a frente, aproxime os braços do corpo, perpendiculares ao chão. Os antebraços devem apontar para a polia enquanto seguram a barra. Esta é sua posição inicial.\nUsando o tríceps, abaixe a barra até tocar a frente das coxas e os braços ficarem totalmente estendidos, perpendiculares ao chão. Os braços devem permanecer sempre parados junto ao tronco e somente os antebraços devem se mover. Expire enquanto realiza este movimento.\nApós um segundo de pausa na posição contraída, suba a barra lentamente até o ponto de partida. Inspire durante esta etapa.\nRepita pelo número recomendado de repetições.',
  'Triceps Pushdown - Rope Attachment':
    'Prenda uma corda a uma polia alta e segure com pegada neutra (palmas voltadas uma para a outra).\nEm pé, com o tronco reto e uma inclinação muito pequena para a frente, aproxime os braços do corpo, perpendiculares ao chão. Os antebraços devem apontar para a polia enquanto seguram a corda com as palmas voltadas uma para a outra. Esta é sua posição inicial.\nUsando o tríceps, abaixe a corda levando cada lado dela para a lateral das coxas. No final do movimento, os braços ficam totalmente estendidos e perpendiculares ao chão. Os braços devem permanecer sempre parados junto ao tronco e somente os antebraços devem se mover. Expire enquanto realiza este movimento.\nApós um segundo de pausa na posição contraída, suba a corda lentamente até o ponto de partida. Inspire durante esta etapa.\nRepita pelo número recomendado de repetições.',
  'Triceps Pushdown - V-Bar Attachment':
    'Prenda uma barra em V a uma polia alta e segure com pegada pronada (palmas para baixo) na largura dos ombros.\nEm pé, com o tronco reto e uma inclinação muito pequena para a frente, aproxime os braços do corpo, perpendiculares ao chão. Os antebraços devem apontar para a polia enquanto seguram a barra. Os polegares devem ficar mais altos que os dedos mínimos. Esta é sua posição inicial.\nUsando o tríceps, abaixe a barra até tocar a frente das coxas e os braços ficarem totalmente estendidos, perpendiculares ao chão. Os braços devem permanecer sempre parados junto ao tronco e somente os antebraços devem se mover. Expire enquanto realiza este movimento.\nApós um segundo de pausa na posição contraída, suba a barra em V lentamente até o ponto de partida. Inspire durante esta etapa.\nRepita pelo número recomendado de repetições.',
  'Triceps Stretch':
    'Leve a mão atrás da cabeça, segure o cotovelo e puxe suavemente. Mantenha por 10 a 20 segundos e depois troque de lado.',
  'Tuck Crunch':
    'Para começar, deite-se no chão ou em um colchonete com as costas pressionadas contra o chão. Os braços devem ficar ao lado do corpo com as palmas para baixo.\nCruze as pernas envolvendo um tornozelo no outro. Eleve lentamente as pernas no ar até que as coxas fiquem perpendiculares ao chão, com uma leve flexão nos joelhos. Nota: os joelhos e os dedos dos pés devem ficar paralelos ao chão, ao contrário das coxas.\nTire os braços do chão e cruze-os sobre o peito. Esta é a posição inicial.\nMantendo a lombar pressionada contra o chão, eleve lentamente o tronco. Lembre-se de expirar durante esta parte do exercício.\nComece a abaixar lentamente o tronco de volta à posição inicial enquanto inspira.\nRepita pelo número recomendado de repetições.',
  'Two-Arm Dumbbell Preacher Curl':
    'Segure um halter em cada mão e apoie a parte superior dos braços no banco Scott ou no banco inclinado. Os halteres devem ser mantidos na altura dos ombros. Esta será sua posição inicial.\nEnquanto inspira, abaixe lentamente os halteres até que a parte superior do braço fique estendida e o bíceps completamente alongado.\nEnquanto expira, use os bíceps para elevar os pesos até que os bíceps estejam totalmente contraídos e os halteres fiquem na altura dos ombros.\nContraia forte os bíceps por um segundo na posição contraída e repita pelo número recomendado de repetições.',
  'Two-Arm Kettlebell Clean':
    'Coloque dois kettlebells entre os pés. Para assumir a posição inicial, leve o quadril para trás e olhe para a frente.\nLeve os kettlebells até os ombros estendendo as pernas e o quadril enquanto os eleva em direção aos ombros. Gire os punhos ao fazer isso.\nAbaixe os kettlebells de volta à posição inicial e repita.',
  'Two-Arm Kettlebell Jerk':
    'Leve dois kettlebells até os ombros. Suba-os até os ombros estendendo as pernas e o quadril enquanto os impulsiona em direção aos ombros. Gire os punhos ao fazer isso, de modo que as palmas fiquem voltadas para a frente. Agache alguns centímetros e inverta o movimento rapidamente, empurrando os dois kettlebells acima da cabeça. Imediatamente após o impulso inicial, agache novamente e posicione-se sob os kettlebells. Quando os kettlebells estiverem com os braços travados acima, fique em pé para completar o exercício.',
  'Two-Arm Kettlebell Military Press':
    'Leve dois kettlebells até os ombros. Suba-os até os ombros estendendo as pernas e o quadril enquanto os impulsiona em direção aos ombros. Gire os punhos ao fazer isso, de modo que as palmas fiquem voltadas para a frente.\nEmpurre os kettlebells para cima e para fora. Quando os kettlebells passarem pela cabeça, incline-se para o peso de modo que fiquem apoiados atrás da cabeça. Contraia os dorsais, os glúteos e o abdômen para ter mais estabilidade.',
  'Two-Arm Kettlebell Row':
    'Coloque dois kettlebells à frente dos pés. Flexione levemente os joelhos e depois leve o quadril para trás o máximo possível enquanto se inclina para a frente para assumir a posição inicial.\nSegure os dois kettlebells e puxe-os em direção ao abdômen, retraindo as escápulas e flexionando os cotovelos. Mantenha as costas retas. Abaixe e repita.',
  'Underhand Cable Pulldowns':
    'Sente-se em uma máquina de puxada com uma barra larga presa à polia superior. Ajuste o apoio de joelhos da máquina à sua altura. Esses apoios impedem que a resistência da barra levante seu corpo.\nSegure a barra da puxada com as palmas voltadas para o tronco (pegada supinada). Certifique-se de que as mãos fiquem mais próximas que a largura dos ombros.\nCom os dois braços estendidos à frente segurando a barra na largura de pegada escolhida, incline o tronco para trás cerca de 30 graus, criando uma curvatura na lombar e projetando o peito para fora. Esta é sua posição inicial.\nEnquanto expira, puxe a barra para baixo até tocar a parte superior do peito, levando os ombros e a parte superior dos braços para baixo e para trás. Dica: concentre-se em contrair os músculos das costas ao chegar à posição de contração total e mantenha os cotovelos próximos ao corpo. A parte superior do tronco deve permanecer parada enquanto você leva a barra até você e somente os braços devem se mover. Os antebraços não devem fazer nenhum trabalho além de segurar a barra.\nApós um segundo na posição contraída, enquanto inspira, leve lentamente a barra de volta à posição inicial, quando os braços estiverem totalmente estendidos e os dorsais totalmente alongados.\nRepita este movimento pelo número prescrito de repetições.',
  'Upper Back Stretch':
    'Entrelace os dedos com os polegares para baixo e arredonde os ombros enquanto estende as mãos para a frente.',
  'Upper Back-Leg Grab':
    'Sentado, incline-se para a frente para abraçar as coxas por baixo com os dois braços.\nMantenha os joelhos juntos e as pernas estendidas enquanto leva o peito em direção aos joelhos. Você também pode alongar o meio das costas afastando as costas dos joelhos enquanto os abraça.',
  'Upright Barbell Row':
    'Segure uma barra com pegada pronada ligeiramente mais estreita que a largura dos ombros. A barra deve ficar apoiada na parte superior das coxas, com os braços estendidos e uma leve flexão nos cotovelos. As costas também devem estar retas. Esta será sua posição inicial.\nAgora expire e use a parte lateral dos ombros para elevar a barra, subindo os cotovelos para cima e para os lados. Mantenha a barra próxima ao corpo enquanto a eleva. Continue levantando até quase tocar o queixo. Dica: os cotovelos devem conduzir o movimento e devem estar sempre mais altos que os antebraços. Lembre-se de manter o tronco parado e fazer uma pausa de um segundo no topo do movimento.\nAbaixe a barra lentamente de volta à posição inicial. Inspire durante esta parte do movimento.\nRepita pelo número recomendado de repetições.',
  'Upright Cable Row':
    'Segure uma barra reta presa a uma polia baixa com pegada pronada (palmas voltadas para as coxas) ligeiramente mais estreita que a largura dos ombros. A barra deve ficar apoiada na parte superior das coxas. Os braços devem estar estendidos com uma leve flexão nos cotovelos e as costas retas. Esta será sua posição inicial.\nUse a parte lateral dos ombros para elevar a barra do cabo enquanto expira. A barra deve ficar próxima ao corpo enquanto sobe. Continue levantando até quase tocar o queixo. Dica: os cotovelos devem conduzir o movimento. Ao levantar a barra, os cotovelos devem estar sempre mais altos que os antebraços. Além disso, mantenha o tronco parado e faça uma pausa de um segundo no topo do movimento.\nAbaixe a barra lentamente de volta à posição inicial. Inspire durante esta parte do movimento.\nRepita pelo número recomendado de repetições.',
  'Upright Row - With Bands':
    'Para começar, fique em pé sobre uma faixa elástica de modo que a tensão comece com os braços estendidos. Segure as alças com pegada pronada (palmas voltadas para as coxas) ligeiramente mais estreita que a largura dos ombros. As alças devem ficar apoiadas na parte superior das coxas. Os braços devem estar estendidos com uma leve flexão nos cotovelos e as costas retas. Esta será sua posição inicial.\nUse a parte lateral dos ombros para elevar as alças enquanto expira. As alças devem ficar próximas ao corpo enquanto sobem. Continue levantando até quase tocarem o queixo. Dica: os cotovelos devem conduzir o movimento. Ao levantar as alças, os cotovelos devem estar sempre mais altos que os antebraços. Além disso, mantenha o tronco parado e faça uma pausa de um segundo no topo do movimento.\nAbaixe as alças lentamente de volta à posição inicial. Inspire durante esta parte do movimento.\nRepita pelo número recomendado de repetições.',
  'Upward Stretch':
    'Estenda as duas mãos retas acima da cabeça, com as palmas unidas.\nEmpurre lentamente as mãos para cima e para trás, mantendo as costas retas.',
  'V-Bar Pulldown':
    'Sente-se em uma máquina de puxada com uma barra em V presa à polia superior.\nAjuste o apoio de joelhos da máquina à sua altura. Esses apoios impedem que a resistência da barra levante seu corpo.\nSegure a barra em V com as palmas voltadas uma para a outra (pegada neutra). Projete o peito para fora e incline-se levemente para trás (cerca de 30 graus) para ativar melhor os dorsais. Esta será sua posição inicial.\nUsando os dorsais, puxe a barra para baixo enquanto aproxima as escápulas. Continue até que o peito quase toque a barra em V. Expire ao executar este movimento. Dica: mantenha o tronco parado durante todo o movimento.\nApós um segundo na posição contraída, leve lentamente a barra de volta à posição inicial enquanto inspira.\nRepita pelo número prescrito de repetições.',
  'V-Bar Pullup':
    'Comece posicionando o centro da barra em V no centro da barra fixa (supondo que a estação de barra fixa que você está usando não tenha pegadores neutros). As alças da barra em V ficarão voltadas para baixo para que você possa se pendurar na barra fixa por meio delas.\nDepois de posicionar a barra em V com segurança, segure-a de cada lado e pendure-se. Projete o peito para fora e incline-se levemente para trás para ativar melhor os dorsais. Esta será sua posição inicial.\nUsando os dorsais, eleve o tronco inclinando a cabeça levemente para trás para não bater o queixo na barra. Continue até que o peito quase toque a barra em V. Expire ao executar este movimento.\nApós um segundo na posição contraída, abaixe lentamente o corpo de volta à posição inicial enquanto inspira.\nRepita pelo número prescrito de repetições.',
  'Vertical Swing':
    'Deixe o halter pendurado à altura dos braços estendidos entre as pernas, segurando-o com as duas mãos. Mantenha as costas retas e a cabeça erguida.\nBalance o halter entre as pernas, flexionando o quadril e dobrando levemente os joelhos.\nInverta o movimento com força, estendendo quadril, joelhos e tornozelos para se impulsionar para cima, balançando o halter acima da cabeça.\nAo aterrissar, absorva o impacto com as pernas e traga o halter até o tronco antes da próxima repetição.',
  'Walking, Treadmill':
    'Para começar, suba na esteira e selecione a opção desejada no menu. A maioria das esteiras tem um modo manual, ou você pode selecionar um programa. Normalmente é possível inserir sua idade e peso para estimar a quantidade de calorias queimadas durante o exercício. A inclinação pode ser ajustada para mudar a intensidade do treino.\nAs esteiras oferecem conveniência e benefícios cardiovasculares, e geralmente têm menos impacto que caminhar ao ar livre. Ao caminhar, você deve se mover em um ritmo de moderado a rápido, não em passo lento. Por ser uma atividade de menor intensidade, a caminhada não queima tantas calorias quanto algumas outras atividades, mas ainda traz ótimos benefícios. Uma pessoa de 150 lb queimará cerca de 175 calorias caminhando 4 milhas por hora durante 30 minutos, em comparação com 450 calorias correndo ao dobro da velocidade. Mantenha a postura correta ao caminhar e segure nas alças somente quando necessário, como ao descer ou ao verificar a frequência cardíaca.',
  'Weighted Ball Hyperextension':
    'Para começar, deite-se sobre uma bola de exercício com o tronco apoiado na bola e paralelo ao chão. As pontas dos pés devem pressionar o chão para ajudar a manter o equilíbrio. Coloque um anilha de peso sob o queixo ou atrás do pescoço. Esta é a posição inicial.\nEleve lentamente o tronco flexionando na cintura e na lombar. Lembre-se de expirar durante este movimento.\nMantenha a contração na lombar por um segundo e abaixe o tronco de volta à posição inicial enquanto inspira.\nRepita pelo número recomendado de repetições indicado no seu programa.',
  'Weighted Ball Side Bend':
    'Para começar, deite-se sobre uma bola de exercício com o lado esquerdo do tronco (cintura, quadril e ombro) apoiado na bola.\nOs pés devem estar no chão, com as pernas cruzadas e pendendo da bola. Segure uma anilha com a mão direita, diretamente ao lado direito da cabeça. Dica: certifique-se de que o lado liso da anilha fique apoiado na cabeça.\nColoque o braço esquerdo cruzado sobre o tronco de modo que a palma fique sobre os oblíquos. Deve haver um ângulo reto entre o antebraço esquerdo e a parte superior do braço. Esta é a posição inicial.\nEleve a lateral do tronco flexionando lateralmente na cintura enquanto expira.\nMantenha a contração por um segundo e abaixe lentamente de volta à posição inicial enquanto inspira.\nRepita pelo número recomendado de repetições.\nTroque de lado e repita o exercício.',
  'Weighted Bench Dip':
    'Para este exercício, você precisará colocar um banco atrás das costas e outro à sua frente. Com os bancos perpendiculares ao corpo, segure a borda de um dos bancos com as mãos próximas ao corpo, separadas na largura dos ombros. Os braços devem estar totalmente estendidos.\nAs pernas ficarão estendidas para a frente sobre o outro banco. As pernas devem ficar paralelas ao chão enquanto o tronco fica perpendicular ao chão. Peça ao seu parceiro que coloque o halter sobre o seu colo. Nota: este exercício é melhor realizado com um parceiro, pois colocar o peso no colo pode ser difícil e causar lesões sem ajuda. Esta será sua posição inicial.\nAbaixe lentamente o corpo enquanto inspira, flexionando os cotovelos até chegar a um ângulo ligeiramente menor que 90 graus entre a parte superior do braço e o antebraço. Dica: mantenha os cotovelos o mais próximos possível durante todo o movimento. Os antebraços devem apontar sempre para baixo.\nUsando o tríceps para elevar o tronco novamente, empurre-se de volta à posição inicial enquanto expira.\nRepita pelo número recomendado de repetições.',
  'Weighted Crunches':
    'Deite-se de costas com os pés apoiados no chão ou em um banco, com os joelhos flexionados a 90 graus.\nSegure um peso junto ao peito, ou você pode segurá-lo estendido acima do tronco. Esta será sua posição inicial.\nAgora, expire e comece a descolar lentamente os ombros do chão. Seus ombros devem subir cerca de 10 cm do chão enquanto a lombar permanece no chão.\nNo topo do movimento, contraia os abdominais e faça uma breve pausa.\nDepois inspire e abaixe lentamente de volta à posição inicial.',
  'Weighted Jump Squat':
    'Posicione uma barra com pouca carga sobre a parte de trás dos ombros. Você também pode usar um colete com peso, um saco de areia ou outro tipo de resistência para este exercício.\nO peso deve ser leve o suficiente para não atrapalhar significativamente seu movimento. Seus pés devem ficar um pouco além da largura dos ombros, com a cabeça e o peito erguidos. Esta será sua posição inicial.\nUsando um contramovimento, agache parcialmente e inverta imediatamente a direção para saltar com explosão, estendendo quadril, joelhos e tornozelos. Mantenha uma boa postura durante todo o salto.\nAo retornar ao chão, absorva o impacto com as pernas.',
  'Weighted Pull Ups':
    'Prenda um peso a um cinto de lastro e ajuste-o em volta da cintura. Segure a barra fixa com as palmas das mãos voltadas para a frente. Para uma pegada média, as mãos devem ficar na largura dos ombros. Os dois braços devem estar estendidos à sua frente segurando a barra na pegada escolhida.\nVocê deve inclinar o tronco para trás cerca de 30 graus, criando uma curvatura na lombar e projetando o peito para fora. Esta será sua posição inicial.\nAgora, expire e puxe o tronco para cima até que a cabeça fique acima das mãos. Concentre-se em contrair as escápulas para trás e para baixo ao chegar à posição superior de contração.\nApós um breve momento na posição superior de contração, inspire e abaixe lentamente o tronco de volta à posição inicial, com os braços estendidos e os dorsais totalmente alongados.',
  'Weighted Sissy Squat':
    'Em pé, com os pés na largura dos ombros e os calcanhares elevados sobre a ponta dos pés, use uma das mãos para se segurar nas colunas de um rack de agachamento e o braço oposto para segurar uma anilha sobre o peito. Esta é sua posição inicial.\nEnquanto usa um braço para se apoiar, flexione os joelhos e abaixe lentamente o tronco em direção ao chão, levando a pelve e os joelhos para a frente. Inspire ao descer e pare quando a parte superior e a inferior das pernas quase formarem um ângulo de 90 graus. Mantenha a posição de alongamento por um segundo.\nApós esse segundo de pausa, use os músculos das coxas para elevar o tronco de volta à posição inicial. Expire ao subir.\nRepita pelo número recomendado de vezes.',
  'Weighted Sit-Ups - With Bands':
    'Comece prendendo as faixas elásticas na base do banco declinado. Posicione as alças para o lado de dentro do banco declinado, de modo que, ao se deitar, você consiga alcançar as duas.\nEncaixe as pernas no banco declinado até ficarem presas com segurança. Agora alcance as faixas elásticas com as duas mãos. Use uma pegada pronada (palmas para a frente) para segurar as alças. Posicione-as perto da clavícula e gire os punhos para uma pegada neutra (palmas voltadas para o tronco). Nota: os braços devem permanecer parados durante todo o exercício. Esta é a posição inicial.\nEleve o tronco até que a parte superior do corpo fique perpendicular ao chão enquanto expira. Mantenha a contração por um segundo e abaixe a parte superior do corpo de volta à posição inicial enquanto inspira.\nRepita pelo número recomendado de repetições.',
  'Weighted Squat':
    'Comece posicionando dois bancos planos separados na largura dos ombros. Suba neles e prenda o cinto de lastro em volta da cintura com a carga com a qual você se sinta confortável. Certifique-se de que as pontas dos pés estejam voltadas para fora.\nDepois de ficar totalmente em pé, com o peso pendurado entre as pernas, posicione os braços totalmente estendidos ao lado do corpo. Esta é a posição inicial.\nComece flexionando os joelhos enquanto mantém a postura reta com a cabeça erguida. Continue descendo até que o ângulo entre a coxa e a panturrilha fique ligeiramente menor que 90 graus (ponto em que as coxas ficam abaixo da paralela ao chão). Inspire durante esta parte do movimento. Dica: se você realizou o exercício corretamente, a frente dos joelhos deve formar uma linha reta imaginária com os dedos dos pés, perpendicular à frente. Se os joelhos passarem dessa linha imaginária (se passarem da ponta dos pés), você está colocando estresse excessivo no joelho e o exercício foi executado de forma incorreta.\nComece a subir o corpo empurrando o banco plano principalmente com a parte da frente do pé enquanto estende novamente as pernas e volta à posição inicial. Expire durante esta parte do exercício.\nRepita pelo número recomendado de repetições.',
  'Wide Stance Barbell Squat':
    'Este exercício é melhor realizado dentro de um rack de agachamento por segurança. Para começar, primeiro posicione a barra em um rack que combine com a sua altura. Depois de escolher a altura correta e carregar a barra, posicione-se sob a barra e apoie-a na parte de trás dos ombros (ligeiramente abaixo do pescoço).\nSegure a barra com os dois braços, um de cada lado, e tire-a do rack empurrando primeiro com as pernas e, ao mesmo tempo, endireitando o tronco.\nAfaste-se do rack e posicione as pernas em uma base mais larga que a largura dos ombros, com as pontas dos pés levemente voltadas para fora. Mantenha a cabeça erguida o tempo todo, pois olhar para baixo faz você perder o equilíbrio, e mantenha também as costas retas. Esta será sua posição inicial.\nComece a abaixar lentamente a barra flexionando os joelhos enquanto mantém a postura reta com a cabeça erguida. Continue descendo até que o ângulo entre a coxa e a panturrilha fique ligeiramente menor que 90 graus (ponto em que as coxas ficam abaixo da paralela ao chão). Inspire durante esta parte do movimento. Dica: se você realizou o exercício corretamente, a frente dos joelhos deve formar uma linha reta imaginária com os dedos dos pés, perpendicular à frente. Se os joelhos passarem dessa linha imaginária (se passarem da ponta dos pés), você está colocando estresse excessivo no joelho e o exercício foi executado de forma incorreta.\nComece a subir a barra enquanto expira, empurrando o chão com o calcanhar enquanto estende novamente as pernas e volta à posição inicial.\nRepita pelo número recomendado de repetições.',
  'Wide Stance Stiff Legs':
    'Comece com uma barra carregada no chão. Assuma uma base larga e depois flexione o quadril para segurar a barra. O quadril deve ficar o mais para trás possível e as pernas quase retas. Mantenha as costas retas e a cabeça e o peito erguidos. Esta será sua posição inicial.\nComece o movimento ativando o quadril, levando-o para a frente enquanto deixa os braços pendurados retos. Continue até ficar totalmente em pé e depois retorne lentamente o peso à posição inicial. Nas repetições seguintes, o peso não precisa tocar o chão.',
  'Wide-Grip Barbell Bench Press':
    'Deite-se em um banco reto com os pés firmes no chão. Usando uma pegada larga e pronada (palmas para a frente), cerca de 3 polegadas além da largura dos ombros (em cada mão), tire a barra do rack e segure-a reta acima de você com os braços travados. A barra ficará perpendicular ao tronco e ao chão. Esta será sua posição inicial.\nEnquanto inspira, desça lentamente até sentir a barra na parte média do peito.\nApós uma pausa de um segundo, leve a barra de volta à posição inicial enquanto expira e empurra a barra com os músculos do peito. Trave os braços e contraia o peito na posição contraída, mantenha por um segundo e depois comece a descer lentamente de novo. Dica: a descida deve levar pelo menos o dobro do tempo da subida.\nRepita o movimento pelo número prescrito de repetições.',
  'Wide-Grip Decline Barbell Bench Press':
    'Deite-se em um banco declinado com os pés firmemente presos na parte da frente do banco. Usando uma pegada larga e pronada (palmas para a frente), cerca de 3 polegadas além da largura dos ombros (em cada mão), tire a barra do rack e segure-a reta acima de você com os braços travados. A barra ficará perpendicular ao tronco e ao chão. Esta será sua posição inicial.\nEnquanto inspira, desça lentamente até sentir a barra na parte inferior do peito.\nApós uma pausa de um segundo, leve a barra de volta à posição inicial enquanto expira e empurra a barra com os músculos do peito. Trave os braços e contraia o peito na posição contraída, mantenha por um segundo e depois comece a descer lentamente de novo. Dica: a descida deve levar pelo menos o dobro do tempo da subida.\nRepita o movimento pelo número prescrito de repetições.',
  'Wide-Grip Decline Barbell Pullover':
    'Deite-se em um banco declinado com as duas pernas firmemente presas. Alcance a barra atrás da cabeça usando uma pegada pronada (palmas para fora). Certifique-se de segurar a barra mais larga que a largura dos ombros para este exercício. Levante lentamente a barra do chão usando os braços.\nQuando estiver bem posicionado, os braços devem estar totalmente estendidos e perpendiculares ao chão. Esta é a posição inicial.\nComece abaixando a barra para trás em um movimento semicircular, como se fosse colocá-la no chão, mas pare quando os braços estiverem paralelos ao chão. Dica: mantenha os braços totalmente estendidos o tempo todo. O movimento deve acontecer somente na articulação do ombro. Inspire durante esta parte do movimento.\nAgora eleve a barra enquanto expira até voltar à posição inicial. Lembre-se de manter o controle total da barra o tempo todo.\nRepita o movimento pelo número prescrito de repetições do seu programa de treino.\nAo terminar a série, abaixe lentamente a barra até ficar na altura da cabeça e solte-a.',
  'Wide-Grip Lat Pulldown':
    'Sente-se em uma máquina de puxada com uma barra larga presa à polia superior. Certifique-se de ajustar o apoio de joelhos da máquina à sua altura. Esses apoios impedem que a resistência da barra levante seu corpo.\nSegure a barra com as palmas voltadas para a frente usando a pegada prescrita. Nota sobre as pegadas: na pegada larga, as mãos devem ficar afastadas a uma distância maior que a largura dos ombros. Na pegada média, as mãos devem ficar afastadas a uma distância igual à largura dos ombros, e na pegada fechada, a uma distância menor que a largura dos ombros.\nCom os dois braços estendidos à frente segurando a barra na largura de pegada escolhida, incline o tronco para trás cerca de 30 graus, criando uma curvatura na lombar e projetando o peito para fora. Esta é sua posição inicial.\nEnquanto expira, puxe a barra para baixo até tocar a parte superior do peito, levando os ombros e a parte superior dos braços para baixo e para trás. Dica: concentre-se em contrair os músculos das costas ao chegar à posição de contração total. A parte superior do tronco deve permanecer parada e somente os braços devem se mover. Os antebraços não devem fazer nenhum trabalho além de segurar a barra; portanto, não tente puxar a barra com os antebraços.\nApós um segundo na posição contraída, apertando as escápulas uma contra a outra, eleve lentamente a barra de volta à posição inicial, quando os braços estiverem totalmente estendidos e os dorsais totalmente alongados. Inspire durante esta parte do movimento.\nRepita este movimento pelo número prescrito de repetições.',
  'Wide-Grip Pulldown Behind The Neck':
    'Sente-se em uma máquina de puxada com uma barra larga presa à polia superior. Certifique-se de ajustar o apoio de joelhos da máquina à sua altura. Esses apoios impedem que a resistência da barra levante seu corpo.\nSegure a barra com as palmas voltadas para a frente usando a pegada prescrita. Nota sobre as pegadas: na pegada larga, as mãos devem ficar afastadas a uma distância maior que a largura dos ombros. Na pegada média, as mãos devem ficar afastadas a uma distância igual à largura dos ombros, e na pegada fechada, a uma distância menor que a largura dos ombros.\nCom os dois braços estendidos à frente segurando a barra na largura de pegada escolhida, leve o tronco e a cabeça para a frente. Imagine uma linha do centro da barra até a nuca. Esta é sua posição inicial.\nEnquanto expira, puxe a barra para baixo até tocar a nuca, levando os ombros e a parte superior dos braços para baixo e para trás. Dica: concentre-se em contrair os músculos das costas ao chegar à posição de contração total. A parte superior do tronco deve permanecer parada e somente os braços devem se mover. Os antebraços não devem fazer nenhum trabalho além de segurar a barra; portanto, não tente puxar a barra com os antebraços.\nApós um segundo na posição contraída, apertando as escápulas uma contra a outra, eleve lentamente a barra de volta à posição inicial, quando os braços estiverem totalmente estendidos e os dorsais totalmente alongados. Inspire durante esta parte do movimento.\nRepita este movimento pelo número prescrito de repetições.',
  'Wide-Grip Rear Pull-Up':
    'Segure a barra fixa com as palmas voltadas para a frente usando uma pegada larga.\nCom os dois braços estendidos à sua frente segurando a barra, leve o tronco e a cabeça para a frente de modo que haja uma linha imaginária da barra fixa até a nuca. Esta é sua posição inicial.\nPuxe o tronco para cima até que a barra fique perto da nuca. Para isso, leve os ombros e a parte superior dos braços para baixo e para trás enquanto inclina levemente a cabeça para a frente. Expire durante esta parte do movimento. Dica: concentre-se em contrair os músculos das costas ao chegar à posição de contração total. A parte superior do tronco deve permanecer parada enquanto se desloca no espaço e somente os braços devem se mover. Os antebraços não devem fazer nenhum trabalho além de segurar a barra.\nApós um segundo na posição contraída, comece a inspirar e abaixe lentamente o tronco de volta à posição inicial, quando os braços estiverem totalmente estendidos e os dorsais totalmente alongados.\nRepita este movimento pelo número prescrito de repetições.',
  'Wide-Grip Standing Barbell Curl':
    'Fique em pé com o tronco ereto segurando uma barra pela pegada externa larga. As palmas das mãos devem estar voltadas para a frente. Os cotovelos devem ficar próximos ao tronco. Esta será sua posição inicial.\nMantendo a parte superior dos braços parada, eleve os pesos para a frente contraindo os bíceps enquanto expira. Dica: somente os antebraços devem se mover.\nContinue o movimento até que os bíceps estejam totalmente contraídos e a barra fique na altura dos ombros. Mantenha a posição contraída por um segundo e contraia forte os bíceps.\nComece a levar lentamente a barra de volta à posição inicial enquanto inspira.\nRepita pelo número recomendado de repetições.',
  'Wind Sprints':
    'Pendure-se em uma barra fixa usando uma pegada pronada. Os braços e as pernas devem estar estendidos. Esta será sua posição inicial.\nComece elevando rapidamente um joelho o mais alto que puder. Não balance o corpo nem as pernas. 3\nInverta o movimento imediatamente, levando essa perna de volta à posição inicial. Simultaneamente, eleve o joelho oposto o mais alto possível.\nContinue alternando as pernas até completar a série.',
  Windmills:
    'Deite-se de costas com os braços estendidos para os lados e as pernas retas. Esta será sua posição inicial.\nLevante uma perna e cruze-a rapidamente sobre o corpo, tentando tocar o chão perto da mão oposta.\nVolte à posição inicial e repita com a perna oposta. Continue alternando por 10 a 20 repetições.',
  "World's Greatest Stretch":
    'Este é um alongamento em três partes. Comece dando um afundo para a frente, com o pé da frente totalmente apoiado no chão e sobre a ponta do pé de trás. Com os joelhos flexionados, agache até que o joelho quase toque o chão. Mantenha o tronco ereto e sustente esta posição por 10 a 20 segundos.\nAgora, apoie no chão o braço do mesmo lado da perna da frente, com o cotovelo ao lado do pé. A outra mão deve ser apoiada no chão, paralela à perna da frente, para ajudar a sustentar você durante esta parte do alongamento.\nApós 10 a 20 segundos, posicione as mãos dos dois lados do pé da frente. Levante do chão a ponta do pé da frente e estenda a perna. Pode ser necessário reposicionar a perna de trás para isso. Mantenha por 10 a 20 segundos e depois repita toda a sequência para o outro lado.',
  'Wrist Circles':
    'Comece em pé, reto, com os pés separados na largura dos ombros. Eleve os braços para os lados até ficarem totalmente estendidos e paralelos ao chão, em uma altura alinhada com os ombros. Dica: o tronco e os braços devem formar a letra "T". As palmas devem estar voltadas para baixo. Esta é a posição inicial.\nMantendo todo o corpo parado, exceto os punhos, comece a girar os dois punhos para a frente em um movimento circular. Dica: imagine que você está tentando desenhar círculos usando as mãos como pincel. Respire normalmente enquanto realiza este exercício.\nRepita pelo número recomendado de repetições.',
  'Wrist Roller':
    'Para começar, fique em pé, reto, segurando um rolo de punho com pegada pronada (palmas para baixo). Os pés devem ficar separados na largura dos ombros.\nLevante lentamente os dois braços até ficarem totalmente estendidos e paralelos ao chão à sua frente. Nota: certifique-se de que a corda não esteja enrolada no rolo. Todo o seu corpo deve permanecer parado, exceto os antebraços. Esta é a posição inicial.\nGire um punho de cada vez em um movimento para cima para elevar o peso até a barra, enrolando a corda em volta do rolo.\nQuando o peso chegar à barra, comece a abaixá-lo lentamente girando o punho em um movimento para baixo até o peso chegar à posição inicial.\nRepita pelo número prescrito de repetições do seu programa.',
  'Wrist Rotations with Straight Bar':
    'Segure uma barra com as duas mãos e as palmas voltadas para baixo, com as mãos separadas aproximadamente na largura dos ombros. Esta será sua posição inicial.\nAlternando entre as duas mãos, execute o movimento estendendo o punho como se estivesse enrolando um jornal. Continue alternando de um lado para o outro até a falha.\nInverta o movimento flexionando o punho, enrolando na direção oposta. Continue o movimento alternado até a falha.',
  'Yoke Walk':
    'O yoke normalmente é feito com um aparelho de yoke, mas às vezes é visto com geladeiras ou outros objetos pesados.\nComece apoiando o aparelho na parte de trás dos ombros. Com o olhar para a frente e as costas arqueadas, levante o yoke empurrando com os calcanhares.\nComece a caminhar o mais rápido possível com passos curtos e rápidos. Você pode segurar os postes laterais do yoke para ajudar a estabilizá-lo e mantê-lo em posição. Continue pela distância indicada o mais rápido possível, normalmente 75 a 100 pés.',
  'Zercher Squats':
    'Este exercício é melhor realizado dentro de um rack de agachamento por segurança. Para começar, primeiro posicione a barra em um rack que combine com a sua altura. A altura correta deve ficar acima da cintura, mas abaixo do peito. Depois de escolher a altura correta e carregar a barra, una as mãos e apoie a barra sobre os braços, entre o antebraço e a parte superior do braço.\nLevante a barra de modo que fique apoiada sobre os antebraços. Se você está segurando a barra corretamente, deve parecer que está com os braços cruzados, mas com uma barra atravessada sobre eles.\nAfaste-se do rack e posicione as pernas em uma base média, na largura dos ombros, com as pontas dos pés levemente voltadas para fora. Mantenha a cabeça erguida o tempo todo, pois olhar para baixo faz você perder o equilíbrio, e mantenha também as costas retas. Esta será sua posição inicial. (Nota: para efeitos desta explicação, usaremos a base média descrita acima, que trabalha o desenvolvimento geral; porém, você pode escolher qualquer uma das três bases discutidas na seção de posicionamento dos pés).\nComece a abaixar a barra flexionando os joelhos enquanto mantém a postura reta com a cabeça erguida. Continue descendo até que o ângulo entre a coxa e a panturrilha fique ligeiramente menor que 90 graus (ponto em que as coxas ficam abaixo da paralela ao chão). Inspire durante esta parte do movimento. Dica: se você realizou o exercício corretamente, a frente dos joelhos deve formar uma linha reta imaginária com os dedos dos pés, perpendicular à frente. Se os joelhos passarem dessa linha imaginária (se passarem da ponta dos pés), você está colocando estresse excessivo no joelho e o exercício foi executado de forma incorreta.\nComece a subir a barra enquanto expira, empurrando o chão principalmente com a parte da frente do pé enquanto estende novamente as pernas e volta à posição inicial.\nRepita pelo número recomendado de repetições.',
  'Zottman Curl':
    'Fique em pé com o tronco ereto e um halter em cada mão, mantidos com os braços estendidos. Os cotovelos devem ficar próximos ao tronco.\nCertifique-se de que as palmas das mãos estejam voltadas uma para a outra. Esta será sua posição inicial.\nMantendo a parte superior do braço parada, eleve os pesos contraindo os bíceps enquanto expira. Somente os antebraços devem se mover. O punho deve girar de modo que você fique com uma pegada supinada (palmas para cima). Continue o movimento até que os bíceps estejam totalmente contraídos e os halteres fiquem na altura dos ombros.\nMantenha a posição contraída por um segundo enquanto contrai os bíceps.\nAgora, na posição contraída, gire o punho até ficar com uma pegada pronada (palmas para baixo), com o polegar em posição mais alta que o dedo mínimo.\nComece a abaixar lentamente os halteres usando a pegada pronada.\nQuando os halteres se aproximarem das coxas, comece a girar o punho para voltar a uma pegada neutra (palmas voltadas para o corpo).\nRepita pelo número recomendado de repetições.',
  'Zottman Preacher Curl':
    'Segure um halter em cada mão e apoie a parte superior dos braços no banco Scott ou no banco inclinado. Os halteres devem ser mantidos na altura dos ombros e os cotovelos devem estar flexionados. Segure os halteres com as palmas das mãos voltadas para baixo. Esta será sua posição inicial.\nEnquanto inspira, abaixe lentamente os halteres mantendo as palmas para baixo até que a parte superior do braço fique estendida e os bíceps totalmente alongados.\nAgora gire os punhos ao chegar à parte inferior do movimento para que as palmas das mãos fiquem voltadas para cima.\nEnquanto expira, use os bíceps para elevar os pesos até que estejam totalmente contraídos e os halteres fiquem na altura dos ombros. Lembre-se novamente de que, para garantir a contração completa, você precisa levar o dedo mínimo mais alto que o polegar.\nContraia forte os bíceps por um segundo na posição contraída e gire os punhos para que as palmas fiquem voltadas para baixo novamente.\nRepita pelo número recomendado de repetições.',
};
